@pure_lazy
def _refresh_callback_branch_ref_if_needed(
    txn: _VersionedWriteTxnState,
    plan: _VersionedDmlUserIdPlan,
    branch_ref: ScalarServerRef[BranchId],
) -> tuple[ScalarServerRef[BranchId], frozenset[ServerPlanRefId]]:
    original_dependency_refs = frozenset(ServerPlanRefId(ref) for ref in lazy_param_deps(branch_ref))
    branch_anchor = getattr(txn, "_branch_anchor", None)
    if isinstance(branch_anchor, BranchId):
        return ServerRefs.scalar(branch_anchor), original_dependency_refs
    branch_shape = inspect_server_value_shape_for_planning(
        branch_ref,
        site="_refresh_callback_branch_ref_if_needed",
    )
    if branch_shape.has_literal_value and isinstance(branch_shape.literal_value, BranchId):
        return branch_ref, frozenset()
    symbolic_ref_id = branch_shape.symbolic_ref_id
    if symbolic_ref_id is not None:
        producer_ref_id = str(symbolic_ref_id).split(".", 1)[0]
        if any(str(step.ref_id) == producer_ref_id for step in plan._steps):
            return branch_ref, frozenset()
    write_ctx_result = getattr(txn, "_write_branch_context_result", None)
    if isinstance(write_ctx_result, LazyResult):
        write_ctx_shape = inspect_server_value_shape_for_planning(
            write_ctx_result,
            site="_refresh_callback_branch_ref_if_needed.write_context",
        )
        resolved_branch_id = getattr(write_ctx_shape.literal_value, "branch_id", None) if write_ctx_shape.has_literal_value else None
        if isinstance(resolved_branch_id, BranchId):
            object.__setattr__(txn, "_branch_anchor", resolved_branch_id)
            return ServerRefs.scalar(resolved_branch_id), original_dependency_refs
    branch_name = _optional_callback_branch_name(txn)
    if branch_name is None:
        return branch_ref, frozenset()
    workspace_id = _optional_callback_workspace_id(txn)
    domain = txn.domain
    refreshed_ctx = txn._add_intent(
        intent_versioning.ResolveVersionedWriteExistingBranchByNameIntent(
            ServerPlanRefId(plan._next_ref()),
            domain=domain,
            branch_name=ServerRefs.scalar(
                branch_name if isinstance(branch_name, BranchName) else BranchName(branch_name),
            ),
            workspace_id=ServerRefs.scalar(workspace_id or domain.workspace_id or WorkspaceId.default()),
            permission_context=bound_permission_context_transport_lazy(txn),
        ),
    )
    return (
        cast(
            "ScalarServerRef[BranchId]",
            project_server_ref_result(cast("LazyResult[object]", refreshed_ctx), "write_ctx_branch"),
        ),
        original_dependency_refs,
    )


