@pure_lazy
def _graph_revision_ref(
    txn: VersionedReadTransactionLazyMixin | VersionedWriteTransactionLazyMixin,
    context_refs: VersionedLazyContextRefs,
    materialization: VersionedLazyMaterializationPolicy,
) -> ScalarServerRef[RevisionId]:
    has_branch_context = context_refs.branch is not UNSET
    if _graph_uses_tip_strategy(
        prefer_tip_strategy=materialization.prefer_tip_strategy,
        has_branch_anchor=has_branch_context,
        materialization=materialization,
    ):
        msg = "Tip graph reads do not require a revision ref"
        raise RuntimeError(msg)
    context_revision_ref = versioned_lazy_context_revision_ref(
        context_refs,
        context=DiagnosticLabel("_graph_revision_ref revision context"),
    )
    if context_revision_ref is not None:
        return context_revision_ref
    if isinstance(txn, VersionedWriteTransactionLazyMixin):
        return _require_scalar_source_ref(
            _graph_write_txn_revision_lazy(txn, context_refs),
            context="_graph_revision_ref write branch tip",
        )
    if has_branch_context:
        read_txn = cast(_VersionedReadTxnState, txn)
        plan = read_txn._get_transaction_plan_lazy()
        ref_id = ServerPlanRefId(plan._next_ref())
        read_txn._add_intent(
            intent_versioning_extended.GetBranchTipIntent(
                ref_id=ref_id,
                config=intent_versioning_extended._GetBranchTipConfig(
                    branch_id=versioned_lazy_context_branch_ref(
                        context_refs,
                        context=DiagnosticLabel("_graph_revision_ref branch context"),
                    ),
                    domain=_txn_domain(txn),
                ),
            ),
        )
        return ServerRefs.from_ref_id(ref_id, variant="scalar", type_hint=RevisionId)
    msg = "Graph revision context requires l7000-owned revision or branch context refs"
    raise RuntimeError(msg)


@pure_lazy
def _non_current_revision_literal(value: object) -> RevisionId | None:
    if isinstance(value, RevisionId) and not value.is_current():
        return value
    if isinstance(value, SysId | str):
        revision_id = RevisionId(str(value))
        if not revision_id.is_current():
            return revision_id
    return None


@pure_lazy
def _transaction_revision_literal(txn: object) -> RevisionId | None:
    for attr_name in (
        "_explicit_read_revision_id",
        "_revision_id",
        "_snapshot_revision_id",
    ):
        candidate = getattr(txn, attr_name, None)
        revision_id = _non_current_revision_literal(candidate)
        if revision_id is not None:
            return revision_id
    if isinstance(txn, VersionedWriteTransactionLazyMixin):
        return _write_txn_explicit_base_revision_id(txn)
    return None


@pure_lazy
def _graph_revision_input(
    txn: VersionedReadTransactionLazyMixin | VersionedWriteTransactionLazyMixin,
    context_refs: VersionedLazyContextRefs,
) -> tuple[RevisionId | None, ServerPlanRefId | None]:
    txn_revision_id = _transaction_revision_literal(txn)
    if txn_revision_id is not None:
        return (txn_revision_id, None)

    if isinstance(txn, VersionedWriteTransactionLazyMixin):
        return _graph_write_txn_revision_input(txn, context_refs)
    if context_refs.branch is not UNSET:
        read_txn = cast(_VersionedReadTxnState, txn)
        plan = read_txn._get_transaction_plan_lazy()
        ref_id = ServerPlanRefId(plan._next_ref())
        read_txn._add_intent(
            intent_versioning_extended.GetBranchTipIntent(
                ref_id=ref_id,
                config=intent_versioning_extended._GetBranchTipConfig(
                    branch_id=versioned_lazy_context_branch_ref(
                        context_refs,
                        context=DiagnosticLabel("_graph_revision_input branch context"),
                    ),
                    domain=_txn_domain(txn),
                ),
            ),
        )
        _preserve_context_ref_across_flush(txn, ref_id)
        return (None, ref_id)
    context_revision_ref = versioned_lazy_context_revision_ref(
        context_refs,
        context=DiagnosticLabel("_graph_revision_input revision context"),
    )
    if context_revision_ref is None:
        return (None, None)
    revision_shape = inspect_server_value_shape_for_planning(
        context_revision_ref,
        site="_graph_revision_input revision context",
    )
    if revision_shape.has_literal_value:
        literal_revision = revision_shape.literal_value
        revision_id = _non_current_revision_literal(literal_revision)
        if revision_id is not None:
            return (revision_id, None)
        if str(literal_revision) == str(RevisionId.current()):
            return (None, None)
    if revision_shape.symbolic_ref_id is None:
        msg = "_graph_revision_input requires a literal or published revision context ref"
        raise RuntimeError(msg)
    _preserve_context_ref_across_flush(txn, revision_shape.symbolic_ref_id)
    return (None, revision_shape.symbolic_ref_id)


@pure_lazy
def _graph_branch_tables(txn: VersionedReadTransactionLazyMixin) -> tuple[str | None, str | None]:
    domain = _txn_domain(txn)
    if getattr(domain, "__nera_ad_hoc_revision_domain__", False):
        return (None, None)
    branch_model = getattr(domain, "branch_model", None)
    revision_branch_index_model = getattr(domain, "revision_branch_index_model", None)
    if not isinstance(branch_model, type) or not isinstance(revision_branch_index_model, type):
        return (None, None)
    return (
        get_table_name(branch_model),
        get_table_name(revision_branch_index_model),
    )


@pure_lazy
def _preserve_context_ref_across_flush(txn: object, ref_id: ServerPlanRefId | str | None) -> None:
    if ref_id is None:
        return
    plan = cast(Any, txn)._get_transaction_plan_lazy()
    preserve_refs: set[str] = set(getattr(plan, "_preserve_across_flush_ref_ids", frozenset()))
    root_ref_id = str(ref_id).split(".", 1)[0]
    expand_ref_closure = getattr(plan, "_expand_ref_closure", None)
    if callable(expand_ref_closure):
        preserve_refs.update(cast("Callable[[set[str]], set[str]]", expand_ref_closure)({root_ref_id}))
    else:
        preserve_refs.add(root_ref_id)
    object.__setattr__(plan, "_preserve_across_flush_ref_ids", frozenset(preserve_refs))


@pure_lazy
def _graph_branch_anchor_ref(
    txn: VersionedReadTransactionLazyMixin,
    registrar: object,
    context_refs: VersionedLazyContextRefs,
    materialization: VersionedLazyMaterializationPolicy,
) -> ScalarServerRef[BranchId | None]:
    if context_refs.branch is not UNSET:
        return cast(
            ScalarServerRef[BranchId | None],
            versioned_lazy_context_branch_ref(
                context_refs,
                context=DiagnosticLabel("_graph_branch_anchor_ref branch context"),
            ),
        )

    domain = _txn_domain(txn)
    branch_table, branch_index_table = _graph_branch_tables(txn)
    if branch_table is None or branch_index_table is None:
        return ServerRefs.scalar(None)
    branch_model = domain.branch_model

    plan = txn._get_transaction_plan_lazy()
    branch_anchor_ref_id = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        ResolveBranchForRevisionStep(
            branch_anchor_ref_id,
            _graph_revision_ref(txn, context_refs, materialization),
            SqlTableName(branch_table),
            SqlTableName(branch_index_table),
            branch_id_column=get_db_column_name(branch_model, DynamicFieldName("sys_id")),
            tip_revision_column=get_db_column_name(branch_model, DynamicFieldName("tip_revision_sys_id")),
            deleted_column=get_db_column_name(branch_model, DynamicFieldName("deleted")),
        ),
    )
    registrar_obj = cast(Any, registrar)
    return cast(
        ScalarServerRef[BranchId | None],
        registrar_obj.server_ref_from_step(
            str(branch_anchor_ref_id),
            variant="scalar",
            type_hint=BranchId,
        ),
    )


