@pure_lazy
def _graph_result_intent_binding[TGraph: Graph](
    txn: VersionedReadTransactionLazyMixin,
    *,
    graph_id: GraphId,
    graph_type: type[TGraph],
    context_refs: VersionedLazyContextRefs,
    materialization: VersionedLazyMaterializationPolicy,
) -> GraphResultIntentBinding:
    plan_owner: _GraphPlanOwner = txn
    if _readthrough_user_session_delegates_graph_visibility(txn):
        if not isinstance(txn, _GraphVisibilityReadTxn):
            raise TypeError("Read-through graph visibility requires a typed plan owner")
        plan_owner = txn._graph_visibility_plan_owner
    plan = plan_owner._get_transaction_plan_lazy()

    def add_to_owned_plan(step: ServerPlanStep[Any]) -> LazyResult[Any]:
        plan.add_step(step)
        return plan.publish_lazy_result(step.ref_id)

    registrar = graph_lazy_step_registrar(
        next_ref_fn=plan._next_ref,
        add_intent_fn=(add_to_owned_plan if plan_owner is not txn else txn._add_intent),
        plan=plan,
    )
    graph_id_ref = registrar.scalar_ref_for(graph_id)
    domain = _txn_domain(txn)
    if domain is None:
        msg = "Versioned graph visibility requires an explicit versioning domain"
        raise RuntimeError(msg)

    def pending_ctx_config_factory() -> intent_graph._ResolveGraphExecutionCtxConfig:
        revision_literal, revision_ref_id = _graph_revision_input(txn, context_refs)
        branch_anchor_literal, branch_anchor_ref_id = _graph_branch_anchor_input(
            txn,
            context_refs,
            materialization,
        )
        return intent_graph._ResolveGraphExecutionCtxConfig(
            graph_id_ref=graph_id_ref,
            graph_type=graph_type,
            revision_literal=revision_literal,
            revision_ref_id=revision_ref_id,
            branch_anchor_literal=branch_anchor_literal,
            branch_anchor_ref_id=branch_anchor_ref_id,
            prefer_tip_strategy=(
                bool(getattr(txn, "_prefer_tip_strategy", False)) and not _readthrough_user_session_delegates_graph_visibility(txn)
            ),
            tip_materialization=materialization.tip_materialization,
            permission_context_ref=(None if permission_context_ref is None else permission_context_ref.ref_id),
            permission_context_type=(None if permission_input.context_type is ResolvedSessionContext else permission_input.context_type),
            force_application_versioning=bool(getattr(domain, "__nera_ad_hoc_revision_domain__", False)),
            include_staged_working_set=(
                isinstance(txn, VersionedWriteTransactionLazyMixin) and _write_txn_explicit_base_revision_id(txn) is None
            ),
            branch_table=SqlTableName(get_table_name(domain.branch_model)),
            revision_branch_index_table=SqlTableName(get_table_name(domain.revision_branch_index_model)),
        )

    from l7200_versioned_transactions.induced_fragment_adapter import (
        _induced_graph_snapshot_from_observed_facts,
        _observed_prerequisites_lazy,
    )
    from l9700_graph_query.semantic_fragment import GraphSnapshotMaterialization

    branch_anchor = getattr(txn, "_branch_anchor", None)
    if not isinstance(branch_anchor, BranchId):
        branch_anchor = versioned_lazy_context_literal_branch(context_refs)
    revision_id = _transaction_revision_literal(txn) or RevisionId.current()
    if getattr(domain, "__nera_ad_hoc_revision_domain__", False):
        snapshot_materialization = GraphSnapshotMaterialization.APPLICATION
    elif isinstance(txn, VersionedWriteTransactionLazyMixin) and _write_txn_explicit_base_revision_id(txn) is None:
        snapshot_materialization = GraphSnapshotMaterialization.SPARSE
    elif _graph_uses_tip_strategy(
        prefer_tip_strategy=materialization.prefer_tip_strategy,
        has_branch_anchor=branch_anchor is not None,
        materialization=materialization,
    ):
        snapshot_materialization = GraphSnapshotMaterialization.TIP
    else:
        snapshot_materialization = GraphSnapshotMaterialization.SPARSE
    snapshot = _induced_graph_snapshot_from_observed_facts(
        graph_id=graph_id,
        graph_type=graph_type,
        revision_id=revision_id,
        branch_anchor=branch_anchor,
        domain=domain,
        materialization=snapshot_materialization,
        prerequisites_provider=lambda: _observed_prerequisites_lazy(txn),
        include_staged_working_set=(
            isinstance(txn, VersionedWriteTransactionLazyMixin) and _write_txn_explicit_base_revision_id(txn) is None
        ),
    )

    from l4000_permissions.lazy_permission_support import (
        permission_planning_input_for_model,
    )

    permission_input = permission_planning_input_for_model(txn, graph_type)
    permission_context_ref = None if permission_input.context_type is ResolvedSessionContext else permission_input.context_ref
    return GraphResultIntentBinding(
        registrar=registrar,
        pending_ctx_config_factory=pending_ctx_config_factory,
        visibility=intent_graph._GraphResultVisibilityConfig(
            graph_id_ref=graph_id_ref,
            graph_type=graph_type,
            revision_id_ref=_current_revision_source_ref_for(
                txn,
                context="graph result visibility revision context",
            ),
            domain=domain,
            error_message="Graph is not visible in the current versioned read context",
            permission_context_ref=(None if permission_context_ref is None else permission_context_ref.ref_id),
            permission_context_type=(None if permission_input.context_type is ResolvedSessionContext else permission_input.context_type),
        ),
        snapshot=snapshot,
        result_binder=_InducedGraphResultBinder(txn),
    )


@pure_lazy
def _enqueue_graph_visibility_guard[TGraph: Graph[Any]](
    txn: VersionedReadTransactionLazyMixin,
    *,
    graph_id: GraphId,
    graph_type: type[TGraph],
    context_refs: VersionedLazyContextRefs,
    materialization: VersionedLazyMaterializationPolicy,
    context: str,
    reuse_cached: bool = True,
) -> tuple[
    ServerPlanRefId,
    Callable[[], intent_graph._ResolveGraphExecutionCtxConfig],
    GraphLazyStepRegistrar,
    ScalarServerRef[GraphId],
]:
    plan = txn._get_transaction_plan_lazy()
    registrar = graph_lazy_step_registrar(
        next_ref_fn=plan._next_ref,
        add_intent_fn=txn._add_intent,
        plan=plan,
    )
    cache_key = _graph_visibility_guard_cache_key(
        graph_id=graph_id,
        graph_type=graph_type,
        context_refs=context_refs,
        materialization=materialization,
    )
    cached = _graph_visibility_guard_cache(txn).get(cache_key)
    current_plan_identity = id(plan)
    if (
        reuse_cached
        and cached is not None
        and cached[0] == current_plan_identity
        and _graph_visibility_plan_contains_ref(plan, cached[1])
        and (_graph_visibility_plan_contains_ref(plan, cached[2]) or _graph_visibility_plan_contains_ref(plan, cached[3]))
    ):
        (
            _cached_plan_identity,
            cached_validated_ref,
            _cached_source_ref,
            _cached_select_ref,
            cached_pending_ctx_config_factory,
            cached_graph_id_ref,
        ) = cached
        return cached_validated_ref, cached_pending_ctx_config_factory, registrar, cached_graph_id_ref
    if reuse_cached and cached is not None and cached[0] == current_plan_identity:
        _graph_visibility_remove_plan_ref(plan, cached[1])
    graph_id_ref = registrar.scalar_ref_for(graph_id)
    permitted_graph_id_ref: ScalarServerRef[GraphId]
    pending_ctx_config: intent_graph._ResolveGraphExecutionCtxConfig | None = None

    def pending_ctx_config_factory() -> intent_graph._ResolveGraphExecutionCtxConfig:
        nonlocal pending_ctx_config
        if pending_ctx_config is not None:
            return pending_ctx_config
        compile_context = build_versioned_graph_compile_context(
            txn,
            graph_id_ref=graph_id_ref,
            graph_type=graph_type,
        )
        pending_ctx_config = intent_graph._ResolveGraphExecutionCtxConfig(
            graph_id_ref=compile_context.graph_id_ref,
            graph_type=graph_type,
            revision_literal=compile_context.revision_literal,
            revision_ref_id=compile_context.revision_ref_id,
            branch_anchor_literal=compile_context.branch_anchor_literal,
            branch_anchor_ref_id=compile_context.branch_anchor_ref_id,
            prefer_tip_strategy=compile_context.prefer_tip_strategy,
            tip_materialization=compile_context.tip_materialization,
            branch_table=compile_context.branch_table,
            revision_branch_index_table=compile_context.revision_branch_index_table,
            revision_parent_table=compile_context.revision_parent_table,
            tip_materialization_ref_id=compile_context.tip_materialization_ref_id,
            tip_revision_ref_id=compile_context.tip_revision_ref_id,
            predicted_source=compile_context.predicted_source,
            predicted_tip_materialization=compile_context.predicted_tip_materialization,
            route_hint_identity=compile_context.route_hint_identity,
            force_application_versioning=compile_context.force_application_versioning,
            include_staged_working_set=compile_context.include_staged_working_set,
            requires_stable_route_snapshot=compile_context.requires_stable_route_snapshot,
        )
        return pending_ctx_config

    visible_graph_ref_id = ServerPlanRefId(plan._next_ref())
    from l4000_permissions.lazy_permission_support import (
        permission_planning_input_for_model,
    )

    permission_input = permission_planning_input_for_model(txn, graph_type)
    permission_context_ref = None if permission_input.context_type is ResolvedSessionContext else permission_input.context_ref
    graph_domain = _txn_domain(txn)
    if graph_domain is None:
        msg = "Versioned graph visibility requires an explicit versioning domain"
        raise RuntimeError(msg)
    visibility_compile_context = _build_graph_compile_context(pending_ctx_config_factory)
    pending_ctx_config = replace(
        pending_ctx_config_factory(),
        predicted_source=visibility_compile_context.predicted_source,
        predicted_tip_materialization=visibility_compile_context.predicted_tip_materialization,
        route_hint_identity=visibility_compile_context.route_hint_identity,
        permission_context_ref=(None if permission_context_ref is None else permission_context_ref.ref_id),
        permission_context_type=(None if permission_input.context_type is ResolvedSessionContext else permission_input.context_type),
    )
    visibility_revision_ref = (
        ServerRefs.scalar(visibility_compile_context.revision_literal)
        if isinstance(visibility_compile_context.revision_literal, RevisionId)
        else (
            ServerRefs.from_ref_id(
                visibility_compile_context.revision_ref_id,
                variant="scalar",
                type_hint=RevisionId,
            )
            if visibility_compile_context.revision_ref_id is not None
            else _current_revision_source_ref_for(
                txn,
                context="graph visibility revision context",
            )
        )
    )
    visibility_branch_ref = (
        ServerRefs.scalar(visibility_compile_context.branch_anchor_literal)
        if isinstance(visibility_compile_context.branch_anchor_literal, BranchId)
        else (
            ServerRefs.from_ref_id(
                visibility_compile_context.branch_anchor_ref_id,
                variant="scalar",
                type_hint=BranchId,
            )
            if visibility_compile_context.branch_anchor_ref_id is not None
            else None
        )
    )
    plan.add_step(
        intent_versioning_extended.VersionedSelectOneIntent(
            visible_graph_ref_id,
            model_cls=graph_type,
            config=ServerRefs.scalar(
                intent_versioning_extended._VersionedSelectOneConfig(
                    sys_id=ServerRefs.scalar(graph_id),
                    revision_id=visibility_revision_ref,
                    domain=graph_domain,
                    branch_id=visibility_branch_ref,
                    include_deleted=False,
                    preferred_source=visibility_compile_context.predicted_source,
                    permission_context_ref=(None if permission_context_ref is None else permission_context_ref.ref_id),
                    permission_context_type=(
                        None if permission_input.context_type is ResolvedSessionContext else permission_input.context_type
                    ),
                ),
            ),
        ),
    )
    visible_graph = cast("LazyResult[TGraph | None]", txn._add_intent_by_ref(visible_graph_ref_id))
    visible_graph_ref = _require_step_ref_id(
        visible_graph,
        context=context,
    )
    visible_graph_raw_rows_ref = ServerPlanRefId(f"{visible_graph_ref}.raw_rows")
    permitted_graph_id_ref = ServerRefs.from_ref_id(
        ServerPlanRefId(f"{visible_graph_raw_rows_ref}.sys_id"),
        variant="scalar",
        type_hint=GraphId,
    )
    validated_ref = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        RequirePermittedRowStep(
            validated_ref,
            config=_RequirePermittedRowConfig(
                source_ref=visible_graph_raw_rows_ref,
                error_message="Graph is not visible in the current versioned read context",
            ),
        ),
    )
    if reuse_cached:
        _graph_visibility_guard_cache(txn)[cache_key] = (
            current_plan_identity,
            validated_ref,
            visible_graph_raw_rows_ref,
            visible_graph_ref,
            pending_ctx_config_factory,
            permitted_graph_id_ref,
        )
    return validated_ref, pending_ctx_config_factory, registrar, permitted_graph_id_ref


@pure_lazy
def _readthrough_user_session_delegates_graph_visibility(
    txn: object,
) -> bool:
    if not isinstance(txn, _GraphVisibilityReadTxn):
        return False
    if not txn.delegates_graph_visibility_to_remote:
        return False
    session_id = txn.session_id
    return not (session_id.is_schema_session())


@pure_lazy
def _published_lazy_ref_id(value: object, *, context: str) -> str | None:
    if not isinstance(value, LazyResult):
        return None
    shape = inspect_server_value_shape_for_planning(
        value,
        site=context,
    )
    return None if shape.symbolic_ref_id is None else str(shape.symbolic_ref_id)


