def _optional_database_object_model(
    value: object,
) -> type[DatabaseObjectRow] | None:
    """Narrow immutable model metadata without consulting transaction state."""
    if value is None:
        return None
    assert isinstance(value, type)
    assert issubclass(value, DatabaseObjectRow)
    return value


@pure_lazy
def _table_name_set(value: object | None) -> set[SqlTableName] | None:
    """Brand supplied table identities without schema or connection access."""
    if value is None:
        return None
    if not isinstance(value, list | tuple | set | frozenset):
        raise TypeError("Speculative table names must be a finite collection")
    table_names: set[SqlTableName] = set()
    for item in value:
        if not isinstance(item, str):
            raise TypeError("Speculative table names must be strings")
        table_names.add(SqlTableName(item))
    return table_names


