    deleted_tables: frozenset[SqlTableName] = frozenset()
    staged_commit_ids: frozenset[StagedCommitId] = frozenset()
    named_branch_scopes: frozenset[_NamedSpeculativeBranchScope] = frozenset()

    @property
    def insert_only_tables(self: _ConnectionSpeculativePublishFacts) -> frozenset[SqlTableName]:
        return self.touched_tables - self.non_insert_tables - self.deleted_tables

    def merged_with(
        self: _ConnectionSpeculativePublishFacts,
        other: _ConnectionSpeculativePublishFacts,
    ) -> _ConnectionSpeculativePublishFacts:
        return _ConnectionSpeculativePublishFacts(
            touched_tables=self.touched_tables | other.touched_tables,
            non_insert_tables=self.non_insert_tables | other.non_insert_tables,
            deleted_tables=self.deleted_tables | other.deleted_tables,
            staged_commit_ids=self.staged_commit_ids | other.staged_commit_ids,
