def _require_connection_speculative_publish_facts_lazy(
    value: object,
    *,
    lifecycle: Literal["durable", "pending"],
    validate_entries: bool = True,
) -> dict[_ConnectionSpeculativePublishKey, _ConnectionSpeculativePublishFacts]:
    if not isinstance(value, dict):
        msg = f"Missing {lifecycle} speculative publication fact ledger"
        raise TypeError(msg)
    if not validate_entries:
        return value
    for key, facts in value.items():
        if not isinstance(key, _ConnectionSpeculativePublishKey) or not isinstance(
            facts,
            _ConnectionSpeculativePublishFacts,
        ):
            msg = f"Invalid {lifecycle} speculative publication fact for key {key!r}"
            raise TypeError(msg)
        if not isinstance(key.prefix.domain_name, _VersioningDomainName):
            msg = f"Invalid {lifecycle} speculative publication domain identity"
            raise TypeError(msg)
        valid_branch = isinstance(key.prefix.branch_id, BranchId) or (
            lifecycle == "pending" and isinstance(key.prefix.branch_id, BranchScopeToken)
        )
        if not valid_branch or not isinstance(
            key.prefix.connection_id,
            ConnectionId,
        ):
            msg = f"Invalid {lifecycle} speculative publication scope identity"
            raise TypeError(msg)
        if not isinstance(key.staged_commit_id, StagedCommitId):
            msg = f"Invalid {lifecycle} speculative publication staged-commit identity"
            raise TypeError(msg)
        if any(
            not isinstance(scope, _NamedSpeculativeBranchScope)
            or not isinstance(scope.branch_name, BranchName)
            or not isinstance(scope.workspace_id, WorkspaceId)
            for scope in facts.named_branch_scopes
        ):
            raise TypeError("Invalid speculative publication named branch locator")
        if any(not isinstance(table_name, SqlTableName) for table_name in facts.touched_tables):
            msg = f"Invalid {lifecycle} speculative publication touched-table identity"
            raise TypeError(msg)
        if any(not isinstance(table_name, SqlTableName) for table_name in facts.non_insert_tables):
            msg = f"Invalid {lifecycle} speculative publication non-insert table identity"
            raise TypeError(msg)
        if any(not isinstance(table_name, SqlTableName) for table_name in facts.deleted_tables):
            msg = f"Invalid {lifecycle} speculative publication deleted-table identity"
            raise TypeError(msg)
        if any(not isinstance(staged_id, StagedCommitId) for staged_id in facts.staged_commit_ids):
            msg = f"Invalid {lifecycle} speculative publication staged scope"
            raise TypeError(msg)
        value[key] = _ConnectionSpeculativePublishFacts(
            touched_tables=frozenset(facts.touched_tables),
            non_insert_tables=frozenset(facts.non_insert_tables),
            deleted_tables=frozenset(facts.deleted_tables),
            staged_commit_ids=frozenset(facts.staged_commit_ids),
            named_branch_scopes=frozenset(facts.named_branch_scopes),
        )
    return value


class _ConnectionSpeculativePublishFactStore:
    """Transaction-owned interface over connection-shared publication hints."""

    __slots__ = ("_durable", "_pending")

    def __init__(
        self: _ConnectionSpeculativePublishFactStore,
        durable: dict[object, object],
        pending: dict[object, object],
    ) -> None:
        self._durable = _require_connection_speculative_publish_facts_lazy(
            durable,
            lifecycle="durable",
        )
        self._pending = _require_connection_speculative_publish_facts_lazy(
            pending,
            lifecycle="pending",
        )

    @classmethod
    def from_owned_ledgers(
        cls,
        durable: dict[object, object],
        pending: dict[object, object],
    ) -> _ConnectionSpeculativePublishFactStore:
        """Attach connection-owned ledgers without rescanning prior typed facts."""
        store = cls.__new__(cls)
        store._durable = _require_connection_speculative_publish_facts_lazy(
            durable,
            lifecycle="durable",
            validate_entries=False,
        )
        store._pending = _require_connection_speculative_publish_facts_lazy(
            pending,
            lifecycle="pending",
            validate_entries=False,
        )
        return store

    def snapshot(
        self: _ConnectionSpeculativePublishFactStore,
        *,
        lifecycle: Literal["durable", "pending"],
    ) -> tuple[tuple[_ConnectionSpeculativePublishKey, _ConnectionSpeculativePublishFacts], ...]:
        source = self._durable if lifecycle == "durable" else self._pending
        return tuple(source.items())

    def all_snapshots(
        self: _ConnectionSpeculativePublishFactStore,
    ) -> tuple[tuple[_ConnectionSpeculativePublishKey, _ConnectionSpeculativePublishFacts], ...]:
        return (*self.snapshot(lifecycle="durable"), *self.snapshot(lifecycle="pending"))

    def record(
        self: _ConnectionSpeculativePublishFactStore,
        key: _ConnectionSpeculativePublishKey,
        *,
        table_name: SqlTableName,
        operation: _ConnectionSpeculativeOperation | None,
        named_scope: _NamedSpeculativeBranchScope | None,
        insert_only_downgraded: bool,
    ) -> None:
        existing = self._pending.get(key, _ConnectionSpeculativePublishFacts())
        table_names = frozenset({SqlTableName(table_name)})
        self._pending[key] = existing.merged_with(
            _ConnectionSpeculativePublishFacts(
                touched_tables=table_names,
                non_insert_tables=(frozenset() if operation == "insert" and not insert_only_downgraded else table_names),
                deleted_tables=(table_names if operation == "delete" else frozenset()),
                staged_commit_ids=frozenset({key.staged_commit_id}),
                named_branch_scopes=(frozenset() if named_scope is None else frozenset({named_scope})),
            ),
        )

    def promote(
        self: _ConnectionSpeculativePublishFactStore,
        *,
        staged_commit_id: StagedCommitId | None,
        resolved_branch: BranchId | ScalarServerRef[BranchId] | None,
    ) -> None:
        owned = tuple((key, facts) for key, facts in self._pending.items() if key.staged_commit_id == staged_commit_id)
        if any(not isinstance(key.prefix.branch_id, BranchId) for key, _facts in owned) and not isinstance(resolved_branch, BranchId):
            raise TypeError("Committed publication facts require a resolved branch ID")
        for key, facts in owned:
            durable_key = key
            if not isinstance(key.prefix.branch_id, BranchId):
                assert isinstance(resolved_branch, BranchId)
                durable_key = _ConnectionSpeculativePublishKey(
                    _ConnectionSpeculativePublishPrefix(
                        key.prefix.domain_name,
                        resolved_branch,
                        key.prefix.connection_id,
                    ),
                    key.staged_commit_id,
                )
            self._durable[durable_key] = self._durable.get(
                durable_key,
                _ConnectionSpeculativePublishFacts(),
            ).merged_with(facts)
            self._pending.pop(key)

    def discard_pending(
        self: _ConnectionSpeculativePublishFactStore,
        *,
        staged_commit_id: StagedCommitId | None,
    ) -> None:
        for key in tuple(self._pending):
            if key.staged_commit_id == staged_commit_id:
                self._pending.pop(key)

    def discard(
        self: _ConnectionSpeculativePublishFactStore,
        *,
        keys: frozenset[_ConnectionSpeculativePublishKey],
    ) -> None:
        for source in (self._durable, self._pending):
            for key in keys:
                source.pop(key, None)

    def replace(
        self: _ConnectionSpeculativePublishFactStore,
        *,
        selected_staged_commit_ids: frozenset[StagedCommitId],
        touched_table_names: frozenset[SqlTableName],
        non_insert_table_names: frozenset[SqlTableName],
        deleted_table_names: frozenset[SqlTableName],
    ) -> None:
        for source in (self._durable, self._pending):
            for key, previous in tuple(source.items()):
                if key.staged_commit_id not in selected_staged_commit_ids:
                    continue
                source[key] = _ConnectionSpeculativePublishFacts(
                    touched_tables=touched_table_names,
                    non_insert_tables=non_insert_table_names,
                    deleted_tables=deleted_table_names,
                    staged_commit_ids=frozenset({key.staged_commit_id}),
                    named_branch_scopes=previous.named_branch_scopes,
                )

    def record_missing(
        self: _ConnectionSpeculativePublishFactStore,
        *,
        prefix: _ConnectionSpeculativePublishPrefix | None,
        selected_staged_commit_ids: frozenset[StagedCommitId],
        touched_table_names: frozenset[SqlTableName],
        non_insert_table_names: frozenset[SqlTableName],
        deleted_table_names: frozenset[SqlTableName],
        named_scope: _NamedSpeculativeBranchScope | None,
    ) -> None:
        known_ids = {
            key.staged_commit_id
            for source in (self._durable, self._pending)
            for key in source
            if key.staged_commit_id in selected_staged_commit_ids
        }
        missing_ids = selected_staged_commit_ids - known_ids
        if not missing_ids:
            return
        if prefix is None or not isinstance(prefix.branch_id, BranchId):
            raise RuntimeError("Authoritative publication facts require a concrete branch scope")
        named_scopes = frozenset() if named_scope is None else frozenset({named_scope})
        for staged_commit_id in missing_ids:
            self._durable[_ConnectionSpeculativePublishKey(prefix, staged_commit_id)] = _ConnectionSpeculativePublishFacts(
                touched_tables=touched_table_names,
                non_insert_tables=non_insert_table_names,
                deleted_tables=deleted_table_names,
                staged_commit_ids=frozenset({staged_commit_id}),
                named_branch_scopes=named_scopes,
            )

    def has_pending_symbolic_scope(
        self: _ConnectionSpeculativePublishFactStore,
        staged_commit_id: StagedCommitId | None,
    ) -> bool:
        return any(key.staged_commit_id == staged_commit_id and not isinstance(key.prefix.branch_id, BranchId) for key in self._pending)


def _require_authoritative_speculative_fact_sets_lazy(
    selected_staged_commit_ids: tuple[StagedCommitId, ...],
    *,
    touched_table_names: frozenset[SqlTableName],
    non_insert_table_names: frozenset[SqlTableName],
    deleted_table_names: frozenset[SqlTableName],
) -> frozenset[StagedCommitId]:
    selected_ids = frozenset(selected_staged_commit_ids)
    if not selected_ids:
        raise ValueError("Authoritative publication facts require a selected staged scope")
    if any(not isinstance(staged_id, StagedCommitId) for staged_id in selected_ids):
        raise TypeError("Authoritative publication facts require typed staged-commit identities")
    if any(not isinstance(table_name, SqlTableName) for table_name in touched_table_names):
        raise TypeError("Authoritative publication facts require typed touched-table identities")
    if any(not isinstance(table_name, SqlTableName) for table_name in non_insert_table_names):
        raise TypeError("Authoritative publication facts require typed non-insert table identities")
    if any(not isinstance(table_name, SqlTableName) for table_name in deleted_table_names):
        raise TypeError("Authoritative publication facts require typed deleted-table identities")
    if not non_insert_table_names <= touched_table_names:
        raise ValueError("Authoritative non-insert facts must be a subset of touched tables")
    if not deleted_table_names <= non_insert_table_names:
        raise ValueError("Authoritative tombstone facts must be a subset of non-insert tables")
    return selected_ids


type _ConnectionSpeculativeOperation = Literal["insert", "update", "delete"]
type _GraphVisibilityContextKey = tuple[str, str | None]
type _GraphVisibilityGuardCacheKey = tuple[
    str,
    type[Graph[Any]],
    _GraphVisibilityContextKey,
    _GraphVisibilityContextKey,
    _GraphVisibilityContextKey,
    BranchTipMaterialization,
    BranchPointMaterialization | None,
    bool,
]
type _GraphVisibilityGuardCacheValue = tuple[
    int,
    ServerPlanRefId,
    ServerPlanRefId,
    ServerPlanRefId,
    Callable[[], intent_graph._ResolveGraphExecutionCtxConfig],
    ScalarServerRef[GraphId],
]


@pure_lazy
def _graph_visibility_context_key(value: object | None) -> _GraphVisibilityContextKey:
    if value is None:
        return ("none", None)
    if isinstance(value, ScalarServerRef):
        return ("ref", None if value.ref_id is None else str(value.ref_id))
    return (type(value).__qualname__, str(value))


@pure_lazy
def _graph_visibility_guard_cache_key(
    *,
    graph_id: GraphId,
    graph_type: type[Graph[Any]],
    context_refs: VersionedLazyContextRefs,
    materialization: VersionedLazyMaterializationPolicy,
) -> _GraphVisibilityGuardCacheKey:
    return (
        str(graph_id),
        graph_type,
        _graph_visibility_context_key(context_refs.branch),
        _graph_visibility_context_key(context_refs.revision),
        _graph_visibility_context_key(context_refs.workspace),
        materialization.tip_materialization,
        materialization.branchpoint_materialization,
        materialization.prefer_tip_strategy,
    )


@pure_lazy
def _graph_visibility_guard_cache(
    txn: object,
) -> dict[_GraphVisibilityGuardCacheKey, _GraphVisibilityGuardCacheValue]:
    raw_cache = getattr(txn, "_graph_visibility_guard_cache", None)
    if isinstance(raw_cache, dict):
        return cast("dict[_GraphVisibilityGuardCacheKey, _GraphVisibilityGuardCacheValue]", raw_cache)
    cache: dict[_GraphVisibilityGuardCacheKey, _GraphVisibilityGuardCacheValue] = {}
    object.__setattr__(txn, "_graph_visibility_guard_cache", cache)
    return cache


@pure_lazy
def _graph_visibility_plan_contains_ref(plan: object, ref_id: ServerPlanRefId) -> bool:
    raw_steps = getattr(plan, "_steps", None)
    if raw_steps is None:
        raw_steps = getattr(plan, "steps", ())
    if not isinstance(raw_steps, list | tuple):
        return False
    return any(str(getattr(step, "ref_id", "")) == str(ref_id) for step in raw_steps)


@pure_lazy
def _graph_visibility_remove_plan_ref(plan: object, ref_id: ServerPlanRefId) -> None:
    raw_steps = getattr(plan, "_steps", None)
    attr_name = "_steps"
    if raw_steps is None:
        raw_steps = getattr(plan, "steps", None)
        attr_name = "steps"
    if not isinstance(raw_steps, list):
        return
    raw_steps[:] = [step for step in raw_steps if str(getattr(step, "ref_id", "")) != str(ref_id)]
    if getattr(plan, attr_name, raw_steps) is not raw_steps:
        object.__setattr__(plan, attr_name, raw_steps)


@pure_lazy
def _versioned_lazy_materialization_policy(txn: object) -> VersionedLazyMaterializationPolicy:
    from l7000_versioned_schema.branch_materialization import (
        resolve_branch_tip_materialization_for_tests,
        resolve_branchpoint_materialization_for_tests,
    )

    raw_tip_materialization = getattr(txn, "_branch_tip_materialization", BranchTipMaterialization.MATERIALIZED)
    tip_materialization = (
        raw_tip_materialization
        if isinstance(raw_tip_materialization, BranchTipMaterialization)
        else BranchTipMaterialization.MATERIALIZED
    )
    raw_branchpoint_materialization = getattr(txn, "_branchpoint_materialization", None)
    branchpoint_materialization = (
        raw_branchpoint_materialization if isinstance(raw_branchpoint_materialization, BranchPointMaterialization) else None
    )
    tip_materialization = resolve_branch_tip_materialization_for_tests(tip_materialization)
    if branchpoint_materialization is not None:
        branchpoint_materialization = resolve_branchpoint_materialization_for_tests(branchpoint_materialization)
    return VersionedLazyMaterializationPolicy(
        tip_materialization=tip_materialization,
        branchpoint_materialization=branchpoint_materialization,
        prefer_tip_strategy=bool(getattr(txn, "_prefer_tip_strategy", False)),
    )


@pure_lazy
def _graph_uses_tip_strategy(
    *,
    prefer_tip_strategy: bool,
    has_branch_anchor: bool,
    materialization: VersionedLazyMaterializationPolicy,
) -> bool:
    return prefer_tip_strategy and has_branch_anchor and materialization.tip_materialization is BranchTipMaterialization.MATERIALIZED


