        versioned_query_steps.VersionedResolveTypeMapStep(
            rows_ref,
            _build_versioned_resolve_type_map_config(resolve_input),
        ),
    )
    return txn._add_intent(
        VersionedTypeNameMapStep(
            ServerPlanRefId(plan._next_ref()),
