@pure_lazy
def _initial_publication_epoch(txn: object) -> PublicationEpoch:
    lazy_revision = getattr(txn, "_lazy_revision", None)
    branch_scope = str(getattr(txn, "_branch_scope_token", "branch:unknown"))
    lazy_revision_ref = _published_lazy_ref_id(
        lazy_revision,
        context="initial publication epoch base revision",
    )
    if lazy_revision_ref is not None:
        base_revision_ref = ServerPlanRefId(lazy_revision_ref)
    else:
        base_revision_id = getattr(txn, "_base_revision_id", None)
        if base_revision_id is None and isinstance(lazy_revision, LazyResult):
            shape = inspect_server_value_shape_for_planning(
                lazy_revision,
                site="initial publication epoch base revision",
            )
            if shape.has_literal_value:
                base_revision_id = shape.literal_value
        base_revision_ref = ServerPlanRefId(
            f"revision:{base_revision_id}" if base_revision_id is not None else f"initial_revision:{branch_scope}"
        )
    staged_commit_id = str(getattr(txn, "_staged_commit_id", "unallocated"))
    return PublicationEpoch(
        epoch_id=PublicationEpochId(f"initial:{branch_scope}:{staged_commit_id}"),
        base_revision_ref=base_revision_ref,
        predecessor_publication_ref=None,
        frontier=VersionedCommitEffectFrontier(()),
    )


@pure_lazy
def _require_active_publication_epoch(txn: object) -> PublicationEpoch:
    epoch = getattr(txn, "_active_publication_epoch", None)
    if epoch is None:
        epoch = _initial_publication_epoch(txn)
        object.__setattr__(txn, "_active_publication_epoch", epoch)
    if not isinstance(epoch, PublicationEpoch):
        msg = "versioned.publication_epoch.complete: transaction epoch must use PublicationEpoch."
        raise TypeError(msg)
    return epoch


@pure_lazy
def _current_versioned_write_tail_refs(
    txn: object,
    *,
    plan: object | None = None,
) -> frozenset[ServerPlanRefId]:
    epoch = _require_active_publication_epoch(txn)
    if plan is None:
        return epoch.ordering_refs
    _require_versioned_publication_state(txn, plan=plan)
    producer_step = getattr(plan, "producer_step", None)
    if not callable(producer_step):
        return frozenset()
    live_effects_by_physical_ref = {effect.physical_effect_ref: effect for effect in _plan_owned_commit_effects(plan, epoch.frontier)}
    ordering_refs: set[ServerPlanRefId] = set()
    for ref in epoch.ordering_refs:
        if producer_step(ref) is not None:
            ordering_refs.add(ref)
            continue
        effect = live_effects_by_physical_ref.get(ref)
        if effect is not None:
            ordering_refs.add(effect.physical_effect_ref)
    return frozenset(ordering_refs)


@pure_lazy
def _versioned_commit_effect_for_step(step: object) -> VersionedCommitEffect | None:
    delegates_probe = getattr(step, "delegates_versioned_commit_effects", None)
    if callable(delegates_probe) and delegates_probe():
        return None
    if getattr(step, "versioned_commit_effect_owner", False) is not True:
        return None
    effect_ref_probe = getattr(step, "commit_dependency_ref_id", None)
    tables_written_probe = getattr(step, "tables_written", None)
    dependencies_probe = getattr(step, "dependencies", None)
    semantic_ref = getattr(step, "ref_id", None)
    if (
        not callable(effect_ref_probe)
        or not callable(tables_written_probe)
        or not callable(dependencies_probe)
        or not isinstance(semantic_ref, str)
    ):
        msg = "versioned.commit_effect.complete: effect owner must declare exact tables and dependencies."
        raise TypeError(msg)
    staged_tables = tuple(sorted(str(table) for table in cast("Iterable[object]", tables_written_probe())))
    if not staged_tables:
        return None
    effect_ref = effect_ref_probe()
    if not isinstance(effect_ref, str):
        msg = "versioned.commit_effect.complete: staged producer effect ref must be typed."
        raise TypeError(msg)
    cardinality_probe = getattr(step, "staged_row_cardinality", None)
    cardinality = cardinality_probe() if callable(cardinality_probe) else StagedRowCardinality.MAY_BE_EMPTY
    staged_commit_ids_probe = getattr(step, "staged_commit_ids_for_effect", None)
    staged_commit_ids = (
        tuple(str(staged_commit_id) for staged_commit_id in cast("Iterable[object]", staged_commit_ids_probe()))
        if callable(staged_commit_ids_probe)
        else ()
    )
    if not isinstance(cardinality, StagedRowCardinality):
        msg = "versioned.commit_effect.complete: staged producer cardinality must be typed."
        raise TypeError(msg)
    return VersionedCommitEffect(
        semantic_ref=ServerPlanRefId(semantic_ref),
        physical_effect_ref=ServerPlanRefId(effect_ref),
        staged_table=staged_tables[0],
        predecessor_refs=tuple(
            sorted(ServerPlanRefId(str(ref)) for ref in cast("Iterable[object]", dependencies_probe())),
        ),
        cardinality=cardinality,
        additional_staged_tables=staged_tables[1:],
        staged_commit_ids=staged_commit_ids,
    )


@pure_lazy
def _record_publication_epoch_write(
    txn: object,
    *,
    semantic_ref: ServerPlanRefId,
    ordering_ref: ServerPlanRefId,
) -> None:
    get_plan = getattr(txn, "_get_transaction_plan_lazy", None)
    if not callable(get_plan):
        msg = "versioned.publication_epoch.complete: transaction must expose its semantic plan."
        raise TypeError(msg)
    plan = cast(Any, get_plan())
    closure = plan.producer_dependency_closure(frozenset({semantic_ref})) | frozenset({semantic_ref})
    epoch = _require_active_publication_epoch(txn)
    effects = tuple(
        effect
        for ref in closure
        if (producer := plan.producer_step(ref)) is not None
        if (effect := _versioned_commit_effect_for_step(producer)) is not None
        if (epoch.predecessor_publication_ref is None or epoch.predecessor_publication_ref in effect.predecessor_refs)
    )
    epoch = epoch.with_effects(
        effects,
        ordering_refs=frozenset({ordering_ref}),
    )
    object.__setattr__(txn, "_active_publication_epoch", epoch)


@pure_lazy
def _record_versioned_write_tail[T](
    txn: object,
    lazy_result: LazyResult[T],
    *,
    context: str,
) -> LazyResult[T]:
    semantic_ref = _require_step_ref_id(lazy_result, context=context)
    commit_dependency_ref_id = getattr(lazy_result, "_commit_dependency_ref_id", None)
    ordering_ref = (
        ServerPlanRefId(commit_dependency_ref_id)
        if isinstance(commit_dependency_ref_id, str) and commit_dependency_ref_id
        else semantic_ref
    )
    _record_publication_epoch_write(
        txn,
        semantic_ref=semantic_ref,
        ordering_ref=ordering_ref,
    )
    return lazy_result


@pure_lazy
def _record_versioned_write_tail_ref[T](
    txn: object,
    ref: ObjectServerRef[T] | ScalarServerRef[T],
) -> ObjectServerRef[T] | ScalarServerRef[T]:
    shape = inspect_server_value_shape_for_planning(ref, site="versioned write dependency ref")
    if shape.symbolic_ref_id is None:
        msg = "Versioned write dependency ref must carry a symbolic plan ref"
        raise RuntimeError(msg)
    semantic_ref = ServerPlanRefId(shape.symbolic_ref_id)
    plan = cast(Any, txn)._get_transaction_plan_lazy()
    producing_step = plan.producer_step(semantic_ref)
    commit_dependency_ref = getattr(producing_step, "commit_dependency_ref_id", None)
    raw_dependency_ref = commit_dependency_ref() if callable(commit_dependency_ref) else semantic_ref
    ordering_ref = ServerPlanRefId(raw_dependency_ref) if isinstance(raw_dependency_ref, str) else semantic_ref
    _record_publication_epoch_write(
        txn,
        semantic_ref=semantic_ref,
        ordering_ref=ordering_ref,
    )
    return ref


@pure_lazy
def _domain_versioned_table_names(domain: type[VersioningDomain]) -> frozenset[SqlTableName]:
    return frozenset(get_table_name(model) for model in domain.all_versioned_models())


@pure_lazy
def _txn_domain_versioned_table_names(txn: _VersionedWriteTxnState) -> frozenset[SqlTableName]:
    domain = txn.domain
    cached = getattr(txn, "_domain_versioned_table_names", None)
    cached_domain = getattr(txn, "_domain_versioned_table_names_domain", None)
    if isinstance(cached, frozenset) and cached_domain is domain:
        return cast("frozenset[SqlTableName]", cached)
    table_names: set[SqlTableName] = set()
    for model in domain.all_versioned_models():
        try:
            table_names.add(get_table_name(model))
        except AttributeError:
            continue
    result = frozenset(table_names)
    setattr(txn, "_domain_versioned_table_names", result)
    setattr(txn, "_domain_versioned_table_names_domain", domain)
    return result


@pure_lazy
def _validate_concrete_graph_edge_self_loop(
    model_cls: type[DatabaseObjectRow[SysId]],
    instance: DatabaseObjectRow[SysId],
) -> None:
    from l1100_exceptions.exceptions import IntegrityError
    from l9600_graphs.edge_constraints import should_add_self_loop_check
    from l9600_graphs.graph import GraphEdge

    if not issubclass(model_cls, GraphEdge) or not should_add_self_loop_check(model_cls):
        return
    assert isinstance(instance, GraphEdge)
    if instance.source_sys_id == instance.target_sys_id:
        table_name = get_table_name(model_cls)
        raise IntegrityError(
            f"Self-loop CHECK constraint failed for '{table_name}'.source_sys_id: {instance.source_sys_id}",
        )


@pure_lazy
def _require_versioned_model_in_domain(
    txn: _VersionedWriteTxnState,
    model_cls: type[DatabaseObjectRow[SysId]],
    *,
    operation: str,
) -> None:
    table_name = get_table_name(model_cls)
    if table_name in _txn_domain_versioned_table_names(txn):
        return
    model_name = f"{model_cls.__module__}.{model_cls.__qualname__}"
    domain_name = getattr(txn.domain, "__name__", repr(txn.domain))
    msg = (
        f"{operation} cannot stage versioned write for model {model_name} "
        f"(table {table_name!r}) because that table is not part of VersioningDomain "
        f"{domain_name}. Add the model to the domain graph/versioned model set, "
        "or write it through a non-versioned transaction."
    )
    raise db_exc.ProgrammingError(msg)


@pure_lazy
def _require_touched_tables_in_domain(
    txn: _VersionedWriteTxnState,
    touched_tables: Iterable[SqlTableName],
    *,
    operation: str,
) -> None:
    domain_tables = _txn_domain_versioned_table_names(txn)
    missing = tuple(sorted(table_name for table_name in touched_tables if table_name not in domain_tables))
    if not missing:
        return
    domain_name = getattr(txn.domain, "__name__", repr(txn.domain))
    msg = (
        f"{operation} cannot publish staged versioned writes for tables not in "
        f"VersioningDomain {domain_name}: {', '.join(missing)}. Add the model(s) "
        "to the domain graph/versioned model set, or write them through a "
        "non-versioned transaction."
    )
    raise db_exc.ProgrammingError(msg)


@pure_lazy
def _require_versioned_publication_state(
    txn: object,
    *,
    plan: object,
) -> tuple[ServerPlanRefId, ScalarServerRef[RevisionId]] | None:
    """Validate and return the boundary owned by the immutable active epoch."""
    active_epoch = _require_active_publication_epoch(txn)
    publication_ref = active_epoch.predecessor_publication_ref
    if publication_ref is None:
        return None
    if publication_ref not in active_epoch.ordering_refs:
        msg = f"versioned.publication_epoch.successor_ordered: active epoch lost its publication boundary {publication_ref!r}."
        raise ValueError(msg)
    producer_step = getattr(plan, "producer_step", None)
    publication = producer_step(publication_ref) if callable(producer_step) else None
    if publication is None:
        msg = (
            "versioned.publication_state.boundary_owned: active epoch publication boundary "
            f"is not owned by this plan; boundary={publication_ref!r}."
        )
        raise ValueError(msg)
    owned_revision_ref = getattr(publication, "new_revision_ref", None)
    if not isinstance(owned_revision_ref, ScalarServerRef):
        msg = (
            "versioned.publication_state.boundary_owned: latest publication must own a "
            f"ScalarServerRef revision value; boundary={publication_ref!r}."
        )
        raise ValueError(msg)
    owned_shape = inspect_server_value_shape_for_planning(
        owned_revision_ref,
        site="publication state owned revision",
    )
    owned_literal = owned_shape.literal_value
    unwrap_owned_literal = getattr(owned_literal, "unwrap_to_str", None)
    owned_identity = (
        ServerPlanRefId(owned_shape.symbolic_ref_id)
        if owned_shape.symbolic_ref_id is not None
        else ServerPlanRefId(
            f"revision:{unwrap_owned_literal() if callable(unwrap_owned_literal) else owned_literal}",
        )
    )
    if owned_identity != active_epoch.base_revision_ref:
        msg = (
            "versioned.publication_state.boundary_owned: epoch base revision must be the "
            f"exact value owned by publication {publication_ref!r}; "
            f"epoch={active_epoch.base_revision_ref!r} owned={owned_identity!r}."
        )
        raise ValueError(msg)
    return publication_ref, owned_revision_ref


@pure_lazy
def _plan_owned_commit_effects(
    plan: object,
    frontier: VersionedCommitEffectFrontier,
) -> tuple[VersionedCommitEffect, ...]:
    """Return effects whose semantic producers remain in this execution slice."""
    producer_step = getattr(plan, "producer_step", None)
    if not callable(producer_step):
        return ()
    owned: list[VersionedCommitEffect] = []
    for effect in frontier.effects:
        producer = producer_step(effect.semantic_ref)
        if producer is not None and _versioned_commit_effect_for_step(producer) == effect:
            owned.append(effect)
    return tuple(owned)


@pure_lazy
def _versioned_publish_dependencies(
    plan: object,
    dependencies: Iterable[ServerPlanRefId],
    *,
    always_keep: Iterable[ServerPlanRefId],
    future_physical_effect_refs: Iterable[ServerPlanRefId],
) -> frozenset[ServerPlanRefId]:
    keep = {ServerPlanRefId(ref) for ref in always_keep}
    future_effects = {ServerPlanRefId(ref) for ref in future_physical_effect_refs}
    steps_by_ref = {str(step.ref_id): step for step in getattr(plan, "_steps", ())}
    filtered: set[ServerPlanRefId] = set()
    for ref in dependencies:
        normalized = ServerPlanRefId(ref)
        # Physical effect refs are calculated by semantic producers before lowering and
        # therefore need not be top-level semantic step ids. See
        # docs/design/VERSIONED_COMMIT_EFFECT_FRONTIER.rst.
        if normalized in future_effects:
            filtered.add(normalized)
            continue
        normalized_text = str(normalized)
        physical_parent_ref = next(
            (normalized_text.removesuffix(suffix) for suffix in (".write", ".raw", "_insert_batch") if normalized_text.endswith(suffix)),
            normalized_text,
        )
        if normalized in keep and (normalized_text in steps_by_ref or physical_parent_ref in steps_by_ref):
            filtered.add(normalized)
            continue
        step = steps_by_ref.get(str(normalized))
        if step is None:
            continue
        step_tags = getattr(step, "step_tags", None)
        tags = cast("frozenset[str]", step_tags()) if callable(step_tags) else frozenset()
        if tags >= {"versioned", "raw", "bulk"}:
            continue
        if "versioned" in tags:
            filtered.add(normalized)
            continue
        if isinstance(step, StaticValueAfterDepsIntent):
            continue
        if _is_terminal_projection_step_tags(tags):
            continue
        is_read_only = getattr(step, "is_read_only", None)
        if callable(is_read_only) and is_read_only():
            filtered.add(normalized)
    return frozenset(filtered)


@pure_lazy
def _default_diff_to_revision_input(
    txn: VersionedReadTransactionLazyMixin,
    context_refs: VersionedLazyContextRefs,
) -> RevisionId | LazyResult[RevisionId] | ScalarServerRef[RevisionId]:
    if isinstance(txn, VersionedWriteTransactionLazyMixin):
        write_base_revision_id = _write_txn_base_revision_id(txn)
        if write_base_revision_id is not None:
            return write_base_revision_id
    revision_ref = versioned_lazy_context_revision_ref(
        context_refs,
        context=DiagnosticLabel("default diff to_revision_id context"),
    )
    if revision_ref is None:
        msg = "to_revision_id requires l7000-owned revision context refs when omitted"
        raise RuntimeError(msg)
    return revision_ref


