@pure_lazy
def _build_versioned_raw_query_spec[T: VersionedObjectRow[SysId]](
    model_cls: type[T],
    *,
    object_id: ScalarServerRef[SysId] | None = None,
    include_deleted: bool = False,
) -> QuerySpec[T]:
    filters: list[QueryFilter] = []
    if object_id is not None:
        filters.append(QueryFilter(column="sys_id", operator="=", value=object_id))

    raw_type_names = collect_polymorphic_type_names(model_cls)
    type_filter_types = tuple(raw_type_names) if raw_type_names else None
    from l1000_schema.typed_field import field

    return QuerySpec(
        model_cls=model_cls,
        table=get_table_name(model_cls),
        select_columns=[field(getattr(model_cls, field_name)) for field_name in model_cls.model_fields],
        distinct=False,
        joins=[],
        filters=filters,
        order_by=[],
        limit=1 if object_id is not None else None,
        offset=None,
        group_by=[],
        aggregations=[],
        having=[],
        window_functions=[],
        include_deleted=include_deleted,
        type_filter_types=type_filter_types,
        type_filter_column="type_name" if type_filter_types is not None else None,
    )


@pure_lazy
def _trust_shape_for_model(
    txn: object,
