@pure_lazy
def _schema_metadata_snapshot_for_revision_metadata(txn: object) -> SchemaMetadataSnapshot:
    from l3200_metadata.schema_metadata_snapshot import capture_schema_metadata_snapshot

    def require_complete_snapshot(snapshot: SchemaMetadataSnapshot) -> SchemaMetadataSnapshot:
        if snapshot.schema_hash:
            return snapshot
        recaptured_snapshot = capture_schema_metadata_snapshot()
        if recaptured_snapshot.schema_hash:
            return recaptured_snapshot
        msg = "Versioned commit requires complete schema metadata. The transaction schema snapshot has an empty schema hash."
        raise ValueError(msg)

    snapshot = getattr(txn, "schema_metadata_snapshot", None)
    if isinstance(snapshot, SchemaMetadataSnapshot):
        return require_complete_snapshot(snapshot)
    raw_snapshot = getattr(txn, "_schema_metadata_snapshot", None)
    if isinstance(raw_snapshot, SchemaMetadataSnapshot):
        return require_complete_snapshot(raw_snapshot)
    captured_snapshot = capture_schema_metadata_snapshot()
    return require_complete_snapshot(captured_snapshot)


_PRIVATE_PUBLICATION_INPUT_NAMES = frozenset(
    {"speculative_publish_table_names", "speculative_insert_only_table_names"},
)


def _reject_private_publication_metadata_lazy(
    revision_metadata: Mapping[str, _RevisionMetadataValue],
) -> None:
    private_names = tuple(sorted(_PRIVATE_PUBLICATION_INPUT_NAMES & revision_metadata.keys()))
    if private_names:
        msg = f"Revision metadata contains a private publication input: {private_names!r}"
        raise TypeError(msg)


@pure_lazy
def _with_default_revision_metadata(
    revision_metadata: Mapping[str, _RevisionMetadataValue],
    *,
    schema_metadata: SchemaMetadataSnapshot,
) -> dict[str, _RevisionMetadataValue]:
    effective_revision_metadata = dict(revision_metadata)
    if not str(effective_revision_metadata.get("schema_hash") or ""):
        effective_revision_metadata["schema_hash"] = schema_metadata.schema_hash
        effective_revision_metadata["json_schema_epoch"] = schema_metadata.json_schema_epoch
    else:
        effective_revision_metadata.setdefault(
            "json_schema_epoch",
            schema_metadata.json_schema_epoch,
        )
    return effective_revision_metadata


@pure_lazy
def _normalize_key_field_names[T: DatabaseObjectRow](
    key_columns: Sequence[Field[Any, T]] | None,
) -> tuple[str, ...]:
    key_names = extract_field_names(tuple(list(key_columns) if key_columns else []))
