        raise ValueError("key_columns cannot be empty")
    return key_names


@pure_lazy
def _map_raw_column_name(
    source_cls: type[DatabaseObjectRow],
    model_cls: type[DatabaseObjectRow],
    column_name: SqlColumnName,
) -> str:
    source_fields = collect_polymorphic_fields(source_cls)
    model_fields = collect_polymorphic_fields(model_cls)
    field_name = str(column_name)
    source_pointer_columns = {large_column_pointer_name(config.column) for config in get_large_column_configs(source_cls)}
    model_pointer_columns = {large_column_pointer_name(config.column) for config in get_large_column_configs(model_cls)}
    if field_name in source_pointer_columns & model_pointer_columns:
        return field_name
    if field_name == "type_name" and collect_polymorphic_type_names(model_cls):
        return field_name
    if field_name in source_fields and field_name in model_fields:
        return field_name

    for field_name_obj in source_fields:
        field_name = str(field_name_obj)
        owner_cls = field_owner_class(source_cls, field_name)
        if get_db_column_name(owner_cls, DynamicFieldName(field_name)) == column_name:
            if field_name not in model_fields:
                break
            return field_name

    raise ValueError(column_name)


@pure_lazy
def _normalize_raw_field_names(
    model_cls: type[DatabaseObjectRow],
