) -> list[str]:
    return list(normalize_raw_field_names(model_cls, columns, db_column_source))


@pure_lazy
def _raw_rows_with_model_defaults(
    model_cls: type[DatabaseObjectRow],
    field_names: Sequence[str],
    rows: Sequence[Sequence[object]],
) -> tuple[tuple[str, ...], tuple[tuple[object, ...], ...]]:
    """Add declared model defaults omitted by a raw versioned insert."""
    completed_field_names = list(field_names)
    default_field_names: list[str] = []
    data_field_names, _db_columns = intent_versioning_extended._collect_versioned_batch_data_columns(
        model_cls,
    )
    for field_name in data_field_names:
        if field_name in completed_field_names or field_name in {"sys_id", "created_at", "updated_at"}:
            continue
        field_info = model_cls.model_fields.get(field_name)
        if field_info is not None and field_info.get_default(call_default_factory=False) is not PydanticUndefined:
            default_field_names.append(field_name)
    completed_field_names.extend(default_field_names)
    completed_rows = tuple(
        (
            *tuple(row),
            *(model_cls.model_fields[field_name].get_default(call_default_factory=True) for field_name in default_field_names),
        )
        for row in rows
    )
    return tuple(completed_field_names), completed_rows


@pure_lazy
def _instance_rows_for_versioned_key_many[T: DatabaseObjectRow](
    model_cls: type[T],
    instances: Sequence[T],
    key_field_names: Sequence[str],
) -> tuple[list[str], list[tuple[Any, ...]], tuple[SqlColumnName, ...]]:
    versioning_fields = {"branch_id", "revision_id", "staged_commit_id", "deleted"}
    source_field_names: list[str] = []
    for key_name in key_field_names:
        if key_name not in source_field_names:
            source_field_names.append(key_name)
    field_sources = [model_cls, *(type(instance) for instance in instances)]
    for field_source in field_sources:
        for field_name, field_info in field_source.model_fields.items():
            if field_name in versioning_fields:
                continue
            if is_derived_column(field_info):
                continue
            if field_name not in source_field_names:
                source_field_names.append(field_name)

    def _source_value(instance: T, field_name: str) -> object:
        value = getattr(instance, field_name, None)
        if field_name == "type_name" and value is None:
            return canonical_polymorphic_type_name(type(instance))
        if isinstance(value, BaseModel):
            return value.model_dump(mode="json")
        return value

    rows = [tuple(_source_value(instance, field_name) for field_name in source_field_names) for instance in instances]
    source_db_columns = _instance_db_columns_for_versioned_key_many(
        model_cls,
        instances,
        source_field_names,
    )
    return source_field_names, rows, source_db_columns


@pure_lazy
def _instance_db_columns_for_versioned_key_many[T: DatabaseObjectRow](
    model_cls: type[T],
    instances: Sequence[T],
    source_field_names: Sequence[str],
) -> tuple[SqlColumnName, ...]:
    """Resolve each source field through the concrete model that declares it."""
    field_sources = tuple(
        dict.fromkeys((model_cls, *(type(instance) for instance in instances))),
    )
    db_columns: list[SqlColumnName] = []
    for field_name in source_field_names:
        declaring_models = tuple(field_source for field_source in field_sources if field_name in field_source.model_fields)
        if not declaring_models:
            msg = f"No model in the {model_cls.__name__} family declares field {field_name!r}"
            raise ValueError(msg)
        candidate_columns = {get_db_column_name(field_source, DynamicFieldName(field_name)) for field_source in declaring_models}
        if len(candidate_columns) != 1:
            model_names = ", ".join(model.__name__ for model in declaring_models)
            msg = (
                f"Field {field_name!r} maps to conflicting database columns "
                f"{sorted(str(column) for column in candidate_columns)!r} across "
                f"models [{model_names}]"
            )
            raise ValueError(msg)
        db_columns.append(next(iter(candidate_columns)))
    return tuple(db_columns)


@pure_lazy
def _instance_rows_for_versioned_raw_insert_many[T: DatabaseObjectRow](
    model_cls: type[T],
    instances: Sequence[T],
) -> tuple[list[str], list[tuple[Any, ...]]]:
    source_field_names, source_rows, _source_db_columns = _instance_rows_for_versioned_key_many(model_cls, instances, ())
    if (
        "type_name" in collect_polymorphic_fields(model_cls)
        and collect_polymorphic_type_names(model_cls)
        and "type_name" not in source_field_names
    ):
        source_field_names = [*source_field_names, "type_name"]
        type_name = canonical_polymorphic_type_name(model_cls)
        source_rows = [(*row, type_name) for row in source_rows]
    return source_field_names, source_rows


@pure_lazy
def _publish_versioned_dml_user_id(
    plan: _VersionedDmlUserIdPlan,
    session_id_raw: str | SessionId,
    *,
    after_refs: frozenset[ServerPlanRefId] = frozenset(),
) -> _VersionedDmlUserIdPublication:
    from l4000_permissions.permission_enforcement import is_system_or_schema_session

    session_id = session_id_raw if isinstance(session_id_raw, SessionId) else SessionId(session_id_raw)
    if is_system_or_schema_session(session_id.unwrap_to_sql()):
        return _VersionedDmlUserIdPublication(
            ref_id=ServerPlanRefId("__system_session_permission_user_ref"),
            permission_action_enabled=False,
        )

    from impl.common.l2070_server_plan.steps.session_user_id import SessionUserIdStep

    user_id_ref = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        SessionUserIdStep(
            user_id_ref,
            ServerRefs.scalar(session_id),
            after_refs=after_refs,
        ),
    )
    return _VersionedDmlUserIdPublication(
        ref_id=user_id_ref,
        permission_action_enabled=True,
    )


@pure_lazy
def _ensure_versioned_staged_commit_id[T: VersionedObjectRow](
    instance: T,
    staged_commit_id: StagedCommitId,
) -> T:
    if instance.staged_commit_id is not None:
        return instance
    updated_instance = instance.model_copy(update={"staged_commit_id": staged_commit_id})
    if not isinstance(updated_instance, type(instance)):
        msg = f"model_copy returned unexpected type: {type(updated_instance)!r}"
        raise TypeError(msg)
    return updated_instance


@pure_lazy
def register_precommit_validation_lazy[ValidationT](
    txn: VersionedWriteTransactionLazyMixin,
    validation: LazyResult[ValidationT],
) -> LazyResult[ValidationT]:
    """Register a SQL assertion in the versioned commit validation region."""
    shape = inspect_server_value_shape_for_planning(
        validation,
        site="versioned precommit validation",
    )
    if shape.symbolic_ref_id is None:
        raise ValueError("Versioned precommit validation must publish a plan-owned reference")
    txn.register_precommit_validation_ref(ServerPlanRefId(shape.symbolic_ref_id))
    return validation


class VersionedWriteTransactionLazyMixin(VersionedWritePlanTarget, WriteTransactionLazyMixin):  # pyright: ignore[reportUntypedBaseClass]
    """Lazy methods for SyncVersionedWriteTransaction CRUD."""

    _staged_commit_id: StagedCommitId | None
    _branch_published: bool
    _speculative_publish_fact_store: _ConnectionSpeculativePublishFactStore
    _precommit_validation_refs: frozenset[ServerPlanRefId]
    _speculative_named_branch_scope: _NamedSpeculativeBranchScope | None = None

    @property
    def _versioned_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> Mapping[_ConnectionSpeculativePublishKey, _ConnectionSpeculativePublishFacts]:
        """Return a read-only durable snapshot for diagnostics."""
        txn = cast(_VersionedWriteTxnState, self)
        return MappingProxyType(dict(txn._speculative_publish_fact_store.snapshot(lifecycle="durable")))

    @_versioned_speculative_publish_facts.setter
    def _versioned_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        value: dict[object, object],
    ) -> None:
        current_store = getattr(self, "_speculative_publish_fact_store", None)
        pending = {} if current_store is None else dict(current_store.snapshot(lifecycle="pending"))
        self._speculative_publish_fact_store = _ConnectionSpeculativePublishFactStore(value, pending)

    @property
    def _pending_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> Mapping[_ConnectionSpeculativePublishKey, _ConnectionSpeculativePublishFacts]:
        """Return a read-only pending snapshot for diagnostics."""
        txn = cast(_VersionedWriteTxnState, self)
        return MappingProxyType(dict(txn._speculative_publish_fact_store.snapshot(lifecycle="pending")))

    @_pending_connection_speculative_publish_facts.setter
    def _pending_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        value: dict[object, object],
    ) -> None:
        current_store = getattr(self, "_speculative_publish_fact_store", None)
        durable = {} if current_store is None else dict(current_store.snapshot(lifecycle="durable"))
        self._speculative_publish_fact_store = _ConnectionSpeculativePublishFactStore(durable, value)

    def register_precommit_validation_ref(
        self: VersionedWriteTransactionLazyMixin,
        ref_id: ServerPlanRefId,
    ) -> None:
        """Require a validation result before this transaction commits."""
        self._precommit_validation_refs = frozenset({*self._precommit_validation_refs, ref_id})

    def _commit_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> None:
        """Promote facts only after the owning database transaction commits.

        Rolled-back writes must not shape later publication SQL. See
        ``docs/design/NER_1381_SPECULATIVE_PUBLICATION_ARCHITECTURE.rst``.
        """
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.promote(
            staged_commit_id=txn._staged_commit_id,
            resolved_branch=txn._branch_anchor,
        )

