        self: VersionedWriteTransactionLazyMixin,
    ) -> _NamedSpeculativeBranchScope | None:
        scope = self._speculative_named_branch_scope
        if scope is not None and not isinstance(scope, _NamedSpeculativeBranchScope):
            raise TypeError("Invalid named speculative branch scope: expected a typed branch locator")
        return scope

    def versioned_transaction_planning_snapshot(
        self: VersionedWriteTransactionLazyMixin,
    ) -> VersionedTransactionPlanningSnapshot:
        txn = cast(_VersionedWriteTxnState, self)
        base_revision_id = txn.base_revision_id
        context_refs = get_versioned_lazy_context_refs(self)
        revision_ref = versioned_lazy_context_revision_ref(
            context_refs,
            context=DiagnosticLabel("versioned planning snapshot revision context"),
        )
        bound_context_refs = VersionedLazyContextRefs(
            branch=versioned_lazy_context_branch_ref(
                context_refs,
                context=DiagnosticLabel("versioned planning snapshot branch context"),
            ),
            revision=UNSET if revision_ref is None else revision_ref,
            workspace=context_refs.workspace,
        )

        def _staging_context_factory(
            model_cls: type[DatabaseObjectRow[SysId]],
        ) -> intent_transaction.VersionedStagingCtx:
            return self._get_versioned_staging_context(model_cls, context_refs=bound_context_refs)

        return VersionedTransactionPlanningSnapshot(
            branch_tip_materialization=txn._branch_tip_materialization,
            lazy_revision=txn._lazy_revision,
            lazy_branch=txn._lazy_branch,
            explicit_base_revision_id=txn._explicit_base_revision_id,
            base_revision_id=base_revision_id,
            revision_id=base_revision_id,
            domain=txn.domain,
            staging_context_factory=_staging_context_factory,
            touched_versioned_tables=frozenset(txn._inline_touched_versioned_tables),
        )

    def _mark_commit_branch_touched_model_lazy(
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[DatabaseObjectRow[SysId]],
        *,
        operation: _ConnectionSpeculativeOperation | None = None,
    ) -> None:
        self._mark_commit_branch_touched_table_name_lazy(get_table_name(model_cls), operation=operation)

    def _mark_commit_branch_touched_table_name_lazy(
        self: VersionedWriteTransactionLazyMixin,
        table_name: SqlTableName,
        *,
        operation: _ConnectionSpeculativeOperation | None = None,
    ) -> None:
        if not table_name:
            raise ValueError("Versioned publication facts require a non-empty table name")
        txn = cast(_VersionedWriteTxnState, self)
        txn._inline_touched_versioned_tables.add(table_name)
        self._record_connection_speculative_publish_table_lazy(table_name, operation=operation)

    @pure_lazy
    def _connection_speculative_publish_prefix(
        self: VersionedWriteTransactionLazyMixin,
    ) -> _ConnectionSpeculativePublishPrefix | None:
        txn = cast(_VersionedWriteTxnState, self)
        branch = txn._lazy_branch if txn._branch_anchor is None else txn._branch_anchor
        branch_id: BranchId | BranchScopeToken
        if isinstance(branch, BranchId):
            branch_id = branch
        elif isinstance(branch, ScalarServerRef):
            branch_id = opaque_scope_token(branch)
            branch_ref_id = branch.ref_id
            if branch_ref_id is not None:
                found_seed, seed_value = read_seeded_constant_from_ctx(None, ServerPlanRefId(branch_ref_id))
                if found_seed:
                    if not isinstance(seed_value, BranchId):
                        raise TypeError("Speculative publication scope requires a typed seeded branch ID")
                    branch_id = seed_value
        else:
            return None
        connection_id = txn._connection_id
        if not isinstance(connection_id, ConnectionId):
            raise TypeError("Speculative publication scope requires a typed connection ID")
        domain = txn.domain
        domain_name = domain.name
        return _ConnectionSpeculativePublishPrefix(
            domain_name=_VersioningDomainName(str(domain_name)),
            branch_id=branch_id,
            connection_id=connection_id,
        )

    @pure_lazy
    def _connection_speculative_publish_key(
        self: VersionedWriteTransactionLazyMixin,
    ) -> _ConnectionSpeculativePublishKey | None:
        prefix = self._connection_speculative_publish_prefix()
        if prefix is None:
            return None
        staged_commit_id = cast(_VersionedWriteTxnState, self)._staged_commit_id
        if not isinstance(staged_commit_id, StagedCommitId):
            raise RuntimeError("Speculative publication scope requires a typed staged-commit ID")
        return _ConnectionSpeculativePublishKey(
            prefix=prefix,
            staged_commit_id=staged_commit_id,
        )

    @pure_lazy
    def _connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        *,
        all_connections: bool = False,
    ) -> _ConnectionSpeculativePublishFacts | None:
        prefix = self._connection_speculative_publish_prefix()
        if prefix is None:
            return None
        txn = cast(_VersionedWriteTxnState, self)
        durable_snapshot = txn._speculative_publish_fact_store.snapshot(lifecycle="durable")
        pending_snapshot = txn._speculative_publish_fact_store.snapshot(lifecycle="pending")

        named_scope = self._checked_speculative_named_branch_scope()

        def _matches_scope(
            key: _ConnectionSpeculativePublishKey,
            facts: _ConnectionSpeculativePublishFacts,
        ) -> bool:
            if (
                isinstance(prefix.branch_id, BranchScopeToken)
                and named_scope is not None
                and named_scope in facts.named_branch_scopes
                and key.prefix.domain_name == prefix.domain_name
                and (all_connections or key.prefix.connection_id == prefix.connection_id)
            ):
                return True
            if (
                isinstance(key.prefix.branch_id, BranchScopeToken)
                and isinstance(txn._lazy_branch, ScalarServerRef)
                and key.prefix.branch_id == opaque_scope_token(txn._lazy_branch)
                and key.staged_commit_id == txn._staged_commit_id
                and key.prefix.domain_name == prefix.domain_name
                and key.prefix.connection_id == prefix.connection_id
            ):
                return True
            if not all_connections:
                return key.prefix == prefix
            return key.prefix.domain_name == prefix.domain_name and key.prefix.branch_id == prefix.branch_id

        sources = tuple(
            facts for snapshot in (durable_snapshot, pending_snapshot) for key, facts in snapshot if _matches_scope(key, facts)
        )
        if not sources:
            return None
        if len(sources) == 1:
            return sources[0]
        combined = _ConnectionSpeculativePublishFacts()
        for facts in sources:
            combined = combined.merged_with(facts)
        return combined

    def _set_speculative_named_branch_scope(
        self: VersionedWriteTransactionLazyMixin,
        branch_name: BranchName,
        workspace_id: WorkspaceId,
    ) -> None:
        """Retain a locator for speculative hints, never for branch authority."""
        self._speculative_named_branch_scope = _NamedSpeculativeBranchScope(
            branch_name=branch_name,
            workspace_id=workspace_id,
        )

    def _record_connection_speculative_publish_table_lazy(
        self: VersionedWriteTransactionLazyMixin,
        table_name: SqlTableName,
        *,
        operation: _ConnectionSpeculativeOperation | None,
    ) -> None:
        txn = cast(_VersionedWriteTxnState, self)
        named_scope = self._checked_speculative_named_branch_scope()
        staged_commit_id = txn._ensure_staged_commit_id()
        key = self._connection_speculative_publish_key()
        if key is None:
            return
        del staged_commit_id
        txn._speculative_publish_fact_store.record(
            key,
            table_name=SqlTableName(table_name),
            operation=operation,
            named_scope=named_scope,
            insert_only_downgraded=txn._versioned_speculative_insert_only_downgraded,
        )

    def _discard_connection_speculative_publish_fact_keys(
        self: VersionedWriteTransactionLazyMixin,
        keys: frozenset[_ConnectionSpeculativePublishKey],
    ) -> None:
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.discard(keys=keys)

    def _replace_exact_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        selected_staged_commit_ids: tuple[StagedCommitId, ...],
        *,
        touched_table_names: frozenset[SqlTableName],
        non_insert_table_names: frozenset[SqlTableName],
        deleted_table_names: frozenset[SqlTableName],
    ) -> None:
        """Replace known selected scopes with facts from authoritative SQL evidence."""
        selected_ids = _require_authoritative_speculative_fact_sets_lazy(
            selected_staged_commit_ids,
            touched_table_names=touched_table_names,
            non_insert_table_names=non_insert_table_names,
            deleted_table_names=deleted_table_names,
        )
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.replace(
            selected_staged_commit_ids=selected_ids,
            touched_table_names=touched_table_names,
            non_insert_table_names=non_insert_table_names,
            deleted_table_names=deleted_table_names,
        )

    def _record_missing_connection_scoped_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        selected_staged_commit_ids: tuple[StagedCommitId, ...],
        *,
        touched_table_names: frozenset[SqlTableName],
        non_insert_table_names: frozenset[SqlTableName],
        deleted_table_names: frozenset[SqlTableName],
    ) -> None:
        """Record selected scopes that the current logical connection owns."""
        selected_ids = _require_authoritative_speculative_fact_sets_lazy(
            selected_staged_commit_ids,
            touched_table_names=touched_table_names,
            non_insert_table_names=non_insert_table_names,
            deleted_table_names=deleted_table_names,
        )
        txn = cast(_VersionedWriteTxnState, self)
        txn._speculative_publish_fact_store.record_missing(
            prefix=self._connection_speculative_publish_prefix(),
            selected_staged_commit_ids=selected_ids,
            touched_table_names=touched_table_names,
            non_insert_table_names=non_insert_table_names,
            deleted_table_names=deleted_table_names,
            named_scope=self._checked_speculative_named_branch_scope(),
        )

    def _consume_exact_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
        selected_staged_commit_ids: tuple[StagedCommitId, ...],
    ) -> None:
        """Discard facts for the exact selected staged scopes."""
        selected_ids = frozenset(selected_staged_commit_ids)
        txn = cast(_VersionedWriteTxnState, self)
        keys = frozenset(
            key for key, _facts in txn._speculative_publish_fact_store.all_snapshots() if key.staged_commit_id in selected_ids
        )
        self._discard_connection_speculative_publish_fact_keys(keys)

    def _consume_all_connection_speculative_publish_facts(
        self: VersionedWriteTransactionLazyMixin,
    ) -> None:
        """Discard all facts for the current branch and logical connection."""
        txn = cast(_VersionedWriteTxnState, self)
        branch_id = txn._branch_anchor
        if not isinstance(branch_id, BranchId):
            raise RuntimeError("Published speculative facts require a concrete branch scope")
        prefix = _ConnectionSpeculativePublishPrefix(
            domain_name=_VersioningDomainName(txn.domain.name),
            branch_id=branch_id,
            connection_id=txn._connection_id,
        )
        keys = frozenset(
            key
            for key, _facts in txn._speculative_publish_fact_store.all_snapshots()
            if key.prefix == prefix
            or (
                isinstance(key.prefix.branch_id, BranchScopeToken)
                and isinstance(txn._lazy_branch, ScalarServerRef)
                and key.prefix.branch_id == opaque_scope_token(txn._lazy_branch)
                and key.staged_commit_id == txn._staged_commit_id
                and key.prefix.domain_name == prefix.domain_name
                and key.prefix.connection_id == prefix.connection_id
            )
        )
        self._discard_connection_speculative_publish_fact_keys(keys)

    @pure_lazy
    def _connection_speculative_publish_log_snapshot(
        self: VersionedWriteTransactionLazyMixin,
    ) -> dict[str, object]:
        facts = self._connection_speculative_publish_facts()
        key = self._connection_speculative_publish_prefix()
        if facts is None:
            return {
                "key": key,
                "available": False,
                "touched_tables": (),
                "non_insert_tables": (),
                "deleted_tables": (),
                "insert_only_tables": (),
            }
        return {
            "key": key,
            "available": True,
            "touched_tables": tuple(sorted(facts.touched_tables)),
            "non_insert_tables": tuple(sorted(facts.non_insert_tables)),
            "deleted_tables": tuple(sorted(facts.deleted_tables)),
            "insert_only_tables": tuple(sorted(facts.insert_only_tables)),
        }

