    def _mark_commit_branch_delete_side_effect_tables_lazy(
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[DatabaseObjectRow[SysId]],
    ) -> None:
        from impl.common.l7100_versioned_operations.fk_cascade import get_fk_map

        self._mark_commit_branch_touched_model_lazy(model_cls, operation="delete")
        txn = cast(_VersionedWriteTxnState, self)
        deleted_tables = txn._inline_deleted_versioned_tables
        deleted_tables.add(get_table_name(model_cls))
        domain = cast(_VersionedWriteTxnState, self).domain
        fk_map = get_fk_map(domain)
        # Expand the touched set through producer-declared CASCADE and SET NULL
        # relationships without publishing unrelated domain tables.
        seen: set[type[DatabaseObjectRow[SysId]]] = set()
        pending: list[type[DatabaseObjectRow[SysId]]] = [model_cls]
        while pending:
            parent_model = pending.pop()
            if parent_model in seen:
                continue
            seen.add(parent_model)
            parent_table = get_table_name(parent_model)
            for _key_model, relationships in fk_map.items():
                for relationship in relationships:
                    if get_table_name(relationship.parent_model) != parent_table:
                        continue
                    on_delete = relationship.on_delete.upper().replace(" ", "_")
                    if on_delete not in {"CASCADE", "SET_NULL"}:
                        continue
                    child_model_cast = cast("type[DatabaseObjectRow[SysId]]", relationship.child_model)
                    child_operation: _ConnectionSpeculativeOperation = "delete" if on_delete == "CASCADE" else "update"

                    self._mark_commit_branch_touched_model_lazy(
                        child_model_cast,
                        operation=child_operation,
                    )
                    if on_delete == "CASCADE":
                        deleted_tables.add(get_table_name(child_model_cast))
                        pending.append(child_model_cast)

    def _has_pending_versioned_writes_for_plan(
        self: VersionedWriteTransactionLazyMixin,
    ) -> bool:
        snapshot = self.versioned_transaction_planning_snapshot()
        return bool(snapshot.touched_versioned_tables)

    def _speculative_publish_table_names_hint(
        self: VersionedWriteTransactionLazyMixin,
    ) -> frozenset[str]:
        """Return the SQL-checked publish hint for staged writes known to this transaction."""

        pending_refs = self._flush_pending_lazy_ops_to_plan()
        del pending_refs
        snapshot = self.versioned_transaction_planning_snapshot()
        touched_tables = set(snapshot.touched_versioned_tables)
        touched_tables.update(self._plan_staging_table_names_hint())
        txn = cast(_VersionedWriteTxnState, self)
        deleted_tables = set(txn._inline_deleted_versioned_tables)
        touched_tables.update(deleted_tables)
        if not touched_tables:
            return frozenset()
        return frozenset(touched_tables)

    @pure_lazy
    def _plan_staging_table_names_hint(self: VersionedWriteTransactionLazyMixin) -> set[SqlTableName]:
        """Return versioned base tables with staging contexts already present in the lazy plan."""

        txn = cast(_VersionedWriteTxnState, self)
        domain_table_names = _txn_domain_versioned_table_names(txn)

        plan = self._get_transaction_plan_lazy()
        staged_to_base = {
            derive_versioned_table_names(VersionedBaseTableName(str(base_table))).staged: base_table for base_table in domain_table_names
        }
        touched_tables: set[SqlTableName] = set()
        for step in plan._steps:
            for raw_table_name in step.tables_written():
                table_name = staged_to_base.get(VersionedStagedTableName(str(raw_table_name)))
                if table_name is not None:
                    touched_tables.add(table_name)
        return touched_tables

    @pure_lazy
    def _expand_speculative_publish_tables_for_side_effects(
        self: VersionedWriteTransactionLazyMixin,
        touched_tables: set[SqlTableName],
    ) -> set[SqlTableName]:
        from impl.common.l7100_versioned_operations.fk_cascade import get_fk_map

        txn = cast(_VersionedWriteTxnState, self)
        domain_table_names = _txn_domain_versioned_table_names(txn)
        child_tables_by_parent: dict[SqlTableName, set[SqlTableName]] = {}
        fk_map = get_fk_map(txn.domain)
        for parent_model, relationships in fk_map.items():
            parent_table = get_table_name(parent_model)
            if parent_table not in domain_table_names:
                continue
            for relationship in relationships:
                on_delete = relationship.on_delete.upper().replace(" ", "_")
                if on_delete not in {"CASCADE", "SET_NULL"}:
                    continue
                child_table = get_table_name(relationship.child_model)
                if child_table not in domain_table_names:
                    continue
                child_tables_by_parent.setdefault(parent_table, set()).add(child_table)

        for graph_definition in txn.domain.graphs:
            graph_member_tables = {
                get_table_name(model_cls) for model_cls in (*graph_definition.node_types, *graph_definition.edge_types)
            }
            if graph_member_tables & touched_tables:
                for graph_table in graph_member_tables:
                    child_tables_by_parent.setdefault(graph_table, set()).update(
                        graph_member_tables - {graph_table},
                    )

        pending = list(touched_tables)
        seen: set[SqlTableName] = set()
        while pending:
            parent_table = pending.pop()
            if parent_table in seen:
                continue
            seen.add(parent_table)
            for child_table in child_tables_by_parent.get(parent_table, ()):
                if child_table in touched_tables:
                    continue
                touched_tables.add(child_table)
                pending.append(child_table)
        return touched_tables

    def _ensure_staged_commit_id(
        self: VersionedWriteTransactionLazyMixin,
    ) -> StagedCommitId:
        """Return the staged commit ID, generating it on first use."""
        txn = cast(_VersionedWriteTxnState, self)
        staged_commit_id = txn._staged_commit_id
        if staged_commit_id is None:
            staged_commit_id = StagedCommitId.new()
            txn._staged_commit_id = staged_commit_id
        return staged_commit_id

    def _staged_commit_id_value(self: VersionedWriteTransactionLazyMixin) -> str:
        """Return the staged commit ID as a SQL-safe string."""
        staged_commit_id = self._ensure_staged_commit_id()
        return staged_commit_id.unwrap_to_str()

    @pure_lazy
    def _check_versioned_or_delegate[T](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
    ) -> bool:
        """Return True if model_cls is versioned."""
        return issubclass(model_cls, VersionedObjectRow)

    @pure_lazy
    def query_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
    ) -> Any:
        """Query versioned tables through the versioned plan and unversioned tables through the base write transaction."""
        versioned_or_delegate = self._check_versioned_or_delegate(model_cls)
        if not versioned_or_delegate:
            return WriteTransactionLazyMixin.query_lazy(
                cast(Any, cast(_VersionedWriteTxnState, self).base_write_transaction),
                model_cls,
            )
        return _VersionedWriteQueryBuilder(cast(Any, self), cast("type[VersionedObjectRow[SysId]]", model_cls))

    @pure_lazy
    def query_unfiltered_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        *,
        internal_permission_query_request: InternalPermissionQueryRequest | None = None,
    ) -> Any:
        """Unfiltered query variant with the same versioned routing as ``query_lazy``.

        ``WriteTransactionLazyMixin.query_unfiltered_lazy`` builds a plain
        ``WriteQueryBuilder``, so its read terminals bypass the versioned
        lowering that ``query_lazy`` gets from ``_VersionedWriteQueryBuilder``.
        """
        if not self._check_versioned_or_delegate(model_cls):
            return ReadTransactionLazyMixin.query_unfiltered_lazy(
                cast(Any, cast(_VersionedWriteTxnState, self).base_read_transaction),
                model_cls,
                internal_permission_query_request=internal_permission_query_request,
            )
        builder = _VersionedWriteQueryBuilder(cast(Any, self), cast("type[VersionedObjectRow[SysId]]", model_cls))
        return builder._without_permission_filtering(internal_permission_query_request)

    @pure_lazy
    def _get_versioned_staging_context(
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[DatabaseObjectRow[SysId]],
        *,
        context_refs: VersionedLazyContextRefs,
    ) -> intent_transaction.VersionedStagingCtx:
        """Compute all versioned staging data. Pure — no I/O."""
        txn = cast(_VersionedWriteTxnState, self)
        _require_versioned_model_in_domain(
            txn,
            model_cls,
            operation="versioned staging",
        )
        txn._ensure_staged_commit_id()
        lazy_branch = versioned_lazy_context_branch_ref(
            context_refs,
            context=DiagnosticLabel("_get_versioned_staging_context branch context"),
        )
        _require_versioned_publication_state(
            txn,
            plan=txn._get_transaction_plan_lazy(),
        )
        lazy_revision = versioned_lazy_context_revision_ref(
            context_refs,
            context=DiagnosticLabel("_get_versioned_staging_context revision context"),
        )
        literal_branch_anchor = versioned_lazy_context_literal_branch(context_refs)
        branch_scope_token = txn._branch_scope_token
        staged_commit_id_raw = txn._staged_commit_id_value()

        backend = versioned_backend_registry_module.versioned_backend_registry.get("sparse", self)
        # Register subtype fields so auxiliary models include them
        physical = backend._get_physical_table_model(model_cls)
        backend._register_polymorphic_fields(physical, model_cls)
        staged_model = backend._get_or_create_staged_model(model_cls)
        tip_model = backend._get_or_create_tip_model(model_cls)

        common_columns = physical_data_db_columns_staged_tip_intersection(staged_model, tip_model)

        # Polymorphic discriminator names
        raw_type_names = collect_polymorphic_type_names(model_cls)
        type_ids: list[str] | None = list(raw_type_names) if raw_type_names else None

        conn_id_raw = txn.connection_id.unwrap_to_uuid_compatible_str()
        sess_id_raw = txn.session_id.unwrap_to_sql()
        domain = txn.domain

        staging_ctx = intent_transaction.VersionedStagingCtx(
            staged_model=staged_model,
            tip_model=tip_model,
            common_columns=common_columns,
            type_ids=type_ids,
            lazy_branch=lazy_branch,
            lazy_revision=lazy_revision,
            branch_tip_materialization=_versioned_lazy_materialization_policy(txn).tip_materialization,
            staged_commit_id_raw=staged_commit_id_raw,
            domain=domain,
            connection_id_raw=conn_id_raw,
            session_id_raw=sess_id_raw,
            staged_visibility=txn._staged_visibility,
            branch_scope_token=branch_scope_token,
            literal_branch=literal_branch_anchor,
            sparse_table_name_value=SqlTableName(
                derive_versioned_table_names(VersionedBaseTableName(str(get_table_name(model_cls)))).sparse
            ),
        )
        txn._inline_touched_versioned_tables.add(SqlTableName(get_table_name(model_cls)))
        return staging_ctx

    @pure_lazy
    def _prepare_versioned_instance[T: VersionedObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: T,
        staging_ctx: intent_transaction.VersionedStagingCtx,
    ) -> T:
        """Prepare instance for versioned staging. Pure — no I/O."""
        prepared_obj = _prepare_instance.prepare_instance_for_insert_lazy(model_cls, instance)
        if not isinstance(prepared_obj, model_cls):
            msg = f"prepare_instance_for_insert_lazy returned unexpected type: {type(prepared_obj)!r}"
            raise TypeError(msg)
        prepared: T = prepared_obj
        txn = cast(_VersionedWriteTxnState, self)
        prepared = _inject_trust_defaults(
            _trust_shape_for_model(self, model_cls),
            prepared,
            txn.session_id,
        )
        return _ensure_versioned_staged_commit_id(
            prepared,
            StagedCommitId(staging_ctx.staged_commit_id_raw),
        )

