    @pure_lazy
    def delete_many_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        ids: Sequence[SysId] | LazyResult[Sequence[SysId]] | ScalarSequenceServerRef[SysId],
    ) -> LazyResult[int]:
        """Delete many rows through the authoritative bulk delete intent."""
        literal_ids: Sequence[SysId] | None = ids if isinstance(ids, Sequence) and not isinstance(ids, LazyResult) else None
        if literal_ids is not None:
            tracked_deleted_by_model = getattr(self, "_versioned_literal_delete_ids_by_model", {})
            assert isinstance(tracked_deleted_by_model, dict)
            previously_deleted = tracked_deleted_by_model.get(
                cast("type[DatabaseObjectRow[SysId]]", model_cls),
                set(),
            )
            assert isinstance(previously_deleted, set)
            literal_ids = tuple(
                dict.fromkeys(sys_id for sys_id in literal_ids if str(sys_id) not in previously_deleted),
            )
        if literal_ids is None and isinstance(ids, LazyResult):
            shape = inspect_server_value_shape_for_planning(ids, site="delete_many_lazy ids")
            if shape.symbolic_ref_id is None and shape.has_literal_value:
                literal_ids = tuple(cast("Sequence[SysId]", shape.literal_value))
        if literal_ids is not None and not literal_ids:
            return LazyResult.of(0)
        if not self._check_versioned_or_delegate(model_cls):
            if literal_ids is None:
                msg = "delete_many_lazy requires literal ids for non-versioned models"
                raise TypeError(msg)
            id_instances = tuple(model_cls.model_construct(sys_id=sys_id) for sys_id in literal_ids)
            return super().delete_by_key_many_lazy(
                model_cls,
                id_instances,
                [field(model_cls.sys_id)],
            )

        self._mark_commit_branch_delete_side_effect_tables_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls))
        _check_write_permission_lazy(self, model_cls)
        permission_context_ref, permission_context_type = _versioned_permission_context(
            self,
            model_cls,
        )
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(
            cast("type[DatabaseObjectRow[SysId]]", model_cls),
            context_refs=context_refs,
        )
        plan = self._get_transaction_plan_lazy()
        source_ids_ref = (
            None
            if literal_ids is not None
            else _require_scalar_sequence_source_ref(
                ids,
                context="delete_many_lazy ids",
            )
        )
        source_ref_id = None if source_ids_ref is None else getattr(source_ids_ref, "ref_id", None)
        if literal_ids is None and source_ref_id is None:
            literal_ids = tuple(
                _require_concrete_lazy_input(
                    cast("LazyResult[Iterable[SysId]]", ids),
                    context="delete_many_lazy ids",
                )
            )
        prior_refs = _current_versioned_write_tail_refs(self, plan=plan)
        if literal_ids is not None:
            raw_deleted_by_model: object = getattr(
                self,
                "_versioned_literal_delete_ids_by_model",
                {},
            )
            assert isinstance(raw_deleted_by_model, dict)
            deleted_by_model: dict[type[DatabaseObjectRow[SysId]], set[str]] = {}
            for deleted_model, deleted_values in raw_deleted_by_model.items():
                assert isinstance(deleted_model, type) and issubclass(
                    deleted_model,
                    DatabaseObjectRow,
                )
                assert isinstance(deleted_values, set)
                assert all(isinstance(value, str) for value in deleted_values)
                deleted_by_model[deleted_model] = {value for value in deleted_values if isinstance(value, str)}
            model_key = model_cls
            deleted_ids = set(deleted_by_model.get(model_key, set()))
            deleted_ids.update(str(sys_id) for sys_id in literal_ids)
            deleted_by_model[model_key] = deleted_ids
            object.__setattr__(self, "_versioned_literal_delete_ids_by_model", deleted_by_model)
        return _record_versioned_write_tail(
            self,
            self._add_intent(
                intent_versioning_extended.VersionedDeleteManyIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    config=ServerRefs.scalar(
                        intent_versioning_extended._VersionedDeleteManyConfig(
                            sys_ids=tuple(literal_ids or ()),
                            staging_ctx=sc,
                            after_refs=prior_refs,
                            source_ref=None if source_ref_id is None else ServerPlanRefId(source_ref_id),
                            permission_context_ref=permission_context_ref,
                            permission_context_type=permission_context_type,
                        ),
                    ),
                ),
            ),
            context="delete_many_lazy versioned delete",
        )

