                key_field_names=tuple(normalized_keys),
                source_db_columns=source_db_columns,
            ),
        )
        plan.add_step(matched_step)
        matched_columns = matched_step.cte_publication_contract().columns
        validate_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_lazy_support.ValidateVersionedSourceCountStep(
                validate_ref,
                config=versioned_lazy_support._ValidateVersionedSourceCountConfig(
                    source_ref=matched_ref,
                    expected_count=1,
                    error_message=(f"No row found matching key columns ({', '.join(normalized_keys)}) for {model_cls.__name__}"),
                ),
            ),
        )
        batch_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            intent_versioning_extended.VersionedUpdateManyBatchIntent(
                ref_id=batch_ref,
                model_cls=model_cls,
                instances=cast(
                    "ObjectSequenceServerRef[T]",
                    ServerRefs.from_ref_id(
                        matched_ref,
                        variant="object_sequence",
                    ),
                ),
                config=ServerRefs.scalar(
                    intent_versioning_extended._VersionedUpdateManyBatchConfig(
                        staging_ctx=sc,
                        source_order=(intent_versioning_extended._VersionedBatchSourceOrder.INPUT_ORDINAL),
                        source_columns=matched_columns,
                        after_refs=frozenset({validate_ref}),
                        permission_context_ref=permission_context_ref,
                        permission_context_type=permission_context_type,
                    ),
                ),
            ),
        )
        result_ref = plan._next_ref()
        plan.add_step(
            intent_versioning_extended._TakeFirstResolvedItemStep(
                ServerPlanRefId(result_ref),
                source_ref=intent_versioning_extended.versioned_write_raw_rows_source_ref(
                    ServerPlanRefId(f"{batch_ref}_batch_return"),
                ),
                model_cls=model_cls,
            ),
        )
        return cast(LazyResult[T], self._add_intent_by_ref(result_ref))

