    def delete_many_returning_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        ids: Sequence[SysId],
        returning_columns: Sequence[str] | None = None,
    ) -> LazyResult[list[dict[str, Any]]]:
        """Delete multiple versioned rows and return deleted payloads."""
        deleted_by_model = getattr(self, "_versioned_literal_delete_ids_by_model", {})
        assert isinstance(deleted_by_model, dict)
        model_key = cast("type[DatabaseObjectRow[SysId]]", model_cls)
        previously_deleted = deleted_by_model.get(model_key, set())
        assert isinstance(previously_deleted, set)
        ids = tuple(
            dict.fromkeys(sys_id for sys_id in ids if str(sys_id) not in previously_deleted),
        )
        if not ids:
            return LazyResult.of([])
        if not self._check_versioned_or_delegate(model_cls):
            _check_write_permission_lazy(self, model_cls)
            plan = self._get_transaction_plan_lazy()
            return self._add_intent(
                intent_crud.DeleteManyReturningIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    config=ServerRefs.scalar(
                        intent_crud._DeleteManyReturningPayload(
                            sys_ids=tuple(ids),
                            returning_columns=intent_crud._shape_returning_columns_payload(
                                None if returning_columns is None else list(returning_columns),
                            ),
                            after_refs=frozenset(),
                        ),
                    ),
                ),
            )
        deleted_by_model = dict(deleted_by_model)
        deleted_by_model[model_key] = {*previously_deleted, *(str(sys_id) for sys_id in ids)}
        object.__setattr__(self, "_versioned_literal_delete_ids_by_model", deleted_by_model)
        permission_context_ref, permission_context_type = _versioned_permission_context(
            self,
            model_cls,
        )
        plan = self._get_transaction_plan_lazy()
        result = self._add_intent(
            intent_crud.DeleteManyReturningIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                model_cls=model_cls,
                config=ServerRefs.scalar(
                    intent_crud._DeleteManyReturningPayload(
                        sys_ids=tuple(ids),
                        returning_columns=intent_crud._shape_returning_columns_payload(
                            None if returning_columns is None else list(returning_columns),
                        ),
                        after_refs=frozenset(),
                        permission_context_ref=permission_context_ref,
                        permission_context_type=permission_context_type,
                    ),
                ),
            ),
        )
        result._expected_type = None
        return result

