        if isinstance(rows, Sequence) and len(rows) == 0:
            return LazyResult.of(0)
        self._mark_commit_branch_touched_model_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls), operation="update")
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        plan = self._get_transaction_plan_lazy()
        prior_refs = _current_versioned_write_tail_refs(self, plan=plan)
        isolate_from_sql_batch = bool(prior_refs)
        if isinstance(rows, intent_versioning_extended.DeferredRawRowSource):
            # SQL-visible deferred sources preserve write ordering through
            # dependency CTEs and therefore remain eligible for one batch.
            isolate_from_sql_batch = False
        elif isinstance(rows, Sequence) and not isinstance(rows, str | bytes):
            raw_field_names = _normalize_raw_field_names(model_cls, columns, db_column_source)
            if "sys_id" in raw_field_names:
                sys_id_index = tuple(raw_field_names).index("sys_id")
                raw_sys_ids = {str(row[sys_id_index]) for row in cast("Sequence[Sequence[object]]", rows)}
                deleted_by_model = getattr(self, "_versioned_literal_delete_ids_by_model", {})
                assert isinstance(deleted_by_model, dict)
                isolate_from_sql_batch = bool(
                    prior_refs and raw_sys_ids & deleted_by_model.get(cast("type[DatabaseObjectRow[SysId]]", model_cls), set())
                )
        return _record_versioned_write_tail(
            self,
            self._add_intent(
                intent_versioning_extended.VersionedRawUpsertManyIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    config=ServerRefs.scalar(
                        intent_versioning_extended._VersionedRawUpsertManyConfig(
                            staging_ctx=sc,
                            columns=tuple(columns),
                            rows=rows,
                            conflict_columns=None if conflict_columns is None else tuple(conflict_columns),
                            change_detection_columns=tuple(change_detection_columns),
                            db_column_source=_optional_database_object_model(db_column_source),
                            after_refs=prior_refs,
                            isolate_from_sql_batch=isolate_from_sql_batch,
                            emit_side_effects=emit_side_effects,
                        ),
                    ),
                ),
            ),
            context="upsert_many_raw_lazy versioned raw upsert",
        )

    @pure_lazy
    def upsert_many_batch_raw_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        columns: Sequence[str],
        rows: object,
        conflict_columns: Sequence[str] | None = None,
        chunk_size: int = 256,
        db_column_source: type[Any] | None = None,
    ) -> LazyResult[int]:
        """Versioned batching reuses the same lazy upsert intent surface."""
        if not self._check_versioned_or_delegate(model_cls):
            return super().upsert_many_batch_raw_lazy(
                model_cls,
                columns,
                rows,
                conflict_columns,
                chunk_size,
                db_column_source,
            )
        del chunk_size
        return self.upsert_many_raw_lazy(
            model_cls,
            columns,
            rows,
            conflict_columns=conflict_columns,
            db_column_source=db_column_source,
        )

    @pure_lazy
    def update_by_key_many_raw_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        columns: Sequence[str],
        rows: object,
        key_columns: Sequence[str] | None = None,
        db_column_source: type[Any] | None = None,
    ) -> LazyResult[int]:
        """Resolve key-matched rows in SQL, then reuse versioned batch update."""
        if not self._check_versioned_or_delegate(model_cls):
            return super().update_by_key_many_raw_lazy(
                model_cls,
                columns,
                rows,
                key_columns,
                db_column_source,
            )
        _check_write_permission_lazy(self, model_cls)
        if not isinstance(rows, Sequence) or isinstance(rows, str | bytes | bytearray):
            msg = "Versioned raw update-by-key requires a reusable literal row sequence"
            raise TypeError(msg)
        if not rows:
            return LazyResult.of(0)
        normalized_fields = _normalize_raw_field_names(model_cls, columns, db_column_source)
        normalized_keys = (
            tuple(_normalize_raw_field_names(model_cls, key_columns, db_column_source)) if key_columns is not None else ("sys_id",)
        )
        self._mark_commit_branch_touched_model_lazy(
            cast("type[DatabaseObjectRow[SysId]]", model_cls),
            operation="update",
        )
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        plan = self._get_transaction_plan_lazy()
        prior_refs = _current_versioned_write_tail_refs(self, plan=plan)
        matched_ref = ServerPlanRefId(plan._next_ref())
        matched_step = versioned_lazy_support.MatchVersionedRowsByKeyToLiteralSequenceStep(
            matched_ref,
            model_cls=model_cls,
            staging_ctx=sc,
            config=versioned_lazy_support._MatchVersionedRowsByKeyConfig(
                source_field_names=tuple(normalized_fields),
                source_rows=tuple(tuple(row) for row in cast("Sequence[Sequence[object]]", rows)),
                key_field_names=normalized_keys,
                after_refs=prior_refs,
            ),
        )
        plan.add_step(matched_step)
        matched_columns = matched_step.cte_publication_contract().columns
        batch_ref = ServerPlanRefId(plan._next_ref())
        self._add_intent(
            intent_versioning_extended.VersionedUpdateManyBatchIntent(
                ref_id=batch_ref,
                model_cls=model_cls,
                instances=cast(
                    "ObjectSequenceServerRef[T]",
                    ServerRefs.from_ref_id(matched_ref, variant="object_sequence"),
                ),
                config=ServerRefs.scalar(
                    intent_versioning_extended._VersionedUpdateManyBatchConfig(
                        staging_ctx=sc,
                        source_order=(intent_versioning_extended._VersionedBatchSourceOrder.INPUT_ORDINAL),
                        source_columns=matched_columns,
                        after_refs=frozenset({matched_ref}),
                    ),
                ),
            ),
        )
        count_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_lazy_support.ResolvedLenStep(
                count_ref,
                source_ref=str(matched_ref),
                after_refs=frozenset({batch_ref}),
            ),
        )
        return cast(
            "LazyResult[int]",
            _record_versioned_write_tail(
                self,
                self._add_intent_by_ref(count_ref),
                context="update_by_key_many_raw_lazy versioned raw key update",
            ),
        )

    @pure_lazy
    def delete_by_key_many_raw_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        columns: Sequence[str],
        rows: object,
        key_columns: Sequence[str] | None = None,
        db_column_source: type[Any] | None = None,
    ) -> LazyResult[int]:
        """Reject versioned raw key deletes until staged SQL key matching exists."""
        if not self._check_versioned_or_delegate(model_cls):
            return super().delete_by_key_many_raw_lazy(
                model_cls,
                columns,
                rows,
                key_columns,
                db_column_source,
            )
        _check_write_permission_lazy(self, model_cls)
        if not isinstance(rows, Sequence) or isinstance(rows, str | bytes | bytearray):
            msg = "Versioned raw delete-by-key requires a reusable literal row sequence"
            raise TypeError(msg)
        if not rows:
            return LazyResult.of(0)
        normalized_fields = _normalize_raw_field_names(model_cls, columns, db_column_source)
        normalized_keys = (
            tuple(_normalize_raw_field_names(model_cls, key_columns, db_column_source)) if key_columns is not None else ("sys_id",)
        )
        missing_keys = tuple(key for key in normalized_keys if key not in normalized_fields)
        if missing_keys:
            raise ValueError(f"Key columns not in provided columns: {list(missing_keys)!r}")
        self._mark_commit_branch_delete_side_effect_tables_lazy(
            cast("type[DatabaseObjectRow[SysId]]", model_cls),
        )
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        plan = self._get_transaction_plan_lazy()
        prior_refs = _current_versioned_write_tail_refs(self, plan=plan)
        delete_ref = ServerPlanRefId(plan._next_ref())
        matched_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_lazy_support.MatchVersionedRowsByKeyToLiteralSequenceStep(
                matched_ref,
                model_cls=model_cls,
                staging_ctx=sc,
                config=versioned_lazy_support._MatchVersionedRowsByKeyConfig(
                    source_field_names=tuple(normalized_fields),
                    source_rows=tuple(tuple(row) for row in cast("Sequence[Sequence[object]]", rows)),
                    key_field_names=normalized_keys,
                    after_refs=prior_refs | frozenset({ServerPlanRefId(f"{delete_ref}_ensure")}),
                ),
            ),
        )
        result = self._add_intent(
            intent_versioning_extended.VersionedDeleteManyIntent(
                delete_ref,
                model_cls=model_cls,
                config=ServerRefs.scalar(
                    intent_versioning_extended._VersionedDeleteManyConfig(
                        sys_ids=(),
                        staging_ctx=sc,
                        after_refs=frozenset(),
                        source_ref=matched_ref,
                        expected_count=None,
                    ),
                ),
            ),
        )
        return _record_versioned_write_tail(
            self,
            result,
            context="delete_by_key_many_raw_lazy versioned raw key delete",
        )

    # ── Upsert ──

    @pure_lazy
    def upsert_many_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instances: _UpsertManyLazyInstances[T],
        conflict_columns: Sequence[Field[Any, T]] | None = None,
        on_conflict: Mapping[Field[Any, T], Expression[Any, T] | Field[Any, T]] | None = None,
        *,
        _do_nothing_inserted_only: bool = False,
    ) -> LazyResult[list[T]]:
        """Versioned upsert_many with pure-SQL conflict resolution per instance."""
        source = normalize_object_sequence_input(instances, context="upsert_many_lazy instances")
        concrete_list = source.literal_values

        if concrete_list is not None and not concrete_list:
            return LazyResult.of([])

        conflict_names: tuple[str, ...] | None = extract_field_names(tuple(list(conflict_columns))) if conflict_columns else None

        if not self._check_versioned_or_delegate(model_cls):
            plan = self._get_transaction_plan_lazy()
            _check_write_permission_lazy(self, model_cls)
            config_payload = intent_crud._shape_upsert_config_payload(
                list(conflict_columns) if conflict_columns else None,
                dict(on_conflict) if on_conflict is not None else None,
            )
            if source.source_ref_id is not None:
                return self._add_intent(
                    intent_crud.UpsertManyDeferredIntent(
                        ref_id=ServerPlanRefId(plan._next_ref()),
                        model_cls=model_cls,
                        instances=source.to_ref(),
                        config=ServerRefs.scalar(config_payload),
                    ),
                )
            assert concrete_list is not None
            return self._add_intent(
                intent_crud.UpsertManyIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    instances=ServerRefs.object_sequence(cast("Sequence[T]", concrete_list)),
                    config=ServerRefs.scalar(
                        intent_crud._shape_upsert_many_intent_config(
                            model_cls,
                            list(conflict_columns) if conflict_columns else None,
                            dict(on_conflict) if on_conflict is not None else None,
                            cast("Sequence[T]", concrete_list),
                            do_nothing_inserted_only=_do_nothing_inserted_only,
                        ),
                    ),
                ),
            )

        permission_context_ref, permission_context_type = _versioned_permission_context(
            self,
            model_cls,
        )
        self._mark_commit_branch_touched_model_lazy(
            cast("type[DatabaseObjectRow[SysId]]", model_cls),
            operation="update",
        )
        if source.source_ref_id is not None:
            context_refs = get_versioned_lazy_context_refs(self)
            sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
            plan = self._get_transaction_plan_lazy()
            return self._add_intent(
                intent_versioning_extended.VersionedUpsertManyBatchIntent(
                    ref_id=ServerPlanRefId(plan._next_ref()),
                    model_cls=model_cls,
                    instances=_require_object_sequence_source_ref(
                        source.to_ref(),
                        context="upsert_many_lazy deferred versioned instances",
                    ),
                    config=ServerRefs.scalar(
                        intent_versioning_extended._VersionedUpsertManyBatchConfig(
                            staging_ctx=sc,
                            conflict_columns=tuple(conflict_names) if conflict_names is not None else None,
                            on_conflict=cast(
                                Mapping[
                                    intent_versioning_extended._UpsertFieldIdentifier,
                                    intent_versioning_extended._BatchOnConflictValue,
                                ]
                                | None,
                                dict(on_conflict) if on_conflict is not None else None,
                            ),
                            permission_context_ref=permission_context_ref,
                            permission_context_type=permission_context_type,
                        ),
                    ),
                ),
            )

        assert concrete_list is not None
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        assert issubclass(model_cls, VersionedObjectRow)
        v_model = cast(type[VersionedObjectRow], model_cls)
        prepared_list = [self._prepare_versioned_instance(v_model, cast(VersionedObjectRow, inst), sc) for inst in concrete_list]

        plan = self._get_transaction_plan_lazy()
        builder = LazyBuilderContext(plan)
        instances_ref = builder.ref_for(prepared_list)
        config_ref = builder.ref_for(
            intent_versioning_extended._VersionedUpsertManyBatchConfig(
                staging_ctx=sc,
                conflict_columns=tuple(conflict_names) if conflict_names is not None else None,
                on_conflict=cast(
                    Mapping[
                        intent_versioning_extended._UpsertFieldIdentifier,
                        intent_versioning_extended._BatchOnConflictValue,
                    ]
                    | None,
                    dict(on_conflict) if on_conflict is not None else None,
                ),
                literal_instances=tuple(prepared_list),
                permission_context_ref=permission_context_ref,
                permission_context_type=permission_context_type,
            ),
        )
        return self._add_intent(
            intent_versioning_extended.VersionedUpsertManyBatchIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                model_cls=model_cls,
                instances=cast("ObjectSequenceServerRef[T]", instances_ref),
                config=cast(
                    "ScalarServerRef[intent_versioning_extended._VersionedUpsertManyBatchConfig]",
                    config_ref,
                ),
            ),
        )

    @overload
    def upsert_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: LazyResult[T],
        conflict_columns: Sequence[Field[Any, T]] | None = None,
        on_conflict: Mapping[Field[Any, T], Expression[Any, T] | Field[Any, T]] | None = None,
        *,
        on_conflict_where: Expression[bool, T] | None = None,
        after_refs: Sequence[ServerPlanRefId] = (),
        return_raw_rows: Literal[False] = False,
    ) -> LazyResult[T]: ...

    @overload
    def upsert_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: LazyResult[T],
        conflict_columns: Sequence[Field[Any, T]] | None = None,
        on_conflict: Mapping[Field[Any, T], Expression[Any, T] | Field[Any, T]] | None = None,
        *,
        on_conflict_where: Expression[bool, T] | None = None,
        after_refs: Sequence[ServerPlanRefId] = (),
        return_raw_rows: Literal[True],
    ) -> LazyResult[list[dict[str, object]]]: ...

    @pure_lazy
    def upsert_lazy[T: DatabaseObjectRow](
        self: VersionedWriteTransactionLazyMixin,
        model_cls: type[T],
        instance: LazyResult[T],
        conflict_columns: Sequence[Field[Any, T]] | None = None,
        on_conflict: Mapping[Field[Any, T], Expression[Any, T] | Field[Any, T]] | None = None,
        *,
        on_conflict_where: Expression[bool, T] | None = None,
        after_refs: Sequence[ServerPlanRefId] = (),
        return_raw_rows: bool = False,
    ) -> LazyResult[T] | LazyResult[list[dict[str, object]]]:
        """Versioned upsert with pure-SQL conflict resolution."""
        if not self._check_versioned_or_delegate(model_cls):
            base_txn = cast(_VersionedWriteTxnState, self).base_write_transaction
            if return_raw_rows:
                return base_txn.upsert_lazy(
                    model_cls,
                    instance,
                    conflict_columns,
                    on_conflict,
                    on_conflict_where=on_conflict_where,
                    after_refs=after_refs,
                    return_raw_rows=True,
                )
            return base_txn.upsert_lazy(
                model_cls,
                instance,
                conflict_columns,
                on_conflict,
                on_conflict_where=on_conflict_where,
                after_refs=after_refs,
                return_raw_rows=False,
            )

        if on_conflict_where is not None or return_raw_rows:
            msg = "Versioned upsert does not support conditional conflict predicates or raw rows"
            raise ValueError(msg)
        plan = self._get_transaction_plan_lazy()
        _check_write_permission_lazy(self, model_cls)
        permission_context_ref, permission_context_type = _versioned_permission_context(
            self,
            model_cls,
        )
        self._mark_commit_branch_touched_model_lazy(cast("type[DatabaseObjectRow[SysId]]", model_cls), operation="update")
        context_refs = get_versioned_lazy_context_refs(self)
        sc = self._get_versioned_staging_context(model_cls, context_refs=context_refs)
        source_ref = _published_lazy_ref_id(instance, context="upsert_lazy instance")
        normalized_after_refs = frozenset(ServerPlanRefId(ref) for ref in after_refs)
        if source_ref is not None:
            intent: intent_versioning_extended.VersionedUpsertIntent[Any] | intent_versioning_extended.VersionedUpsertDeferredIntent[Any]
            intent = intent_versioning_extended.VersionedUpsertDeferredIntent(
                ServerPlanRefId(plan._next_ref()),
                cast("type[DatabaseObjectRow[SysId]]", model_cls),
                ServerRefs.from_ref_id(ServerPlanRefId(source_ref), variant="object"),
                ServerRefs.scalar(
                    intent_versioning_extended._VersionedUpsertIntentConfig(
                        staging_ctx=sc,
                        conflict_columns=tuple(cast("Sequence[Any]", conflict_columns)) if conflict_columns else None,
                        on_conflict=cast("Mapping[Any, Any] | None", dict(on_conflict) if on_conflict is not None else None),
                        after_refs=normalized_after_refs,
                        permission_context_ref=permission_context_ref,
                        permission_context_type=permission_context_type,
                    )
                ),
            )
        else:
            literal_instance = _require_concrete_lazy_input(instance, context="upsert_lazy instance")
            builder = LazyBuilderContext(plan)
            intent = intent_versioning_extended.VersionedUpsertIntent(
                ServerPlanRefId(plan._next_ref()),
                cast("type[DatabaseObjectRow[SysId]]", model_cls),
                cast("ObjectServerRef[DatabaseObjectRow[SysId]]", builder.ref_for(literal_instance)),
                cast(
                    "ScalarServerRef[Any]",
                    builder.ref_for(
                        intent_versioning_extended._VersionedUpsertIntentConfig(
                            staging_ctx=sc,
                            conflict_columns=tuple(cast("Sequence[Any]", conflict_columns)) if conflict_columns else None,
                            on_conflict=cast("Mapping[Any, Any] | None", dict(on_conflict) if on_conflict is not None else None),
                            after_refs=normalized_after_refs,
                            permission_context_ref=permission_context_ref,
                            permission_context_type=permission_context_type,
                        )
                    ),
                ),
            )
        return self._add_intent(intent)

    # ── Transaction lifecycle ──

    @pure_lazy
    def commit_lazy(self: VersionedWriteTransactionLazyMixin) -> LazyResult[Literal[None]]:
        """Versioned commit: flush pending lazy ORM ops, then commit.

        ``commit()`` is always stage-only for versioned writes.  Publication is
        explicit through ``commit_branch()`` / ``commit_branch_async()``.  This
        split is load-bearing for DoltDB: its native branch publish must first
        make staged SQL writes visible to ``DOLT_COMMIT``, but that staging
        precondition is an implementation detail inside ``commit_branch()``, not
        a public reinterpretation of ``commit()`` as publish.

        The lowering of CommitIntent (in sql_backend_executor) detects that
        the transaction is versioned and prepends a VersionedStateMarkStep.
        """
        txn = cast(_VersionedWriteTxnState, self)
        had_pending_commit = bool(getattr(txn, "_has_pending_lazy_commit", False))
        self._flush_pending_lazy_ops_to_plan()
        from l2055_lazy_result.commit_refs import commit_after_refs_lazy

        plan = self._get_transaction_plan_lazy()
        plan.mark_terminal_lifecycle_selected()
        prior_refs = frozenset(ServerPlanRefId(step.ref_id) for step in plan._steps)
        if had_pending_commit:
            result = commit_after_refs_lazy(
                self,
                after_refs=prior_refs,
                flush_pending_ops=False,
            )
        else:
            object.__setattr__(self, "_has_pending_lazy_commit", True)
            result = commit_after_refs_lazy(self, after_refs=prior_refs, flush_pending_ops=True)
        object.__setattr__(self, "_latest_stage_commit_result", result)
        return result

    @pure_lazy
    def commit_staged_lazy(self: VersionedWriteTransactionLazyMixin) -> LazyResult[Literal[None]]:
        """Durably commit staged rows after all prior lazy plan work."""

        plan = self._get_transaction_plan_lazy()
        prior_refs = frozenset(ServerPlanRefId(step.ref_id) for step in plan._steps)
        return self.commit_staged_after_refs_lazy(after_refs=prior_refs)

    @pure_lazy
    def commit_staged_after_refs_lazy(
        self: VersionedWriteTransactionLazyMixin,
        *after: LazyResult[Any] | object,
        after_refs: Iterable[ServerPlanRefId] = frozenset(),
    ) -> LazyResult[Literal[None]]:
        """Durably commit staged rows without publish-grade lifecycle work."""

        from l2055_lazy_result.commit_refs import collect_plan_ref_dependencies

        object.__setattr__(self, "_has_pending_lazy_commit", True)
        depends_on = set(collect_plan_ref_dependencies(*after, after_refs=after_refs))
        depends_on.update(ServerPlanRefId(ref) for ref in self._flush_pending_lazy_ops_to_plan())
        plan = self._get_transaction_plan_lazy()
        return self._add_intent(
            intent_transaction.StagedCommitIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                depends_on=frozenset(depends_on),
            ),
        )

    @legacy_sync
    def commit_staged(self: VersionedWriteTransactionLazyMixin) -> None:
        raise AssertionError("legacy_sync should delegate to commit_staged_lazy()")

    @legacy_async
    async def commit_staged_async(self: VersionedWriteTransactionLazyMixin) -> None:
        raise AssertionError("legacy_async should delegate to commit_staged_lazy()")

    @legacy_sync
    def commit_staged_after_refs(
        self: VersionedWriteTransactionLazyMixin,
        *after: object,
        after_refs: Iterable[ServerPlanRefId] = frozenset(),
    ) -> None:
        raise AssertionError("legacy_sync should delegate to commit_staged_after_refs_lazy()")

    @legacy_async
    async def commit_staged_after_refs_async(
        self: VersionedWriteTransactionLazyMixin,
        *after: object,
        after_refs: Iterable[ServerPlanRefId] = frozenset(),
    ) -> None:
        raise AssertionError("legacy_async should delegate to commit_staged_after_refs_lazy()")

    @pure_lazy
    def rollback_lazy(self: VersionedWriteTransactionLazyMixin) -> LazyResult[Literal[None]]:
        """Add a rollback intent; executor lifecycle owns pending-op cleanup."""
        self._flush_pending_lazy_ops_to_plan()
        plan = self._get_transaction_plan_lazy()
        plan.mark_terminal_lifecycle_selected()
        prior_refs = frozenset(ServerPlanRefId(step.ref_id) for step in plan._steps)
        object.__setattr__(self, "_has_pending_lazy_commit", True)
        return self._add_intent(
            intent_transaction.RollbackIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                depends_on=prior_refs,
            ),
        )

    @pure_lazy
    def publish_revision_lazy(
        self: VersionedWriteTransactionLazyMixin,
        *,
        ordered_parent_revision_ids: Sequence[RevisionId],
        expected_tip_revision_id: RevisionId | None = None,
        rippling: bool | None = None,
        allow_empty: bool = False,
        rollup_all_connections: bool = False,
        rollup_my_connection: bool = False,
        revision_id: RevisionId | None = None,
        **revision_metadata: _RevisionMetadataValue,
    ) -> LazyResult[RevisionId]:
        """Atomically publish staged result state with ordered revision parents.

        For a non-empty sequence, the first parent is the target-side parent and
        branch-tip compare-and-swap value. An empty sequence publishes a true root
        and requires an explicit branch-tip compare-and-swap value.
        """
        parents = tuple(ordered_parent_revision_ids)
        if len(set(parents)) != len(parents):
            raise ValueError("publish_revision ordered parents contain a duplicate parent revision")
        if parents:
            effective_expected_tip = parents[0]
            if expected_tip_revision_id is not None and expected_tip_revision_id != effective_expected_tip:
                raise ValueError("publish_revision expected tip must equal the first ordered parent revision")
        else:
            if expected_tip_revision_id is None:
                raise ValueError(
                    "publish_revision requires expected_tip_revision_id when ordered parents are empty",
                )
            effective_expected_tip = expected_tip_revision_id
        if revision_id is not None and revision_id in parents:
            raise ValueError("publish_revision cannot declare the new revision as its own parent")
        return self.commit_branch_after_refs_lazy(
            expected_tip_revision_id=effective_expected_tip,
            ordered_parent_revision_ids=parents,
            rippling=rippling,
            allow_empty=allow_empty,
            rollup_all_connections=rollup_all_connections,
            rollup_my_connection=rollup_my_connection,
            revision_id=revision_id,
            flush_pending_ops=True,
            revision_metadata_values=revision_metadata,
        )

    @pure_lazy
    def commit_branch_lazy(
        self: VersionedWriteTransactionLazyMixin,
        *,
        expected_tip_revision_id: RevisionId | LazyResult[RevisionId] | ScalarServerRef[RevisionId] | None = None,
        rippling: bool | None = None,
        allow_empty: bool = False,
        rollup_all_connections: bool = False,
        rollup_my_connection: bool = False,
        revision_id: RevisionId | None = None,
        **revision_metadata: _RevisionMetadataValue,
    ) -> LazyResult[RevisionId]:
        """Add a CommitBranchIntent after currently queued versioned writes."""
        selected_ids_value = revision_metadata.pop("explicit_staged_commit_ids", ())
        if not isinstance(selected_ids_value, Iterable) or isinstance(selected_ids_value, (str, bytes)):
            raise TypeError("explicit_staged_commit_ids must be an iterable of StagedCommitId values")
        selected_staged_values: tuple[object, ...] = tuple(selected_ids_value)
        if any(not isinstance(staged_id, StagedCommitId) for staged_id in selected_staged_values):
            raise TypeError("explicit_staged_commit_ids must contain only StagedCommitId values")
        explicit_staged_commit_ids: tuple[StagedCommitId, ...] = tuple(
            staged_id for staged_id in selected_staged_values if isinstance(staged_id, StagedCommitId)
        )
        txn = cast(_VersionedWriteTxnState, self)
        txn._check_versioned_publish_lifecycle(operation="commit_branch() / commit_branch_async()")
        return self.commit_branch_after_refs_lazy(
            expected_tip_revision_id=expected_tip_revision_id,
            rippling=rippling,
            allow_empty=allow_empty,
            rollup_all_connections=rollup_all_connections,
            rollup_my_connection=rollup_my_connection,
            explicit_staged_commit_ids=explicit_staged_commit_ids,
            revision_id=revision_id,
            flush_pending_ops=True,
            revision_metadata_values=revision_metadata,
        )

    @pure_lazy
    def commit_branch_after_refs_lazy(
        self: VersionedWriteTransactionLazyMixin,
        *after: LazyResult[Any] | object,
        before_commit_refs: frozenset[ServerPlanRefId] = frozenset(),
        expected_tip_revision_id: RevisionId | LazyResult[RevisionId] | ScalarServerRef[RevisionId] | None = None,
        ordered_parent_revision_ids: tuple[RevisionId, ...] | None = None,
        _ordered_parent_relationship_types: tuple[ParentType, ...] | None = None,
        rippling: bool | None = None,
        allow_empty: bool = False,
        rollup_all_connections: bool = False,
        rollup_my_connection: bool = False,
        explicit_staged_commit_ids: Iterable[StagedCommitId] = (),
        defer_database_commit: bool = False,
        after_refs: Iterable[ServerPlanRefId] = frozenset(),
        flush_pending_ops: bool = True,
        revision_id: RevisionId | None = None,
        revision_metadata_values: Mapping[str, _RevisionMetadataValue] | None = None,
        _revision_timestamp: AwareDatetime | None = None,
        _revision_session_id: SessionId | None = None,
        **revision_metadata: _RevisionMetadataValue,
    ) -> LazyResult[RevisionId]:
        """Add a CommitBranchIntent after explicit plan-owned predecessor refs."""
        from l2055_lazy_result.commit_refs import collect_plan_ref_dependencies

        before_commit_refs = frozenset(
            {
                *before_commit_refs,
                *self._precommit_validation_refs,
            },
        )
        _reject_private_publication_metadata_lazy(revision_metadata)
        if revision_metadata_values is not None:
            _reject_private_publication_metadata_lazy(revision_metadata_values)
        if _ordered_parent_relationship_types is not None and (
            ordered_parent_revision_ids is None or len(_ordered_parent_relationship_types) != len(ordered_parent_revision_ids)
        ):
            raise ValueError("Ordered parent relationship types must match the ordered parent revisions")
        object.__setattr__(self, "_has_pending_lazy_commit", True)
        txn = cast(_VersionedWriteTxnState, self)
        txn._check_versioned_publish_lifecycle(operation="commit_branch() / commit_branch_async()")
        txn._prepare_commit_branch_publish(rippling=rippling)
        plan = self._get_transaction_plan_lazy()
        plan.mark_terminal_lifecycle_selected()
        prepublish_dependencies = set(collect_plan_ref_dependencies(*after, after_refs=after_refs))
        context_refs = get_versioned_lazy_context_refs(txn)
        full_context_refs = get_versioned_context_refs(txn)
        branch_ref = versioned_lazy_context_branch_ref(context_refs, context=DiagnosticLabel("commit_branch_lazy branch_id"))
        branch_ref, superseded_branch_dependency_refs = _refresh_callback_branch_ref_if_needed(
            txn,
            plan,
            branch_ref,
        )
        branch_dependency_refs = {ServerPlanRefId(ref) for ref in lazy_param_deps(branch_ref)}
        steps_by_ref = {str(step.ref_id): step for step in plan._steps}
        write_context_dependency_refs = set(txn._write_branch_context_dependency_refs)
        write_context_symbolic_roots: set[ServerPlanRefId] = set()
        write_context_result = txn._write_branch_context_result
        if isinstance(write_context_result, LazyResult):
            write_context_shape = inspect_server_value_shape_for_planning(
                write_context_result,
                site="commit_branch_lazy write context ordering",
            )
            if write_context_shape.symbolic_ref_id is not None:
                write_context_symbolic_roots.add(ServerPlanRefId(write_context_shape.symbolic_ref_id))
        if full_context_refs is not None:
            write_context_dependency_refs.update(full_context_refs.dependency_refs)

        def dependency_closure(refs: Iterable[ServerPlanRefId]) -> set[ServerPlanRefId]:
            pending = [ServerPlanRefId(ref) for ref in refs]
            seen: set[ServerPlanRefId] = set()
            while pending:
                ref = pending.pop()
                if ref in seen:
                    continue
                seen.add(ref)
                step = steps_by_ref.get(str(ref))
                if step is not None:
                    pending.extend(ServerPlanRefId(dep) for dep in step.dependencies())
            return seen

        branch_dependency_closure_refs = dependency_closure(
            branch_dependency_refs | write_context_dependency_refs,
        )
        branch_publish_dependency_refs = branch_dependency_closure_refs - write_context_symbolic_roots
        prepublish_dependencies.update(branch_publish_dependency_refs)
        if flush_pending_ops:
            # Ensure deferred update/delete operations are materialized into the plan
            # before publishing staged commits as a branch revision.
            prepublish_dependencies.update(ServerPlanRefId(ref) for ref in self._flush_pending_lazy_ops_to_plan())
        publication_state = _require_versioned_publication_state(txn, plan=plan)
        active_epoch = _require_active_publication_epoch(txn)
        commit_effect_frontier = active_epoch.frontier
        if publication_state is not None:
            publication_ref = publication_state[0]
            unordered_effects = tuple(
                effect.semantic_ref
                for effect in commit_effect_frontier.effects
                if publication_ref not in plan.producer_dependency_closure(frozenset({effect.semantic_ref}))
            )
            if unordered_effects:
                msg = (
                    "versioned.publication_epoch.successor_ordered: successor staged effects "
                    f"must depend on publication {publication_ref!r}; producers={unordered_effects!r}."
                )
                raise ValueError(msg)
        live_commit_effects = _plan_owned_commit_effects(plan, commit_effect_frontier)
        write_tail_refs = {effect.physical_effect_ref for effect in live_commit_effects}
        prepublish_dependencies.update(write_tail_refs)

        explicit_after_value_refs: set[ServerPlanRefId] = set()
        response_wrapper_dependency_refs: dict[ServerPlanRefId, frozenset[ServerPlanRefId]] = {}
        dependency_free_response_wrapper_refs: set[ServerPlanRefId] = set()
        for value in after:
            ref_id = _published_value_ref_id(value, context="commit_branch_after_refs_lazy after dependency")
            if ref_id is None:
                continue
            explicit_after_ref = ServerPlanRefId(ref_id)
            explicit_after_value_refs.add(explicit_after_ref)
            prepublish_dependencies.add(explicit_after_ref)
            step = steps_by_ref.get(str(ref_id))
            if step is None:
                continue
            dependency_refs = frozenset(ServerPlanRefId(dep) for dep in step.dependencies())
            is_ordering_only_response = type(step).__name__ == "StaticValueAfterDepsIntent" or step.allows_later_sql_transport()
            if dependency_refs and is_ordering_only_response:
                response_wrapper_dependency_refs[ServerPlanRefId(ref_id)] = dependency_refs
            elif not dependency_refs and is_ordering_only_response:
                dependency_free_response_wrapper_refs.add(ServerPlanRefId(ref_id))
        expanded_dependencies: set[ServerPlanRefId] = set()
        for ref in prepublish_dependencies:
            replacement_refs = response_wrapper_dependency_refs.get(ref)
            if replacement_refs is not None:
                expanded_dependencies.update(replacement_refs)
                continue
            step = steps_by_ref.get(str(ref))
            step_dependencies = step.dependencies() if step is not None else frozenset()
            expanded_dependencies.add(ref)
            if step is not None and step.is_read_only() and step_dependencies:
                expanded_dependencies.update(ServerPlanRefId(dep) for dep in step_dependencies)
        prepublish_dependencies = set(
            _versioned_publish_dependencies(
                plan,
                expanded_dependencies,
                always_keep={
                    *branch_publish_dependency_refs,
                    *branch_dependency_closure_refs,
                    *write_tail_refs,
                    *dependency_free_response_wrapper_refs,
                    *explicit_after_value_refs,
                },
                future_physical_effect_refs=write_tail_refs,
            ),
        )
        prepublish_dependencies.update(ServerPlanRefId(ref) for ref in after_refs)

        merged_revision_metadata: dict[str, _RevisionMetadataValue] = {}
        if revision_metadata_values is not None:
            merged_revision_metadata.update(revision_metadata_values)
        merged_revision_metadata.update(revision_metadata)
        effective_revision_metadata = _with_default_revision_metadata(
            merged_revision_metadata,
            schema_metadata=_schema_metadata_snapshot_for_revision_metadata(txn),
        )

        ref_id = ServerPlanRefId(plan._next_ref())
        domain = txn.domain
        connection_id: ConnectionId | None = txn.connection_id
        session_id = txn.session_id
        inline_staged_commit_id = txn._staged_commit_id

        prepublish_dependencies.difference_update(superseded_branch_dependency_refs)
        branch_scope_token = txn._branch_scope_token
        session_ref = ServerRefs.scalar(session_id)
        implicit_expected_tip = expected_tip_revision_id
        if not isinstance(implicit_expected_tip, RevisionId | LazyResult | ScalarServerRef):
            if txn._concurrent_commit_behavior == ConcurrentBranchCommitBehavior.FAIL_FAST:
                implicit_expected_tip = txn._base_revision_id
        expected_tip_ref = normalize_optional_scalar_input(
            implicit_expected_tip,
            context="commit_branch_lazy expected_tip_revision_id",
        )
        if rollup_all_connections and rollup_my_connection:
            msg = "commit_branch: rollup_all_connections=True and rollup_my_connection=True are mutually exclusive. Pass at most one."
            raise ValueError(msg)
        selected_staged_commit_ids = tuple(dict.fromkeys(explicit_staged_commit_ids))
        if selected_staged_commit_ids and (rollup_all_connections or rollup_my_connection):
            msg = "commit_branch: explicit_staged_commit_ids cannot be combined with rollup_all_connections or rollup_my_connection"
            raise ValueError(msg)
        if rollup_my_connection and (connection_id is None or not connection_id.unwrap_to_str()):
            msg = "commit_branch: rollup_my_connection=True requires a non-empty connection_id"
            raise ValueError(msg)
        revision_metadata_payload = intent_transaction._RevisionMetadataPayload(
            values=effective_revision_metadata,
        )
        if plan._steps and isinstance(plan._steps[-1], intent_transaction.CommitIntent):
            pending_commit = plan._steps[-1]
            plan._steps[-1] = intent_transaction.CommitIntentElidedByCommitBranchStep(
                ServerPlanRefId(pending_commit.ref_id),
            )
        inline_touched_tables_raw = txn._inline_touched_versioned_tables
        inline_deleted_tables_raw = txn._inline_deleted_versioned_tables
        inline_touched_tables = _table_name_set(inline_touched_tables_raw)
        inline_deleted_tables = _table_name_set(inline_deleted_tables_raw)
        connection_speculative_publish_table_names = self._connection_speculative_publish_table_names(
            all_connections=rollup_all_connections,
        )
        connection_speculative_non_insert_table_names = self._connection_speculative_non_insert_table_names(
            all_connections=rollup_all_connections,
        )
        connection_speculative_deleted_table_names = self._connection_speculative_deleted_table_names(
            all_connections=rollup_all_connections,
        )
        connection_speculative_insert_only_table_names = self._connection_speculative_insert_only_table_names(
            all_connections=rollup_all_connections,
        )
        plan_staging_table_names = self._plan_staging_table_names_hint()
        if plan_staging_table_names:
            inline_touched_tables = set(inline_touched_tables or ()) | plan_staging_table_names
        if connection_speculative_publish_table_names:
            inline_touched_tables = set(inline_touched_tables or ()) | connection_speculative_publish_table_names
        if connection_speculative_deleted_table_names:
            inline_deleted_tables = set(inline_deleted_tables or ()) | connection_speculative_deleted_table_names
        if connection_speculative_non_insert_table_names:
            inline_touched_tables = set(inline_touched_tables or ()) | connection_speculative_non_insert_table_names
        side_effect_expanded = False
        if inline_touched_tables:
            unexpanded_touched_tables = set(inline_touched_tables)
            inline_touched_tables = self._expand_speculative_publish_tables_for_side_effects(
                inline_touched_tables,
            )
            side_effect_expanded = inline_touched_tables != unexpanded_touched_tables
            _require_touched_tables_in_domain(
                txn,
                inline_touched_tables,
                operation="commit_branch_lazy",
            )
        has_inline_touched_tables = bool(inline_touched_tables)
        scope_kind: intent_transaction.CommitBranchScopeKind
        inline_id_for_intent: StagedCommitId | None
        connection_id_for_intent: ConnectionId | None
        staged_visibility = txn._staged_visibility
        if rollup_my_connection:
            if connection_id is None or not connection_id.unwrap_to_str():
                msg = "commit_branch: rollup_my_connection=True requires a non-empty connection_id"
                raise ValueError(msg)
            scope_kind = "connection_scoped"
            inline_id_for_intent = None
            connection_id_for_intent = connection_id
        elif staged_visibility is StagedVisibility.CONNECTION and connection_id is not None and not rollup_all_connections:
            scope_kind = "connection_scoped"
            inline_id_for_intent = inline_staged_commit_id if has_inline_touched_tables else None
            connection_id_for_intent = connection_id
        elif inline_staged_commit_id is not None and not rollup_all_connections:
            scope_kind = "inline"
            inline_id_for_intent = inline_staged_commit_id
            connection_id_for_intent = None
        elif connection_id is not None and not rollup_all_connections:
            scope_kind = "connection_scoped"
            inline_id_for_intent = inline_staged_commit_id if has_inline_touched_tables else None
            connection_id_for_intent = connection_id
        else:
            scope_kind = "branch_scoped"
            inline_id_for_intent = inline_staged_commit_id if has_inline_touched_tables else None
            connection_id_for_intent = None
        inline_touched_table_hint = frozenset(inline_touched_tables) if inline_touched_tables is not None else frozenset()
        effective_speculative_publish_table_names = None
        if inline_touched_table_hint:
            effective_speculative_publish_table_names = inline_touched_table_hint
        effective_speculative_insert_only_table_names: frozenset[SqlTableName] | None = (
            None if effective_speculative_publish_table_names is not None else frozenset()
        )
        if scope_kind in {"inline", "branch_scoped"} or side_effect_expanded:
            # Generated relationship, merge, and graph writes can change operation
            # kinds after planning. Keep the table hint without claiming insert-only work.
            effective_speculative_insert_only_table_names = frozenset()
        if (
            effective_speculative_insert_only_table_names is None
            and connection_speculative_insert_only_table_names is not None
            and effective_speculative_publish_table_names is not None
        ):
            effective_speculative_insert_only_table_names = frozenset(
                table_name
                for table_name in connection_speculative_insert_only_table_names
                if table_name in effective_speculative_publish_table_names
            )
        if scope_kind != "inline" and effective_speculative_publish_table_names is None:
            logger.warning(
                "Versioned publish is not using touched-table speculation. This should be exceedingly "
                "rare; if this occurs with any frequency, the speculation mechanism is broken and "
                "needs to be fixed. scope_kind=%s domain=%s connection_id=%s branch_ref=%s "
                "recorded_connection_facts=%s inline_touched_tables=%s plan_staging_table_names=%s",
                scope_kind,
                domain.name,
                connection_id.unwrap_to_uuid_compatible_str() if connection_id is not None else None,
                branch_ref,
                self._connection_speculative_publish_log_snapshot(),
                tuple(sorted(inline_touched_table_hint)),
                tuple(sorted(plan_staging_table_names)),
            )
        ordering_only_response_refs = set(response_wrapper_dependency_refs) | dependency_free_response_wrapper_refs
        live_explicit_after_value_refs = frozenset(
            ref
            for ref in explicit_after_value_refs
            if ref not in ordering_only_response_refs
            and any(str(ref) == step_ref or str(ref).startswith(f"{step_ref}.") for step_ref in steps_by_ref)
        )
        for explicit_ref in live_explicit_after_value_refs:
            producer = plan.producer_step(explicit_ref)
            dependency_probe = getattr(producer, "commit_dependency_ref_id", None)
            dependency_ref = dependency_probe() if callable(dependency_probe) else explicit_ref
            if not isinstance(dependency_ref, str):
                msg = "versioned.commit_effect.complete: commit dependency ref must be typed."
                raise TypeError(msg)
            _record_publication_epoch_write(
                txn,
                semantic_ref=explicit_ref,
                ordering_ref=ServerPlanRefId(dependency_ref),
            )
        active_epoch = _require_active_publication_epoch(txn)
        commit_effect_frontier = active_epoch.frontier
        live_commit_effects = _plan_owned_commit_effects(plan, commit_effect_frontier)
        prepublish_dependencies.update(effect.physical_effect_ref for effect in live_commit_effects)
        commit_input = _VersionedCommitBranchInput(
            branch_id=branch_ref,
            session_id=session_ref,
            expected_tip_revision_id=expected_tip_ref,
            allow_empty=allow_empty,
            is_new_branch=txn._is_new_branch,
            revision_metadata=revision_metadata_payload,
            scope_kind=scope_kind,
            inline_staged_commit_id=inline_id_for_intent,
            connection_id=connection_id_for_intent,
            explicit_staged_commit_ids=selected_staged_commit_ids,
            branch_scope_token=branch_scope_token,
            inline_touched_table_names=(
                frozenset(inline_touched_tables) if scope_kind == "inline" and inline_touched_tables is not None else None
            ),
            inline_deleted_table_names=(
                frozenset(inline_deleted_tables) if scope_kind == "inline" and inline_deleted_tables is not None else None
            ),
            speculative_publish_table_names=(effective_speculative_publish_table_names),
            prepublish_dependencies=frozenset(prepublish_dependencies),
            prepublish_result_dependencies=frozenset(
                effect.semantic_ref
                for effect in live_commit_effects
                if (producer := plan.producer_step(effect.semantic_ref)) is not None
                and producer.requires_prepublish_result_materialization()
            ),
        )
        intent = intent_transaction.make_commit_branch_intent(
            ref_id,
            domain=domain,
            branch_id=commit_input.branch_id,
            session_id=commit_input.session_id,
            allow_empty=commit_input.allow_empty,
            is_new_branch=commit_input.is_new_branch,
            revision_metadata=commit_input.revision_metadata,
            scope_kind=commit_input.scope_kind,
            inline_staged_commit_id=commit_input.inline_staged_commit_id,
            connection_id=commit_input.connection_id,
            explicit_staged_commit_ids=commit_input.explicit_staged_commit_ids,
            expected_tip_revision_id=commit_input.expected_tip_revision_id,
            ordered_parent_revision_ids=ordered_parent_revision_ids,
            ordered_parent_relationship_types=_ordered_parent_relationship_types,
            concurrent_commit_behavior=txn._concurrent_commit_behavior,
            branch_scope_token=commit_input.branch_scope_token,
            # Current branch reads are tip-backed even for legacy TIPLESS branch
            # metadata, so commits must keep the tip table current as well.
            materialize_tip=BranchTipMaterialization.MATERIALIZED,
            inline_touched_table_names=commit_input.inline_touched_table_names,
            inline_deleted_table_names=commit_input.inline_deleted_table_names,
            speculative_publish_table_names=commit_input.speculative_publish_table_names,
            speculative_insert_only_table_names=effective_speculative_insert_only_table_names,
            revision_id=revision_id,
            defer_database_commit=defer_database_commit,
            revision_timestamp=_revision_timestamp,
            revision_session_id=_revision_session_id,
        )
        publication_epoch = active_epoch
        epoch_id = publication_epoch.epoch_id
        effect_staged_commit_ids = tuple(
            dict.fromkeys(
                (
                    *(staged_commit_id for effect in live_commit_effects for staged_commit_id in effect.staged_commit_ids),
                    *(str(staged_commit_id) for staged_commit_id in selected_staged_commit_ids),
                    *((str(txn._staged_commit_id),) if txn._staged_commit_id is not None else ()),
                ),
            ),
        )
        if commit_effect_frontier.effects and not effect_staged_commit_ids and not allow_empty:
            msg = "versioned.admission.requirement_complete: non-empty staged effects require an exact staged-commit ID."
            raise ValueError(msg)
        intent.publication_epoch = publication_epoch
        intent.publication_epoch_id = epoch_id
        intent.staged_admission_source_keys = tuple(
            StagedSourceKey(
                staged_table_name=staged_table,
                branch_scope_token=str(branch_scope_token),
            )
            for effect in commit_effect_frontier.effects
            for staged_table in effect.staged_tables()
        )
        intent.staged_admission_producers = tuple(
            StagedRowProductionEffect(
                semantic_ref=effect.semantic_ref,
                physical_effect_ref=effect.physical_effect_ref,
                source_key=StagedSourceKey(
                    staged_table_name=staged_table,
                    branch_scope_token=str(branch_scope_token),
                ),
                staged_commit_id_raw=staged_commit_id_raw,
                epoch_id=epoch_id,
                source_generation=publication_epoch.source_generation,
                cardinality=effect.cardinality,
            )
            for effect in live_commit_effects
            for staged_table in effect.staged_tables()
            for staged_commit_id_raw in (effect.staged_commit_ids or effect_staged_commit_ids)
        )
        intent.prepublish_dependencies = frozenset(str(ref) for ref in commit_input.prepublish_dependencies)
        intent.precommit_dependencies = before_commit_refs
        result = self._add_intent(cast(Any, intent))
        if before_commit_refs:
            steps = plan.semantic_plan_builder.steps_snapshot()
            known_refs = {step.ref_id for step in steps}
            if not before_commit_refs <= known_refs:
                raise ValueError("Commit validation requires steps owned by this plan")
            selected_refs = set(before_commit_refs)
            all_steps = {step.ref_id: step for step in steps}
            read_steps = {ref: step for ref, step in all_steps.items() if step.is_read_only() and "precondition" not in step.step_tags()}
            while True:
                dependencies = {
                    ServerPlanRefId(dependency)
                    for ref in selected_refs
                    for dependency in all_steps[ref].dependencies()
                    if ServerPlanRefId(dependency) in read_steps
                }
                expanded = selected_refs | dependencies
                if expanded == selected_refs:
                    break
                selected_refs = expanded
            validations = tuple(step for step in steps if step.ref_id in selected_refs)
            if any(not step.is_read_only() for step in validations):
                raise ValueError("Precommit results and validation require read-only steps")
            anchor = intent.commit_validation_anchor()
            intent.precommit_validation_steps = tuple(step.with_commit_validation_anchor(anchor) for step in validations)
            plan.semantic_plan_builder.replace_steps(tuple(step for step in steps if step.ref_id not in selected_refs))
        intent.prepublish_result_dependencies = commit_input.prepublish_result_dependencies
        if result._pre_populated is not None:
            result._pre_populated = None
        object.__setattr__(self, "_latest_commit_branch_result", result)
        new_revision_shape = inspect_server_value_shape_for_planning(
            intent.new_revision_ref,
            site="publication successor revision",
        )
        new_revision_identity = (
            ServerPlanRefId(new_revision_shape.symbolic_ref_id)
            if new_revision_shape.symbolic_ref_id is not None
            else ServerPlanRefId(f"revision:{intent._new_revision_id}")
        )
        object.__setattr__(
            self,
            "_active_publication_epoch",
            publication_epoch.open_successor(
                publication_ref=ServerPlanRefId(intent.ref_id),
                revision_ref=new_revision_identity,
            ),
        )
        _require_versioned_publication_state(self, plan=plan)
        return result

