    @pure_lazy
    def squash_branch_lazy(
        self: VersionedWriteTransactionLazyMixin,
        *,
        base_revision_id: RevisionId,
        **revision_metadata: _RevisionMetadataValue,
    ) -> LazyResult[RevisionId]:
        """Add a SquashBranchIntent to the plan."""
        self._flush_pending_lazy_ops_to_plan()
        txn = cast(_VersionedWriteTxnState, self)
        if txn.has_unpublished_staged_changes:
            msg = "Cannot squash branch with unpublished staged writes; publish or roll them back first"
            raise db_exc.ProgrammingError(msg)

        effective_revision_metadata = _with_default_revision_metadata(
            revision_metadata,
            schema_metadata=_schema_metadata_snapshot_for_revision_metadata(txn),
        )

        plan = self._get_transaction_plan_lazy()
        intent_cls = (
            intent_merge.SquashBranchByIdIntent if "message" in revision_metadata else intent_merge.SquashBranchByIdDefaultMessageIntent
        )
        context_refs = get_versioned_lazy_context_refs(txn)
        return self._add_intent(
            intent_cls(
                ref_id=ServerPlanRefId(plan._next_ref()),
                domain=txn.domain,
                branch_id=versioned_lazy_context_branch_ref(
                    context_refs,
                    context=DiagnosticLabel("squash_branch_lazy branch_id"),
                ),
                base_revision_id=ServerRefs.scalar(base_revision_id),
                session_id=ServerRefs.scalar(txn.session_id),
                revision_metadata=ServerRefs.object(
                    intent_merge.shape_revision_metadata_payload(
                        domain=txn.domain,
                        provided=effective_revision_metadata,
                        default_message=None,
                        required_label="Squash branch",
                        skip_message_when_default_none=True,
                    ),
                ),
            ),
        )

