    @pure_lazy
    def row_lazy[T: DatabaseObjectRow](
        self: VersionedReadTransactionLazyMixin,
        row_id: LazyResult[RowId[T]],
        model_cls: type[T] | None = None,
    ) -> LazyResult[T]:
        """Lookup a row by typed RowId. Raises ObjectNotFoundError if not found.

        Adds a SelectOneRequiredIntent that compiles to the same SQL as
        select_one but whose post_op raises ObjectNotFoundError instead
        of returning None.

        When ``row_id`` is still pending (not yet resolved), an explicit
        ``model_cls`` is required so lowering can target the correct table
        before the ``RowId`` value exists. The pending ``LazyResult`` must
        carry a plan step ref pointing at the step that
        will produce the ``RowId``.
        """
        source_ref = _published_lazy_ref_id(row_id, context="row_lazy row_id")
        if source_ref is not None:
            if model_cls is None:
                msg = "row_lazy with pending LazyResult[RowId] requires an explicit model_cls for plan lowering"
                raise TypeError(msg)
            plan = self._get_transaction_plan_lazy()
            sys_id_ref = plan._next_ref()
            plan.add_step(
                versioned_lazy_support.SysIdFromResolvedRowIdStep(
                    sys_id_ref,
                    source_ref=source_ref,
                    explicit_model_cls=model_cls,
                ),
            )
            lazy_sys_id = self._add_intent_by_ref(sys_id_ref)
            return self._add_intent(
                cast(_SelectOneRequiredIntentFactory[T], intent_query.SelectOneRequiredIntent)(
                    ref_id=plan._next_ref(),
                    model_cls=model_cls,
                    sys_id=lazy_sys_id,
                ),
            )
        if not isinstance(row_id, LazyResult):
            msg = "Pending LazyResult[RowId] for row_lazy must carry a plan step ref"
            raise RuntimeError(msg)
        inner_id = _require_concrete_lazy_input(row_id, context="row_lazy row_id")
        resolved_model_cls = type(inner_id).resolve_target_table()
        if model_cls is not None and model_cls is not resolved_model_cls:
            msg = f"RowId target {resolved_model_cls.__name__} does not match explicit model_cls {model_cls.__name__}"
            raise TypeError(msg)
        plan = self._get_transaction_plan_lazy()
        sys_id = _row_id_to_sys_id(inner_id)
        return self._add_intent(
            intent_query.SelectOneRequiredIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                model_cls=resolved_model_cls,
                sys_id=ServerRefs.scalar(sys_id),
            ),
        )

