    def has_any_parent_lazy(
        self: VersionedReadTransactionLazyMixin,
        revision_id: RevisionId | LazyResult[RevisionId] | ScalarServerRef[RevisionId],
    ) -> LazyResult[bool]:
        plan = self._get_transaction_plan_lazy()
        revision_ref = self._metadata_revision_ref(revision_id)
        domain = _txn_domain(self)

        parent_exists_ref = ServerPlanRefId(plan._next_ref())
        self._add_intent(
            intent_query_extended.QueryExistsIntent(
                ref_id=parent_exists_ref,
                model_cls=domain.revision_parent_model,
                config=intent_query_extended._QueryExistsConfig(
                    query_spec=revision_metadata_query_specs.revision_parent_exists_spec(
                        domain,
                        revision_id=revision_ref,
                    ),
                ),
            ),
        )

        legacy_exists_ref = ServerPlanRefId(plan._next_ref())
        self._add_intent(
            intent_query_extended.QueryExistsIntent(
                ref_id=legacy_exists_ref,
                model_cls=domain.revision_model,
                config=intent_query_extended._QueryExistsConfig(
                    query_spec=revision_metadata_query_specs.legacy_parent_exists_spec(
                        domain,
                        revision_id=revision_ref,
                    ),
                ),
            ),
        )

        out_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_lazy_support.BoolOrStep(
                ServerPlanRefId(out_ref),
                left_ref=str(parent_exists_ref),
                right_ref=str(legacy_exists_ref),
            ),
        )
        return cast(LazyResult[bool], self._add_intent_by_ref(out_ref))

    @pure_lazy
    def primary_parent_lazy(
        self: VersionedReadTransactionLazyMixin,
        revision_id: RevisionId | LazyResult[RevisionId] | ScalarServerRef[RevisionId],
    ) -> LazyResult[RevisionId | None]:
        plan = self._get_transaction_plan_lazy()
        revision_ref = self._metadata_revision_ref(revision_id)
        domain = _txn_domain(self)

        parent_raw_ref = ServerPlanRefId(plan._next_ref())
        parent_value_ref = ServerPlanRefId(plan._next_ref())
        self._add_intent(
            intent_query_extended.QueryExecuteRawIntent(
                ref_id=parent_raw_ref,
                model_cls=domain.revision_parent_model,
                config=intent_query_extended._QueryExecuteRawConfig(
                    query_spec=revision_metadata_query_specs.first_parent_row_spec(
                        domain,
                        revision_id=revision_ref,
                    ),
                ),
            ),
        )
        plan.add_step(
            versioned_lazy_support.ProjectScalarFieldFromRowSourceStep(
                parent_value_ref,
                source_ref=parent_raw_ref,
                field_name=SqlColumnName("parent_revision_sys_id"),
                scalar_coercion=ScalarCoercionKind.REVISION_ID,
            ),
        )

        legacy_raw_ref = ServerPlanRefId(plan._next_ref())
        legacy_value_ref = ServerPlanRefId(plan._next_ref())
        self._add_intent(
            intent_query_extended.QueryExecuteRawIntent(
                ref_id=legacy_raw_ref,
                model_cls=domain.revision_model,
                config=intent_query_extended._QueryExecuteRawConfig(
                    query_spec=revision_metadata_query_specs.legacy_parent_row_spec(
                        domain,
                        revision_id=revision_ref,
                    ),
                ),
            ),
        )
        plan.add_step(
            versioned_lazy_support.ProjectScalarFieldFromRowSourceStep(
                legacy_value_ref,
                source_ref=legacy_raw_ref,
                field_name=SqlColumnName("parent_revision_sys_id"),
                scalar_coercion=ScalarCoercionKind.REVISION_ID,
            ),
        )

        out_ref = ServerPlanRefId(plan._next_ref())
        plan.add_step(
            versioned_lazy_support.CoalesceScalarStep[RevisionId](
                out_ref,
                primary_ref=parent_value_ref,
                fallback_ref=legacy_value_ref,
                scalar_coercion=ScalarCoercionKind.REVISION_ID,
            ),
        )
        return cast("LazyResult[RevisionId | None]", self._add_intent_by_ref(out_ref))

