    @pure_lazy
    def get_revision_at_timestamp_lazy(
        self: VersionedReadTransactionLazyMixin,
        branch_id: BranchId,
        target_timestamp: AwareDatetime,
    ) -> LazyResult[RevisionId | None]:
        """Query for the latest revision at or before ``target_timestamp``."""
        if target_timestamp.tzinfo is None or target_timestamp.utcoffset() is None:
            raise ValueError("target_timestamp must be timezone-aware. Use datetime.now(UTC) or a timezone-aware datetime.")

        plan = self._get_transaction_plan_lazy()
        return self._add_intent(
            intent_versioning_extended.RevisionAtTimestampIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                config=intent_versioning_extended._RevisionAtTimestampConfig(
                    branch_id=ServerRefs.scalar(branch_id),
                    target_timestamp=ServerRefs.scalar(target_timestamp),
                    domain=_txn_domain(self),
                ),
            ),
        )

    @pure_lazy
    def graph_lazy[T: Graph[Any]](
        self: VersionedReadTransactionLazyMixin,
        graph_id: GraphId,
        graph_type: type[T],
    ) -> SqlPlanGraphQuery:
        context_refs = get_versioned_lazy_context_refs(self)
        materialization = _versioned_lazy_materialization_policy(self)
        from l7200_versioned_transactions.induced_fragment_adapter import (
            observe_induced_graph_snapshot_lazy,
        )

        if _txn_domain(self) is None:
            msg = "Versioned graph visibility requires an explicit versioning domain"
            raise RuntimeError(msg)
        fragment_snapshot = observe_induced_graph_snapshot_lazy(
            self,
            graph_id=graph_id,
            graph_type=graph_type,
        )
        readthrough_delegates = _readthrough_user_session_delegates_graph_visibility(self)
        initial_binding = (
            _graph_result_intent_binding(
                self,
                graph_id=graph_id,
                graph_type=graph_type,
                context_refs=context_refs,
                materialization=materialization,
            )
            if readthrough_delegates
            else None
        )

        def terminal_binding_factory() -> GraphTerminalBinding:
            terminal_validated_ref, terminal_pending_factory, terminal_registrar, terminal_graph_ref = _enqueue_graph_visibility_guard(
                self,
                graph_id=graph_id,
                graph_type=graph_type,
                context_refs=context_refs,
                materialization=materialization,
                context="graph terminal visible_graph",
                reuse_cached=False,
            )
            return GraphTerminalBinding(
                registrar=terminal_registrar,
                pending_ctx_config_factory=terminal_pending_factory,
                graph_id_source=terminal_graph_ref,
                after_refs=frozenset({terminal_validated_ref}),
            )

        def graph_result_binding_factory(
            result_graph_type: type[Graph],
        ) -> GraphResultIntentBinding:
            if result_graph_type is not graph_type:
                msg = "Graph result witness does not match the bound graph type"
                raise ValueError(msg)
            return _graph_result_intent_binding(
                self,
                graph_id=graph_id,
                graph_type=graph_type,
                context_refs=context_refs,
                materialization=materialization,
            )

        fragment_registrar = _InducedGraphResultBinder(self)

        def fragment_pending_ctx_config_factory() -> intent_graph._ResolveGraphExecutionCtxConfig:
            msg = "fragment-only graph binding cannot compile a terminal directly"
            raise RuntimeError(msg)

        graph_handle = SqlPlanGraphQuery(
            registrar=(fragment_registrar if initial_binding is None else initial_binding.registrar),
            pending_ctx_config_factory=(
                fragment_pending_ctx_config_factory if initial_binding is None else initial_binding.pending_ctx_config_factory
            ),
            graph_id=(
                ServerRefs.unbound_scalar(GraphId) if initial_binding is None else initial_binding.registrar.scalar_ref_for(graph_id)
            ),
            graph_id_source=graph_id,
            graph_type=graph_type,
            versioning_strategy_preview=_graph_versioning_strategy_preview(self, context_refs, materialization),
            terminal_binding_factory=(None if readthrough_delegates else terminal_binding_factory),
            graph_result_binding_factory=graph_result_binding_factory,
            fragment_snapshot=fragment_snapshot,
            delegate_public_traversal=readthrough_delegates,
        )
        return graph_handle

    @pure_lazy
    def diff_bytes_lazy[T: DatabaseObjectRow[SysId]](
        self: VersionedReadTransactionLazyMixin,
        model_cls: type[T],
        object_id: LazyResult[SysId],
        column: str,
        from_revision_id: LazyResult[RevisionId],
        to_revision_id: LazyResult[RevisionId] | None = None,
        *,
        block_size: int = 512,
    ) -> LazyResult[BlobDiff]:
        """Compute diff between blob content at two revisions.

        Adds a DiffBytesIntent that lowers to two versioned reads (one per
        revision) plus a Python-side diff computation step. Fast-paths
        when both blobs are identical (same SHA-256 hash).
        """
        backend = versioned_backend_registry_module.versioned_backend_registry.get("sparse", self)
        sparse_model = backend._get_or_create_sparse_model(model_cls)
        raw_type_names = collect_polymorphic_type_names(model_cls)
        type_ids: list[str] | None = list(raw_type_names) if raw_type_names else None

        plan = self._get_transaction_plan_lazy()
        context_refs = get_versioned_lazy_context_refs(self)
        return self._add_intent(
            intent_diff_bytes.DiffBytesIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                model_cls=model_cls,
                sys_id=_require_scalar_source_ref(
                    object_id,
                    context="diff_bytes_lazy object_id",
                ),
                config=intent_diff_bytes._shape_blob_diff_config_payload(
                    column=column,
                    from_revision_id=_require_scalar_source_ref(
                        from_revision_id,
                        context="diff_bytes_lazy from_revision_id",
                    ),
                    to_revision_id=normalize_optional_scalar_input(
                        to_revision_id,
                        context="diff_bytes_lazy to_revision_id",
                    ),
                    default_to_revision_id=_require_scalar_source_ref(
                        _default_diff_to_revision_input(self, context_refs),
                        context="diff_bytes_lazy default_to_revision_id",
                    ),
                    block_size=block_size,
                    type_ids=type_ids,
                ),
                domain=_txn_domain(self),
                sparse_model_cls=sparse_model,
            ),
        )


