def decode(resolved, source_ref, preflight_ref):
    executed_dependencies = tuple(
        dependency for dependency in dependencies() if resolved.get(dependency) is not None
    )
    database_receipts = tuple(
        dependency
        for dependency in (str(preflight_ref), str(source_ref))
        if resolved.get(dependency) is not None
    )
    database_round_trips = MatchDatabaseRoundTripCount(len(database_receipts))
    database_execution_operations = MatchStageOperationCount(len(database_receipts))
    dependency_traversal_operations = MatchStageOperationCount(len(executed_dependencies))
    return database_round_trips, database_execution_operations, dependency_traversal_operations

