"""Public execution observation for every Phase 2 matrix cell."""

from __future__ import annotations

from collections.abc import Iterable
from functools import cache
from typing import Any
from uuid import UUID

from pydantic import BaseModel, ConfigDict

from conform.l5250_matching.case_matrix import (
    ExecutionSurface,
    MatchCaseCount,
    MatchCaseId,
    PermissionShape,
    PolymorphismShape,
)
from conform.l5250_matching.phase2_case_matrix import (
    PHASE2_EXACT_DENSE_MATRIX,
    FilterShape,
    Phase2Backend,
    Phase2ResultShape,
    Phase2ValidCase,
    RelationCardinality,
    ScoreShape,
)
from data_layer.connection import AsyncDatabaseConnection, SyncDatabaseConnection
from data_layer.lazy_result import lazy_tuple
from data_layer.matching import MatchRelationSpec
from data_layer.schema import field
from data_layer.session import SessionId, UserSession
from data_layer.transaction import AsyncReadTransaction, AsyncWriteTransaction, SyncReadTransaction, SyncWriteTransaction
from data_layer.types import UserId


type _ObservedEdges = tuple[tuple[str, str, float], ...]
type _SemanticKey = tuple[PermissionShape, str, _ObservedEdges]

_BACKEND_BY_FIXTURE = {
    "sqlite": Phase2Backend.SQLITE,
    "postgres": Phase2Backend.POSTGRESQL,
    "mariadb": Phase2Backend.MARIADB,
}
_PERMISSION_INDEX = {shape: index for index, shape in enumerate(PermissionShape, start=1)}


class Phase2ExecutionReport(BaseModel):
    """Typed public execution results for expanded matrix cells."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    executed_class_ids: tuple[MatchCaseId, ...]
    validated_cell_ids: tuple[MatchCaseId, ...]
    public_result_count: MatchCaseCount


def _user_id(shape: PermissionShape) -> UserId:
    return UserId(UUID(f"00000000-0000-7000-8000-{_PERMISSION_INDEX[shape]:012d}"))


def _other_id(shape: PermissionShape) -> UserId:
    return UserId(UUID(f"00000000-0000-7001-8000-{_PERMISSION_INDEX[shape]:012d}"))


def _session_id(shape: PermissionShape) -> SessionId:
    return SessionId(UUID(f"00000000-0000-7002-8000-{_PERMISSION_INDEX[shape]:012d}"))


def _owners(shape: PermissionShape, ordinal: int) -> tuple[UserId, UserId]:
    user_id = _user_id(shape)
    other_id = _other_id(shape)
    if shape is PermissionShape.DENY_LEFT:
        return other_id, user_id
    if shape is PermissionShape.DENY_RIGHT:
        return user_id, other_id
    if shape is PermissionShape.DENY_BOTH:
        return other_id, other_id
    if shape is PermissionShape.MIXED_VISIBLE_ROWS and ordinal == 1:
        return other_id, other_id
    return user_id, user_id


def _rows() -> Iterable[tuple[Any, Any]]:
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2SecureDenseLeft,
        Phase2SecureDenseRight,
    )

    left_vectors = ((1.0, 0.0), (0.0, 1.0))
    right_vectors = ((2.0, 1.0), (1.0, 3.0))
    for shape in PermissionShape:
        for ordinal in range(2):
            left_owner, right_owner = _owners(shape, ordinal)
            yield (
                Phase2SecureDenseLeft(
                    label=f"left-{ordinal}",
                    coordinate_x=left_vectors[ordinal][0],
                    coordinate_y=left_vectors[ordinal][1],
                    owner_id=left_owner,
                    matrix_group=shape.value,
                    matrix_first_group=shape.value if ordinal == 0 else "",
                    matrix_ordinal=ordinal,
                ),
                Phase2SecureDenseRight(
                    label=f"right-{ordinal}",
                    coordinate_x=right_vectors[ordinal][0],
                    coordinate_y=right_vectors[ordinal][1],
                    owner_id=right_owner,
                    matrix_group=shape.value,
                    matrix_first_group=shape.value if ordinal == 0 else "",
                    matrix_ordinal=ordinal,
                ),
            )


def _session_for(shape: PermissionShape) -> SessionId:
    return _session_id(shape)


def _semantic_key(case: Phase2ValidCase) -> _SemanticKey:
    return (
        case.permission_shape,
        case.result_shape.value,
        _expected_edges(case),
    )


def _representatives(cases: Iterable[Phase2ValidCase]) -> dict[_SemanticKey, Phase2ValidCase]:
    representatives: dict[_SemanticKey, Phase2ValidCase] = {}
    for case in cases:
        representatives.setdefault(_semantic_key(case), case)
    return representatives


def _endpoint_expression(row_type: type[Any], case: Phase2ValidCase, *, left: bool):
    restrict_to_first = case.relation_cardinality is RelationCardinality.SINGLETON
    restrict_to_first = restrict_to_first or (
        case.filter_shape in ({FilterShape.LEFT, FilterShape.ALL} if left else {FilterShape.RIGHT, FilterShape.ALL})
    )
    if case.relation_cardinality is RelationCardinality.EMPTY:
        return field(row_type.matrix_group) == "no-phase2-matrix-row"
    if restrict_to_first:
        return field(row_type.matrix_first_group) == case.permission_shape.value
    return field(row_type.matrix_group) == case.permission_shape.value


@cache
def _secure_relation_types() -> tuple[type[MatchRelationSpec[Any]], type[MatchRelationSpec[Any]]]:
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2SecureDenseLeft,
        Phase2SecureDenseRight,
    )

    return MatchRelationSpec[Phase2SecureDenseLeft], MatchRelationSpec[Phase2SecureDenseRight]


def _spec(case: Phase2ValidCase, name: str):
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2SecureDenseLeft,
        Phase2SecureDenseRight,
    )
    from data_layer import matching

    left_relation_type, right_relation_type = _secure_relation_types()
    equal_scores = case.score_shape in {ScoreShape.EQUAL, ScoreShape.THRESHOLD_BOUNDARY}
    left_coordinates: tuple[matching.MatchDenseCoordinateSpec[Any], ...]
    right_coordinates: tuple[matching.MatchDenseCoordinateSpec[Any], ...]
    if equal_scores:
        left_coordinates = (matching.MatchDenseCoordinateSpec.from_field(field(Phase2SecureDenseLeft.equal_coordinate)),)
        right_coordinates = (matching.MatchDenseCoordinateSpec.from_field(field(Phase2SecureDenseRight.equal_coordinate)),)
    else:
        left_coordinates = (
            matching.MatchDenseCoordinateSpec.from_field(field(Phase2SecureDenseLeft.coordinate_x)),
            matching.MatchDenseCoordinateSpec.from_field(field(Phase2SecureDenseLeft.coordinate_y)),
        )
        right_coordinates = (
            matching.MatchDenseCoordinateSpec.from_field(field(Phase2SecureDenseRight.coordinate_x)),
            matching.MatchDenseCoordinateSpec.from_field(field(Phase2SecureDenseRight.coordinate_y)),
        )
    left_filter = matching.MatchEndpointFilterSpec.from_expression(
        _endpoint_expression(Phase2SecureDenseLeft, case, left=True),
    )
    right_filter = matching.MatchEndpointFilterSpec.from_expression(
        _endpoint_expression(Phase2SecureDenseRight, case, left=False),
    )
    pair_filter = (
        matching.MatchPairFieldComparisonSpec.from_fields(
            field(Phase2SecureDenseLeft.matrix_ordinal),
            matching.MatchPairComparisonOperator.EQUAL,
            field(Phase2SecureDenseRight.matrix_ordinal),
        )
        if case.filter_shape in {FilterShape.PAIR, FilterShape.ALL}
        else matching.NoMatchFilter()
    )
    result_shape: matching.TopKPerLeftMatchShape | matching.ThresholdJoinMatchShape
    if case.result_shape.value == "top_k_per_left":
        result_shape = matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(2))
    else:
        result_shape = matching.ThresholdJoinMatchShape(
            threshold=matching.MatchScoreValue(1.0),
            boundary=matching.MatchThresholdBoundary.INCLUSIVE,
            result_limit=matching.MatchResultLimit(4),
        )
    dimensions = matching.MatchVectorDimensions(len(left_coordinates))
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId(f"phase2:matrix:{name}"),
        left=left_relation_type(
            relation_ref_id=matching.MatchRelationRefId(f"phase2:matrix:{name}:left"),
            row_type=Phase2SecureDenseLeft,
            representation=matching.MatchDenseRepresentationSpec[Phase2SecureDenseLeft](
                representation_ref_id=matching.MatchRepresentationRefId(f"phase2:matrix:{name}:left:dense"),
                dimensions=dimensions,
                coordinates=left_coordinates,
            ),
        ),
        right=right_relation_type(
            relation_ref_id=matching.MatchRelationRefId(f"phase2:matrix:{name}:right"),
            row_type=Phase2SecureDenseRight,
            representation=matching.MatchDenseRepresentationSpec[Phase2SecureDenseRight](
                representation_ref_id=matching.MatchRepresentationRefId(f"phase2:matrix:{name}:right:dense"),
                dimensions=dimensions,
                coordinates=right_coordinates,
            ),
        ),
        kernel=matching.MatchKernelSpec(
            kernel_ref_id=matching.MatchKernelRefId(f"phase2:matrix:{name}:dot"),
            kind=matching.MatchKernelKind.DENSE_DOT_PRODUCT,
            score_direction=matching.MatchScoreDirection.HIGHER_IS_BETTER,
        ),
        policies=matching.MatchPolicies(
            guarantee=matching.MatchGuarantee.EXACT,
            missing_representation=matching.FailMissingRepresentationPolicy(),
            self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
            duplicates=matching.RejectDuplicatePairsPolicy(),
            freshness=matching.RequireCurrentFreshnessPolicy(),
        ),
        result_shape=result_shape,
        filters=matching.MatchFilterSet(left=left_filter, right=right_filter, pair=pair_filter),
        work_limits=matching.MatchWorkLimits.standard_exact_dense(),
    )


def _observed_edges(result: Any) -> _ObservedEdges:
    return tuple((edge.left.label, edge.right.label, float(edge.score.canonical)) for edge in result.edges)


def _expected_edges(case: Phase2ValidCase) -> _ObservedEdges:
    return tuple((edge.left_label, edge.right_label, edge.score) for edge in case.expected_edges)


def _backend_cases(backend_type: str, surface: ExecutionSurface) -> tuple[Phase2ValidCase, ...]:
    backend = _BACKEND_BY_FIXTURE[backend_type]
    return tuple(case for case in PHASE2_EXACT_DENSE_MATRIX.valid_cases if case.backend is backend and case.execution_surface is surface)


def _validate_outcomes(
    cases: tuple[Phase2ValidCase, ...],
    outcomes: dict[_SemanticKey, _ObservedEdges],
) -> tuple[MatchCaseId, ...]:
    from conform.l5250_matching.phase2_oracle import evaluate_phase2_fixture

    for case in cases:
        observed = outcomes[_semantic_key(case)]
        independent_expected = evaluate_phase2_fixture(
            permission_shape=case.permission_shape.value,
            relation_cardinality=case.relation_cardinality.value,
            filter_shape=case.filter_shape.value,
            score_shape=case.score_shape.value,
            result_shape=case.result_shape.value,
        )
        if observed != _expected_edges(case) or observed != independent_expected:
            msg = (
                f"Phase 2 public matrix mismatch for {case.case_id}: "
                f"matrix={_expected_edges(case)}, independent={independent_expected}, observed={observed}"
            )
            raise AssertionError(msg)
    return tuple(MatchCaseId(case.case_id) for case in cases)


def execute_sync_matrix_cells(
    connection: SyncDatabaseConnection,
    backend_type: str,
) -> Phase2ExecutionReport:
    """Execute sync and lazy representatives and validate every equivalent cell."""
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2SecureDenseLeft,
        Phase2SecureDenseRight,
    )
    from data_layer import matching

    def seed(txn: SyncWriteTransaction) -> None:
        for shape in PermissionShape:
            txn.insert(
                UserSession,
                UserSession(sys_id=_session_id(shape), session_type="user", user_id=_user_id(shape)),
            )
        for left_row, right_row in _rows():
            txn.insert(Phase2SecureDenseLeft, left_row)
            txn.insert(Phase2SecureDenseRight, right_row)

    connection.session(SessionId.schema()).write(fn=seed)
    executed_class_ids: list[MatchCaseId] = []
    validated_cell_ids: list[MatchCaseId] = []
    for surface in (ExecutionSurface.LAZY, ExecutionSurface.SYNC):
        cases = _backend_cases(backend_type, surface)
        representatives = _representatives(cases)
        outcomes: dict[_SemanticKey, _ObservedEdges] = {}
        for permission_shape in PermissionShape:
            selected = tuple((key, case) for key, case in representatives.items() if case.permission_shape is permission_shape)

            def execute(txn: SyncReadTransaction) -> None:
                if surface is ExecutionSurface.LAZY:
                    pending = tuple(
                        matching.match_lazy(txn, _spec(case, f"{surface.value}:{permission_shape.value}:{index}"))
                        for index, (_, case) in enumerate(selected)
                    )
                    results = lazy_tuple(*pending).resolve()
                    for (key, _), result in zip(selected, results, strict=True):
                        outcomes[key] = _observed_edges(result)
                else:
                    for index, (key, case) in enumerate(selected):
                        spec = _spec(case, f"{surface.value}:{permission_shape.value}:{index}")
                        outcomes[key] = _observed_edges(matching.match(txn, spec))

            connection.session(_session_for(permission_shape)).read(fn=execute)
        executed_class_ids.extend(
            PHASE2_EXACT_DENSE_MATRIX.execution_class_for(case).execution_class_id for case in representatives.values()
        )
        validated_cell_ids.extend(_validate_outcomes(cases, outcomes))
    return Phase2ExecutionReport(
        executed_class_ids=tuple(executed_class_ids),
        validated_cell_ids=tuple(validated_cell_ids),
        public_result_count=MatchCaseCount(len(executed_class_ids)),
    )


async def execute_async_matrix_cells(
    connection: AsyncDatabaseConnection,
    backend_type: str,
) -> Phase2ExecutionReport:
    """Execute async representatives and validate every equivalent async cell."""
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2SecureDenseLeft,
        Phase2SecureDenseRight,
    )
    from data_layer import matching

    async def seed(txn: AsyncWriteTransaction) -> None:
        for shape in PermissionShape:
            await txn.insert_async(
                UserSession,
                UserSession(sys_id=_session_id(shape), session_type="user", user_id=_user_id(shape)),
            )
        for left_row, right_row in _rows():
            await txn.insert_async(Phase2SecureDenseLeft, left_row)
            await txn.insert_async(Phase2SecureDenseRight, right_row)

    await connection.session(SessionId.schema()).write_async(fn=seed)
    cases = _backend_cases(backend_type, ExecutionSurface.ASYNC)
    representatives = _representatives(cases)
    outcomes: dict[_SemanticKey, _ObservedEdges] = {}
    for permission_shape in PermissionShape:
        selected = tuple((key, case) for key, case in representatives.items() if case.permission_shape is permission_shape)

        async def execute(txn: AsyncReadTransaction) -> None:
            for index, (key, case) in enumerate(selected):
                spec = _spec(case, f"async:{permission_shape.value}:{index}")
                result = await matching.match_async(txn, spec)
                outcomes[key] = _observed_edges(result)

        await connection.session(_session_for(permission_shape)).read_async(fn=execute)
    validated_cell_ids = _validate_outcomes(cases, outcomes)
    return Phase2ExecutionReport(
        executed_class_ids=tuple(
            PHASE2_EXACT_DENSE_MATRIX.execution_class_for(case).execution_class_id for case in representatives.values()
        ),
        validated_cell_ids=validated_cell_ids,
        public_result_count=MatchCaseCount(len(representatives)),
    )


class Phase2ConcreteEndpointTypeOutcome(BaseModel):
    """Concrete endpoint types returned by one public polymorphism check."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    case_id: MatchCaseId
    check_case_id: MatchCaseId
    left_type_name: str
    right_type_name: str


class Phase2PermissionPolymorphismSurfaceOutcome(BaseModel):
    """Observed result of one directly executed mandatory-factor cell."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    execution_surface: str
    permission_shape: str
    left_type_name: str
    right_type_name: str
    observed_edge_labels: tuple[tuple[str, str], ...]
    concrete_endpoint_types: tuple[tuple[str, str], ...]


def _other_session_id(shape: PermissionShape) -> SessionId:
    return SessionId(UUID(f"00000000-0000-7003-8000-{_PERMISSION_INDEX[shape]:012d}"))


def _session_id_for_owner(owner_id: UserId) -> SessionId:
    for shape in PermissionShape:
        if owner_id == _user_id(shape):
            return _session_id(shape)
        if owner_id == _other_id(shape):
            return _other_session_id(shape)
    msg = f"No matrix session owns user {owner_id}"
    raise AssertionError(msg)


def _combined_endpoint_type(shape: PolymorphismShape, *, left: bool) -> type[Any]:
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2SecureDenseLeft,
        Phase2SecureDenseRight,
    )
    from conform.l5250_matching.test_phase2_additional_contracts import (
        Phase2CombinedPolyLeft,
        Phase2CombinedPolyRight,
    )

    if shape is PolymorphismShape.CONCRETE:
        return Phase2SecureDenseLeft if left else Phase2SecureDenseRight
    return Phase2CombinedPolyLeft if left else Phase2CombinedPolyRight


def _combined_label(permission: PermissionShape, shape: PolymorphismShape, ordinal: int, *, left: bool) -> str:
    endpoint = "left" if left else "right"
    return f"combined-{permission.value}-{shape.value}-{endpoint}-{ordinal}"


def _combined_spec(
    permission: PermissionShape,
    left_shape: PolymorphismShape,
    right_shape: PolymorphismShape,
):
    from data_layer import matching

    left_type = _combined_endpoint_type(left_shape, left=True)
    right_type = _combined_endpoint_type(right_shape, left=False)
    identity = f"{permission.value}:{left_shape.value}:{right_shape.value}"
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId(f"phase2:combined:{identity}"),
        left=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId(f"phase2:combined:{identity}:left"),
            row_type=left_type,
            representation=matching.MatchDenseRepresentationSpec(
                representation_ref_id=matching.MatchRepresentationRefId(f"phase2:combined:{identity}:left:dense"),
                dimensions=matching.MatchVectorDimensions(2),
                coordinates=(
                    matching.MatchDenseCoordinateSpec.from_field(field(left_type.coordinate_x)),
                    matching.MatchDenseCoordinateSpec.from_field(field(left_type.coordinate_y)),
                ),
            ),
        ),
        right=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId(f"phase2:combined:{identity}:right"),
            row_type=right_type,
            representation=matching.MatchDenseRepresentationSpec(
                representation_ref_id=matching.MatchRepresentationRefId(f"phase2:combined:{identity}:right:dense"),
                dimensions=matching.MatchVectorDimensions(2),
                coordinates=(
                    matching.MatchDenseCoordinateSpec.from_field(field(right_type.coordinate_x)),
                    matching.MatchDenseCoordinateSpec.from_field(field(right_type.coordinate_y)),
                ),
            ),
        ),
        kernel=matching.MatchKernelSpec(
            kernel_ref_id=matching.MatchKernelRefId(f"phase2:combined:{identity}:dot"),
            kind=matching.MatchKernelKind.DENSE_DOT_PRODUCT,
            score_direction=matching.MatchScoreDirection.HIGHER_IS_BETTER,
        ),
        policies=matching.MatchPolicies(
            guarantee=matching.MatchGuarantee.EXACT,
            missing_representation=matching.FailMissingRepresentationPolicy(),
            self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
            duplicates=matching.RejectDuplicatePairsPolicy(),
            freshness=matching.RequireCurrentFreshnessPolicy(),
        ),
        result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
        filters=matching.MatchFilterSet(
            left=matching.MatchEndpointFilterSpec.from_expression(
                field(left_type.label) == _combined_label(permission, left_shape, 0, left=True),
            ),
            right=matching.MatchEndpointFilterSpec.from_expression(
                field(right_type.label) == _combined_label(permission, right_shape, 0, left=False),
            ),
            pair=matching.NoMatchFilter(),
        ),
        work_limits=matching.MatchWorkLimits.standard_exact_dense(),
    )


def _polymorphic_check_spec(
    left_shape: PolymorphismShape,
    right_shape: PolymorphismShape,
):
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2DenseLeft,
        Phase2DenseRight,
        Phase2PolyDenseLeft,
        Phase2PolyDenseRight,
    )
    from data_layer import matching

    left_type = Phase2DenseLeft if left_shape is PolymorphismShape.CONCRETE else Phase2PolyDenseLeft
    right_type = Phase2DenseRight if right_shape is PolymorphismShape.CONCRETE else Phase2PolyDenseRight
    left_label = f"check-left-{left_shape.value}"
    right_label = f"check-right-{right_shape.value}"
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId(f"phase2:poly-check:{left_shape.value}:{right_shape.value}"),
        left=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId(f"phase2:poly-check:{left_shape.value}:left"),
            row_type=left_type,
            representation=matching.MatchDenseRepresentationSpec(
                representation_ref_id=matching.MatchRepresentationRefId(
                    f"phase2:poly-check:{left_shape.value}:left:dense",
                ),
                dimensions=matching.MatchVectorDimensions(2),
                coordinates=(
                    matching.MatchDenseCoordinateSpec.from_field(field(left_type.coordinate_x)),
                    matching.MatchDenseCoordinateSpec.from_field(field(left_type.coordinate_y)),
                ),
            ),
        ),
        right=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId(f"phase2:poly-check:{right_shape.value}:right"),
            row_type=right_type,
            representation=matching.MatchDenseRepresentationSpec(
                representation_ref_id=matching.MatchRepresentationRefId(
                    f"phase2:poly-check:{right_shape.value}:right:dense",
                ),
                dimensions=matching.MatchVectorDimensions(2),
                coordinates=(
                    matching.MatchDenseCoordinateSpec.from_field(field(right_type.coordinate_x)),
                    matching.MatchDenseCoordinateSpec.from_field(field(right_type.coordinate_y)),
                ),
            ),
        ),
        kernel=matching.MatchKernelSpec(
            kernel_ref_id=matching.MatchKernelRefId(
                f"phase2:poly-check:{left_shape.value}:{right_shape.value}:kernel",
            ),
            kind=matching.MatchKernelKind.DENSE_DOT_PRODUCT,
            score_direction=matching.MatchScoreDirection.HIGHER_IS_BETTER,
        ),
        policies=matching.MatchPolicies(
            guarantee=matching.MatchGuarantee.EXACT,
            missing_representation=matching.FailMissingRepresentationPolicy(),
            self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
            duplicates=matching.RejectDuplicatePairsPolicy(),
            freshness=matching.RequireCurrentFreshnessPolicy(),
        ),
        result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
        filters=matching.MatchFilterSet(
            left=matching.MatchEndpointFilterSpec.from_expression(field(left_type.label) == left_label),
            right=matching.MatchEndpointFilterSpec.from_expression(field(right_type.label) == right_label),
            pair=matching.NoMatchFilter(),
        ),
        work_limits=matching.MatchWorkLimits.standard_exact_dense(),
    )


def execute_polymorphism_product(
    connection: SyncDatabaseConnection,
) -> tuple[Phase2ConcreteEndpointTypeOutcome, ...]:
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2DenseLeft,
        Phase2DenseRight,
        Phase2PolyDenseLeft,
        Phase2PolyDenseLeftSubtype,
        Phase2PolyDenseRight,
        Phase2PolyDenseRightSubtype,
    )
    from data_layer import matching

    def seed(txn: SyncWriteTransaction) -> None:
        txn.insert(
            Phase2DenseLeft,
            Phase2DenseLeft(label="check-left-concrete", coordinate_x=1.0, coordinate_y=0.0),
        )
        txn.insert(
            Phase2DenseRight,
            Phase2DenseRight(label="check-right-concrete", coordinate_x=1.0, coordinate_y=0.0),
        )
        txn.insert(
            Phase2PolyDenseLeft,
            Phase2PolyDenseLeft(label="check-left-base_instance", coordinate_x=1.0, coordinate_y=0.0),
        )
        txn.insert(
            Phase2PolyDenseLeft,
            Phase2PolyDenseLeftSubtype(
                label="check-left-subtype_instance",
                coordinate_x=1.0,
                coordinate_y=0.0,
                left_detail="subtype",
            ),
        )
        txn.insert(
            Phase2PolyDenseRight,
            Phase2PolyDenseRight(label="check-right-base_instance", coordinate_x=1.0, coordinate_y=0.0),
        )
        txn.insert(
            Phase2PolyDenseRight,
            Phase2PolyDenseRightSubtype(
                label="check-right-subtype_instance",
                coordinate_x=1.0,
                coordinate_y=0.0,
                right_detail="subtype",
            ),
        )

    connection.session(SessionId.schema()).write(fn=seed)
    outcomes: list[Phase2ConcreteEndpointTypeOutcome] = []
    for left_shape in PolymorphismShape:
        for right_shape in PolymorphismShape:
            check_case_id = MatchCaseId(f"polymorphism-check-{left_shape.value}-{right_shape.value}")
            spec = _polymorphic_check_spec(left_shape, right_shape)
            result = connection.session(SessionId.schema()).read(fn=lambda txn: matching.match(txn, spec))
            assert isinstance(result, matching.TopKPerLeftMatchResult)
            assert len(result.edges) == 1
            edge = result.edges[0]
            outcomes.append(
                Phase2ConcreteEndpointTypeOutcome(
                    case_id=check_case_id,
                    check_case_id=check_case_id,
                    left_type_name=type(edge.left).__name__,
                    right_type_name=type(edge.right).__name__,
                ),
            )
    return tuple(outcomes)


def _combined_seed_rows() -> tuple[tuple[type[Any], Any], ...]:
    from conform.l5250_matching.test_phase2_exact_dense import (
        Phase2SecureDenseLeft,
        Phase2SecureDenseRight,
    )
    from conform.l5250_matching.test_phase2_additional_contracts import (
        Phase2CombinedPolyLeft,
        Phase2CombinedPolyLeftSubtype,
        Phase2CombinedPolyRight,
        Phase2CombinedPolyRightSubtype,
    )

    rows: list[tuple[type[Any], Any]] = []
    for permission in PermissionShape:
        rows.extend(
            (
                (
                    UserSession,
                    UserSession(sys_id=_session_id(permission), session_type="user", user_id=_user_id(permission)),
                ),
                (
                    UserSession,
                    UserSession(
                        sys_id=_other_session_id(permission),
                        session_type="user",
                        user_id=_other_id(permission),
                    ),
                ),
            ),
        )
        row_count = 2 if permission is PermissionShape.MIXED_VISIBLE_ROWS else 1
        for shape in PolymorphismShape:
            for ordinal in range(row_count):
                left_owner, right_owner = _owners(permission, ordinal)
                left_label = _combined_label(permission, shape, 0, left=True)
                right_label = _combined_label(permission, shape, 0, left=False)
                if shape is PolymorphismShape.CONCRETE:
                    rows.extend(
                        (
                            (
                                Phase2SecureDenseLeft,
                                Phase2SecureDenseLeft(
                                    label=left_label,
                                    coordinate_x=1.0,
                                    coordinate_y=0.0,
                                    owner_id=left_owner,
                                ),
                            ),
                            (
                                Phase2SecureDenseRight,
                                Phase2SecureDenseRight(
                                    label=right_label,
                                    coordinate_x=1.0,
                                    coordinate_y=0.0,
                                    owner_id=right_owner,
                                ),
                            ),
                        ),
                    )
                    continue
                left_row = (
                    Phase2CombinedPolyLeft(
                        label=left_label,
                        coordinate_x=1.0,
                        coordinate_y=0.0,
                        owner_id=left_owner,
                    )
                    if shape is PolymorphismShape.BASE_INSTANCE
                    else Phase2CombinedPolyLeftSubtype(
                        label=left_label,
                        coordinate_x=1.0,
                        coordinate_y=0.0,
                        owner_id=left_owner,
                        detail="combined-subtype",
                    )
                )
                right_row = (
                    Phase2CombinedPolyRight(
                        label=right_label,
                        coordinate_x=1.0,
                        coordinate_y=0.0,
                        owner_id=right_owner,
                    )
                    if shape is PolymorphismShape.BASE_INSTANCE
                    else Phase2CombinedPolyRightSubtype(
                        label=right_label,
                        coordinate_x=1.0,
                        coordinate_y=0.0,
                        owner_id=right_owner,
                        detail="combined-subtype",
                    )
                )
                rows.extend(((Phase2CombinedPolyLeft, left_row), (Phase2CombinedPolyRight, right_row)))
    return tuple(rows)


def _combined_outcome(
    result: Any,
    permission: PermissionShape,
    left_shape: PolymorphismShape,
    right_shape: PolymorphismShape,
    surface: ExecutionSurface,
) -> Phase2PermissionPolymorphismSurfaceOutcome:
    expected_left_types = {
        PolymorphismShape.CONCRETE: "Phase2SecureDenseLeft",
        PolymorphismShape.BASE_INSTANCE: "Phase2CombinedPolyLeft",
        PolymorphismShape.SUBTYPE_INSTANCE: "Phase2CombinedPolyLeftSubtype",
    }
    expected_right_types = {
        PolymorphismShape.CONCRETE: "Phase2SecureDenseRight",
        PolymorphismShape.BASE_INSTANCE: "Phase2CombinedPolyRight",
        PolymorphismShape.SUBTYPE_INSTANCE: "Phase2CombinedPolyRightSubtype",
    }
    expected_count = (
        0
        if permission
        in {
            PermissionShape.DENY_LEFT,
            PermissionShape.DENY_RIGHT,
            PermissionShape.DENY_BOTH,
        }
        else 1
    )
    observed_labels = tuple((edge.left.label, edge.right.label) for edge in result.edges)
    endpoint_types = tuple((type(edge.left).__name__, type(edge.right).__name__) for edge in result.edges)
    expected_types = tuple((expected_left_types[left_shape], expected_right_types[right_shape]) for _ in range(expected_count))
    if len(observed_labels) != expected_count or endpoint_types != expected_types:
        msg = (
            f"Combined factor cell returned labels={observed_labels}, types={endpoint_types}; "
            f"expected count={expected_count}, types={expected_types}"
        )
        raise AssertionError(msg)
    return Phase2PermissionPolymorphismSurfaceOutcome(
        execution_surface=surface.value,
        permission_shape=permission.value,
        left_type_name=left_shape.value,
        right_type_name=right_shape.value,
        observed_edge_labels=observed_labels,
        concrete_endpoint_types=endpoint_types,
    )


def _combined_seed_groups() -> tuple[tuple[SessionId, tuple[tuple[type[Any], tuple[Any, ...]], ...]], ...]:
    groups: dict[SessionId, dict[type[Any], list[Any]]] = {}
    for row_type, row in _combined_seed_rows():
        session_id = SessionId.schema() if row_type is UserSession else _session_id_for_owner(row.owner_id)
        groups.setdefault(session_id, {}).setdefault(row_type, []).append(row)
    return tuple(
        (
            session_id,
            tuple((row_type, tuple(rows)) for row_type, rows in rows_by_type.items()),
        )
        for session_id, rows_by_type in groups.items()
    )


def execute_permission_polymorphism_surface_product(
    connection: SyncDatabaseConnection,
    backend_type: str,
) -> tuple[Phase2PermissionPolymorphismSurfaceOutcome, ...]:
    """Execute the sync and lazy mandatory-factor product directly."""
    del backend_type
    from data_layer import matching

    for session_id, row_groups in _combined_seed_groups():

        def seed(txn: SyncWriteTransaction) -> None:
            for row_type, rows in row_groups:
                txn.insert_many(row_type, rows)

        connection.session(session_id).write(fn=seed)
    outcomes: list[Phase2PermissionPolymorphismSurfaceOutcome] = []
    for permission in PermissionShape:

        def execute(txn: SyncReadTransaction) -> None:
            shape_pairs = tuple(
                (left_shape, right_shape)
                for left_shape in PolymorphismShape
                for right_shape in PolymorphismShape
            )
            specs = tuple(
                _combined_spec(permission, left_shape, right_shape)
                for left_shape, right_shape in shape_pairs
            )
            for (left_shape, right_shape), spec in zip(shape_pairs, specs, strict=True):
                outcomes.append(
                    _combined_outcome(
                        matching.match(txn, spec),
                        permission,
                        left_shape,
                        right_shape,
                        ExecutionSurface.SYNC,
                    ),
                )
            lazy_results = lazy_tuple(
                *(matching.match_lazy(txn, spec) for spec in specs),
            ).resolve()
            for (left_shape, right_shape), result in zip(shape_pairs, lazy_results, strict=True):
                outcomes.append(
                    _combined_outcome(
                        result,
                        permission,
                        left_shape,
                        right_shape,
                        ExecutionSurface.LAZY,
                    ),
                )

        connection.session(_session_for(permission)).read(fn=execute)
    return tuple(outcomes)


async def execute_permission_polymorphism_async_product(
    connection: AsyncDatabaseConnection,
    backend_type: str,
) -> tuple[Phase2PermissionPolymorphismSurfaceOutcome, ...]:
    """Execute the asynchronous mandatory-factor product directly."""
    del backend_type
    from data_layer import matching

    for session_id, row_groups in _combined_seed_groups():

        async def seed(txn: AsyncWriteTransaction) -> None:
            for row_type, rows in row_groups:
                await txn.insert_many_async(row_type, rows)

        await connection.session(session_id).write_async(fn=seed)
    outcomes: list[Phase2PermissionPolymorphismSurfaceOutcome] = []
    for permission in PermissionShape:

        async def execute(txn: AsyncReadTransaction) -> None:
            for left_shape in PolymorphismShape:
                for right_shape in PolymorphismShape:
                    spec = _combined_spec(permission, left_shape, right_shape)
                    result = await matching.match_async(txn, spec)
                    outcomes.append(
                        _combined_outcome(
                            result,
                            permission,
                            left_shape,
                            right_shape,
                            ExecutionSurface.ASYNC,
                        ),
                    )

        await connection.session(_session_for(permission)).read_async(fn=execute)
    return tuple(outcomes)

