"""Independent exhaustive evaluator for the Phase 2 fixture."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True, slots=True)
class _Endpoint:
    label: str
    vector: tuple[float, float]


def _fixture_relations(
    relation_cardinality: str,
    score_shape: str,
) -> tuple[list[_Endpoint], list[_Endpoint]]:
    count = {"empty": 0, "singleton": 1, "multiple": 2}[relation_cardinality]
    if score_shape == "distinct":
        left_vectors = ((1.0, 0.0), (0.0, 1.0))
        right_vectors = ((2.0, 1.0), (1.0, 3.0))
    else:
        left_vectors = ((1.0, 0.0), (1.0, 0.0))
        right_vectors = ((1.0, 0.0), (1.0, 0.0))
    left = [_Endpoint(f"left-{index}", left_vectors[index]) for index in range(count)]
    right = [_Endpoint(f"right-{index}", right_vectors[index]) for index in range(count)]
    return left, right


def _apply_visibility(
    left: list[_Endpoint],
    right: list[_Endpoint],
    permission_shape: str,
) -> tuple[list[_Endpoint], list[_Endpoint]]:
    if permission_shape in {"deny_left", "deny_both"}:
        left = []
    elif permission_shape == "mixed_visible_rows":
        left = left[:1]
    if permission_shape in {"deny_right", "deny_both"}:
        right = []
    elif permission_shape == "mixed_visible_rows":
        right = right[:1]
    return left, right


def evaluate_phase2_fixture(
    *,
    permission_shape: str,
    relation_cardinality: str,
    filter_shape: str,
    score_shape: str,
    result_shape: str,
) -> tuple[tuple[str, str, float], ...]:
    """Evaluate one valid cell without using the matrix expectation builder."""
    left, right = _fixture_relations(relation_cardinality, score_shape)
    left, right = _apply_visibility(left, right, permission_shape)
    if filter_shape in {"left", "all"}:
        left = [endpoint for endpoint in left if endpoint.label == "left-0"]
    if filter_shape in {"right", "all"}:
        right = [endpoint for endpoint in right if endpoint.label == "right-0"]

    edges: list[tuple[str, str, float]] = []
    for left_endpoint in left:
        for right_endpoint in right:
            if filter_shape in {"pair", "all"} and left_endpoint.label[-1] != right_endpoint.label[-1]:
                continue
            score = sum(
                left_value * right_value
                for left_value, right_value in zip(left_endpoint.vector, right_endpoint.vector, strict=True)
            )
            if result_shape == "threshold_join" and score < 1.0:
                continue
            edges.append((left_endpoint.label, right_endpoint.label, score))

    if result_shape == "threshold_join":
        return tuple(sorted(edges, key=lambda edge: (-edge[2], edge[0], edge[1])))
    ordered = sorted(edges, key=lambda edge: (edge[0], -edge[2], edge[1]))
    selected: list[tuple[str, str, float]] = []
    counts: dict[str, int] = {}
    for edge in ordered:
        prior_count = counts.get(edge[0], 0)
        if prior_count < 2:
            selected.append(edge)
            counts[edge[0]] = prior_count + 1
    return tuple(selected)

