"""Production-independent oracle for Phase 3 dense result profiles."""

from __future__ import annotations

from typing import Literal


type OracleEndpoint = tuple[str, float]
type OracleEdge = tuple[str, str]


def expected_phase3_edges(
    left_rows: tuple[OracleEndpoint, ...],
    right_rows: tuple[OracleEndpoint, ...],
    result_shape: Literal["top_left", "top_right", "global", "threshold"],
) -> tuple[OracleEdge, ...]:
    """Evaluate the declared one-dimensional dense profile without production code."""
    scored = sorted(
        (
            (left_label, right_label, left_value * right_value)
            for left_label, left_value in left_rows
            for right_label, right_value in right_rows
        ),
        key=lambda edge: (-edge[2], edge[0], edge[1]),
    )
    if result_shape == "top_left":
        selected = []
        counts: dict[str, int] = {}
        for edge in scored:
            if counts.get(edge[0], 0) < 2:
                selected.append(edge)
                counts[edge[0]] = counts.get(edge[0], 0) + 1
    elif result_shape == "top_right":
        selected = []
        seen_right: set[str] = set()
        for edge in scored:
            if edge[1] not in seen_right:
                selected.append(edge)
                seen_right.add(edge[1])
    elif result_shape == "threshold":
        selected = [edge for edge in scored if edge[2] >= 1.0][:2]
    else:
        selected = scored[:2]
    return tuple((left_label, right_label) for left_label, right_label, _score in selected)

