"""Executable typed-expression matrix for matching Phase 4."""

from __future__ import annotations

from conform._async_test_helper import run_async_test_with_system_authority
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict

from conform.l5250_matching.model_updates import validated_model_update
from conform.l5250_matching.test_phase4_expression_kernels import (
    Phase4ExpressionLeft,
    Phase4ExpressionRight,
    _two_field_expression_spec,
)
from data_layer import matching
from data_layer.lazy_result import lazy_tuple
from data_layer.connection import AsyncDatabaseConnection, SyncDatabaseConnection
from data_layer.schema import field
from data_layer.session import SessionId, UserSession
from data_layer.transaction import AsyncReadTransaction, AsyncWriteTransaction, SyncReadTransaction, SyncWriteTransaction
from data_layer.types import UserId
from uuid import UUID


class Phase4PermissionPolymorphismOutcome(BaseModel):
    """Observed expression work for one mandatory-factor cell."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    execution_surface: Phase4Surface
    expression_profile: Phase4Profile
    permission_shape: str
    left_type_name: str
    right_type_name: str
    expression_node_operations: int
    observed_edges: tuple[tuple[str, str], ...]
    observed_scores: tuple[float, ...]
    observed_ranks: tuple[int, ...]
    oracle_scores: tuple[float, ...]
    oracle_ranks: tuple[int, ...]


class Phase4InheritedFactorOutcome(BaseModel):
    """Public expression outcome used by one inherited-factor check."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    factor_name: str
    factor_value: str
    public_outcome: str
    observed_edges: tuple[tuple[str, str], ...]
    oracle_edges: tuple[tuple[str, str], ...]


class Phase4MatrixOutcome(BaseModel):
    """Outcomes from public expression-matrix execution."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    executed_case_ids: tuple[str, ...]
    invalid_case_ids: tuple[str, ...]
    inherited_case_ids: tuple[str, ...]
    inherited_outcomes: tuple[Phase4InheritedFactorOutcome, ...]


type Phase4Profile = Literal[
    "left_field",
    "right_field",
    "add",
    "subtract",
    "multiply",
    "divide",
    "absolute",
    "null",
    "division_by_zero",
    "non_finite",
]
type Phase4Surface = Literal["lazy", "sync", "async"]
type _Expression = (
    matching.MatchLeftFieldExpression
    | matching.MatchRightFieldExpression
    | matching.MatchAddExpression
    | matching.MatchSubtractExpression
    | matching.MatchMultiplyExpression
    | matching.MatchDivideExpression
    | matching.MatchFunctionExpression
)


class Phase4MatrixCase(BaseModel):
    """One typed expression-matrix case identity."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    case_id: str
    profile: Phase4Profile
    surface: Phase4Surface


class Phase4InheritedFactors(BaseModel):
    """Closed inherited factor vocabulary owned by the Phase 4 matrix."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    filters: tuple[str, ...] = ("none", "left", "right", "pair", "all")
    result_policies: tuple[str, ...] = ("fail", "omit", "declared_score", "materialize")
    result_shapes: tuple[str, ...] = ("top_left", "top_right", "global", "threshold")
    versions: tuple[str, ...] = ("unversioned", "branch_tip", "pinned_revision", "cross_branch")
    freshness: tuple[str, ...] = (
        "current",
        "stale_accepted",
        "stale_rejected",
        "bounded_watermark",
        "exact_completion",
    )
    permissions: tuple[str, ...] = ("allow", "deny_left", "deny_right", "deny_both", "mixed")
    left_polymorphism: tuple[str, ...] = ("concrete", "base_instance", "subtype_instance")
    right_polymorphism: tuple[str, ...] = ("concrete", "base_instance", "subtype_instance")
    score_directions: tuple[str, ...] = ("higher_is_better", "lower_is_better")
    null_policies: tuple[str, ...] = ("reject", "coalesce_zero")
    exact_bound_variants: tuple[str, ...] = ("finite", "boundary")


_VALID_PROFILES: tuple[Phase4Profile, ...] = (
    "left_field",
    "right_field",
    "add",
    "subtract",
    "multiply",
    "divide",
    "absolute",
)
_INVALID_PROFILES: tuple[Phase4Profile, ...] = ("null", "division_by_zero", "non_finite")
_SURFACES: tuple[Phase4Surface, ...] = ("lazy", "sync", "async")


class Phase4ExpressionMatrixManifest(BaseModel):
    """Complete executable expression profiles and inherited factor ownership."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    valid_cases: tuple[Phase4MatrixCase, ...]
    invalid_cases: tuple[Phase4MatrixCase, ...]
    inherited_factors: Phase4InheritedFactors
    executes_public_results: bool

    def validate_complete(self: Phase4ExpressionMatrixManifest) -> Phase4ExpressionMatrixManifest:
        """Reject removal of a required expression, surface, or inherited factor."""
        expected_valid = {(profile, surface) for profile in _VALID_PROFILES for surface in _SURFACES}
        expected_invalid = {(profile, surface) for profile in _INVALID_PROFILES for surface in _SURFACES}
        observed_valid = {(case.profile, case.surface) for case in self.valid_cases}
        observed_invalid = {(case.profile, case.surface) for case in self.invalid_cases}
        if observed_valid != expected_valid or observed_invalid != expected_invalid or not self.executes_public_results:
            msg = "Phase 4 expression matrix is incomplete"
            raise ValueError(msg)
        expected_inherited = Phase4InheritedFactors()
        if self.inherited_factors != expected_inherited:
            msg = "Phase 4 inherited factor vocabulary is incomplete"
            raise ValueError(msg)
        return self

    def execute_public_cases(
        self: Phase4ExpressionMatrixManifest,
        connection: SyncDatabaseConnection,
        async_connection: AsyncDatabaseConnection,
    ) -> Phase4MatrixOutcome:
        """Execute every valid and invalid cell through its declared public surface."""
        valid_ids: set[str] = set()
        invalid_ids: set[str] = set()
        valid_observations: dict[str, tuple[tuple[str, str], ...]] = {}
        sync_session = connection.session(SessionId.schema())
        for surface in ("lazy", "sync"):
            surface_cases = tuple(case for case in self.valid_cases if case.surface == surface)
            if not surface_cases:
                continue

            def execute_surface(
                txn: SyncReadTransaction,
            ) -> tuple[tuple[Phase4MatrixCase, matching.TopKPerLeftMatchResult], ...]:
                results: list[tuple[Phase4MatrixCase, matching.TopKPerLeftMatchResult]] = []
                for surface_case in surface_cases:
                    spec = _valid_spec(surface_case.profile, surface_case.case_id)
                    if surface == "lazy":
                        result = matching.match_lazy(txn, spec).resolve()
                    else:
                        result = matching.match(txn, spec)
                    assert isinstance(result, matching.TopKPerLeftMatchResult)
                    results.append((surface_case, result))
                return tuple(results)

            for case, result in sync_session.read(fn=execute_surface):
                assert result.edges
                valid_ids.add(case.case_id)
                valid_observations[case.case_id] = tuple((edge.left.label, edge.right.label) for edge in result.edges)
        for case in self.invalid_cases:
            if case.surface == "async":
                continue
            spec = _invalid_spec(case.profile, case.case_id)

            def execute_invalid(txn: SyncReadTransaction):
                if case.surface == "lazy":
                    return matching.match_lazy(txn, spec).resolve()
                return matching.match(txn, spec)

            try:
                sync_session.read(fn=execute_invalid)
            except matching.MatchExpressionEvaluationError:
                invalid_ids.add(case.case_id)
            else:
                msg = f"invalid Phase 4 case returned a result: {case.case_id}"
                raise AssertionError(msg)

        async def execute_async_cases() -> None:
            async_cases = tuple(case for case in self.valid_cases if case.surface == "async")
            if async_cases:

                async def execute_surface_async(
                    txn: AsyncReadTransaction,
                ) -> tuple[tuple[Phase4MatrixCase, matching.TopKPerLeftMatchResult], ...]:
                    results: list[tuple[Phase4MatrixCase, matching.TopKPerLeftMatchResult]] = []
                    for async_case in async_cases:
                        spec = _valid_spec(async_case.profile, async_case.case_id)
                        result = await matching.match_async(txn, spec)
                        assert isinstance(result, matching.TopKPerLeftMatchResult)
                        results.append((async_case, result))
                    return tuple(results)

                async_session = async_connection.session(SessionId.schema())
                for case, result in await async_session.read_async(fn=execute_surface_async):
                    assert result.edges
                    valid_ids.add(case.case_id)
                    valid_observations[case.case_id] = tuple((edge.left.label, edge.right.label) for edge in result.edges)
            for case in self.invalid_cases:
                if case.surface != "async":
                    continue
                spec = _invalid_spec(case.profile, case.case_id)

                async def execute_invalid(txn: AsyncReadTransaction):
                    return await matching.match_async(txn, spec)

                try:
                    await async_connection.session(SessionId.schema()).read_async(fn=execute_invalid)
                except matching.MatchExpressionEvaluationError:
                    invalid_ids.add(case.case_id)
                else:
                    msg = f"invalid Phase 4 case returned a result: {case.case_id}"
                    raise AssertionError(msg)

        run_async_test_with_system_authority(execute_async_cases())
        inherited_case_ids = tuple(
            f"{factor_name}:{factor_value}"
            for factor_name, factor_values in self.inherited_factors.model_dump().items()
            for factor_value in factor_values
        )
        inherited_outcomes = _execute_inherited_factor_outcomes(
            connection,
            async_connection,
            self.inherited_factors,
            valid_observations,
        )
        return Phase4MatrixOutcome(
            executed_case_ids=tuple(case.case_id for case in self.valid_cases if case.case_id in valid_ids),
            invalid_case_ids=tuple(case.case_id for case in self.invalid_cases if case.case_id in invalid_ids),
            inherited_case_ids=inherited_case_ids,
            inherited_outcomes=inherited_outcomes,
        )


_PERMISSION_SHAPES = ("allow_all", "deny_left", "deny_right", "deny_both", "mixed_visible_rows")
_POLYMORPHISM_SHAPES = ("concrete", "base_instance", "subtype_instance")


def _factor_user_id(permission_index: int) -> UserId:
    return UserId(UUID(f"00000000-0000-7040-8000-{permission_index:012d}"))


def _factor_other_id(permission_index: int) -> UserId:
    return UserId(UUID(f"00000000-0000-7041-8000-{permission_index:012d}"))


def _factor_session_id(permission_index: int) -> SessionId:
    return SessionId(UUID(f"00000000-0000-7042-8000-{permission_index:012d}"))


def _factor_other_session_id(permission_index: int) -> SessionId:
    return SessionId(UUID(f"00000000-0000-7043-8000-{permission_index:012d}"))


def _factor_owners(permission: str, permission_index: int, ordinal: int) -> tuple[UserId, UserId]:
    user_id = _factor_user_id(permission_index)
    other_id = _factor_other_id(permission_index)
    if permission == "deny_left":
        return other_id, user_id
    if permission == "deny_right":
        return user_id, other_id
    if permission == "deny_both":
        return other_id, other_id
    if permission == "mixed_visible_rows" and ordinal == 1:
        return other_id, other_id
    return user_id, user_id


def _factor_row_types(left_shape: str, right_shape: str) -> tuple[type[Any], type[Any]]:
    from conform.l5250_matching.test_phase4_expression_kernels import (
        Phase4SecureExpressionLeft,
        Phase4SecureExpressionRight,
    )
    from conform.l5250_matching.test_phase4_reopened_definition import (
        Phase4CombinedPolyLeft,
        Phase4CombinedPolyRight,
    )

    left_type = Phase4SecureExpressionLeft if left_shape == "concrete" else Phase4CombinedPolyLeft
    right_type = Phase4SecureExpressionRight if right_shape == "concrete" else Phase4CombinedPolyRight
    return left_type, right_type


def _factor_expression(profile: Phase4Profile, left_field: Any, right_field: Any) -> _Expression:
    left = matching.MatchLeftFieldExpression.from_field(left_field)
    right = matching.MatchRightFieldExpression.from_field(right_field)
    if profile == "left_field":
        return left
    if profile == "right_field":
        return right
    if profile == "add":
        return matching.MatchAddExpression(left=left, right=right)
    if profile == "subtract":
        return matching.MatchSubtractExpression(left=left, right=right)
    if profile == "multiply":
        return matching.MatchMultiplyExpression(left=left, right=right)
    if profile == "divide":
        return matching.MatchDivideExpression(numerator=left, denominator=right)
    if profile == "absolute":
        return matching.MatchFunctionExpression(function=matching.MatchExpressionFunction.ABSOLUTE, argument=left)
    msg = f"Unsupported valid factor expression profile: {profile}"
    raise ValueError(msg)


def _factor_spec(permission: str, left_shape: str, right_shape: str, profile: Phase4Profile):
    left_type, right_type = _factor_row_types(left_shape, right_shape)
    left_field = field(left_type.coordinate) if left_shape == "concrete" else field(left_type.value)
    right_field = field(right_type.coordinate) if right_shape == "concrete" else field(right_type.value)
    identity = f"{profile}:{permission}:{left_shape}:{right_shape}"
    expression = _factor_expression(profile, left_field, right_field)
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId(f"phase4:factor:{identity}"),
        left=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId(f"phase4:factor:{identity}:left"),
            row_type=left_type,
            representation=matching.MatchDenseRepresentationSpec(
                representation_ref_id=matching.MatchRepresentationRefId(f"phase4:factor:{identity}:left:dense"),
                dimensions=matching.MatchVectorDimensions(1),
                coordinates=(matching.MatchDenseCoordinateSpec.from_field(left_field),),
            ),
        ),
        right=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId(f"phase4:factor:{identity}:right"),
            row_type=right_type,
            representation=matching.MatchDenseRepresentationSpec(
                representation_ref_id=matching.MatchRepresentationRefId(f"phase4:factor:{identity}:right:dense"),
                dimensions=matching.MatchVectorDimensions(1),
                coordinates=(matching.MatchDenseCoordinateSpec.from_field(right_field),),
            ),
        ),
        kernel=matching.MatchTypedExpressionKernelSpec(
            kernel_ref_id=matching.MatchKernelRefId(f"phase4:factor:{identity}:kernel"),
            expression=expression,
            null_policy=matching.MatchExpressionNullPolicy.REJECT,
            score_direction=matching.MatchScoreDirection.HIGHER_IS_BETTER,
        ),
        policies=matching.MatchPolicies(
            guarantee=matching.MatchGuarantee.EXACT,
            missing_representation=matching.FailMissingRepresentationPolicy(),
            self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
            duplicates=matching.RejectDuplicatePairsPolicy(),
            freshness=matching.RequireCurrentFreshnessPolicy(),
        ),
        result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
        filters=matching.MatchFilterSet(
            left=matching.MatchEndpointFilterSpec.from_expression(
                field(left_type.label) == f"{permission}:{left_shape}:left",
            ),
            right=matching.MatchEndpointFilterSpec.from_expression(
                field(right_type.label) == f"{permission}:{right_shape}:right",
            ),
            pair=matching.NoMatchFilter(),
        ),
        work_limits=matching.MatchWorkLimits.standard_exact_dense(),
    )


def _factor_seed_rows() -> tuple[tuple[type[Any], Any], ...]:
    from conform.l5250_matching.test_phase4_expression_kernels import (
        Phase4SecureExpressionLeft,
        Phase4SecureExpressionRight,
    )
    from conform.l5250_matching.test_phase4_reopened_definition import (
        Phase4CombinedPolyLeft,
        Phase4CombinedPolyLeftSubtype,
        Phase4CombinedPolyRight,
        Phase4CombinedPolyRightSubtype,
    )

    rows: list[tuple[type[Any], Any]] = []
    for permission_index, permission in enumerate(_PERMISSION_SHAPES, start=1):
        rows.extend(
            (
                (
                    UserSession,
                    UserSession(
                        sys_id=_factor_session_id(permission_index),
                        session_type="user",
                        user_id=_factor_user_id(permission_index),
                    ),
                ),
                (
                    UserSession,
                    UserSession(
                        sys_id=_factor_other_session_id(permission_index),
                        session_type="user",
                        user_id=_factor_other_id(permission_index),
                    ),
                ),
            ),
        )
        row_count = 2 if permission == "mixed_visible_rows" else 1
        for shape in _POLYMORPHISM_SHAPES:
            identity = f"{permission}:{shape}"
            for ordinal in range(row_count):
                left_owner, right_owner = _factor_owners(permission, permission_index, ordinal)
                if shape == "concrete":
                    rows.extend(
                        (
                            (
                                Phase4SecureExpressionLeft,
                                Phase4SecureExpressionLeft(
                                    label=f"{identity}:left",
                                    coordinate=1.0,
                                    protected_value=1.0,
                                    owner_id=left_owner,
                                ),
                            ),
                            (
                                Phase4SecureExpressionRight,
                                Phase4SecureExpressionRight(
                                    label=f"{identity}:right",
                                    coordinate=1.0,
                                    protected_value=1.0,
                                    owner_id=right_owner,
                                ),
                            ),
                        ),
                    )
                    continue
                left_row = (
                    Phase4CombinedPolyLeft(label=f"{identity}:left", value=1.0, owner_id=left_owner)
                    if shape == "base_instance"
                    else Phase4CombinedPolyLeftSubtype(
                        label=f"{identity}:left",
                        value=1.0,
                        owner_id=left_owner,
                        detail="subtype",
                    )
                )
                right_row = (
                    Phase4CombinedPolyRight(label=f"{identity}:right", value=1.0, owner_id=right_owner)
                    if shape == "base_instance"
                    else Phase4CombinedPolyRightSubtype(
                        label=f"{identity}:right",
                        value=1.0,
                        owner_id=right_owner,
                        detail="subtype",
                    )
                )
                rows.extend(((Phase4CombinedPolyLeft, left_row), (Phase4CombinedPolyRight, right_row)))
    return tuple(rows)


def _factor_outcome(
    result,
    profile: Phase4Profile,
    permission: str,
    left_shape: str,
    right_shape: str,
    surface: Phase4Surface,
):
    expected_count = 0 if permission in {"deny_left", "deny_right", "deny_both"} else 1
    if len(result.edges) != expected_count:
        msg = f"Phase 4 mandatory-factor cell returned {len(result.edges)} edges; expected {expected_count}"
        raise AssertionError(msg)
    expected_score = {
        "left_field": 1.0,
        "right_field": 1.0,
        "add": 2.0,
        "subtract": 0.0,
        "multiply": 1.0,
        "divide": 1.0,
        "absolute": 1.0,
    }[profile]
    observed_scores = tuple(float(edge.score.canonical) for edge in result.edges)
    observed_ranks = tuple(int(edge.left_rank) for edge in result.edges)
    oracle_scores = tuple(expected_score for _edge in result.edges)
    oracle_ranks = tuple(range(1, len(result.edges) + 1))
    return Phase4PermissionPolymorphismOutcome(
        execution_surface=surface,
        expression_profile=profile,
        permission_shape=permission,
        left_type_name=left_shape,
        right_type_name=right_shape,
        expression_node_operations=int(result.work.expression_evaluations),
        observed_edges=tuple((edge.left.label, edge.right.label) for edge in result.edges),
        observed_scores=observed_scores,
        observed_ranks=observed_ranks,
        oracle_scores=oracle_scores,
        oracle_ranks=oracle_ranks,
    )


def _factor_seed_groups() -> tuple[tuple[SessionId, type[Any], list[Any]], ...]:
    owner_sessions = {
        owner_id: session_id
        for permission_index, _permission in enumerate(_PERMISSION_SHAPES, start=1)
        for owner_id, session_id in (
            (_factor_user_id(permission_index), _factor_session_id(permission_index)),
            (_factor_other_id(permission_index), _factor_other_session_id(permission_index)),
        )
    }
    groups: dict[tuple[SessionId, type[Any]], list[Any]] = {}
    for row_type, row in _factor_seed_rows():
        session_id = SessionId.schema() if row_type is UserSession else owner_sessions[row.owner_id]
        groups.setdefault((session_id, row_type), []).append(row)
    return tuple((session_id, row_type, rows) for (session_id, row_type), rows in groups.items())


def execute_permission_polymorphism_product(
    connection: SyncDatabaseConnection,
    backend_type: str,
) -> tuple[Phase4PermissionPolymorphismOutcome, ...]:
    """Execute each permission and endpoint-type cell through sync and lazy surfaces."""
    del backend_type

    groups_by_session: dict[SessionId, list[tuple[type[Any], list[Any]]]] = {}
    for session_id, row_type, rows in _factor_seed_groups():
        groups_by_session.setdefault(session_id, []).append((row_type, rows))
    for session_id, groups in groups_by_session.items():

        def seed(txn: SyncWriteTransaction, *, groups: list[tuple[type[Any], list[Any]]] = groups) -> None:
            for row_type, rows in groups:
                txn.insert_many(row_type, rows)

        connection.session(session_id).write(fn=seed)
    outcomes: list[Phase4PermissionPolymorphismOutcome] = []
    for permission_index, permission in enumerate(_PERMISSION_SHAPES, start=1):

        def execute(txn: SyncReadTransaction) -> None:
            for profile in _VALID_PROFILES:
                cells = tuple(
                    (left_shape, right_shape, _factor_spec(permission, left_shape, right_shape, profile))
                    for left_shape in _POLYMORPHISM_SHAPES
                    for right_shape in _POLYMORPHISM_SHAPES
                )
                sync_results = tuple(matching.match(txn, spec) for _, _, spec in cells)
                pending = tuple(matching.match_lazy(txn, spec) for _, _, spec in cells)
                lazy_results = lazy_tuple(*pending).resolve()
                for (left_shape, right_shape, _), sync_result, lazy_result in zip(
                    cells,
                    sync_results,
                    lazy_results,
                    strict=True,
                ):
                    outcomes.append(
                        _factor_outcome(
                            sync_result,
                            profile,
                            permission,
                            left_shape,
                            right_shape,
                            "sync",
                        )
                    )
                    outcomes.append(
                        _factor_outcome(
                            lazy_result,
                            profile,
                            permission,
                            left_shape,
                            right_shape,
                            "lazy",
                        )
                    )

        connection.session(_factor_session_id(permission_index)).read(fn=execute)
    return tuple(outcomes)


async def execute_permission_polymorphism_async_product(
    connection: AsyncDatabaseConnection,
    backend_type: str,
    *,
    seed_data: bool = True,
) -> tuple[Phase4PermissionPolymorphismOutcome, ...]:
    """Execute each permission and endpoint-type cell through the async surface."""
    del backend_type

    if seed_data:
        groups_by_session: dict[SessionId, list[tuple[type[Any], list[Any]]]] = {}
        for session_id, row_type, rows in _factor_seed_groups():
            groups_by_session.setdefault(session_id, []).append((row_type, rows))
        for session_id, groups in groups_by_session.items():

            async def seed(
                txn: AsyncWriteTransaction,
                *,
                groups: list[tuple[type[Any], list[Any]]] = groups,
            ) -> None:
                for row_type, rows in groups:
                    await txn.insert_many_async(row_type, rows)

            await connection.session(session_id).write_async(fn=seed)
    outcomes: list[Phase4PermissionPolymorphismOutcome] = []
    for permission_index, permission in enumerate(_PERMISSION_SHAPES, start=1):

        async def execute(txn: AsyncReadTransaction) -> None:
            for profile in _VALID_PROFILES:
                for left_shape in _POLYMORPHISM_SHAPES:
                    for right_shape in _POLYMORPHISM_SHAPES:
                        spec = _factor_spec(permission, left_shape, right_shape, profile)
                        result = await matching.match_async(txn, spec)
                        outcomes.append(
                            _factor_outcome(
                                result,
                                profile,
                                permission,
                                left_shape,
                                right_shape,
                                "async",
                            ),
                        )

        await connection.session(_factor_session_id(permission_index)).read_async(fn=execute)
    return tuple(outcomes)


def _expression(profile: str) -> _Expression:
    left_first = matching.MatchLeftFieldExpression.from_field(field(Phase4ExpressionLeft.first))
    left_second = matching.MatchLeftFieldExpression.from_field(field(Phase4ExpressionLeft.second))
    right_first = matching.MatchRightFieldExpression.from_field(field(Phase4ExpressionRight.first))
    right_second = matching.MatchRightFieldExpression.from_field(field(Phase4ExpressionRight.second))
    if profile == "left_field":
        return left_first
    if profile == "right_field":
        return right_first
    if profile == "add":
        return matching.MatchAddExpression(left=left_first, right=right_first)
    if profile == "subtract":
        return matching.MatchSubtractExpression(left=left_first, right=right_first)
    if profile == "multiply":
        return matching.MatchMultiplyExpression(left=left_first, right=right_first)
    if profile == "divide":
        return matching.MatchDivideExpression(numerator=left_first, denominator=right_second)
    if profile == "absolute":
        return matching.MatchFunctionExpression(
            function=matching.MatchExpressionFunction.ABSOLUTE,
            argument=matching.MatchSubtractExpression(left=left_second, right=right_first),
        )
    msg = f"unknown valid expression profile: {profile}"
    raise ValueError(msg)


def _filtered_spec(name: str, expression: _Expression, left_label: str, right_label: str):
    base = _two_field_expression_spec(name)
    assert isinstance(base.kernel, matching.MatchTypedExpressionKernelSpec)
    return validated_model_update(
        base,
        {
            "kernel": validated_model_update(base.kernel, {"expression": expression}),
            "result_shape": matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
            "filters": matching.MatchFilterSet(
                left=matching.MatchEndpointFilterSpec.from_expression(field(Phase4ExpressionLeft.label) == left_label),
                right=matching.MatchEndpointFilterSpec.from_expression(field(Phase4ExpressionRight.label) == right_label),
                pair=matching.NoMatchFilter(),
            ),
        },
    )


def _valid_spec(profile: str, name: str):
    return _filtered_spec(name, _expression(profile), "valid-left", "valid-right")


def _invalid_spec(profile: str, name: str):
    if profile == "null":
        expression: _Expression = matching.MatchLeftFieldExpression.model_validate(
            {"row_type": Phase4ExpressionLeft, "field_name": "nullable_value"},
        )
        return _filtered_spec(name, expression, "null-left", "null-right")
    if profile == "division_by_zero":
        expression = matching.MatchDivideExpression(
            numerator=matching.MatchLeftFieldExpression.from_field(field(Phase4ExpressionLeft.first)),
            denominator=matching.MatchRightFieldExpression.from_field(field(Phase4ExpressionRight.first)),
        )
        return _filtered_spec(name, expression, "zero-left", "zero-right")
    product = matching.MatchMultiplyExpression(
        left=matching.MatchLeftFieldExpression.from_field(field(Phase4ExpressionLeft.first)),
        right=matching.MatchRightFieldExpression.from_field(field(Phase4ExpressionRight.first)),
    )
    return _filtered_spec(
        name,
        matching.MatchMultiplyExpression(left=product, right=product),
        "huge-left",
        "huge-right",
    )


def _observe_inherited_spec(
    connection: SyncDatabaseConnection,
    spec,
) -> tuple[str, tuple[tuple[str, str], ...]]:
    def execute(txn: SyncReadTransaction):
        return matching.match(txn, spec)

    try:
        result = connection.session(SessionId.schema()).read(fn=execute)
    except matching.MatchError as error:
        return type(error).__name__, ()
    assert isinstance(
        result,
        matching.TopKPerLeftMatchResult
        | matching.TopKPerRightMatchResult
        | matching.GlobalTopKMatchResult
        | matching.ThresholdJoinMatchResult,
    )
    return type(result).__name__, tuple((edge.left.label, edge.right.label) for edge in result.edges)


def _inherited_filter_spec(value: str, name: str):
    base = _valid_spec("add", name)
    left_filter = matching.MatchEndpointFilterSpec.from_expression(
        field(Phase4ExpressionLeft.label) == "valid-left",
    )
    right_filter = matching.MatchEndpointFilterSpec.from_expression(
        field(Phase4ExpressionRight.label) == "valid-right",
    )
    pair_filter = matching.MatchPairFieldComparisonSpec.from_fields(
        field(Phase4ExpressionLeft.label),
        matching.MatchPairComparisonOperator.NOT_EQUAL,
        field(Phase4ExpressionRight.label),
    )
    filters = {
        "none": matching.MatchFilterSet.no_filters(),
        "left": matching.MatchFilterSet(left=left_filter, right=matching.NoMatchFilter(), pair=matching.NoMatchFilter()),
        "right": matching.MatchFilterSet(left=matching.NoMatchFilter(), right=right_filter, pair=matching.NoMatchFilter()),
        "pair": matching.MatchFilterSet(left=matching.NoMatchFilter(), right=matching.NoMatchFilter(), pair=pair_filter),
        "all": matching.MatchFilterSet(left=left_filter, right=right_filter, pair=pair_filter),
    }
    return validated_model_update(base, {"filters": filters[value]})


def _inherited_policy_spec(value: str, name: str):
    base = _valid_spec("add", name)
    policy = {
        "fail": matching.FailMissingRepresentationPolicy(),
        "omit": matching.OmitMissingRepresentationPolicy(),
        "declared_score": matching.EmitDeclaredMissingScorePolicy(score=matching.MatchScoreValue(0.0)),
        "materialize": matching.RequireMaterializedRepresentationPolicy(),
    }[value]
    return validated_model_update(
        base,
        {"policies": validated_model_update(base.policies, {"missing_representation": policy})},
    )


def _inherited_shape_spec(value: str, name: str):
    base = _valid_spec("add", name)
    shape = {
        "top_left": matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
        "top_right": matching.TopKPerRightMatchShape(neighbor_count=matching.NeighborCount(1)),
        "global": matching.GlobalTopKMatchShape(neighbor_count=matching.NeighborCount(1)),
        "threshold": matching.ThresholdJoinMatchShape(
            threshold=matching.MatchScoreValue(0.0),
            boundary=matching.MatchThresholdBoundary.INCLUSIVE,
            result_limit=matching.MatchResultLimit(1),
        ),
    }[value]
    return validated_model_update(base, {"result_shape": shape})


def _inherited_freshness_outcome(
    connection: SyncDatabaseConnection,
    value: str,
) -> Phase4InheritedFactorOutcome:
    from conform.l5250_matching.test_phase3_result_policies import _artifact_state
    from data_layer.matching import publish_matching_artifact

    base = _valid_spec("add", f"inherited:freshness:{value}")
    freshness = {
        "current": matching.RequireCurrentFreshnessPolicy(),
        "stale_accepted": matching.AcceptStaleWithDiagnosticsFreshnessPolicy(),
        "stale_rejected": matching.RequireCurrentFreshnessPolicy(),
        "bounded_watermark": matching.RequireBoundedWatermarkFreshnessPolicy(
            required_watermark=matching.MatchArtifactWatermark(8),
        ),
        "exact_completion": matching.ExactCompletionFreshnessPolicy(),
    }[value]
    spec = validated_model_update(
        base,
        {"policies": validated_model_update(base.policies, {"freshness": freshness})},
    )
    if value != "current":
        state = _artifact_state(8, 7, maintenance_mode="asynchronous")
        connection.session(SessionId.schema()).write(fn=lambda txn: publish_matching_artifact(txn, spec, state))
    if value == "bounded_watermark":
        connection.session(SessionId.schema()).write(
            fn=lambda txn: publish_matching_artifact(txn, spec, _artifact_state(8, 8, generation=2)),
        )
    outcome, edges = _observe_inherited_spec(connection, spec)
    oracle_edges = () if value == "stale_rejected" else (("valid-left", "valid-right"),)
    return Phase4InheritedFactorOutcome(
        factor_name="freshness",
        factor_value=value,
        public_outcome=outcome,
        observed_edges=edges,
        oracle_edges=oracle_edges,
    )


def _versioned_expression_spec():
    from conform.l5250_matching.test_phase3_result_policies import (
        Phase3VersionedLeft,
        Phase3VersionedRight,
    )

    expression = matching.MatchAddExpression(
        left=matching.MatchLeftFieldExpression.from_field(field(Phase3VersionedLeft.coordinate)),
        right=matching.MatchRightFieldExpression.from_field(field(Phase3VersionedRight.coordinate)),
    )
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId("phase4:inherited:versioned"),
        left=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId("phase4:inherited:versioned:left"),
            row_type=Phase3VersionedLeft,
            representation=matching.MatchDenseRepresentationSpec(
                representation_ref_id=matching.MatchRepresentationRefId("phase4:inherited:versioned:left:dense"),
                dimensions=matching.MatchVectorDimensions(1),
                coordinates=(matching.MatchDenseCoordinateSpec.from_field(field(Phase3VersionedLeft.coordinate)),),
            ),
        ),
        right=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId("phase4:inherited:versioned:right"),
            row_type=Phase3VersionedRight,
            representation=matching.MatchDenseRepresentationSpec(
                representation_ref_id=matching.MatchRepresentationRefId("phase4:inherited:versioned:right:dense"),
                dimensions=matching.MatchVectorDimensions(1),
                coordinates=(matching.MatchDenseCoordinateSpec.from_field(field(Phase3VersionedRight.coordinate)),),
            ),
        ),
        kernel=matching.MatchTypedExpressionKernelSpec(
            kernel_ref_id=matching.MatchKernelRefId("phase4:inherited:versioned:kernel"),
            expression=expression,
            null_policy=matching.MatchExpressionNullPolicy.REJECT,
            score_direction=matching.MatchScoreDirection.HIGHER_IS_BETTER,
        ),
        policies=matching.MatchPolicies(
            guarantee=matching.MatchGuarantee.EXACT,
            missing_representation=matching.FailMissingRepresentationPolicy(),
            self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
            duplicates=matching.RejectDuplicatePairsPolicy(),
            freshness=matching.RequireCurrentFreshnessPolicy(),
        ),
        result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
        filters=matching.MatchFilterSet.no_filters(),
        work_limits=matching.MatchWorkLimits.standard_exact_dense(),
    )


def _execute_version_factor_outcomes(
    connection: SyncDatabaseConnection,
    unversioned_edges: tuple[tuple[str, str], ...],
) -> tuple[Phase4InheritedFactorOutcome, ...]:
    from conform.l5250_matching.test_phase3_result_policies import (
        PHASE3_MATCH_DOMAIN,
        Phase3VersionedLeft,
        Phase3VersionedRight,
        Phase3VersionedRightSubtype,
    )
    from data_layer.versioned_schema import SyncVersionedDatabaseConnection
    from data_layer.versioned_transactions import SyncVersionedReadTransaction, SyncVersionedWriteTransaction
    from data_layer_testing.versioning.revision_helpers import create_test_revision

    if not isinstance(connection, SyncVersionedDatabaseConnection):
        raise TypeError("Phase 4 version factors require a versioned connection")
    _initial_revision, branch_id = create_test_revision(
        connection,
        PHASE3_MATCH_DOMAIN,
        message="phase4 inherited version seed",
        branch_name="phase4-inherited-expression",
    )

    def insert_rows(txn: SyncVersionedWriteTransaction):
        txn.insert(Phase3VersionedLeft, Phase3VersionedLeft(label="version-left", coordinate=1.0))
        txn.insert(
            Phase3VersionedRight,
            Phase3VersionedRightSubtype(label="version-right", coordinate=2.0, detail="expression"),
        )
        return txn.commit_branch(message="phase4 inherited expression rows")

    revision_id = connection.write_version(
        session_id=SessionId.schema(),
        domain=PHASE3_MATCH_DOMAIN,
        branch=branch_id,
        fn=insert_rows,
    )
    spec = _versioned_expression_spec()

    def execute(txn: SyncVersionedReadTransaction):
        return matching.match(txn, spec)

    branch_result = connection.version(PHASE3_MATCH_DOMAIN, branch_id, SessionId.schema()).read(fn=execute)
    pinned_result = connection.read_version(
        session_id=SessionId.schema(),
        domain=PHASE3_MATCH_DOMAIN,
        revision=revision_id,
        fn=execute,
    )

    def create_feature(txn: SyncVersionedWriteTransaction):
        feature_branch_id = txn.create_branch("phase4-inherited-feature", from_revision_id=revision_id)
        txn.commit()
        return feature_branch_id

    feature_branch_id = connection.write_version(
        session_id=SessionId.schema(),
        domain=PHASE3_MATCH_DOMAIN,
        branch=branch_id,
        fn=create_feature,
    )
    cross_result = connection.version(PHASE3_MATCH_DOMAIN, feature_branch_id, SessionId.schema()).read(fn=execute)
    assert isinstance(branch_result, matching.TopKPerLeftMatchResult)
    assert isinstance(pinned_result, matching.TopKPerLeftMatchResult)
    assert isinstance(cross_result, matching.TopKPerLeftMatchResult)
    versioned_edges = (("version-left", "version-right"),)
    observed = {
        "unversioned": unversioned_edges,
        "branch_tip": tuple((edge.left.label, edge.right.label) for edge in branch_result.edges),
        "pinned_revision": tuple((edge.left.label, edge.right.label) for edge in pinned_result.edges),
        "cross_branch": tuple((edge.left.label, edge.right.label) for edge in cross_result.edges),
    }
    expected = {
        "unversioned": (("valid-left", "valid-right"),),
        "branch_tip": versioned_edges,
        "pinned_revision": versioned_edges,
        "cross_branch": versioned_edges,
    }
    return tuple(
        Phase4InheritedFactorOutcome(
            factor_name="versions",
            factor_value=factor_value,
            public_outcome=type(
                branch_result if factor_value == "branch_tip" else pinned_result if factor_value == "pinned_revision" else cross_result,
            ).__name__,
            observed_edges=observed[factor_value],
            oracle_edges=expected[factor_value],
        )
        for factor_value in ("unversioned", "branch_tip", "pinned_revision", "cross_branch")
    )


def _execute_inherited_factor_outcomes(
    connection: SyncDatabaseConnection,
    async_connection: AsyncDatabaseConnection,
    factors: Phase4InheritedFactors,
    valid_observations: dict[str, tuple[tuple[str, str], ...]],
) -> tuple[Phase4InheritedFactorOutcome, ...]:
    outcomes: list[Phase4InheritedFactorOutcome] = []
    builders = {
        "filters": _inherited_filter_spec,
        "result_policies": _inherited_policy_spec,
        "result_shapes": _inherited_shape_spec,
    }
    for factor_name, builder in builders.items():
        for factor_value in getattr(factors, factor_name):
            spec = builder(factor_value, f"inherited:{factor_name}:{factor_value}")
            outcome, edges = _observe_inherited_spec(connection, spec)
            if factor_name == "filters" and factor_value in {"none", "pair"}:
                oracle_edges = tuple((left_label, "huge-right") for left_label in ("valid-left", "null-left", "zero-left", "huge-left"))
            elif factor_name == "filters" and factor_value == "left":
                oracle_edges = (("valid-left", "huge-right"),)
            elif factor_name == "filters" and factor_value == "right":
                oracle_edges = tuple((left_label, "valid-right") for left_label in ("valid-left", "null-left", "zero-left", "huge-left"))
            else:
                oracle_edges = (("valid-left", "valid-right"),)
            outcomes.append(
                Phase4InheritedFactorOutcome(
                    factor_name=factor_name,
                    factor_value=factor_value,
                    public_outcome=outcome,
                    observed_edges=edges,
                    oracle_edges=oracle_edges,
                ),
            )
    for freshness_value in factors.freshness:
        outcomes.append(_inherited_freshness_outcome(connection, freshness_value))

    for factor_name, factor_values in (
        ("score_directions", factors.score_directions),
        ("null_policies", factors.null_policies),
        ("exact_bound_variants", factors.exact_bound_variants),
    ):
        for factor_value in factor_values:
            base = _valid_spec("add", f"inherited:{factor_name}:{factor_value}")
            assert isinstance(base.kernel, matching.MatchTypedExpressionKernelSpec)
            kernel_updates: dict[str, object] = {}
            if factor_name == "score_directions":
                kernel_updates["score_direction"] = (
                    matching.MatchScoreDirection.HIGHER_IS_BETTER
                    if factor_value == "higher_is_better"
                    else matching.MatchScoreDirection.LOWER_IS_BETTER
                )
            elif factor_name == "null_policies":
                kernel_updates["null_policy"] = (
                    matching.MatchExpressionNullPolicy.REJECT
                    if factor_value == "reject"
                    else matching.MatchExpressionNullPolicy.COALESCE_ZERO
                )
            spec = validated_model_update(
                base,
                {"kernel": validated_model_update(base.kernel, kernel_updates)},
            )
            outcome, edges = _observe_inherited_spec(connection, spec)
            outcomes.append(
                Phase4InheritedFactorOutcome(
                    factor_name=factor_name,
                    factor_value=factor_value,
                    public_outcome=outcome,
                    observed_edges=edges,
                    oracle_edges=(("valid-left", "valid-right"),),
                ),
            )

    sync_product = execute_permission_polymorphism_product(connection, "matrix")
    async_product = run_async_test_with_system_authority(
        execute_permission_polymorphism_async_product(async_connection, "matrix", seed_data=False),
    )
    if len(sync_product) != 630 or len(async_product) != 315:
        raise AssertionError("Phase 4 mandatory-factor execution product is incomplete")
    permission_names = {
        "allow": "allow_all",
        "deny_left": "deny_left",
        "deny_right": "deny_right",
        "deny_both": "deny_both",
        "mixed": "mixed_visible_rows",
    }
    for factor_value in factors.permissions:
        product_value = permission_names[factor_value]
        check = next(
            item
            for item in sync_product
            if item.permission_shape == product_value and item.left_type_name == "concrete" and item.right_type_name == "concrete"
        )
        outcomes.append(
            Phase4InheritedFactorOutcome(
                factor_name="permissions",
                factor_value=factor_value,
                public_outcome=f"{check.execution_surface}:expression",
                observed_edges=check.observed_edges,
                oracle_edges=(
                    ()
                    if product_value in {"deny_left", "deny_right", "deny_both"}
                    else ((f"{product_value}:concrete:left", f"{product_value}:concrete:right"),)
                ),
            ),
        )
    for factor_name in ("left_polymorphism", "right_polymorphism"):
        for factor_value in getattr(factors, factor_name):
            check = next(
                item
                for item in sync_product
                if item.permission_shape == "allow_all"
                and (item.left_type_name if factor_name == "left_polymorphism" else item.right_type_name) == factor_value
            )
            outcomes.append(
                Phase4InheritedFactorOutcome(
                    factor_name=factor_name,
                    factor_value=factor_value,
                    public_outcome=f"{check.execution_surface}:expression",
                    observed_edges=check.observed_edges,
                    oracle_edges=(
                        (
                            (f"allow_all:{factor_value}:left", "allow_all:concrete:right")
                            if factor_name == "left_polymorphism"
                            else ("allow_all:concrete:left", f"allow_all:{factor_value}:right")
                        ),
                    ),
                ),
            )
    outcomes.extend(
        _execute_version_factor_outcomes(connection, valid_observations["sync:add"]),
    )
    return tuple(outcomes)


PHASE4_EXPRESSION_MATRIX = Phase4ExpressionMatrixManifest(
    valid_cases=tuple(
        Phase4MatrixCase(case_id=f"{surface}:{profile}", profile=profile, surface=surface)
        for profile in _VALID_PROFILES
        for surface in _SURFACES
    ),
    invalid_cases=tuple(
        Phase4MatrixCase(case_id=f"{surface}:{profile}", profile=profile, surface=surface)
        for profile in _INVALID_PROFILES
        for surface in _SURFACES
    ),
    inherited_factors=Phase4InheritedFactors(),
    executes_public_results=True,
)

