"""Independent exhaustive evaluator for closed Phase 4 score expressions."""

from __future__ import annotations

import math
from typing import ClassVar, Literal

from pydantic import BaseModel, ConfigDict

from data_layer import matching
from data_layer.schema import ApplicationObjectRow
from data_layer.types import SysId


class Phase4OracleOutcome(BaseModel):
    """One typed successful independent-evaluator outcome."""

    model_config = ConfigDict(frozen=True, extra="forbid")
    values: ClassVar[tuple[str, ...]] = (
        "left_field",
        "right_field",
        "add",
        "subtract",
        "multiply",
        "divide",
        "absolute",
    )

    variant: Literal["left_field", "right_field", "add", "subtract", "multiply", "divide", "absolute"]
    value: float


class Phase4OracleErrorOutcome(BaseModel):
    """Portable failure observed by direct independent arithmetic."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    variant: Literal["null", "division_by_zero", "non_finite"]


class Phase4ExpressionOutcomeEvaluator:
    """Execute the finite portable expression-error matrix."""

    def __call__(self: Phase4ExpressionOutcomeEvaluator) -> Phase4ExpressionOutcomeEvaluator:
        return self

    def execute_complete_error_matrix(
        self: Phase4ExpressionOutcomeEvaluator,
    ) -> tuple[Phase4OracleErrorOutcome, ...]:
        values: tuple[tuple[str, float | None, float | None], ...] = (
            ("null", None, 1.0),
            ("division_by_zero", 1.0, 0.0),
            ("non_finite", 1e148, 1e-200),
        )
        outcomes: list[Phase4OracleErrorOutcome] = []
        for variant, numerator, denominator in values:
            if numerator is None or denominator is None:
                outcomes.append(Phase4OracleErrorOutcome(variant="null"))
                continue
            if denominator == 0.0:
                outcomes.append(Phase4OracleErrorOutcome(variant="division_by_zero"))
                continue
            quotient = numerator / denominator
            if not math.isfinite(quotient):
                outcomes.append(Phase4OracleErrorOutcome(variant="non_finite"))
                continue
            msg = f"Portable error profile unexpectedly produced {quotient}"
            raise AssertionError(msg)
        return tuple(outcomes)


class Phase4OracleError(BaseModel):
    """One typed portable independent-evaluator failure."""

    model_config = ConfigDict(frozen=True, extra="forbid")
    values: ClassVar[tuple[str, ...]] = ("null", "division_by_zero", "non_finite")

    variant: Literal["null", "division_by_zero", "non_finite"]


evaluate_expression_outcome = Phase4ExpressionOutcomeEvaluator()


def _numeric_field(row: ApplicationObjectRow[SysId], field_name: matching.MatchFieldName) -> float:
    value = row.model_dump()[str(field_name)]
    if not isinstance(value, int | float) or isinstance(value, bool):
        raise TypeError(f"Expression field {field_name} is not numeric")
    return float(value)


def evaluate_expression(
    expression: matching.MatchScoreExpression,
    left: ApplicationObjectRow[SysId],
    right: ApplicationObjectRow[SysId],
) -> float:
    """Evaluate one closed expression without database or grammar code."""
    if isinstance(expression, matching.MatchLeftFieldExpression):
        return _numeric_field(left, expression.field_name)
    if isinstance(expression, matching.MatchRightFieldExpression):
        return _numeric_field(right, expression.field_name)
    if isinstance(expression, matching.MatchAddExpression):
        return evaluate_expression(expression.left, left, right) + evaluate_expression(expression.right, left, right)
    if isinstance(expression, matching.MatchSubtractExpression):
        return evaluate_expression(expression.left, left, right) - evaluate_expression(expression.right, left, right)
    if isinstance(expression, matching.MatchMultiplyExpression):
        return evaluate_expression(expression.left, left, right) * evaluate_expression(expression.right, left, right)
    if isinstance(expression, matching.MatchDivideExpression):
        return evaluate_expression(expression.numerator, left, right) / evaluate_expression(
            expression.denominator,
            left,
            right,
        )
    if isinstance(expression, matching.MatchFunctionExpression):
        argument = evaluate_expression(expression.argument, left, right)
        if expression.function is matching.MatchExpressionFunction.ABSOLUTE:
            return abs(argument)
    raise TypeError(f"Unknown score-expression variant: {type(expression).__name__}")

