"""Independent exact string-kernel oracles for matching Phase 6."""

from __future__ import annotations

import unicodedata
from collections import Counter
from typing import Literal


type UnicodeNormalizationForm = Literal["NFC", "NFD", "NFKC", "NFKD"]


def normalize_text(value: str, *, form: UnicodeNormalizationForm, casefold: bool) -> str:
    """Apply the declared portable normalization profile."""
    normalized = unicodedata.normalize(form, value)
    return normalized.casefold() if casefold else normalized


def overlapping_occurrence_count(pattern: str, text: str) -> int:
    """Count overlapping exact substring occurrences."""
    if pattern == "":
        raise ValueError("empty patterns have no implicit substring semantics")
    return sum(text.startswith(pattern, offset) for offset in range(len(text)))


def levenshtein_codepoints(left: str, right: str) -> int:
    """Return exact Levenshtein distance over Unicode code points."""
    if len(left) < len(right):
        left, right = right, left
    previous = list(range(len(right) + 1))
    for left_index, left_value in enumerate(left, start=1):
        current = [left_index]
        for right_index, right_value in enumerate(right, start=1):
            current.append(
                min(
                    current[-1] + 1,
                    previous[right_index] + 1,
                    previous[right_index - 1] + (left_value != right_value),
                )
            )
        previous = current
    return previous[-1]


def qgram_counts(value: str, gram_length: int) -> Counter[str]:
    """Return multiplicity-preserving unpadded q-grams."""
    if gram_length <= 0:
        raise ValueError("gram length must be positive")
    return Counter(value[index : index + gram_length] for index in range(max(0, len(value) - gram_length + 1)))

