"""Phase 7 factor population and observed executable observation contracts.

The dimensions coordinate describes the compared representation: native fp32
coordinates or H14 output bits. H14 source-vector dimensions are separate fit observation.
"""

from __future__ import annotations

from collections.abc import Iterator
from itertools import product
import math
from types import MappingProxyType
from typing import Literal, Mapping, Self

from pydantic import BaseModel, ConfigDict, Field, model_validator


PHASE7_FACTOR_VALUES: Mapping[str, tuple[str, ...]] = MappingProxyType({
    "family": ("native_dense", "h14"),
    "physical_type": ("vector", "halfvec", "bit1024", "portable_packed"),
    "dimensions": ("two", "768", "1024"),
    "artifact_generation": ("missing", "current", "stale", "superseded"),
    "candidate_method": ("exact_native", "exact_portable"),
    "final_kernel": ("dot_product", "hamming"),
    "permission": ("allow_all", "deny_left", "deny_right", "deny_both", "mixed"),
    "left_polymorphism": ("concrete", "base", "subtype"),
    "right_polymorphism": ("concrete", "base", "subtype"),
    "version": ("unversioned", "branch_tip", "pinned_revision", "cross_branch"),
    "filter": ("none", "left", "right", "pair", "all", "selective", "empty"),
    "execution_surface": ("lazy", "sync", "async"),
    "backend": ("sqlite", "postgresql", "mariadb"),
})


# The payload-width extension does not replace any cell in the original population.
PHASE7_H14_PAYLOAD_WIDTHS: tuple[int, ...] = (0, 127, 128, 129)

_PHASE7_STRUCTURAL_AXES = (
    "family", "physical_type", "dimensions", "candidate_method", "final_kernel", "backend",
)
_PHASE7_SEMANTIC_AXES = tuple(
    factor for factor in PHASE7_FACTOR_VALUES if factor not in _PHASE7_STRUCTURAL_AXES
)


class Phase7StructuralClassification(BaseModel, frozen=True):
    """Classify representation compatibility, not permissions or execution outcomes."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    disposition: Literal["valid", "invalid", "inapplicable"]
    reason: Literal[
        "deployed_profile", "kernel_family_mismatch", "h14_dimensions",
        "fp32_precision", "physical_storage", "backend_method", "h14_payload_width",
    ]


def classify_phase7_h14_payload_width(width_bytes: int) -> Phase7StructuralClassification:
    """Classify the explicit canonical and malformed H14 payload-width boundaries."""
    if type(width_bytes) is not int or width_bytes not in PHASE7_H14_PAYLOAD_WIDTHS:
        raise ValueError("Payload width must belong to the declared H14 width extension")
    return Phase7StructuralClassification(
        disposition="valid" if width_bytes == 128 else "invalid",
        reason="h14_payload_width",
    )


def classify_phase7_structure(factors: Mapping[str, str]) -> Phase7StructuralClassification:
    """Partition six structural axes without claiming equivalence of other factors."""
    required = {"family", "physical_type", "dimensions", "candidate_method", "final_kernel", "backend"}
    if set(factors) != required:
        raise ValueError("Structural classification requires exactly six structural factors")
    for factor, value in factors.items():
        if value not in PHASE7_FACTOR_VALUES[factor]:
            raise ValueError("Structural classification requires declared factor values")
    native = factors["family"] == "native_dense"
    postgres = factors["backend"] == "postgresql"
    if factors["final_kernel"] != ("dot_product" if native else "hamming"):
        return Phase7StructuralClassification(disposition="invalid", reason="kernel_family_mismatch")
    if not native and factors["dimensions"] != "1024":
        return Phase7StructuralClassification(disposition="invalid", reason="h14_dimensions")
    if factors["physical_type"] == "halfvec":
        return Phase7StructuralClassification(disposition="invalid", reason="fp32_precision" if native else "physical_storage")
    method = "exact_native" if postgres else "exact_portable"
    if factors["candidate_method"] != method:
        return Phase7StructuralClassification(disposition="inapplicable", reason="backend_method")
    physical_type = ("vector" if native else "bit1024") if postgres else "portable_packed"
    if factors["physical_type"] != physical_type:
        return Phase7StructuralClassification(disposition="inapplicable", reason="physical_storage")
    return Phase7StructuralClassification(disposition="valid", reason="deployed_profile")


def iter_phase7_structurally_valid_cells() -> Iterator[Mapping[str, str]]:
    """Yield all 181,440 valid coordinates without expanding invalid symbolic cells."""
    structural_profiles: Iterator[dict[str, str]] = (
        dict(zip(_PHASE7_STRUCTURAL_AXES, coordinate, strict=True))
        for coordinate in product(*(PHASE7_FACTOR_VALUES[axis] for axis in _PHASE7_STRUCTURAL_AXES))
    )
    valid_profiles = tuple(
        profile for profile in structural_profiles
        if classify_phase7_structure(profile).disposition == "valid"
    )
    for structural in valid_profiles:
        for semantic_coordinate in product(*(
            PHASE7_FACTOR_VALUES[axis] for axis in _PHASE7_SEMANTIC_AXES
        )):
            yield MappingProxyType({
                **structural,
                **dict(zip(_PHASE7_SEMANTIC_AXES, semantic_coordinate, strict=True)),
            })


class Phase7FactorSelection(BaseModel, frozen=True):
    """One actual factor value observed by an executable test case."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    factor: str
    value: str

    @model_validator(mode="after")
    def validate_declared_value(self: Self) -> Self:
        allowed = PHASE7_FACTOR_VALUES.get(self.factor)
        if allowed is None or self.value not in allowed:
            raise ValueError("Phase 7 observation must use one declared factor value")
        return self


class Phase7DirectObservation(BaseModel, frozen=True):
    """One passed executable case and its actual factor coordinates."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    node_id: str
    outcome: Literal["passed"]
    outcome_sha256: str = Field(pattern=r"^[0-9a-f]{64}$")
    factors: tuple[Phase7FactorSelection, ...]

    @model_validator(mode="after")
    def validate_complete_coordinate(self: Self) -> Self:
        if "::test_" not in self.node_id:
            raise ValueError("Phase 7 observation requires a fully qualified pytest node ID")
        names = tuple(item.factor for item in self.factors)
        if len(names) != len(set(names)):
            raise ValueError("Phase 7 observation cannot declare one factor twice")
        return self


class Phase7MatrixManifest(BaseModel, frozen=True):
    """Keep symbolic population separate from observed execution results."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    symbolic_cell_count: int = Field(gt=0)
    direct_observation: tuple[Phase7DirectObservation, ...]

    @model_validator(mode="after")
    def validate_population(self: Self) -> Self:
        expected = math.prod(len(values) for values in PHASE7_FACTOR_VALUES.values())
        if self.symbolic_cell_count != expected:
            raise ValueError("Phase 7 symbolic population must equal the declared factor product")
        return self

    def uncovered_values(self) -> tuple[str, ...]:
        covered = {(item.factor, item.value) for observation in self.direct_observation for item in observation.factors}
        return tuple(
            f"{factor}={value}"
            for factor, values in PHASE7_FACTOR_VALUES.items()
            for value in values
            if (factor, value) not in covered
        )


PHASE7_MATRIX = Phase7MatrixManifest(
    symbolic_cell_count=math.prod(len(values) for values in PHASE7_FACTOR_VALUES.values()),
    direct_observation=(),
)

