"""Independent Phase 10 permission and polymorphism matrix."""

from __future__ import annotations

from itertools import product
from typing import Literal
from uuid import UUID

from conform.bootstrap_families.security import SECURITY_V1
from conform.l5250_matching.model_updates import validated_model_update
from data_layer import matching
from data_layer.connection import SyncDatabaseConnection
from data_layer.permissions import OwnerSharesScheme, UserId
from data_layer.schema import Json, PolymorphicObjectRow, field, register_table
from data_layer.session import SessionId, UserSession
from data_layer.transaction import SyncReadTransaction, SyncWriteTransaction
from data_layer.types import SysId
import numpy as np
import pytest


@register_table(plural="phase10_quantized_permission_lefts")
class Phase10QuantizedPermissionLeft(PolymorphicObjectRow[SysId], concrete_base=True):
    label: str
    vector: Json[list[float]]
    owner_id: UserId

    class Permissions:
        @staticmethod
        def get_scheme() -> OwnerSharesScheme:
            return OwnerSharesScheme()


class Phase10QuantizedPermissionLeftSubtype(Phase10QuantizedPermissionLeft):
    left_detail: str


@register_table(plural="phase10_quantized_permission_rights")
class Phase10QuantizedPermissionRight(PolymorphicObjectRow[SysId], concrete_base=True):
    label: str
    vector: Json[list[float]]
    source_watermark: matching.QuantizedSourceWatermark
    owner_id: UserId

    class Permissions:
        @staticmethod
        def get_scheme() -> OwnerSharesScheme:
            return OwnerSharesScheme()


class Phase10QuantizedPermissionRightSubtype(Phase10QuantizedPermissionRight):
    right_detail: str


TEST_BOOTSTRAP_FAMILY = SECURITY_V1
TEST_BOOTSTRAP_TABLES = (
    Phase10QuantizedPermissionLeft,
    Phase10QuantizedPermissionRight,
    UserSession,
    *matching.QUANTIZED_PROJECTION_TABLES,
)


def _execute_matrix(
    db_connection: SyncDatabaseConnection,
    family: Literal["qjl", "turboquant"],
) -> set[tuple[bool, bool, bool, bool, int]]:
    outcomes: set[tuple[bool, bool, bool, bool, int]] = set()
    for case, (allow_left, allow_right, left_subtype, right_subtype) in enumerate(
        product((False, True), repeat=4),
        start=1,
    ):
        user = UserId(UUID(int=0xD000 + case * 4))
        other = UserId(UUID(int=0xD001 + case * 4))
        session_id = SessionId(UUID(int=0xD002 + case * 4))
        other_session_id = SessionId(UUID(int=0xD003 + case * 4))
        state = (
            matching.build_qjl_projection(source_dimensions=4, projection_dimensions=4, seed=500 + case)
            if family == "qjl"
            else matching.build_turboquant_projection(
                source_dimensions=4,
                total_bit_width=4,
                residual_dimensions=4,
                seed=500 + case,
            )
        )
        representation_id = matching.MatchRepresentationRefId(f"phase10:{family}:permission:{case}")
        wrong_declared_dimensions = family == "turboquant" and allow_left and allow_right and left_subtype and not right_subtype

        def seed_system(txn: SyncWriteTransaction) -> None:
            txn.insert(UserSession, UserSession(sys_id=session_id, session_type="user", user_id=user))
            txn.insert(UserSession, UserSession(sys_id=other_session_id, session_type="user", user_id=other))
            matching.publish_quantized_projection(txn, state)

        db_connection.session(SessionId.schema()).write(fn=seed_system)
        left_values = {
            "label": f"left-{case}",
            "vector": [1.0, 0.0, 0.0, 0.0],
            "owner_id": user if allow_left else other,
        }
        right_values = {
            "label": f"right-{case}",
            "vector": [0.5, 0.5, 0.0, 0.0],
            "source_watermark": matching.QuantizedSourceWatermark(1),
            "owner_id": user if allow_right else other,
        }
        left = (
            Phase10QuantizedPermissionLeftSubtype.model_validate({**left_values, "left_detail": "sub-left"})
            if left_subtype
            else Phase10QuantizedPermissionLeft.model_validate(left_values)
        )
        right = (
            Phase10QuantizedPermissionRightSubtype.model_validate({**right_values, "right_detail": "sub-right"})
            if right_subtype
            else Phase10QuantizedPermissionRight.model_validate(right_values)
        )
        inserted_left = db_connection.session(session_id if allow_left else other_session_id).write(
            fn=lambda txn, row=left: txn.insert(Phase10QuantizedPermissionLeft, row),
        )
        inserted_right = db_connection.session(session_id if allow_right else other_session_id).write(
            fn=lambda txn, row=right: txn.insert(Phase10QuantizedPermissionRight, row),
        )

        code = (
            matching.encode_qjl(np.asarray(inserted_right.vector, dtype=np.float32), state)
            if isinstance(state, matching.QjlProjectionState)
            else matching.encode_turboquant(np.asarray(inserted_right.vector, dtype=np.float32), state)
        )
        wrong_code_family = family == "qjl" and allow_left and allow_right and left_subtype and right_subtype
        wrong_code_size = family == "qjl" and allow_left and allow_right and left_subtype and not right_subtype
        wrong_turbo_code_size = family == "turboquant" and allow_left and allow_right and left_subtype and right_subtype

        def publish_code(txn: SyncWriteTransaction) -> None:
            matching.publish_quantized_code(
                txn,
                source_identity=matching.QuantizedSourceIdentity(str(inserted_right.sys_id)),
                representation_ref_id=representation_id,
                source_watermark=matching.QuantizedSourceWatermark(1),
                code=code,
            )

        missing_visible_code = family == "qjl" and allow_left and allow_right and not left_subtype and not right_subtype
        db_connection.session(SessionId.schema()).write(fn=publish_code)
        stale_visible_source = family == "qjl" and allow_left and allow_right and not left_subtype and right_subtype
        missing_visible_artifact = family == "turboquant" and allow_left and allow_right and not left_subtype and not right_subtype
        spec = matching.match_spec(
            spec_ref_id=matching.MatchSpecRefId(f"phase10:{family}:permission:{case}"),
            pair_scope=matching.MatchPairScope(f"phase10:{family}:permission:{case}"),
            left=matching.MatchRelationSpec[Phase10QuantizedPermissionLeft](
                relation_ref_id=matching.MatchRelationRefId(f"phase10:left:{case}"),
                row_type=Phase10QuantizedPermissionLeft,
                representation=matching.MatchDenseVectorFieldRepresentationSpec.from_field(
                    field(Phase10QuantizedPermissionLeft.vector),
                    dimensions=matching.MatchVectorDimensions(4),
                ),
            ),
            right=matching.MatchRelationSpec[Phase10QuantizedPermissionRight](
                relation_ref_id=matching.MatchRelationRefId(f"phase10:right:{case}"),
                row_type=Phase10QuantizedPermissionRight,
                representation=matching.MatchQuantizedCodeRepresentationSpec.from_relation(
                    Phase10QuantizedPermissionRight,
                    representation_ref_id=representation_id,
                    projection_artifact_id=state.artifact.artifact_id,
                    family=(
                        matching.MatchQuantizedFamily.QJL if family == "qjl" else matching.MatchQuantizedFamily.TURBOQUANT_INNER_PRODUCT
                    ),
                    source_dimensions=matching.MatchVectorDimensions(4),
                    source_watermark=matching.MatchArtifactWatermark(1),
                    source_watermark_field=field(Phase10QuantizedPermissionRight.source_watermark),
                ),
            ),
            kernel=matching.MatchQuantizedInnerProductKernelSpec(
                kernel_ref_id=matching.MatchKernelRefId(f"phase10:kernel:{case}"),
            ),
            policies=matching.MatchPolicies(
                guarantee=matching.MatchGuarantee.EXACT,
                missing_representation=matching.FailMissingRepresentationPolicy(),
                self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
                duplicates=matching.RejectDuplicatePairsPolicy(),
                freshness=matching.RequireCurrentFreshnessPolicy(),
            ),
            result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
            filters=matching.MatchFilterSet.no_filters(),
            work_limits=matching.MatchWorkLimits.standard_exact_dense(),
        )

        def execute(txn: SyncReadTransaction) -> matching.TopKPerLeftMatchResult:
            result = matching.match(txn, spec)
            assert isinstance(result, matching.TopKPerLeftMatchResult)
            return result

        result = db_connection.session(session_id).read(fn=execute)
        expected_count = int(allow_left and allow_right)
        assert len(result.edges) == expected_count
        if wrong_code_family or wrong_code_size or wrong_turbo_code_size:
            invalid_representation_id = matching.MatchRepresentationRefId(
                f"phase10:{family}:invalid-code:{case}",
            )
            invalid_code: matching.QjlCodePayload | matching.TurboQuantInnerProductCodePayload
            if wrong_code_family:
                turbo_state = matching.build_turboquant_projection(
                    source_dimensions=4,
                    total_bit_width=4,
                    residual_dimensions=4,
                    seed=900 + case,
                )
                invalid_code = validated_model_update(
                    matching.encode_turboquant(
                        np.asarray(inserted_right.vector, dtype=np.float32),
                        turbo_state,
                    ),
                    {"projection_artifact_id": state.artifact.artifact_id},
                )
            elif wrong_code_size:
                invalid_code = validated_model_update(code, {"packed_signs": b"\x00\x00"})
            else:
                invalid_code = validated_model_update(
                    code,
                    {"packed_mse_indices": b"\x00\x00\x00"},
                )
            db_connection.session(SessionId.schema()).write(
                fn=lambda txn: matching.publish_quantized_code(
                    txn,
                    source_identity=matching.QuantizedSourceIdentity(str(inserted_right.sys_id)),
                    representation_ref_id=invalid_representation_id,
                    source_watermark=matching.QuantizedSourceWatermark(1),
                    code=invalid_code,
                ),
            )
            invalid_code_spec = validated_model_update(
                spec,
                {
                    "right": validated_model_update(
                        spec.right,
                        {
                            "representation": validated_model_update(
                                spec.right.representation,
                                {"representation_ref_id": invalid_representation_id},
                            ),
                        },
                    ),
                },
            )
            with pytest.raises(matching.MatchArtifactError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, invalid_code_spec),
                )
        if missing_visible_code:
            missing_code_representation = validated_model_update(
                spec.right.representation,
                {
                    "representation_ref_id": matching.MatchRepresentationRefId(
                        f"phase10:{family}:missing-code:{case}",
                    ),
                },
            )
            missing_code_spec = validated_model_update(
                spec,
                {
                    "right": validated_model_update(
                        spec.right,
                        {"representation": missing_code_representation},
                    ),
                },
            )
            with pytest.raises(matching.MatchMissingRepresentationError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, missing_code_spec),
                )
        if stale_visible_source:
            stale_representation = validated_model_update(
                spec.right.representation,
                {"source_watermark": matching.MatchArtifactWatermark(2)},
            )
            stale_spec = validated_model_update(
                spec,
                {
                    "right": validated_model_update(
                        spec.right,
                        {"representation": stale_representation},
                    ),
                },
            )
            with pytest.raises(matching.MatchFreshnessError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, stale_spec),
                )
            mse_state = matching.build_turboquant_mse_projection(
                source_dimensions=4,
                bit_width=4,
                seed=1200 + case,
            )
            db_connection.session(SessionId.schema()).write(
                fn=lambda txn: matching.publish_quantized_projection(txn, mse_state),
            )
            wrong_artifact_kind = validated_model_update(
                spec,
                {
                    "right": validated_model_update(
                        spec.right,
                        {
                            "representation": validated_model_update(
                                spec.right.representation,
                                {"projection_artifact_id": mse_state.artifact.artifact_id},
                            ),
                        },
                    ),
                },
            )
            with pytest.raises(matching.MatchArtifactError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, wrong_artifact_kind),
                )
        if missing_visible_artifact:
            missing_artifact_representation = validated_model_update(
                spec.right.representation,
                {
                    "projection_artifact_id": matching.MatchProjectionArtifactId(
                        "missing:turboquant:artifact",
                    ),
                },
            )
            missing_artifact_spec = validated_model_update(
                spec,
                {
                    "right": validated_model_update(
                        spec.right,
                        {"representation": missing_artifact_representation},
                    ),
                },
            )
            with pytest.raises(matching.MatchArtifactError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, missing_artifact_spec),
                )
        if wrong_declared_dimensions:
            invalid_right_representation = validated_model_update(
                spec.right.representation,
                {"source_dimensions": matching.MatchVectorDimensions(5)},
            )
            invalid_right_spec = validated_model_update(
                spec,
                {
                    "right": validated_model_update(
                        spec.right,
                        {"representation": invalid_right_representation},
                    ),
                },
            )
            with pytest.raises(matching.MatchCompatibilityError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, invalid_right_spec),
                )
            invalid_left_spec = validated_model_update(
                spec,
                {
                    "left": validated_model_update(
                        spec.left,
                        {
                            "representation": validated_model_update(
                                spec.left.representation,
                                {"dimensions": matching.MatchVectorDimensions(5)},
                            ),
                        },
                    ),
                },
            )
            with pytest.raises(matching.MatchCompatibilityError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, invalid_left_spec),
                )
            malformed_label = f"malformed-left-{case}"
            db_connection.session(session_id).write(
                fn=lambda txn: txn.insert(
                    Phase10QuantizedPermissionLeft,
                    Phase10QuantizedPermissionLeft(
                        label=malformed_label,
                        vector=[1.0, 0.0, 0.0],
                        owner_id=user,
                    ),
                ),
            )
            malformed_query_spec = validated_model_update(
                spec,
                {
                    "filters": validated_model_update(
                        spec.filters,
                        {
                            "left": matching.MatchEndpointFilterSpec.from_expression(
                                field(Phase10QuantizedPermissionLeft.label) == malformed_label,
                            ),
                        },
                    ),
                },
            )
            with pytest.raises(matching.MatchCompatibilityError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, malformed_query_spec),
                )
        assert result.work.pair_evaluations == expected_count
        if expected_count == 0:
            unavailable_representation = validated_model_update(
                spec.right.representation,
                {
                    "projection_artifact_id": matching.MatchProjectionArtifactId(
                        f"unavailable:{family}:{case}",
                    ),
                },
            )
            unavailable_spec = validated_model_update(
                spec,
                {
                    "right": validated_model_update(
                        spec.right,
                        {"representation": unavailable_representation},
                    ),
                },
            )

            def execute_unavailable(txn: SyncReadTransaction) -> matching.TopKPerLeftMatchResult:
                unavailable_result = matching.match(txn, unavailable_spec)
                assert isinstance(unavailable_result, matching.TopKPerLeftMatchResult)
                return unavailable_result

            unavailable_result = db_connection.session(session_id).read(fn=execute_unavailable)
            assert not unavailable_result.edges
            assert unavailable_result.work.pair_evaluations == 0
        if result.edges:
            assert result.edges[0].left.sys_id == inserted_left.sys_id
            mismatched_family = (
                matching.MatchQuantizedFamily.TURBOQUANT_INNER_PRODUCT if family == "qjl" else matching.MatchQuantizedFamily.QJL
            )
            mismatched_representation = validated_model_update(
                spec.right.representation,
                {"family": mismatched_family},
            )
            mismatched_spec = validated_model_update(
                spec,
                {
                    "right": validated_model_update(
                        spec.right,
                        {"representation": mismatched_representation},
                    ),
                },
            )
            with pytest.raises(matching.MatchArtifactError):
                db_connection.session(session_id).read(
                    fn=lambda txn: matching.match(txn, mismatched_spec),
                )
            assert isinstance(result.edges[0].left, Phase10QuantizedPermissionLeftSubtype) is left_subtype
            assert isinstance(result.edges[0].right, Phase10QuantizedPermissionRightSubtype) is right_subtype
            db_connection.session(session_id).write(
                fn=lambda txn: txn.delete_by_id(
                    Phase10QuantizedPermissionRight,
                    inserted_right.sys_id,
                ),
            )
            revoked_result = db_connection.session(session_id).read(fn=execute)
            assert not revoked_result.edges
            assert revoked_result.work.pair_evaluations == 0
        outcomes.add((allow_left, allow_right, left_subtype, right_subtype, len(result.edges)))
    return outcomes


def test_turboquant_matching_retains_source_permission_matrix(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    outcomes = _execute_matrix(db_connection, "turboquant")

    assert len(outcomes) == 16
    assert sum(count for *_, count in outcomes) == 4


def test_quantized_matching_retains_source_permission_matrix(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    outcomes = _execute_matrix(db_connection, "qjl")

    assert len(outcomes) == 16
    assert sum(count for *_, count in outcomes) == 4

