"""Additional behavioral contracts for matching Phase 2."""

from __future__ import annotations

from data_layer.session import SessionId

import pytest

from conform.bootstrap_families.security import SECURITY_V1
from conform.l5250_matching.phase2_case_matrix import PHASE2_EXACT_DENSE_MATRIX, Phase2ResultShape
from conform.l5250_matching.test_phase2_exact_dense import TEST_BOOTSTRAP_TABLES as PHASE2_TABLES
from data_layer.connection import AsyncDatabaseConnection, SyncDatabaseConnection
from data_layer.matching import MatchDenseValue
from data_layer.permissions import OwnerSharesScheme
from data_layer.schema import PolymorphicObjectRow, register_table
from data_layer.types import SysId, UserId
from data_layer_testing.rtt_assertion import assert_max_flushes


@register_table(plural="phase2_combined_poly_left_rows")
class Phase2CombinedPolyLeft(PolymorphicObjectRow[SysId], concrete_base=True):
    """Permission-owned polymorphic left endpoint for the combined product."""

    label: str
    coordinate_x: MatchDenseValue
    coordinate_y: MatchDenseValue
    owner_id: UserId

    class Permissions:
        @staticmethod
        def get_scheme() -> OwnerSharesScheme:
            return OwnerSharesScheme()


class Phase2CombinedPolyLeftSubtype(Phase2CombinedPolyLeft):
    """Left subtype used by the combined mandatory-factor product."""

    detail: str


@register_table(plural="phase2_combined_poly_right_rows")
class Phase2CombinedPolyRight(PolymorphicObjectRow[SysId], concrete_base=True):
    """Permission-owned polymorphic right endpoint for the combined product."""

    label: str
    coordinate_x: MatchDenseValue
    coordinate_y: MatchDenseValue
    owner_id: UserId

    class Permissions:
        @staticmethod
        def get_scheme() -> OwnerSharesScheme:
            return OwnerSharesScheme()


class Phase2CombinedPolyRightSubtype(Phase2CombinedPolyRight):
    """Right subtype used by the combined mandatory-factor product."""

    detail: str


Phase2CombinedPolyLeft.model_rebuild()
Phase2CombinedPolyLeftSubtype.model_rebuild()
Phase2CombinedPolyRight.model_rebuild()
Phase2CombinedPolyRightSubtype.model_rebuild()

TEST_BOOTSTRAP_TABLES = (
    *PHASE2_TABLES,
    Phase2CombinedPolyLeft,
    Phase2CombinedPolyLeftSubtype,
    Phase2CombinedPolyRight,
    Phase2CombinedPolyRightSubtype,
)
TEST_BOOTSTRAP_FAMILY = SECURITY_V1


@pytest.mark.workload_weight(90)
def test_phase2_permission_polymorphism_surface_product_executes_concrete_outcomes(
    db_connection: SyncDatabaseConnection,
    backend_type: str,
    system_session_id: SessionId,
) -> None:
    """Every permission and endpoint-type combination must execute on every public surface."""
    from conform.l5250_matching import phase2_matrix_execution

    execute_product = phase2_matrix_execution.execute_permission_polymorphism_surface_product
    assert callable(execute_product)
    with assert_max_flushes(84, label="Phase 2 permission and polymorphism product"):
        outcomes = execute_product(db_connection, backend_type)
    assert len(outcomes) == 90
    assert {
        (outcome.execution_surface, outcome.permission_shape, outcome.left_type_name, outcome.right_type_name) for outcome in outcomes
    } == {
        (surface, permission, left_type, right_type)
        for surface in ("lazy", "sync")
        for permission in ("allow_all", "deny_left", "deny_right", "deny_both", "mixed_visible_rows")
        for left_type in ("concrete", "base_instance", "subtype_instance")
        for right_type in ("concrete", "base_instance", "subtype_instance")
    }


@pytest.mark.workload_weight(45)
async def test_phase2_async_permission_polymorphism_product_executes_concrete_outcomes(
    async_db_connection: AsyncDatabaseConnection,
    backend_type: str,
    system_session_id: SessionId,
) -> None:
    """Every permission and endpoint-type combination executes on the async surface."""
    from conform.l5250_matching.phase2_matrix_execution import (
        execute_permission_polymorphism_async_product,
    )

    outcomes = await execute_permission_polymorphism_async_product(async_db_connection, backend_type)
    assert len(outcomes) == 45
    assert {(outcome.permission_shape, outcome.left_type_name, outcome.right_type_name) for outcome in outcomes} == {
        (permission, left_type, right_type)
        for permission in ("allow_all", "deny_left", "deny_right", "deny_both", "mixed_visible_rows")
        for left_type in ("concrete", "base_instance", "subtype_instance")
        for right_type in ("concrete", "base_instance", "subtype_instance")
    }


def test_phase2_matrix_expected_results_match_independent_oracle() -> None:
    """Every matrix result agrees with the independent exhaustive oracle."""
    from conform.l5250_matching.phase2_oracle import evaluate_phase2_fixture

    for case in PHASE2_EXACT_DENSE_MATRIX.valid_cases:
        independent_expected = evaluate_phase2_fixture(
            permission_shape=case.permission_shape.value,
            relation_cardinality=case.relation_cardinality.value,
            filter_shape=case.filter_shape.value,
            score_shape=case.score_shape.value,
            result_shape=case.result_shape.value,
        )
        expected = tuple(
            (edge.left_label, edge.right_label, edge.score)
            for edge in case.expected_edges
        )
        assert expected == independent_expected
        if case.result_shape is Phase2ResultShape.THRESHOLD_JOIN:
            assert all(not hasattr(edge, "left_rank") for edge in case.expected_edges)

