"""Boundary behavioral contracts for matching Phase 3."""

from __future__ import annotations

import pytest

from conform.bootstrap_families.core import CORE_V1
from conform.l5250_matching.model_updates import validated_model_update
from conform.l5250_matching.phase3_matrix_execution import Phase3SemanticCellOutcome
from conform.l5250_matching.test_phase3_result_policies import (
    MATCHING_OPERATOR_TABLES,
    Phase3DenseLeft,
    Phase3DenseRight,
    _artifact_state,
    _phase3_spec,
)
from data_layer.connection import SyncDatabaseConnection
from data_layer.matching import MatchDenseValue
from data_layer.session import SessionId
from data_layer.transaction import SyncWriteTransaction
from data_layer import matching as matching_operator

TEST_BOOTSTRAP_TABLES = (Phase3DenseLeft, Phase3DenseRight, *MATCHING_OPERATOR_TABLES)
TEST_BOOTSTRAP_FAMILY = CORE_V1


def _seed_pair(connection: SyncDatabaseConnection):
    def seed(txn: SyncWriteTransaction):
        left = txn.insert(
            Phase3DenseLeft,
            Phase3DenseLeft(label="left", coordinate=MatchDenseValue(1.0), representation_present=True),
        )
        right = txn.insert(
            Phase3DenseRight,
            Phase3DenseRight(label="right", coordinate=MatchDenseValue(1.0), representation_present=True),
        )
        return left, right

    return connection.session(SessionId.schema()).write(fn=seed)


def test_phase3_symbolic_cells_carry_executed_public_and_oracle_outcomes() -> None:
    """A Cartesian cell cannot be completed by copying a result class into a comprehension."""
    required_fields = {
        "execution_surface",
        "observed_edges",
        "oracle_edges",
        "execution_outcome_id",
    }
    assert required_fields <= set(Phase3SemanticCellOutcome.model_fields)


def test_initial_artifact_publication_rejects_a_caller_invented_source_watermark(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """MATCH-MNT-004: first publication must derive its source watermark authoritatively."""
    from data_layer import matching

    _seed_pair(db_connection)
    spec = _phase3_spec("initial-authoritative-watermark", missing_policy=matching.FailMissingRepresentationPolicy())
    with pytest.raises(matching.MatchFreshnessError) as exc_info:
        db_connection.session(SessionId.schema()).write(
            fn=lambda txn: matching_operator.publish_matching_artifact(txn, spec, _artifact_state(999, 999)),
        )
    assert exc_info.value.context.invariant is matching.MatchInvariant.ARTIFACT_SOURCE_DELTA


def test_synchronous_source_maintenance_updates_artifact_coverage(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """MATCH-MNT-003: a synchronous source insert must update index state, not only watermarks."""
    from data_layer import matching

    left, right = _seed_pair(db_connection)
    base_state = _artifact_state(1, 1)
    state = validated_model_update(
        base_state,
        {
            "indexed_left_identities": (matching.MatchCursorIdentity(str(left.sys_id)),),
            "indexed_right_identities": (matching.MatchCursorIdentity(str(right.sys_id)),),
        },
    )
    spec = _phase3_spec("synchronous-coverage", missing_policy=matching.FailMissingRepresentationPolicy())
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching_operator.publish_matching_artifact(txn, spec, state),
    )
    inserted = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: txn.insert(
            Phase3DenseLeft,
            Phase3DenseLeft(label="new-left", coordinate=MatchDenseValue(2.0), representation_present=True),
        ),
    )
    coverage = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching_operator.list_matching_artifact_coverage(
            txn,
            str(inserted.sys_id),
            spec_ref_id=spec.spec_ref_id,
        ),
    )
    assert len(coverage) == 1
    assert coverage[0].endpoint == "left"


def test_branch_scoped_artifacts_coexist_for_one_specification_and_pair_scope(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """MATCH-MNT-002 and MATCH-MNT-008 require branch scope in the artifact metadata key."""
    from data_layer import matching

    _seed_pair(db_connection)
    spec = _phase3_spec("coexisting-branches", missing_policy=matching.FailMissingRepresentationPolicy())
    first = _artifact_state(1, 1)
    first = validated_model_update(
        first,
        {
            "identity": validated_model_update(
                first.identity,
                {"branch_scope": matching.MatchArtifactScopeValue("branch:first")},
            ),
        },
    )
    second = _artifact_state(1, 1)
    second = validated_model_update(
        second,
        {
            "identity": validated_model_update(
