                {"branch_scope": matching.MatchArtifactScopeValue("branch:second")},
            ),
        },
    )
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching_operator.publish_matching_artifact(txn, spec, first),
    )
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching_operator.publish_matching_artifact(txn, spec, second),
    )
    metadata = db_connection.session(SessionId.schema()).read(fn=matching_operator.list_matching_artifact_metadata)
    scoped = tuple(row for row in metadata if row.spec_ref_id == str(spec.spec_ref_id))
    assert {row.branch_scope for row in scoped} == {"branch:first", "branch:second"}


def test_branch_publication_preserves_each_coverage_owner_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """Publishing a second branch must not rewrite the first branch's coverage ownership."""
    from data_layer import matching

    left, _right = _seed_pair(db_connection)
    spec = _phase3_spec("coverage-owners", missing_policy=matching.FailMissingRepresentationPolicy())
    base_state = validated_model_update(
        _artifact_state(2, 2),
        {"indexed_left_identities": (matching.MatchCursorIdentity(str(left.sys_id)),)},
    )
    states = tuple(
        validated_model_update(
            base_state,
            {
                "identity": validated_model_update(
                    base_state.identity,
                    {"branch_scope": matching.MatchArtifactScopeValue(branch_scope)},
                ),
            },
        )
        for branch_scope in ("branch:first", "branch:second")
    )
    for state in states:

        def publish(txn: SyncWriteTransaction) -> None:
            matching.publish_matching_artifact(txn, spec, state)

        db_connection.session(SessionId.schema()).write(fn=publish)

    coverage = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.list_matching_artifact_coverage(
            txn,
            str(left.sys_id),
            spec_ref_id=spec.spec_ref_id,
