sources.fa9a14f14db584d4be2862a0bac5e0775bc75998:
"""Phase 5 persisted sparse-posting behavioral conformance."""

from __future__ import annotations

import pytest

from conform.bootstrap_families.security import SECURITY_V1
from conform.l5250_matching.test_phase5_sparse_lexical import (
    Phase5SparseLeft,
    Phase5SparseRight,
    TEST_BOOTSTRAP_TABLES,
    _seed,
    _sparse_spec,
)
from data_layer.connection import SyncDatabaseConnection
from data_layer.session import SessionId
from data_layer.types import SysId

TEST_BOOTSTRAP_FAMILY = SECURITY_V1


def test_sparse_match_uses_persisted_postings_and_executed_counters_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """A rebuilt sparse artifact supplies exact results and measured posting work."""
    from data_layer import matching

    spec = _sparse_spec("persisted-postings", neighbor_count=2)
    _seed(
        db_connection,
        left_rows=(Phase5SparseLeft(label="query", text="alpha beta"),),
        right_rows=(
            Phase5SparseRight(label="alpha-beta", text="alpha alpha beta"),
            Phase5SparseRight(label="alpha-gamma", text="alpha gamma"),
            Phase5SparseRight(label="disjoint", text="delta"),
        ),
    )
    rebuild = getattr(matching, "rebuild_matching_artifact", None)
    build_result_type = getattr(matching, "MatchArtifactBuildResult", None)
    assert rebuild is not None
    assert build_result_type is not None

    build_result = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: rebuild(txn, spec),
    )
    assert isinstance(build_result, build_result_type)
    assert build_result.document_count == 3
    assert build_result.feature_count == 4
    assert build_result.posting_count == 5

    result = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert tuple((edge.right.label, edge.score.canonical) for edge in result.edges) == (
        ("alpha-beta", matching.MatchScoreValue(3.0)),
        ("alpha-gamma", matching.MatchScoreValue(1.0)),
    )
    assert isinstance(result.freshness, matching.MatchArtifactFreshnessDiagnostics)
    assert result.work.posting_advances == matching.MatchPostingAdvanceCount(3)
    assert result.work.pair_evaluations == matching.MatchPairEvaluationCount(3)


def test_posting_insert_update_delete_is_incremental_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """Synchronous source writes update sparse postings in the same transaction."""
    from data_layer import matching

    spec = _sparse_spec("incremental-postings", neighbor_count=1)
    left = Phase5SparseLeft(sys_id=SysId.new(), label="query", text="beta")
    right = Phase5SparseRight(sys_id=SysId.new(), label="right", text="alpha")
    _seed(db_connection, left_rows=(left,), right_rows=(right,))
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )

    inserted = Phase5SparseRight(sys_id=SysId.new(), label="inserted", text="beta")
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: txn.insert(Phase5SparseRight, inserted),
    )
    inserted_result = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    assert isinstance(inserted_result, matching.TopKPerLeftMatchResult)
    assert inserted_result.edges[0].right.sys_id == inserted.sys_id
    assert inserted_result.edges[0].score.canonical == matching.MatchScoreValue(1.0)

    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: txn.update(
            Phase5SparseRight,
            Phase5SparseRight.model_validate({**inserted.model_dump(), "text": "gamma"}),
        ),
    )
    updated_result = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    assert isinstance(updated_result, matching.TopKPerLeftMatchResult)
    assert updated_result.edges[0].score.canonical == matching.MatchScoreValue(0.0)

    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: txn.delete_by_id(Phase5SparseRight, inserted.sys_id),
    )
    deleted_result = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    assert isinstance(deleted_result, matching.TopKPerLeftMatchResult)
    assert len(deleted_result.edges) == 1
    assert deleted_result.edges[0].right.sys_id == right.sys_id
    assert deleted_result.edges[0].score.canonical == matching.MatchScoreValue(0.0)


def test_wand_exact_order_matches_exhaustive_oracle_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """Automatic WAND deployment preserves exact order and prunes bounded blocks."""
    from data_layer import matching

    spec = _sparse_spec("wand-exact", neighbor_count=1)
    _seed(
        db_connection,
        left_rows=(Phase5SparseLeft(label="query", text="a b c"),),
        right_rows=(
            Phase5SparseRight(label="winner", text="a a a a b b b b c c c c"),
            *(Phase5SparseRight(label=f"low-{index}", text="a") for index in range(20)),
        ),
    )
    exhaustive = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    build = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )
    assert build.artifact_identity.physical_method == matching.MatchArtifactScopeValue(
        matching.MatchAccessMethodKind.WAND.value,
    )
    optimized = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )

    assert isinstance(exhaustive, matching.TopKPerLeftMatchResult)
    assert isinstance(optimized, matching.TopKPerLeftMatchResult)
    assert tuple((edge.right.sys_id, edge.score.canonical) for edge in optimized.edges) == tuple(
        (edge.right.sys_id, edge.score.canonical) for edge in exhaustive.edges
    )
    assert optimized.work.posting_advances < matching.MatchPostingAdvanceCount(23)


def test_wand_equal_bound_and_equal_score_ties_are_stable_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """WAND retains every equal-bound contender before canonical tie-breaking."""
    from data_layer import matching

    spec = _sparse_spec("wand-equal-ties", neighbor_count=1)
    first = Phase5SparseRight(sys_id=SysId.new(), label="first", text="a")
    second = Phase5SparseRight(sys_id=SysId.new(), label="second", text="a")
    _seed(
        db_connection,
        left_rows=(Phase5SparseLeft(label="query", text="a"),),
        right_rows=(second, first),
    )
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )
    result = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )

    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert result.edges[0].right.sys_id == min(first.sys_id, second.sys_id)
    assert result.edges[0].score.canonical == matching.MatchScoreValue(1.0)
    assert result.work.posting_advances == matching.MatchPostingAdvanceCount(2)


def test_block_max_wand_bounds_every_block_score_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """Each persisted block publishes independently checkable safe-bound metrics."""
    from collections import Counter

    from data_layer import matching

    spec = _sparse_spec("block-bound-metrics", neighbor_count=1)
    right_rows = (
        Phase5SparseRight(sys_id=SysId.new(), label="high", text="a a a b"),
        Phase5SparseRight(sys_id=SysId.new(), label="middle", text="a b b"),
        Phase5SparseRight(sys_id=SysId.new(), label="low", text="b"),
        *(Phase5SparseRight(sys_id=SysId.new(), label=f"padding-{index}", text="c") for index in range(30)),
    )
    _seed(
        db_connection,
        left_rows=(Phase5SparseLeft(label="query", text="a b"),),
        right_rows=right_rows,
    )
    build = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )

    independent_scores = {
        (token, str(row.sys_id)): float(frequency)
        for row in right_rows
        for token, frequency in Counter(row.text.casefold().split()).items()
    }
    metrics = build.block_bound_metrics
    assert len(metrics) == sum(len(Counter(row.text.casefold().split())) for row in right_rows)
    assert {
        (str(metric.feature_identity), str(metric.first_right_identity)): float(metric.observed_max_contribution)
        for metric in metrics
    } == independent_scores
    assert all(metric.persisted_bound >= metric.observed_max_contribution for metric in metrics)
    assert len({metric.corpus_fingerprint for metric in metrics}) == 1
    assert next(iter({metric.corpus_fingerprint for metric in metrics})) == build.artifact_fingerprint


def test_block_max_wand_exact_order_matches_plain_wand_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """Block-Max WAND preserves the exhaustive order with tighter block pruning."""
    from data_layer import matching

    spec = _sparse_spec("block-max-wand", neighbor_count=1)
    _seed(
        db_connection,
        left_rows=(Phase5SparseLeft(label="query", text="a b c"),),
        right_rows=(
            Phase5SparseRight(label="winner", text="a a a b b b c c c"),
            *(Phase5SparseRight(label=f"low-{index}", text="a") for index in range(40)),
        ),
    )
    exhaustive = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    build = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )
    assert build.artifact_identity.physical_method == matching.MatchArtifactScopeValue(
        matching.MatchAccessMethodKind.BLOCK_MAX_WAND.value,
    )
    block_max = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )

    assert isinstance(exhaustive, matching.TopKPerLeftMatchResult)
    assert isinstance(block_max, matching.TopKPerLeftMatchResult)
    assert tuple((edge.right.sys_id, edge.score.canonical) for edge in block_max.edges) == tuple(
        (edge.right.sys_id, edge.score.canonical) for edge in exhaustive.edges
    )
    assert block_max.work.posting_advances == matching.MatchPostingAdvanceCount(3)


def test_wand_rejects_negative_or_nonadditive_kernel_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """Artifact deployment rejects a kernel without a nonnegative additive check."""
    from data_layer import matching

    valid = _sparse_spec("wand-invalid-kernel", neighbor_count=1)
    invalid_kernel = matching.MatchKernelSpec(
        kernel_ref_id=matching.MatchKernelRefId("phase5:wand-invalid-kernel:invalid"),
        kind=matching.MatchKernelKind.BAG_OF_WORDS,
        score_direction=matching.MatchScoreDirection.HIGHER_IS_BETTER,
        left_representation_kind=matching.MatchRepresentationKind.TOKEN_COUNTS,
        right_representation_kind=matching.MatchRepresentationKind.TOKEN_COUNTS,
        additive_decomposition=matching.MatchAdditiveDecomposition.INVALID,
        exact_evaluator=matching.MatchExactEvaluatorKind.SQL_TERM_FREQUENCY_DOT_PRODUCT,
    )
    invalid = type(valid).model_validate(
        {
            **{name: getattr(valid, name) for name in type(valid).model_fields},
            "kernel": invalid_kernel,
        },
    )
    _seed(
        db_connection,
        left_rows=(Phase5SparseLeft(label="query", text="a"),),
        right_rows=(Phase5SparseRight(label="right", text="a"),),
    )

    with pytest.raises(matching.MatchPhysicalPlanError) as exc_info:
        db_connection.session(SessionId.schema()).write(
            fn=lambda txn: matching.rebuild_matching_artifact(txn, invalid),
        )
    assert exc_info.value.context.invariant is matching.MatchInvariant.PHYSICAL_PLAN_UNAVAILABLE
    assert exc_info.value.context.observed == matching.MatchObservedValue("wand_requires_nonnegative_additive_kernel")


def test_posting_watermark_rejects_mixed_generation_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """Metadata cannot select a generation without matching persisted postings."""
    from data_layer import matching

    spec = _sparse_spec("mixed-posting-generation", neighbor_count=1)
    right = Phase5SparseRight(label="right", text="a")
    _seed(
        db_connection,
        left_rows=(Phase5SparseLeft(label="query", text="a"),),
        right_rows=(right,),
    )
    build = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )
    replacement_identity = matching.MatchArtifactIdentity.model_validate(
        {
            **build.artifact_identity.model_dump(),
            "generation": int(build.artifact_identity.generation) + 1,
        },
    )
    mixed_state = matching.MatchArtifactExecutionState(
        identity=replacement_identity,
        source_watermark=matching.MatchArtifactWatermark(2),
        artifact_watermark=matching.MatchArtifactWatermark(2),
        maintenance_mode=matching.MatchArtifactMaintenanceMode.SYNCHRONOUS,
        permission_scope=matching.MatchPermissionFitScope(str(SessionId.schema())),
        indexed_left_identities=(),
        indexed_right_identities=(matching.MatchCursorIdentity(str(right.sys_id)),),
    )
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.publish_matching_artifact(txn, spec, mixed_state),
    )

    with pytest.raises(matching.MatchArtifactError) as exc_info:
        db_connection.session(SessionId.schema()).read(
            fn=lambda txn: matching.match(txn, spec),
        )
    assert exc_info.value.context.invariant is matching.MatchInvariant.ARTIFACT_GENERATION_REUSE
    assert exc_info.value.context.observed == matching.MatchObservedValue("posting_generation_missing")


def test_sparse_artifact_fingerprint_binds_corpus_ordering_blocks_and_scope_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """A rebuild identity changes when the fitted sparse corpus changes."""
    from data_layer import matching

    spec = _sparse_spec("artifact-fingerprint", neighbor_count=1)
    _seed(
        db_connection,
        left_rows=(Phase5SparseLeft(label="query", text="a"),),
        right_rows=(Phase5SparseRight(label="first", text="a"),),
    )
    first = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: txn.insert(
            Phase5SparseRight,
            Phase5SparseRight(label="second", text="b b"),
        ),
    )
    second = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )

    assert len(first.artifact_fingerprint) == 64
    assert len(second.artifact_fingerprint) == 64
    assert first.artifact_fingerprint != second.artifact_fingerprint

