"""Public exact H14 matching over canonical packed codes."""

from __future__ import annotations

from data_layer_testing.permission_read_scenarios import READ_PERMISSION_PRINCIPALS_BOOTSTRAP_CONTRIBUTOR

from uuid import UUID

from conform.bootstrap_families.security import SECURITY_V1
from data_layer import matching
from data_layer.connection import SyncDatabaseConnection
from data_layer.permissions import (
    NoSecurityScheme,
    OwnerRoleSharesScheme,
    OwnershipScheme,
    RBACScheme,
    register_permissions,
)
from data_layer.schema import ApplicationObjectRow, Column, field, get_table_name, register_table
from data_layer.transaction import SyncReadTransaction, SyncWriteTransaction
from data_layer.types import SysId, UserId
from data_layer_testing.permission_read_scenarios import (
    READ_PERMISSION_SCENARIO_TABLES,
    MatrixScopedRbacScheme,
    ReadPermissionScenario,
)


class Phase6H14Row(ApplicationObjectRow[SysId], abstract=True):
    label: str
    code: bytes = Column()


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(plural="phase6_h14_open_left_rows")
class Phase6H14OpenLeft(Phase6H14Row):
    pass


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(plural="phase6_h14_open_right_rows")
class Phase6H14OpenRight(Phase6H14Row):
    pass


@register_permissions(scheme_factory=OwnershipScheme)
@register_table(plural="phase6_h14_owned_left_rows")
class Phase6H14OwnedLeft(Phase6H14Row):
    owner_id: UserId


@register_permissions(scheme_factory=OwnershipScheme)
@register_table(plural="phase6_h14_owned_right_rows")
class Phase6H14OwnedRight(Phase6H14Row):
    owner_id: UserId


@register_permissions(
    scheme_factory=lambda: OwnerRoleSharesScheme(resource_type="phase6_h14_shared_left_rows")
)
@register_table(plural="phase6_h14_shared_left_rows")
class Phase6H14SharedLeft(Phase6H14Row):
    owner_id: UserId


@register_permissions(
    scheme_factory=lambda: OwnerRoleSharesScheme(resource_type="phase6_h14_shared_right_rows")
)
@register_table(plural="phase6_h14_shared_right_rows")
class Phase6H14SharedRight(Phase6H14Row):
    owner_id: UserId


@register_permissions(scheme_factory=RBACScheme)
@register_table(plural="phase6_h14_rbac_left_rows")
class Phase6H14RbacLeft(Phase6H14Row):
    pass


@register_permissions(scheme_factory=RBACScheme)
@register_table(plural="phase6_h14_rbac_right_rows")
class Phase6H14RbacRight(Phase6H14Row):
    pass


@register_permissions(scheme_factory=MatrixScopedRbacScheme)
@register_table(plural="phase6_h14_scoped_left_rows")
class Phase6H14ScopedLeft(Phase6H14Row):
    owner_id: UserId
    scope_id: str = Column(max_length=255)


@register_permissions(scheme_factory=MatrixScopedRbacScheme)
@register_table(plural="phase6_h14_scoped_right_rows")
class Phase6H14ScopedRight(Phase6H14Row):
    owner_id: UserId
    scope_id: str = Column(max_length=255)


_PHASE6_H14_MODELS = (
    Phase6H14OpenLeft,
    Phase6H14OpenRight,
    Phase6H14OwnedLeft,
    Phase6H14OwnedRight,
    Phase6H14SharedLeft,
    Phase6H14SharedRight,
    Phase6H14RbacLeft,
    Phase6H14RbacRight,
    Phase6H14ScopedLeft,
    Phase6H14ScopedRight,
)

TEST_BOOTSTRAP_TABLES = (*READ_PERMISSION_SCENARIO_TABLES, *_PHASE6_H14_MODELS)
TEST_BOOTSTRAP_FAMILY = SECURITY_V1


def _code(*set_bits: int) -> bytes:
    payload = bytearray(128)
    for bit in set_bits:
        payload[bit // 8] |= 1 << (7 - bit % 8)
    return bytes(payload)


def _scenario_models(
    scenario: ReadPermissionScenario,
) -> tuple[type[Phase6H14Row], type[Phase6H14Row]]:
    return {
        "system": (Phase6H14OpenLeft, Phase6H14OpenRight),
        "authenticated-open": (Phase6H14OpenLeft, Phase6H14OpenRight),
        "owner-clean": (Phase6H14OwnedLeft, Phase6H14OwnedRight),
        "owner-isolated": (Phase6H14OwnedLeft, Phase6H14OwnedRight),
        "direct-share": (Phase6H14SharedLeft, Phase6H14SharedRight),
        "rbac-table": (Phase6H14RbacLeft, Phase6H14RbacRight),
        "rbac-scope": (Phase6H14ScopedLeft, Phase6H14ScopedRight),
    }[scenario.key]


def _spec(
    left_model: type[Phase6H14Row],
    right_model: type[Phase6H14Row],
) -> matching.MatchSpec[Phase6H14Row, Phase6H14Row]:
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId("phase6:h14:exact"),
        pair_scope=matching.MatchPairScope("phase6:h14"),
        left=matching.MatchRelationSpec[Phase6H14Row](
            relation_ref_id=matching.MatchRelationRefId("phase6:h14:left"),
            row_type=left_model,
            representation=matching.MatchH14BinaryFieldRepresentationSpec.from_field(
                field(left_model.code),
                projection_artifact_id=matching.MatchProjectionArtifactId("h14:test-generation"),
            ),
        ),
        right=matching.MatchRelationSpec[Phase6H14Row](
            relation_ref_id=matching.MatchRelationRefId("phase6:h14:right"),
            row_type=right_model,
            representation=matching.MatchH14BinaryFieldRepresentationSpec.from_field(
                field(right_model.code),
                projection_artifact_id=matching.MatchProjectionArtifactId("h14:test-generation"),
            ),
        ),
        kernel=matching.MatchH14HammingKernelSpec(
            kernel_ref_id=matching.MatchKernelRefId("phase6:h14:hamming"),
        ),
        policies=matching.MatchPolicies(
            guarantee=matching.MatchGuarantee.EXACT,
            missing_representation=matching.FailMissingRepresentationPolicy(),
            self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
            duplicates=matching.RejectDuplicatePairsPolicy(),
            freshness=matching.RequireCurrentFreshnessPolicy(),
        ),
        result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(3)),
        filters=matching.MatchFilterSet.no_filters(),
        work_limits=matching.MatchWorkLimits.standard_exact_dense(),
    )


def test_exact_h14_matching_uses_all_1024_bits_and_identity_ties(
    db_connection: SyncDatabaseConnection,
    read_permission_scenario: ReadPermissionScenario,
) -> None:
    scenario = read_permission_scenario
    left_model, right_model = _scenario_models(scenario)
    visible_access = scenario.companion_access_values()
    denied_access = dict(visible_access)
    if "owner_id" in right_model.model_fields:
        denied_access["owner_id"] = UserId.new()
    if "scope_id" in right_model.model_fields:
        denied_access["scope_id"] = f"denied-h14-{scenario.key}"

    query = left_model(label="query", code=_code(0, 1023), **visible_access)
    same_b = right_model(
        sys_id=SysId(UUID("00000000-0000-7000-8000-000000000202")),
        label="same-b",
        code=_code(0, 1023),
        **visible_access,
    )
    far = right_model(
        sys_id=SysId(UUID("00000000-0000-7000-8000-000000000203")),
        label="far",
        code=_code(1, 1022),
        **visible_access,
    )
    same_a = right_model(
        sys_id=SysId(UUID("00000000-0000-7000-8000-000000000201")),
        label="same-a",
        code=_code(0, 1023),
        **visible_access,
    )
    denied = right_model(
        sys_id=SysId(UUID("00000000-0000-7000-8000-000000000200")),
        label="denied-best",
        code=_code(0, 1023),
        **denied_access,
    )

    def seed(txn: SyncWriteTransaction) -> None:
        txn.insert(left_model, query)
        txn.insert_many(right_model, [same_b, far, same_a, denied])
        for model, row_ids in (
            (left_model, (query.sys_id,)),
            (right_model, (same_a.sys_id, same_b.sys_id, far.sys_id)),
        ):
            scenario.grant_companion_read_access(
                txn,
                resource=str(get_table_name(model)),
                model_class_name=model.__name__,
                row_ids=row_ids,
            )

    db_connection.session(scenario.setup_session_id).write(fn=seed)
    spec = _spec(left_model, right_model)

    def execute(txn: SyncReadTransaction) -> matching.MatchResult:
        return matching.match_lazy(txn, spec).resolve()

    result = db_connection.session(scenario.actor_session_id).read(fn=execute)
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    restricted = scenario.key in {"owner-clean", "owner-isolated", "direct-share", "rbac-scope"}
    if restricted:
        assert [edge.right.label for edge in result.edges] == ["same-a", "same-b", "far"]
        assert [float(edge.score.canonical) for edge in result.edges] == [
            1.0,
            1.0,
            1.0 - 4.0 / 1024.0,
        ]
    else:
        assert [edge.right.label for edge in result.edges] == ["denied-best", "same-a", "same-b"]
        assert [float(edge.score.canonical) for edge in result.edges] == [1.0, 1.0, 1.0]


