@pytest.mark.parametrize("freshness", ("require_current", "accept_stale", "exact_completion"))
def test_versioned_text_artifact_is_selected_in_its_branch(
    db_connection: SyncVersionedDatabaseConnection, freshness: str,
    system_session_id: SessionId,
) -> None:
    from conform.conftest import create_test_revision
    from conform.l5250_matching.phase6_case_matrix import _versioned_cases, _versioned_spec
    from data_layer.versioned_transactions import SyncVersionedWriteTransaction

    matching = _phase6_api()
    _, branch_id = create_test_revision(db_connection, PHASE3_MATCH_DOMAIN, message="text artifact scope")
    spec = _versioned_spec(_versioned_cases()[0])
    if freshness != "require_current":
        policy = matching.AcceptStaleWithDiagnosticsFreshnessPolicy() if freshness == "accept_stale" else matching.ExactCompletionFreshnessPolicy()
        spec = validated_model_update(spec, {"policies": validated_model_update(spec.policies, {"freshness": policy})})

    def seed(txn: SyncVersionedWriteTransaction) -> None:
        txn.insert(Phase3VersionedLeft, Phase3VersionedLeft(label="needle", coordinate=1.0))
        txn.insert(Phase3VersionedRight, Phase3VersionedRight(label="needle", coordinate=1.0))
        txn.commit_branch(message="text artifact source")

    db_connection.write_version(session_id=SessionId.schema(), domain=PHASE3_MATCH_DOMAIN, branch=branch_id, fn=seed)

    def build(txn: SyncVersionedWriteTransaction):
        outcome = matching.rebuild_matching_artifact(txn, spec)
        txn.commit()
        return outcome

    build_outcome = db_connection.write_version(
        session_id=SessionId.schema(), domain=PHASE3_MATCH_DOMAIN, branch=branch_id, fn=build,
    )
    result = db_connection.version(PHASE3_MATCH_DOMAIN, branch_id, SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    assert isinstance(result.freshness, matching.MatchArtifactFreshnessDiagnostics)
    assert result.freshness.identity.artifact_fingerprint == build_outcome.artifact_fingerprint
    assert result.work.database_round_trips == matching.MatchDatabaseRoundTripCount(2)

    def fork(txn: SyncVersionedWriteTransaction):
        feature = txn.create_branch(f"text-artifact-feature-{SysId.new()}")
        txn.commit()
        return feature

    feature_branch = db_connection.write_version(
        session_id=SessionId.schema(), domain=PHASE3_MATCH_DOMAIN, branch=branch_id, fn=fork,
    )
    feature_outcome = db_connection.write_version(
        session_id=SessionId.schema(), domain=PHASE3_MATCH_DOMAIN, branch=feature_branch, fn=build,
    )
    assert feature_outcome.artifact_fingerprint != build_outcome.artifact_fingerprint
    for selected_branch, expected_outcome in ((branch_id, build_outcome), (feature_branch, feature_outcome)):
        selected_result = db_connection.version(PHASE3_MATCH_DOMAIN, selected_branch, SessionId.schema()).read(
            fn=lambda txn: matching.match(txn, spec),
        )
        assert isinstance(selected_result.freshness, matching.MatchArtifactFreshnessDiagnostics)
        assert selected_result.freshness.identity.artifact_fingerprint == expected_outcome.artifact_fingerprint

    def mutate(txn: SyncVersionedWriteTransaction) -> None:
        row = txn.query(Phase3VersionedRight).execute()[0]
        txn.update(Phase3VersionedRight, validated_model_update(row, {"label": "changed"}))
        txn.commit_branch(message="invalidate branch text artifact")

    db_connection.write_version(session_id=SessionId.schema(), domain=PHASE3_MATCH_DOMAIN, branch=feature_branch, fn=mutate)
    if freshness == "require_current":
        with pytest.raises(matching.MatchFreshnessError):
            db_connection.version(PHASE3_MATCH_DOMAIN, feature_branch, SessionId.schema()).read(
                fn=lambda txn: matching.match(txn, spec),
            )
    else:
        changed = db_connection.version(PHASE3_MATCH_DOMAIN, feature_branch, SessionId.schema()).read(
            fn=lambda txn: matching.match(txn, spec),
        )
        assert isinstance(changed.freshness, matching.MatchArtifactFreshnessDiagnostics)
        assert changed.freshness.state is matching.MatchArtifactFreshnessState.STALE
        if freshness == "exact_completion":
            assert isinstance(changed, matching.TopKPerLeftMatchResult)
            assert changed.edges[0].score.canonical == matching.MatchScoreValue(0.0)
            assert changed.work.exact_completion_pairs == matching.MatchExactCompletionPairCount(1)
    unchanged = db_connection.version(PHASE3_MATCH_DOMAIN, branch_id, SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    assert isinstance(unchanged.freshness, matching.MatchArtifactFreshnessDiagnostics)
    assert unchanged.freshness.identity.artifact_fingerprint == build_outcome.artifact_fingerprint


