def test_aho_artifact_fingerprints_complete_pattern_set_tdd_red(db_connection: SyncDatabaseConnection, system_session_id: SessionId) -> None:
    """Changing one materialized pattern changes the complete automaton identity."""
    matching = _phase6_api()
    _seed(db_connection, left=(("first", "ana"),), right=(("text", "banana"),))
    spec = _spec("aho-pattern-set")
    first = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )

    def add_pattern(txn: SyncWriteTransaction) -> None:
        txn.insert(Phase6StringLeft, Phase6StringLeft(label="second", text="ban"))

    db_connection.session(SessionId.schema()).write(fn=add_pattern)
    second = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
    )
    assert first.artifact_fingerprint != second.artifact_fingerprint
    assert second.pattern_count == matching.MatchPatternCount(2)
    assert second.automaton_state_count > second.pattern_count
    assert second.automaton_transition_count > second.automaton_state_count
    assert second.automaton_emission_count >= second.pattern_count
    assert second.candidate_representation_kind is matching.MatchRepresentationKind.AUTOMATON
    explanation = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.explain_match_plan(txn, spec),
    )
    assert explanation.physical_method is matching.MatchAccessMethodKind.AHO_CORASICK
    result = _execute(db_connection, spec)
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert {(edge.left.text, edge.score.canonical) for edge in result.edges} == {
        ("ana", matching.MatchScoreValue(2.0)),
        ("ban", matching.MatchScoreValue(1.0)),
    }
    metadata_before = tuple(
        row
        for row in db_connection.session(SessionId.schema()).read(
            fn=matching.list_matching_artifact_metadata,
        )
        if row.spec_fingerprint == str(spec.semantic_fingerprint)
    )
    limited_spec = validated_model_update(
        spec,
        {
            "work_limits": validated_model_update(
                spec.work_limits,
                {"max_automaton_states": matching.MatchAutomatonStateLimit(2)},
            ),
        },
    )
    with pytest.raises(matching.MatchWorkLimitError):
        db_connection.session(SessionId.schema()).write(
            fn=lambda txn: matching.rebuild_matching_artifact(txn, limited_spec),
        )
    metadata_after = tuple(
        row
        for row in db_connection.session(SessionId.schema()).read(
            fn=matching.list_matching_artifact_metadata,
        )
        if row.spec_fingerprint == str(spec.semantic_fingerprint)
    )
    assert metadata_after == metadata_before


def test_aho_positions_use_declared_coordinate_space_tdd_red(db_connection: SyncDatabaseConnection, system_session_id: SessionId) -> None:
    """Automaton occurrences report the coordinate space declared by the kernel."""
    matching = _phase6_api()
    _seed(
        db_connection,
        left=(("accent", "é"), ("other", "zz")),
        right=(("decomposed", "xe\u0301y"),),
    )
    normalized_spec = _spec("aho-coordinates-normalized")
    source_spec = _spec("aho-coordinates-source", coordinate_space="source")
    observed: dict[str, tuple[int, int]] = {}
    for spec in (normalized_spec, source_spec):
        db_connection.session(SessionId.schema()).write(fn=lambda txn: matching.rebuild_matching_artifact(txn, spec))
        result = _execute(db_connection, spec)
        assert isinstance(result, matching.TopKPerLeftMatchResult)
        assert result.edges[0].score.canonical == matching.MatchScoreValue(1.0)
        diagnostics = result.edges[0].diagnostics
        assert isinstance(diagnostics, matching.MatchExactDiagnostics)
        occurrence = diagnostics.substring_occurrences[0]
        observed[occurrence.coordinate_space.value] = (int(occurrence.start), int(occurrence.end))
    assert observed == {"normalized": (1, 2), "source": (1, 3)}


def test_aho_update_publishes_new_generation_atomically_tdd_red(db_connection: SyncDatabaseConnection, system_session_id: SessionId) -> None:
    """A pattern-set update publishes a new complete generation without mixed state."""
    matching = _phase6_api()
    _seed(db_connection, left=(("first", "ana"),), right=(("text", "banana"),))
    spec = _spec("aho-generation")
    first = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.rebuild_matching_artifact(txn, spec),
