    def update_pattern(txn: SyncWriteTransaction) -> None:
        row = txn.query(Phase6StringLeft).filter(field(Phase6StringLeft.label) == "first").execute()[0]
        txn.update(Phase6StringLeft, validated_model_update(row, {"text": "ban"}))

