def test_denied_pattern_and_denied_text_emit_no_candidate_observation_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """Permissions remove both endpoint roles before text candidate publication."""
    matching = _phase6_api()
    owner_id = UserId(UUID("00000000-0000-7000-8000-000000006101"))
    other_id = UserId(UUID("00000000-0000-7000-8000-000000006102"))
    session_id = SessionId(UUID("00000000-0000-7000-8000-000000006103"))
    other_session_id = SessionId(UUID("00000000-0000-7000-8000-000000006104"))
    spec = _typed_text_spec(matching, "permission", Phase6SecureStringLeft, Phase6SecureStringRight)

    def seed_sessions(txn: SyncWriteTransaction) -> None:
        txn.insert(UserSession, UserSession(sys_id=session_id, session_type="user", user_id=owner_id))
        txn.insert(UserSession, UserSession(sys_id=other_session_id, session_type="user", user_id=other_id))

    db_connection.session(system_session_id).write(fn=seed_sessions)
    db_connection.session(other_session_id).write(
        fn=lambda txn: (
