"""Execute Phase 7 benchmark lanes through public database matching plans."""

from __future__ import annotations

from conform.l5250_matching.model_updates import validated_model_update

from typing import Literal

import pytest

from conform.bootstrap_families.security import SECURITY_V1
from conform.l5250_matching.phase7_oracle import bind_fixture_code, h14_fixture, h14_fixture_values
from conform.l5250_matching.test_phase7_h14_exact_matching import Phase7H14Left, Phase7H14Right, _spec as h14_spec
from conform.l5250_matching.test_phase7_native_exact_dense import (
    Phase7PackedDenseLeft,
    Phase7PackedDenseRight,
    _packed,
    _spec as native_spec,
)
from data_layer import matching
from data_layer.connection import SyncDatabaseConnection
from data_layer.session import SessionId
from data_layer.transaction import SyncReadTransaction, SyncWriteTransaction

TEST_BOOTSTRAP_FAMILY = SECURITY_V1
TEST_BOOTSTRAP_TABLES = (
    Phase7H14Left,
    Phase7H14Right,
    Phase7PackedDenseLeft,
    Phase7PackedDenseRight,
    *matching.MATCHING_OPERATOR_TABLES,
)


type _BenchmarkMatchResult = (
    matching.MatchResult[Phase7PackedDenseLeft, Phase7PackedDenseRight] | matching.MatchResult[Phase7H14Left, Phase7H14Right]
)


@pytest.mark.parametrize("family", ["native_dense", "h14"])
def test_phase7_database_benchmark_executes_expected_work(
    db_connection: SyncDatabaseConnection,
    family: Literal["native_dense", "h14"],
    system_session_id: SessionId,
) -> None:
    left_count = 8
    right_count = 32
    if family == "native_dense":
        native = native_spec()
        native_benchmark_spec = validated_model_update(
            native,
            {
                "result_shape": matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(3)),
                "work_limits": validated_model_update(
                    native.work_limits,
                    {
                        "max_left_rows": matching.MatchRowCountLimit(left_count),
                        "max_right_rows": matching.MatchRowCountLimit(right_count),
                    },
                ),
            },
        )

        def seed(txn: SyncWriteTransaction) -> None:
            matching.publish_native_exact_plan(txn, native_benchmark_spec)
            for index in range(left_count):
                txn.insert(
                    Phase7PackedDenseLeft,
                    Phase7PackedDenseLeft(label=f"left-{index}", vector=_packed(1.0, index / left_count)),
                )
            for index in range(right_count):
                txn.insert(
                    Phase7PackedDenseRight,
                    Phase7PackedDenseRight(label=f"right-{index}", vector=_packed(1.0, index / right_count)),
                )

        def execute(txn: SyncReadTransaction) -> _BenchmarkMatchResult:
            return matching.match(txn, native_benchmark_spec)
    else:
        h14 = h14_spec()
        h14_benchmark_spec = validated_model_update(
            h14,
            {
                "result_shape": matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(3)),
                "work_limits": validated_model_update(
                    h14.work_limits,
                    {
                        "max_left_rows": matching.MatchRowCountLimit(left_count),
                        "max_right_rows": matching.MatchRowCountLimit(right_count),
                    },
                ),
            },
        )
        artifact, blobs = h14_fixture()

        def seed(txn: SyncWriteTransaction) -> None:
            matching.publish_h14_projection(txn, artifact, blobs)
            for index in range(left_count):
                row = txn.insert(
                    Phase7H14Left,
                    Phase7H14Left(label=f"left-{index}", **h14_fixture_values(index / left_count)),
                )
                bind_fixture_code(txn, Phase7H14Left, row, artifact)
            for index in range(right_count):
                right_row = txn.insert(
                    Phase7H14Right,
                    Phase7H14Right(label=f"right-{index}", **h14_fixture_values(index / right_count)),
                )
                bind_fixture_code(txn, Phase7H14Right, right_row, artifact)

        def execute(txn: SyncReadTransaction) -> _BenchmarkMatchResult:
            return matching.match(txn, h14_benchmark_spec)

    session = db_connection.session(SessionId.schema())
    session.write(fn=seed)
    result = session.read(fn=execute)
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert len(result.edges) == left_count * 3
    assert result.work.pair_evaluations == matching.MatchPairEvaluationCount(left_count * right_count)
    assert result.work.database_round_trips == matching.MatchDatabaseRoundTripCount(2)
    if family == "h14":
        assert result.work.bit_comparisons == matching.MatchBitComparisonCount(left_count * right_count * 1024)

