"""H14 artifact and tensor publication is atomic in the caller-owned plan."""

from __future__ import annotations

from data_layer_testing.bootstrap_authority import bootstrap_session

from collections.abc import Iterator, Mapping

from collections.abc import Callable
from concurrent.futures import ThreadPoolExecutor
from threading import Barrier, Event
from typing import Any

import pytest

from conform.bootstrap_families.security import SECURITY_V1
from conform.l5250_matching.model_updates import validated_model_update
from conform.l5250_matching.phase7_oracle import h14_fixture, reidentified_h14_artifact
from data_layer import matching
from data_layer.connection import AsyncDatabaseConnection, SyncDatabaseConnection
from data_layer.exceptions import IntegrityError
from data_layer.schema import field
from data_layer.transaction import AsyncReadTransaction, AsyncWriteTransaction, SyncReadTransaction
from data_layer.session import SessionId
from data_layer.transaction import SyncWriteTransaction
from data_layer.types import SysId

TEST_BOOTSTRAP_TABLES = matching.MATCHING_OPERATOR_TABLES
TEST_BOOTSTRAP_FAMILY = SECURITY_V1


@pytest.mark.parametrize("damage", ["none", "missing_tensor", "corrupt_tensor"])
def test_public_loader_verifies_persisted_h14_generation(
    db_connection: SyncDatabaseConnection,
    damage: str,
    system_session_id: SessionId,
) -> None:
    artifact, blobs = h14_fixture()
    session = db_connection.session(SessionId.schema())
    session.write(fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs))
    if damage != "none":
        tensors = session.read(fn=lambda txn: txn.query(matching.MatchingProjectionTensorRow).filter(
            field(matching.MatchingProjectionTensorRow.artifact_id) == artifact.artifact_id,
        ).execute())
        victim = tensors[0]
        if damage == "missing_tensor":
            session.write(fn=lambda txn: txn.delete_by_id(matching.MatchingProjectionTensorRow, victim.sys_id))
        else:
            changed = validated_model_update(victim, {"payload": bytes(len(victim.payload))})
            if changed.payload == victim.payload:
                changed = validated_model_update(victim, {"payload": bytes([255]) * len(victim.payload)})
            session.write(fn=lambda txn: txn.update(matching.MatchingProjectionTensorRow, changed))
        with pytest.raises(matching.MatchArtifactError):
            session.read(fn=lambda txn: matching.load_h14_projection(txn, artifact.artifact_id))
    else:
        loaded = session.read(fn=lambda txn: matching.load_h14_projection(txn, artifact.artifact_id))
        assert loaded.artifact == artifact
        assert loaded.blobs() == blobs


@pytest.mark.parametrize("damage", ["artifact_fingerprint", "tensor_payload", "extra_tensor"])
def test_h14_republication_does_not_repair_corrupt_immutable_generation(
    db_connection: SyncDatabaseConnection,
    damage: str,
    system_session_id: SessionId,
) -> None:
    artifact, blobs = h14_fixture()
    session = db_connection.session(SessionId.schema())
    original = session.write(fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs))
    stored = session.read(fn=lambda txn: txn.select_one(matching.MatchingProjectionArtifactRow, original.sys_id))
    assert original == stored
    repeated = session.write(fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs))
    assert repeated == original
    assert session.read(fn=lambda txn: matching.load_h14_projection(txn, artifact.artifact_id)).blobs() == blobs
    if damage == "artifact_fingerprint":
        changed_artifact = validated_model_update(original, {
            "artifact_fingerprint": matching.MatchArtifactFingerprint("0" * 64),
        })
        session.write(fn=lambda txn: txn.update(matching.MatchingProjectionArtifactRow, changed_artifact))
    else:
        tensors = session.read(fn=lambda txn: txn.query(matching.MatchingProjectionTensorRow).filter(
            field(matching.MatchingProjectionTensorRow.artifact_id) == artifact.artifact_id,
        ).execute())
        victim = tensors[0]
        if damage == "extra_tensor":
            extra = validated_model_update(victim, {"sys_id": SysId.new(), "role": "extra"})
            session.write(fn=lambda txn: txn.insert(matching.MatchingProjectionTensorRow, extra))
        else:
            changed_tensor = validated_model_update(victim, {"payload": b"corrupt"})
            session.write(fn=lambda txn: txn.update(matching.MatchingProjectionTensorRow, changed_tensor))
    with pytest.raises(matching.MatchArtifactError):
        session.write(fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs))
    with pytest.raises(matching.MatchArtifactError):
        session.read(fn=lambda txn: matching.load_h14_projection(txn, artifact.artifact_id))


def test_concurrent_h14_publications_retain_complete_generations(
    db_connection: SyncDatabaseConnection,
    connection_factory: Callable[[], SyncDatabaseConnection],
    system_session_id: SessionId,
) -> None:
    first, blobs = h14_fixture()
    second = reidentified_h14_artifact(first, {
        "training_fingerprint": matching.ProjectionTrainingFingerprint("c" * 64),
    })
    assert first.artifact_id != second.artifact_id
    ready = Barrier(2, timeout=15)

    def publish(artifact: matching.H14ProjectionArtifact) -> None:
        conn = connection_factory()
        conn.connect()
        try:
            ready.wait()
            with bootstrap_session() as worker_session_id:
                conn.session(worker_session_id).write(
                    fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs),
                )
        finally:
            conn.close()

    with ThreadPoolExecutor(max_workers=2) as pool:
        futures = [pool.submit(publish, artifact) for artifact in (first, second)]
        for future in futures:
            future.result()

    session = db_connection.session(SessionId.schema())
    activations = session.read(fn=lambda txn: txn.query(matching.MatchingProjectionActivationRow).execute())
    assert len(activations) == 1
    fingerprints = {artifact.artifact_id: artifact.fingerprint() for artifact in (first, second)}
    assert activations[0].artifact_id in fingerprints
    assert activations[0].artifact_fingerprint == fingerprints[activations[0].artifact_id]
    for artifact in (first, second):
        loaded = session.read(fn=lambda txn: matching.load_h14_projection(txn, artifact.artifact_id))
        assert loaded.artifact == artifact
        assert loaded.blobs() == blobs


@pytest.mark.parametrize("rollback", [False, True])
def test_h14_activation_is_visible_only_after_publication_commit(
    db_connection: SyncDatabaseConnection,
    connection_factory: Callable[[], SyncDatabaseConnection],
    rollback: bool,
    system_session_id: SessionId,
) -> None:
    first, blobs = h14_fixture()
    second = reidentified_h14_artifact(first, {
        "training_fingerprint": matching.ProjectionTrainingFingerprint("e" * 64),
    })
    session = db_connection.session(SessionId.schema())
    session.write(fn=lambda txn: matching.publish_h14_projection(txn, first, blobs))
    assert first.artifact_id != second.artifact_id
    written = Event()
    release = Event()

    class PublicationAborted(RuntimeError):
        pass

    def publish() -> None:
        conn = connection_factory()
        conn.connect()
        try:
            def write(txn: SyncWriteTransaction) -> None:
                matching.publish_h14_projection(txn, second, blobs)
                written.set()
                if not release.wait(15):
                    raise TimeoutError("The publication observer did not release the writer")
                if rollback:
                    raise PublicationAborted
            with bootstrap_session() as worker_session_id:
                conn.session(worker_session_id).write(fn=write)
        finally:
            conn.close()

    with ThreadPoolExecutor(max_workers=1) as pool:
        future = pool.submit(publish)
        try:
            if not written.wait(15):
                future.result(timeout=1)
                raise TimeoutError("The publisher did not reach the transaction boundary")
            active = session.read(fn=lambda txn: txn.query(matching.MatchingProjectionActivationRow).execute())
            assert len(active) == 1
            assert active[0].artifact_id == first.artifact_id
            loaded = session.read(fn=lambda txn: matching.load_h14_projection(txn, first.artifact_id))
            assert loaded.blobs() == blobs
        finally:
            release.set()
        if rollback:
            with pytest.raises(PublicationAborted):
                future.result()
        else:
            future.result()

    active = session.read(fn=lambda txn: txn.query(matching.MatchingProjectionActivationRow).execute())
    assert len(active) == 1
    expected = first if rollback else second
    assert active[0].artifact_id == expected.artifact_id
    assert active[0].artifact_fingerprint == expected.fingerprint()
    if rollback:
        with pytest.raises(matching.MatchArtifactError):
            session.read(fn=lambda txn: matching.load_h14_projection(txn, second.artifact_id))
    else:
        loaded = session.read(fn=lambda txn: matching.load_h14_projection(txn, second.artifact_id))
        assert loaded.artifact == second
        assert loaded.blobs() == blobs


def test_lazy_loader_preserves_retired_generation(
