        })
        for token in ("d", "e")
    )]
    session = db_connection.session(SessionId.schema())
    for artifact in artifacts:
        session.write(fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs))

    def read(txn: SyncReadTransaction):
        protected = txn.query_lazy(matching.MatchingProjectionArtifactRow).filter(
            field(matching.MatchingProjectionArtifactRow.artifact_id) == matching.MatchProjectionArtifactId("missing")
            if empty else field(matching.MatchingProjectionArtifactRow.artifact_id) != artifacts[-1].artifact_id,
        ).execute_lazy()
        return txn.query_lazy(matching.MatchingProjectionArtifactRow).exclude_by_lazy_relation(
            field(matching.MatchingProjectionArtifactRow.artifact_id), protected,
            field(matching.MatchingProjectionArtifactRow.artifact_id),
        ).execute_lazy().resolve()

    remaining = session.read(fn=read)
