def test_h14_refit_retains_immutable_generations_and_moves_activation(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    first, blobs = h14_fixture()
    second = reidentified_h14_artifact(
        first,
        {"training_fingerprint": matching.ProjectionTrainingFingerprint("c" * 64)},
    )

    def publish_both(txn: SyncWriteTransaction) -> None:
        matching.publish_h14_projection(txn, first, blobs)
        matching.publish_h14_projection(txn, second, blobs)

    db_connection.session(SessionId.schema()).write(fn=publish_both)
    artifacts, tensors = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: (
            txn.query(matching.MatchingProjectionArtifactRow).execute(),
            txn.query(matching.MatchingProjectionTensorRow).execute(),
        ),
    )
    assert {row.artifact_id for row in artifacts} == {first.artifact_id, second.artifact_id}
    assert {row.artifact_id for row in tensors} == {first.artifact_id, second.artifact_id}
    activations = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: txn.query(matching.MatchingProjectionActivationRow).execute(),
    )
    assert len(activations) == 1
    assert activations[0].artifact_id == second.artifact_id


def test_h14_publication_uses_the_verified_tensor_snapshot(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    artifact, blobs = h14_fixture()
    session = db_connection.session(SessionId.schema())
    session.write(fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs))
    assert session.read(fn=lambda txn: matching.load_h14_projection(txn, artifact.artifact_id)).blobs() == blobs
    replacement = reidentified_h14_artifact(artifact, {
        "training_fingerprint": matching.ProjectionTrainingFingerprint("1" * 64),
    })
    residual_reads = 0

    class ChangingBlobs(Mapping[matching.ProjectionTensorDigest, bytes]):
        def __getitem__(self: ChangingBlobs, key: matching.ProjectionTensorDigest) -> bytes:
            nonlocal residual_reads
            if key == replacement.residual_tensor.digest:
                residual_reads += 1
                if residual_reads > 1:
                    return bytes(len(blobs[key]))
            return blobs[key]

        def __iter__(self: ChangingBlobs) -> Iterator[matching.ProjectionTensorDigest]:
            return iter(blobs)

        def __len__(self: ChangingBlobs) -> int:
            return len(blobs)

    session.write(fn=lambda txn: matching.publish_h14_projection(txn, replacement, ChangingBlobs()))
    loaded = session.read(fn=lambda txn: matching.load_h14_projection(txn, replacement.artifact_id))
    assert loaded.blobs() == blobs
    assert residual_reads == 1


@pytest.mark.parametrize("corruption", ["missing", "digest", "mutable", "text"])
def test_h14_publication_rejects_changed_tensor_before_any_write(
    db_connection: SyncDatabaseConnection,
    corruption: str,
    system_session_id: SessionId,
) -> None:
    artifact, blobs = h14_fixture()
    session = db_connection.session(SessionId.schema())

    class RollbackControl(RuntimeError):
        pass

    def control(txn: SyncWriteTransaction) -> None:
        published = matching.publish_h14_projection(txn, artifact, blobs)
        assert published.artifact_id == artifact.artifact_id
        raise RollbackControl

    with pytest.raises(RollbackControl):
        session.write(fn=control)
    assert session.read(fn=lambda txn: txn.query(matching.MatchingProjectionArtifactRow).count()) == 0
    invalid_blobs: Any = dict(blobs)
    if corruption == "missing":
        del invalid_blobs[artifact.residual_tensor.digest]
    elif corruption == "mutable":
        invalid_blobs[artifact.residual_tensor.digest] = bytearray(blobs[artifact.residual_tensor.digest])
    elif corruption == "text":
        invalid_blobs[artifact.residual_tensor.digest] = "a" * len(blobs[artifact.residual_tensor.digest])
    else:
        invalid_blobs[artifact.residual_tensor.digest] = bytes(len(blobs[artifact.residual_tensor.digest]))

    with pytest.raises(matching.MatchArtifactError) as caught:
        session.write(fn=lambda txn: matching.publish_h14_projection(txn, artifact, invalid_blobs))
    context = caught.value.context
    assert context.invariant is matching.MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH
    assert context.safe_action is matching.MatchSafeAction.REBUILD_ARTIFACT
    assert context.observed == "h14_publication_tensor_mismatch"
    assert context.executed_work.kind == "unobserved"
    assert artifact.artifact_id not in context.model_dump_json()
    assert isinstance(caught.value.__cause__, ValueError)
    assert session.read(fn=lambda txn: txn.query(matching.MatchingProjectionArtifactRow).count()) == 0
    assert session.read(fn=lambda txn: txn.query(matching.MatchingProjectionTensorRow).count()) == 0
    assert session.read(fn=lambda txn: txn.query(matching.MatchingProjectionActivationRow).count()) == 0

