"""H14 exact matching uses the selected branch snapshot before scoring."""

from __future__ import annotations

from data_layer.types import RevisionMessage

from conform.l5250_matching.model_updates import validated_model_update

from collections.abc import Callable
import json
import pytest

from conform.bootstrap_families.core import CORE_V1
from conform.l5250_matching.phase7_oracle import (
    H14_ARTIFACT_ID,
    bind_fixture_code,
    h14_fixture,
    h14_fixture_values,
)
from data_layer import matching
from data_layer.matching import MATCHING_OPERATOR_TABLES
from data_layer.permissions import NoSecurityScheme, register_permissions
from data_layer.schema import Column, field, register_table
from data_layer.session import SessionId
from data_layer.transaction import SyncWriteTransaction
from data_layer.types import RevisionId, SysId
from data_layer.versioned_schema import (
    BaseRevision,
    SyncVersionedDatabaseConnection,
    VersionedObjectRow,
    VersioningDomain,
    create_versioning_domain,
)
from data_layer.versioned_transactions import SyncVersionedReadTransaction, SyncVersionedWriteTransaction
from data_layer_testing.versioning.revision_helpers import create_test_revision


@register_table(plural="phase7_h14_revisions")
class Phase7H14Revision(BaseRevision):
    message: RevisionMessage = RevisionMessage("")


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(plural="phase7_versioned_h14_lefts")
class Phase7VersionedH14Left(VersionedObjectRow[SysId]):
    label: str
    source_vector: bytes = Column(default=bytes(768 * 4))
    code: matching.PackedH14Code = Column()


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(plural="phase7_versioned_h14_rights")
class Phase7VersionedH14Right(VersionedObjectRow[SysId]):
    label: str
    source_vector: bytes = Column(default=bytes(768 * 4))
    code: matching.PackedH14Code = Column()


for model in (Phase7H14Revision, Phase7VersionedH14Left, Phase7VersionedH14Right):
    model.model_rebuild(_types_namespace={"RevisionId": RevisionId})

PHASE7_H14_DOMAIN = create_versioning_domain(
    name="phase7_h14", revision_model=Phase7H14Revision,
    tables=[Phase7VersionedH14Left, Phase7VersionedH14Right],
)
TEST_BOOTSTRAP_VERSIONING_DOMAINS: tuple[type[VersioningDomain], ...] = (PHASE7_H14_DOMAIN,)
TEST_BOOTSTRAP_TABLES = MATCHING_OPERATOR_TABLES
TEST_BOOTSTRAP_FAMILY = CORE_V1


def _spec() -> matching.MatchSpec[Phase7VersionedH14Left, Phase7VersionedH14Right]:
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId("phase7:h14:versioned"),
        left=matching.MatchRelationSpec[Phase7VersionedH14Left](
            relation_ref_id=matching.MatchRelationRefId("phase7:versioned:left"), row_type=Phase7VersionedH14Left,
            representation=matching.MatchH14BinaryFieldRepresentationSpec.from_field(
                field(Phase7VersionedH14Left.code),
                source_field=field(Phase7VersionedH14Left.source_vector),
                projection_artifact=h14_fixture()[0],
            ),
        ),
        right=matching.MatchRelationSpec[Phase7VersionedH14Right](
            relation_ref_id=matching.MatchRelationRefId("phase7:versioned:right"), row_type=Phase7VersionedH14Right,
            representation=matching.MatchH14BinaryFieldRepresentationSpec.from_field(
                field(Phase7VersionedH14Right.code),
                source_field=field(Phase7VersionedH14Right.source_vector),
                projection_artifact=h14_fixture()[0],
            ),
        ),
        kernel=matching.MatchH14HammingKernelSpec(kernel_ref_id=matching.MatchKernelRefId("phase7:h14:hamming")),
        policies=matching.MatchPolicies(
            guarantee=matching.MatchGuarantee.EXACT,
            missing_representation=matching.FailMissingRepresentationPolicy(),
            self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
            duplicates=matching.RejectDuplicatePairsPolicy(),
            freshness=matching.RequireCurrentFreshnessPolicy(),
        ),
        result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
        filters=matching.MatchFilterSet.no_filters(),
        work_limits=matching.MatchWorkLimits.standard_exact_dense(),
    )


def test_h14_branch_tip_excludes_rows_from_unselected_branch(
    db_connection: SyncVersionedDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    artifact, blobs = h14_fixture()
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs),
    )
    _revision, branch = create_test_revision(
        db_connection, PHASE7_H14_DOMAIN, branch_name="phase7-h14-visible",
    )

    def seed(txn: SyncVersionedWriteTransaction) -> None:
        left = txn.insert(Phase7VersionedH14Left, Phase7VersionedH14Left(label="left", **h14_fixture_values(0.0)))
        right = txn.insert(Phase7VersionedH14Right, Phase7VersionedH14Right(label="visible", **h14_fixture_values(0.0)))
        bind_fixture_code(txn, Phase7VersionedH14Left, left, artifact)
        bind_fixture_code(txn, Phase7VersionedH14Right, right, artifact)
        txn.commit_branch(message="visible H14 rows")

    db_connection.write_version(
        session_id=SessionId.schema(), domain=PHASE7_H14_DOMAIN, branch=branch, fn=seed,
    )

    def execute(txn: SyncVersionedReadTransaction):
        return matching.match(txn, _spec())

    result = db_connection.version(PHASE7_H14_DOMAIN, branch, SessionId.schema()).read(fn=execute)
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert [(edge.left.label, edge.right.label) for edge in result.edges] == [("left", "visible")]


@pytest.mark.parametrize("source_change", [False, True])
def test_h14_pinned_revision_reads_historical_rows(
    db_connection: SyncVersionedDatabaseConnection,
    source_change: bool,
    system_session_id: SessionId,
) -> None:
    artifact, blobs = h14_fixture()
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs),
    )
    _revision, branch = create_test_revision(
        db_connection, PHASE7_H14_DOMAIN, branch_name="phase7-h14-pinned",
    )
    identities: dict[str, SysId] = {}

    def seed(txn: SyncVersionedWriteTransaction) -> RevisionId:
        left = txn.insert(Phase7VersionedH14Left, Phase7VersionedH14Left(label="left", **h14_fixture_values(0.0)))
        right = txn.insert(Phase7VersionedH14Right, Phase7VersionedH14Right(label="old", **h14_fixture_values(0.0)))
        identities["right"] = right.sys_id
        bind_fixture_code(txn, Phase7VersionedH14Left, left, artifact)
        bind_fixture_code(txn, Phase7VersionedH14Right, right, artifact)
        return txn.commit_branch(message="old H14 row")

    pinned = db_connection.write_version(
        session_id=SessionId.schema(), domain=PHASE7_H14_DOMAIN, branch=branch, fn=seed,
    )

    def update(txn: SyncVersionedWriteTransaction) -> None:
        row = txn.select_one(Phase7VersionedH14Right, identities["right"])
        assert row is not None
        updates: dict[str, object] = {"label": "new"}
        if source_change:
            updates.update(h14_fixture_values(1.0))
        replacement = validated_model_update(row, updates)
        txn.update(Phase7VersionedH14Right, replacement)
        if source_change:
            bind_fixture_code(txn, Phase7VersionedH14Right, replacement, artifact)
        txn.commit_branch(message="new H14 row")

    db_connection.write_version(
        session_id=SessionId.schema(), domain=PHASE7_H14_DOMAIN, branch=branch, fn=update,
    )
    result = db_connection.read_version(
        session_id=SessionId.schema(),
        domain=PHASE7_H14_DOMAIN,
        revision=pinned,
        fn=lambda txn: matching.match(txn, _spec()),
    )
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert result.edges[0].right.label == "old"
    assert result.edges[0].right.code == h14_fixture_values(0.0)["code"]
    current = db_connection.version(PHASE7_H14_DOMAIN, branch, SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, _spec()),
    )
    assert isinstance(current, matching.TopKPerLeftMatchResult)
    assert current.edges[0].right.code == h14_fixture_values(1.0 if source_change else 0.0)["code"]


def test_h14_cross_branch_pair_identity_includes_branch_scope(
    db_connection: SyncVersionedDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    artifact, blobs = h14_fixture()
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.publish_h14_projection(txn, artifact, blobs),
    )
    _revision, main_branch = create_test_revision(
        db_connection, PHASE7_H14_DOMAIN, branch_name="phase7-h14-cross",
    )

    def seed(txn: SyncVersionedWriteTransaction) -> RevisionId:
        left = txn.insert(Phase7VersionedH14Left, Phase7VersionedH14Left(label="left", **h14_fixture_values(0.0)))
        right = txn.insert(Phase7VersionedH14Right, Phase7VersionedH14Right(label="right", **h14_fixture_values(0.0)))
        bind_fixture_code(txn, Phase7VersionedH14Left, left, artifact)
        bind_fixture_code(txn, Phase7VersionedH14Right, right, artifact)
        return txn.commit_branch(message="shared H14 rows")

    shared = db_connection.write_version(
        session_id=SessionId.schema(), domain=PHASE7_H14_DOMAIN, branch=main_branch, fn=seed,
    )

    def branch(txn: SyncVersionedWriteTransaction):
        created = txn.create_branch("phase7-h14-feature", from_revision_id=shared)
        txn.commit()
        return created

    feature_branch = db_connection.write_version(
        session_id=SessionId.schema(), domain=PHASE7_H14_DOMAIN, branch=main_branch, fn=branch,
    )
    main_result = db_connection.version(PHASE7_H14_DOMAIN, main_branch, SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, _spec()),
    )
    feature_result = db_connection.version(PHASE7_H14_DOMAIN, feature_branch, SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, _spec()),
    )
    assert isinstance(main_result, matching.TopKPerLeftMatchResult)
    assert isinstance(feature_result, matching.TopKPerLeftMatchResult)
    assert main_result.edges[0].pair_identity != feature_result.edges[0].pair_identity

