"""One public packed dense specification executes through native or portable exact profiles."""

from __future__ import annotations

from collections.abc import Callable
import json
import struct
from uuid import UUID

import pytest

from conform.bootstrap_families.security import SECURITY_V1
from conform.l5250_matching.model_updates import validated_model_update
from data_layer import matching
from data_layer.connection import AsyncDatabaseConnection, SyncDatabaseConnection
from data_layer.matching import MATCHING_OPERATOR_TABLES
from data_layer.schema import ApplicationObjectRow, Column, field, register_table
from data_layer.session import SessionId
from data_layer.transaction import AsyncReadTransaction, AsyncWriteTransaction, SyncWriteTransaction
from data_layer.types import SysId
from data_layer.vector_index import Embedding, EmbeddingPrecision, VectorMetric, vector_indexed


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=2, auto_queue=False)
@register_table(plural="phase7_packed_dense_lefts")
class Phase7PackedDenseLeft(ApplicationObjectRow[SysId]):
    label: str
    content: str = ""
    vector: Embedding = Column(embedding_dimensions=2, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=2, auto_queue=False)
@register_table(plural="phase7_packed_dense_rights")
class Phase7PackedDenseRight(ApplicationObjectRow[SysId]):
    label: str
    content: str = ""
    vector: Embedding = Column(embedding_dimensions=2, embedding_precision=EmbeddingPrecision.FLOAT32)


TEST_BOOTSTRAP_TABLES = (Phase7PackedDenseLeft, Phase7PackedDenseRight, *MATCHING_OPERATOR_TABLES)
TEST_BOOTSTRAP_FAMILY = SECURITY_V1


@pytest.mark.parametrize("right_count", [0, 1])
@pytest.mark.parametrize("right_bound", [1, 2])
def test_native_top_k_can_exceed_the_right_relation_bound(
    db_connection: SyncDatabaseConnection,
    right_count: int,
    right_bound: int,
    system_session_id: SessionId,
) -> None:
    original = _spec()
    spec = validated_model_update(
        original,
        {
            "work_limits": validated_model_update(
                original.work_limits,
                {
                    "max_right_rows": matching.MatchRowCountLimit(right_bound),
                },
            ),
            "result_shape": matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(3)),
        },
    )

    def seed(txn: SyncWriteTransaction) -> None:
        matching.publish_native_exact_plan(txn, spec)
        txn.insert(Phase7PackedDenseLeft, Phase7PackedDenseLeft(label="left", vector=_packed(1, 0)))
        for index in range(right_count):
            txn.insert(
                Phase7PackedDenseRight,
                Phase7PackedDenseRight(
                    label=f"right-{index}",
                    vector=_packed(1, 0),
                ),
            )

    session = db_connection.session(SessionId.schema())
    session.write(fn=seed)
    result = session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert len(result.edges) == right_count
    assert result.work.pair_evaluations == right_count
    assert spec.native_exact_choice.inputs.selected_right_rows == right_bound


def test_native_exact_scan_preserves_fp32_sign_magnitude_and_order(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    original = _spec()
    values = (-4.0, -2.0, -1.0, -0.5, 0.25, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0, 8.0, 16.0)
    spec = validated_model_update(
        original,
        {
            "result_shape": matching.TopKPerLeftMatchShape(
                neighbor_count=matching.NeighborCount(len(values)),
            ),
            "work_limits": validated_model_update(
                original.work_limits,
                {
                    "max_left_rows": matching.MatchRowCountLimit(1),
                    "max_right_rows": matching.MatchRowCountLimit(len(values)),
                },
            ),
        },
    )

    def seed(txn: SyncWriteTransaction) -> None:
        matching.publish_native_exact_plan(txn, spec)
        txn.insert(
            Phase7PackedDenseLeft,
            Phase7PackedDenseLeft(label="left", vector=_packed(1.0, 0.0)),
        )
        txn.insert_many(
            Phase7PackedDenseRight,
            [
                Phase7PackedDenseRight(label=f"right-{value}", vector=_packed(value, 0.0))
                for value in values
            ],
        )

    session = db_connection.session(SessionId.schema())
    session.write(fn=seed)
    result = session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    expected = tuple(reversed(values))
    assert tuple((edge.right.label, float(edge.score.canonical)) for edge in result.edges) == tuple(
        (f"right-{value}", value) for value in expected
    )


def _packed(*values: float) -> bytes:
    return b"EMB\x01\x00" + struct.pack(f"<{len(values)}f", *values)


def _spec() -> matching.MatchSpec[Phase7PackedDenseLeft, Phase7PackedDenseRight]:
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId("phase7:native:exact-dense"),
        left=matching.MatchRelationSpec[Phase7PackedDenseLeft](
            relation_ref_id=matching.MatchRelationRefId("phase7:native:left"),
            row_type=Phase7PackedDenseLeft,
            representation=matching.MatchPackedDenseFieldRepresentationSpec.from_field(
                field(Phase7PackedDenseLeft.vector),
                dimensions=matching.MatchVectorDimensions(2),
            ),
        ),
        right=matching.MatchRelationSpec[Phase7PackedDenseRight](
            relation_ref_id=matching.MatchRelationRefId("phase7:native:right"),
            row_type=Phase7PackedDenseRight,
            representation=matching.MatchPackedDenseFieldRepresentationSpec.from_field(
                field(Phase7PackedDenseRight.vector),
                dimensions=matching.MatchVectorDimensions(2),
            ),
        ),
        kernel=matching.MatchKernelSpec(
            kernel_ref_id=matching.MatchKernelRefId("phase7:native:dot"),
            kind=matching.MatchKernelKind.DENSE_DOT_PRODUCT,
            score_direction=matching.MatchScoreDirection.HIGHER_IS_BETTER,
        ),
        policies=matching.MatchPolicies(
            guarantee=matching.MatchGuarantee.EXACT,
            missing_representation=matching.FailMissingRepresentationPolicy(),
            self_edges=matching.MatchSelfEdgePolicy.INCLUDE,
            duplicates=matching.RejectDuplicatePairsPolicy(),
            freshness=matching.RequireCurrentFreshnessPolicy(),
        ),
        result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
        filters=matching.MatchFilterSet.no_filters(),
        work_limits=validated_model_update(
            matching.MatchWorkLimits.standard_exact_dense(),
            {
                "max_left_rows": matching.MatchRowCountLimit(1),
                "max_right_rows": matching.MatchRowCountLimit(3),
            },
        ),
    )


def _batch_spec() -> matching.MatchSpec[Phase7PackedDenseLeft, Phase7PackedDenseRight]:
    spec = _spec()
    return validated_model_update(
        spec,
        {
            "work_limits": validated_model_update(
                spec.work_limits,
                {
                    "max_left_rows": matching.MatchRowCountLimit(2_000),
                    "max_right_rows": matching.MatchRowCountLimit(10_000),
                },
            ),
        },
    )


def test_bootstrap_persists_authoritative_plan_and_reconstruction_reuses_it(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    spec = _spec()
    published = db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.publish_native_exact_plan(txn, spec),
    )
    assert published.spec_fingerprint == str(spec.semantic_fingerprint)
    representation = spec.left.representation
    assert isinstance(representation, matching.MatchPackedDenseFieldRepresentationSpec)
    assert published.profile_identity == str(representation.native_profile.identity())
    reconstructed = _spec()
    rows = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: txn.query(matching.MatchingNativeExactPlanRow).execute(),
    )
    assert len(rows) == 1
    assert rows[0].plan_identity == str(reconstructed.native_exact_choice.plan_identity)
    assert rows[0].operator == "<#>"
    assert rows[0].operator_class == "vector_ip_ops"


def test_native_execution_rejects_missing_persisted_plan_before_scoring(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    spec = _spec()
    with pytest.raises(matching.MatchCompatibilityError) as raised:
        db_connection.session(SessionId.schema()).read(fn=lambda txn: matching.match(txn, spec))
    assert raised.value.context.safe_action is matching.MatchSafeAction.MIGRATE_PERSISTED_SPEC
    assert raised.value.context.observed == "matching_native_exact_plans_0"
    backend = "postgresql" if db_connection.backend_type.value == "postgres" else db_connection.backend_type.value


def test_physical_plan_change_requires_explicit_migration(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    original = _spec()
    replacement = _batch_spec()
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.publish_native_exact_plan(txn, original),
    )
    with pytest.raises(matching.MatchCompatibilityError):
        db_connection.session(SessionId.schema()).write(
            fn=lambda txn: matching.migrate_native_exact_plan(txn, replacement),
        )
    with db_connection.schema_transaction(SessionId.schema()) as schema:
        matching.NativeExactBootstrapContributor(spec=replacement).migrate_from_lazy(
            schema,
            previous_spec=original,
        ).resolve()
    rows = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: txn.query(matching.MatchingNativeExactPlanRow).execute(),
    )
    assert len(rows) == 1
    assert rows[0].spec_fingerprint == str(replacement.semantic_fingerprint)
    with pytest.raises(matching.MatchCompatibilityError):
        db_connection.session(SessionId.schema()).read(fn=lambda txn: matching.match(txn, original))


def test_native_batch_scan_choice_is_persisted_before_execution(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    spec = _batch_spec()
    choice = spec.native_exact_choice

    def seed(txn: SyncWriteTransaction) -> None:
        matching.publish_native_exact_plan(txn, spec)
        txn.insert(Phase7PackedDenseLeft, Phase7PackedDenseLeft(label="batch-q", vector=_packed(1, 0)))
        txn.insert(Phase7PackedDenseRight, Phase7PackedDenseRight(label="batch-r", vector=_packed(1, 0)))
        txn.insert(Phase7PackedDenseRight, Phase7PackedDenseRight(label="batch-low-a", vector=_packed(0, 1)))
        txn.insert(Phase7PackedDenseRight, Phase7PackedDenseRight(label="batch-low-b", vector=_packed(0, 1)))

    db_connection.session(SessionId.schema()).write(fn=seed)
    result = db_connection.session(SessionId.schema()).read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert [(edge.right.label, float(edge.score.canonical)) for edge in result.edges] == [("batch-r", 1.0)]
    assert result.work.pair_evaluations == matching.MatchPairEvaluationCount(3)
    explanation = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.explain_match_plan(txn, spec),
    )
    assert explanation.native_exact_choice == choice
    assert choice.strategy is matching.NativeExactExecutionStrategy.BATCH_SCAN


def test_application_result_contains_no_backend_method_tdd_red(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    """The public result does not expose the selected physical method."""
    serialized_spec = _spec().model_dump(mode="python", warnings="error")
    assert serialized_spec["left"]["representation"]["kind"] == "packed_dense_field"

    def seed(txn: SyncWriteTransaction) -> None:
        matching.publish_native_exact_plan(txn, _spec())
        txn.insert(Phase7PackedDenseLeft, Phase7PackedDenseLeft(label="left", vector=_packed(1, 0)))
        txn.insert(Phase7PackedDenseRight, Phase7PackedDenseRight(label="right", vector=_packed(1, 0)))

    session = db_connection.session(SessionId.schema())
    session.write(fn=seed)
    result = session.read(fn=lambda txn: matching.match(txn, _spec()))
    assert isinstance(result, matching.TopKPerLeftMatchResult)

    def keys(value: object) -> set[str]:
        if isinstance(value, dict):
            return set(value).union(*(keys(item) for item in value.values()))
        if isinstance(value, list):
            return set().union(*(keys(item) for item in value))
        return set()

    public_keys = keys(result.model_dump(mode="json"))
    assert public_keys.isdisjoint(
        {"backend", "physical_method", "physical_type", "operator_class", "extension_version"},
    )


def test_native_exact_scan_matches_portable_exact_order(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    def seed(txn: SyncWriteTransaction) -> None:
        matching.publish_native_exact_plan(txn, _spec())
        txn.insert(Phase7PackedDenseLeft, Phase7PackedDenseLeft(label="q", vector=_packed(1, 2)))
        for identity, label, vector in (
            ("00000000-0000-7000-8000-000000000711", "high", _packed(2, 2)),
            ("00000000-0000-7000-8000-000000000712", "tie-a", _packed(1, 1)),
            ("00000000-0000-7000-8000-000000000713", "tie-b", _packed(1, 1)),
        ):
            txn.insert(
                Phase7PackedDenseRight,
                Phase7PackedDenseRight(
                    sys_id=SysId(UUID(identity)),
                    label=label,
                    vector=vector,
                ),
            )

    db_connection.session(SessionId.schema()).write(fn=seed)
    result = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.match_lazy(txn, _spec()).resolve(),
    )
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert [(edge.right.label, float(edge.score.canonical)) for edge in result.edges] == [("high", 6.0)]
    explanation = db_connection.session(SessionId.schema()).read(
        fn=lambda txn: matching.explain_match_plan(txn, _spec()),
    )
    assert explanation.exactness is matching.MatchExactness.EXACT
    assert explanation.physical_method in {
        matching.MatchAccessMethodKind.PGVECTOR_EXACT_VECTOR_SCAN,
        matching.MatchAccessMethodKind.EXACT_DENSE_SCAN,
    }
    assert isinstance(explanation.native_exact_choice, matching.NativeExactPlanChoice)
    assert explanation.native_exact_choice.strategy is matching.NativeExactExecutionStrategy.PER_LEFT_LATERAL
    assert matching.MatchCompatibilityVersion("0.8.6") in explanation.compatibility_versions


async def test_native_async_public_surface_preserves_exact_order(
    async_db_connection: AsyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    async def seed(txn: AsyncWriteTransaction) -> None:
        await matching.publish_native_exact_plan_async(txn, _spec())
        await txn.insert_async(
            Phase7PackedDenseLeft,
            Phase7PackedDenseLeft(label="q", vector=_packed(1, 2)),
        )
        for identity, label, vector in (
            ("00000000-0000-7000-8000-000000000721", "high", _packed(2, 2)),
            ("00000000-0000-7000-8000-000000000722", "tie", _packed(1, 1)),
        ):
            await txn.insert_async(
                Phase7PackedDenseRight,
                Phase7PackedDenseRight(
                    sys_id=SysId(UUID(identity)),
                    label=label,
                    vector=vector,
                ),
            )

    await async_db_connection.session(SessionId.schema()).write_async(fn=seed)

    async def execute(txn: AsyncReadTransaction) -> matching.MatchResult:
        return await matching.match_async(txn, _spec())

    result = await async_db_connection.session(SessionId.schema()).read_async(fn=execute)
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert [(edge.right.label, float(edge.score.canonical)) for edge in result.edges] == [
        ("high", 6.0),
    ]

