"""Native dense matching uses schema-owned versioned storage and snapshot visibility."""

from __future__ import annotations

from data_layer.types import RevisionMessage

from collections.abc import Callable
import json

import pytest

from conform.bootstrap_families.core import CORE_V1
from conform.l5250_matching.model_updates import validated_model_update
from conform.l5250_matching.test_phase7_native_exact_dense import _packed, _spec as native_spec
from data_layer import matching
from data_layer.permissions import NoSecurityScheme, register_permissions
from data_layer.schema import Column, field, register_table
from data_layer.session import SessionId
from data_layer.types import RevisionId, SysId
from data_layer.vector_index import Embedding
from data_layer.versioned_schema import BaseRevision, SyncVersionedDatabaseConnection, VersionedObjectRow, VersioningDomain, create_versioning_domain
from data_layer.versioned_transactions import SyncVersionedWriteTransaction
from data_layer_testing.versioning.revision_helpers import create_test_revision


@register_table(plural="phase7_native_revisions")
class NativeRevision(BaseRevision):
    message: RevisionMessage = RevisionMessage("")


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(plural="phase7_versioned_native_lefts")
class NativeLeft(VersionedObjectRow[SysId]):
    label: str
    vector: Embedding = Column(embedding_dimensions=2)


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(plural="phase7_versioned_native_rights")
class NativeRight(VersionedObjectRow[SysId]):
    label: str
    vector: Embedding = Column(embedding_dimensions=2)


for model in (NativeRevision, NativeLeft, NativeRight):
    model.model_rebuild(_types_namespace={"RevisionId": RevisionId})

NATIVE_DOMAIN = create_versioning_domain(name="phase7_native", revision_model=NativeRevision, tables=[NativeLeft, NativeRight])
TEST_BOOTSTRAP_VERSIONING_DOMAINS: tuple[type[VersioningDomain], ...] = (NATIVE_DOMAIN,)
TEST_BOOTSTRAP_TABLES = matching.MATCHING_OPERATOR_TABLES
TEST_BOOTSTRAP_FAMILY = CORE_V1


def _versioned_spec(right_rows: int = 2) -> matching.MatchSpec[NativeLeft, NativeRight]:
    original = native_spec()
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId("phase7:native:versioned"),
        left=matching.MatchRelationSpec[NativeLeft](
            relation_ref_id=matching.MatchRelationRefId("phase7:native:versioned:left"),
            row_type=NativeLeft,
            representation=matching.MatchPackedDenseFieldRepresentationSpec.from_field(field(NativeLeft.vector), dimensions=matching.MatchVectorDimensions(2)),
        ),
        right=matching.MatchRelationSpec[NativeRight](
            relation_ref_id=matching.MatchRelationRefId("phase7:native:versioned:right"),
            row_type=NativeRight,
            representation=matching.MatchPackedDenseFieldRepresentationSpec.from_field(field(NativeRight.vector), dimensions=matching.MatchVectorDimensions(2)),
        ),
        kernel=original.kernel, policies=original.policies, result_shape=original.result_shape,
        filters=original.filters,
        work_limits=validated_model_update(original.work_limits, {"max_right_rows": right_rows}),
    )


@pytest.mark.parametrize("pinned", [False, True])
@pytest.mark.parametrize("right_rows", [2, 130])
def test_native_versioned_matching_uses_the_selected_snapshot(
    db_connection: SyncVersionedDatabaseConnection,
    pinned: bool,
    right_rows: int,
    system_session_id: SessionId,
) -> None:
    spec = _versioned_spec(right_rows)
    db_connection.session(SessionId.schema()).write(fn=lambda txn: matching.publish_native_exact_plan(txn, spec))
    _, branch = create_test_revision(db_connection, NATIVE_DOMAIN, branch_name="native-visible")
    ids: list[SysId] = []

    def seed(txn: SyncVersionedWriteTransaction) -> RevisionId:
        txn.insert(NativeLeft, NativeLeft(label="left", vector=_packed(1, 0)))
        right = txn.insert(NativeRight, NativeRight(label="old", vector=_packed(1, 0)))
        ids.append(right.sys_id)
        txn.insert_many(NativeRight, [
            NativeRight(label=f"other-{index}", vector=_packed(-1, 0))
            for index in range(right_rows - 1)
        ])
        return txn.commit_branch(message="native original")

    revision = db_connection.write_version(session_id=SessionId.schema(), domain=NATIVE_DOMAIN, branch=branch, fn=seed)
    control = db_connection.version(NATIVE_DOMAIN, branch, SessionId.schema()).read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(control, matching.TopKPerLeftMatchResult)
    assert [(edge.right.label, float(edge.score.canonical)) for edge in control.edges] == [("old", 1.0)]
    assert control.edges[0].left.revision_id == revision
    assert control.edges[0].right.revision_id == revision

    def update(txn: SyncVersionedWriteTransaction) -> RevisionId:
        row = txn.select_one(NativeRight, ids[0])
        assert isinstance(row, NativeRight)
        txn.update(NativeRight, validated_model_update(row, {"label": "new", "vector": _packed(0, 1)}))
        return txn.commit_branch(message="native replacement")

    updated_revision = db_connection.write_version(session_id=SessionId.schema(), domain=NATIVE_DOMAIN, branch=branch, fn=update)
    if pinned:
        result = db_connection.read_version(
            session_id=SessionId.schema(), domain=NATIVE_DOMAIN, revision=revision,
            fn=lambda txn: matching.match(txn, spec),
        )
    else:
        result = db_connection.version(NATIVE_DOMAIN, branch, SessionId.schema()).read(
            fn=lambda txn: matching.match(txn, spec),
        )
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    expected = ("old", 1.0) if pinned else ("new", 0.0)
    assert [(edge.right.label, float(edge.score.canonical)) for edge in result.edges] == [expected]
    assert result.work.pair_evaluations == matching.MatchPairEvaluationCount(right_rows)
    assert result.edges[0].left.revision_id == revision
    assert result.edges[0].right.revision_id == (revision if pinned else updated_revision)
    assert result.edges[0].left.deleted is False
    assert result.edges[0].right.deleted is False


def test_native_cross_branch_pair_identity_includes_branch_scope(
    db_connection: SyncVersionedDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    spec = _versioned_spec()
    db_connection.session(SessionId.schema()).write(
        fn=lambda txn: matching.publish_native_exact_plan(txn, spec),
    )
    _revision, main_branch = create_test_revision(
        db_connection, NATIVE_DOMAIN, branch_name="phase7-native-cross",
    )

    def seed(txn: SyncVersionedWriteTransaction) -> RevisionId:
        txn.insert(NativeLeft, NativeLeft(label="left", vector=_packed(1, 0)))
        txn.insert(NativeRight, NativeRight(label="right", vector=_packed(1, 0)))
        return txn.commit_branch(message="shared native rows")

    shared = db_connection.write_version(
        session_id=SessionId.schema(), domain=NATIVE_DOMAIN, branch=main_branch, fn=seed,
    )

    def branch(txn: SyncVersionedWriteTransaction):
        created = txn.create_branch("phase7-native-feature", from_revision_id=shared)
        txn.commit()
        return created

    feature_branch = db_connection.write_version(
        session_id=SessionId.schema(), domain=NATIVE_DOMAIN, branch=main_branch, fn=branch,
    )
    main_result = db_connection.version(NATIVE_DOMAIN, main_branch, SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    feature_result = db_connection.version(NATIVE_DOMAIN, feature_branch, SessionId.schema()).read(
        fn=lambda txn: matching.match(txn, spec),
    )
    assert isinstance(main_result, matching.TopKPerLeftMatchResult)
    assert isinstance(feature_result, matching.TopKPerLeftMatchResult)
    assert main_result.edges[0].pair_identity != feature_result.edges[0].pair_identity

