"""Exercise native packed matching at the declared wide dimension boundaries."""

from __future__ import annotations

from data_layer_testing.permission_read_scenarios import READ_PERMISSION_PRINCIPALS_BOOTSTRAP_CONTRIBUTOR

from collections.abc import Callable
import json
import struct
from uuid import UUID

import pytest

from conform.bootstrap_families.security import SECURITY_V1
from conform.l5250_matching.model_updates import validated_model_update
from conform.l5250_matching.test_phase7_native_exact_dense import _spec
from data_layer import matching
from data_layer.connection import SyncDatabaseConnection
from data_layer.permissions import (
    NoSecurityScheme,
    OwnerRoleSharesScheme,
    OwnershipScheme,
    RBACScheme,
    register_permissions,
)
from data_layer.schema import ApplicationObjectRow, Column, field, get_table_name, register_table
from data_layer.session import SessionId
from data_layer.transaction import SyncWriteTransaction
from data_layer.types import SysId, UserId
from data_layer.vector_index import Embedding, EmbeddingPrecision, VectorMetric, vector_indexed
from data_layer_testing.permission_read_scenarios import (
    READ_PERMISSION_SCENARIO_TABLES,
    MatrixScopedRbacScheme,
    ReadPermissionScenario,
)


class WideNativeRow(ApplicationObjectRow[SysId]):
    label: str
    content: str = ""
    vector: Embedding


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=768, auto_queue=False)
@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(plural="phase7_native_768_rows")
class Native768Row(WideNativeRow):
    vector: Embedding = Column(embedding_dimensions=768, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=1024, auto_queue=False)
@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(plural="phase7_native_1024_rows")
class Native1024Row(WideNativeRow):
    vector: Embedding = Column(embedding_dimensions=1024, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=768, auto_queue=False)
@register_permissions(scheme_factory=OwnershipScheme)
@register_table(plural="phase7_native_owned_768_rows")
class NativeOwned768Row(WideNativeRow):
    owner_id: UserId
    vector: Embedding = Column(embedding_dimensions=768, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=1024, auto_queue=False)
@register_permissions(scheme_factory=OwnershipScheme)
@register_table(plural="phase7_native_owned_1024_rows")
class NativeOwned1024Row(WideNativeRow):
    owner_id: UserId
    vector: Embedding = Column(embedding_dimensions=1024, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=768, auto_queue=False)
@register_permissions(
    scheme_factory=lambda: OwnerRoleSharesScheme(resource_type="phase7_native_shared_768_rows"),
)
@register_table(plural="phase7_native_shared_768_rows")
class NativeShared768Row(WideNativeRow):
    owner_id: UserId
    vector: Embedding = Column(embedding_dimensions=768, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=1024, auto_queue=False)
@register_permissions(
    scheme_factory=lambda: OwnerRoleSharesScheme(resource_type="phase7_native_shared_1024_rows"),
)
@register_table(plural="phase7_native_shared_1024_rows")
class NativeShared1024Row(WideNativeRow):
    owner_id: UserId
    vector: Embedding = Column(embedding_dimensions=1024, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=768, auto_queue=False)
@register_permissions(scheme_factory=RBACScheme)
@register_table(plural="phase7_native_rbac_768_rows")
class NativeRbac768Row(WideNativeRow):
    vector: Embedding = Column(embedding_dimensions=768, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=1024, auto_queue=False)
@register_permissions(scheme_factory=RBACScheme)
@register_table(plural="phase7_native_rbac_1024_rows")
class NativeRbac1024Row(WideNativeRow):
    vector: Embedding = Column(embedding_dimensions=1024, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=768, auto_queue=False)
@register_permissions(scheme_factory=MatrixScopedRbacScheme)
@register_table(plural="phase7_native_scoped_768_rows")
class NativeScoped768Row(WideNativeRow):
    owner_id: UserId
    scope_id: str = Column(max_length=255)
    vector: Embedding = Column(embedding_dimensions=768, embedding_precision=EmbeddingPrecision.FLOAT32)


@vector_indexed("content", metric=VectorMetric.DOT_PRODUCT, dimensions=1024, auto_queue=False)
@register_permissions(scheme_factory=MatrixScopedRbacScheme)
@register_table(plural="phase7_native_scoped_1024_rows")
class NativeScoped1024Row(WideNativeRow):
    owner_id: UserId
    scope_id: str = Column(max_length=255)
    vector: Embedding = Column(embedding_dimensions=1024, embedding_precision=EmbeddingPrecision.FLOAT32)


_NATIVE_MODELS = (
    Native768Row,
    Native1024Row,
    NativeOwned768Row,
    NativeOwned1024Row,
    NativeShared768Row,
    NativeShared1024Row,
    NativeRbac768Row,
    NativeRbac1024Row,
    NativeScoped768Row,
    NativeScoped1024Row,
)

TEST_BOOTSTRAP_FAMILY = SECURITY_V1
TEST_BOOTSTRAP_TABLES = (*READ_PERMISSION_SCENARIO_TABLES, *_NATIVE_MODELS, *matching.MATCHING_OPERATOR_TABLES)


def _scenario_model(
    scenario: ReadPermissionScenario,
    dimensions: int,
) -> type[WideNativeRow]:
    return {
        "system": {768: Native768Row, 1024: Native1024Row},
        "authenticated-open": {768: Native768Row, 1024: Native1024Row},
        "owner-clean": {768: NativeOwned768Row, 1024: NativeOwned1024Row},
        "owner-isolated": {768: NativeOwned768Row, 1024: NativeOwned1024Row},
        "direct-share": {768: NativeShared768Row, 1024: NativeShared1024Row},
        "rbac-table": {768: NativeRbac768Row, 1024: NativeRbac1024Row},
        "rbac-scope": {768: NativeScoped768Row, 1024: NativeScoped1024Row},
    }[scenario.key][dimensions]


def _packed_coordinate(dimensions: int, coordinate: int, value: float = 1.0) -> bytes:
    values = [0.0] * dimensions
    values[coordinate] = value
    return b"EMB\x01\x00" + struct.pack(f"<{dimensions}f", *values)


def _assert_wide_dimension_semantics(
    db_connection: SyncDatabaseConnection,
    dimensions: int,
    scenario: ReadPermissionScenario | None = None,
) -> None:
    model = (Native768Row if dimensions == 768 else Native1024Row) if scenario is None else _scenario_model(scenario, dimensions)
    original = _spec()
    representation = matching.MatchPackedDenseFieldRepresentationSpec.from_field(
        field(model.vector),
        dimensions=matching.MatchVectorDimensions(dimensions),
    )
    spec = matching.MatchSpec[WideNativeRow, WideNativeRow](
        spec_ref_id=matching.MatchSpecRefId(f"phase7:native:wide:{dimensions}"),
        left=matching.MatchRelationSpec[WideNativeRow](
            relation_ref_id=matching.MatchRelationRefId(f"wide:{dimensions}:left"),
            row_type=model,
            representation=representation,
        ),
        right=matching.MatchRelationSpec[WideNativeRow](
            relation_ref_id=matching.MatchRelationRefId(f"wide:{dimensions}:right"),
            row_type=model,
            representation=representation,
        ),
        kernel=original.kernel,
        policies=original.policies,
        pair_scope=original.pair_scope,
        result_shape=original.result_shape,
        filters=original.filters,
        work_limits=validated_model_update(
            original.work_limits,
            {
                "max_left_rows": matching.MatchRowCountLimit(3),
                "max_right_rows": matching.MatchRowCountLimit(3),
            },
        ),
    )

    authorized_access = {} if scenario is None else scenario.companion_access_values()
    first = model(
        sys_id=SysId(UUID("00000000-0000-7000-8000-000000000101")),
        label="first",
        vector=_packed_coordinate(dimensions, 0),
        **authorized_access,
    )
    last = model(
        sys_id=SysId(UUID("00000000-0000-7000-8000-000000000102")),
        label="last",
        vector=_packed_coordinate(dimensions, dimensions - 1),
        **authorized_access,
    )

    def seed(txn: SyncWriteTransaction) -> None:
        matching.publish_native_exact_plan(txn, spec)
        txn.insert_many(model, [first, last])
        if scenario is not None:
            scenario.grant_companion_read_access(
                txn,
                resource=str(get_table_name(model)),
                model_class_name=model.__name__,
                row_ids=(first.sys_id, last.sys_id),
            )

    setup_session_id = SessionId.schema() if scenario is None else scenario.setup_session_id
    actor_session_id = SessionId.schema() if scenario is None else scenario.actor_session_id
    db_connection.session(setup_session_id).write(fn=seed)
    actor_session = db_connection.session(actor_session_id)
    result = actor_session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert len(result.edges) == 2
    assert {edge.left.label for edge in result.edges} == {"first", "last"}
    assert all(edge.left.sys_id == edge.right.sys_id and float(edge.score.canonical) == 1.0 for edge in result.edges)
    assert result.work.pair_evaluations == matching.MatchPairEvaluationCount(4)
    if scenario is None:
        return

    denied_access = scenario.companion_access_values()
    if "owner_id" in model.model_fields:
        denied_access["owner_id"] = UserId.new()
    if "scope_id" in model.model_fields:
        denied_access["scope_id"] = f"denied-wide-{scenario.key}-{dimensions}"
    denied = model(
        sys_id=SysId(UUID("00000000-0000-7000-8000-000000000100")),
        label="denied",
        vector=_packed_coordinate(dimensions, 0, 2.0),
        **denied_access,
    )
    db_connection.session(setup_session_id).write(fn=lambda txn: txn.insert(model, denied))
    controlled = actor_session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(controlled, matching.TopKPerLeftMatchResult)
    restricted = scenario.key in {"owner-clean", "owner-isolated", "direct-share", "rbac-scope"}
    if restricted:
        assert {(edge.left.label, edge.right.label, float(edge.score.canonical)) for edge in controlled.edges} == {
            ("first", "first", 1.0),
            ("last", "last", 1.0),
        }
        assert controlled.work.pair_evaluations == matching.MatchPairEvaluationCount(4)
    else:
