)


def _spec(family: Literal["native", "h14"]) -> matching.MatchSpec[RedLeft, RedRight]:
    original = native_spec() if family == "native" else h14_spec()
    left = original.left.model_dump()
    right = original.right.model_dump()
    left["row_type"] = RedLeft
    right["row_type"] = RedRight
    field_name = "vector" if family == "native" else "code"
    left["representation"] = {
        **original.left.representation.model_dump(),
        "row_type": RedLeft,
        "field_name": field_name,
        "representation_ref_id": matching.MatchRepresentationRefId(
            f"{RedLeft.__module__}.{RedLeft.__qualname__}:{field_name}:{'packed-fp32' if family == 'native' else 'h14'}",
        ),
        "availability": matching.MatchRepresentationPresenceSpec.from_field(field(RedLeft.present)),
    }
    right["representation"] = {
        **original.right.representation.model_dump(),
        "row_type": RedRight,
        "field_name": field_name,
        "representation_ref_id": matching.MatchRepresentationRefId(
            f"{RedRight.__module__}.{RedRight.__qualname__}:{field_name}:{'packed-fp32' if family == 'native' else 'h14'}",
        ),
        "availability": matching.MatchRepresentationPresenceSpec.from_field(field(RedRight.present)),
    }
    return matching.MatchSpec[RedLeft, RedRight].model_validate(
        {
            **original.model_dump(),
            "left": left,
            "right": right,
        }
    )


def _malformed_spec() -> matching.MatchSpec[MalformedPackedLeft, MalformedPackedRight]:
    return matching.match_spec(
        spec_ref_id=matching.MatchSpecRefId("phase7:malformed-packed"),
        left=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId("phase7:malformed-packed:left"),
            row_type=MalformedPackedLeft,
            representation=matching.MatchPackedDenseFieldRepresentationSpec.from_field(
                field(MalformedPackedLeft.vector),
                dimensions=matching.MatchVectorDimensions(2),
            ),
        ),
        right=matching.MatchRelationSpec(
            relation_ref_id=matching.MatchRelationRefId("phase7:malformed-packed:right"),
            row_type=MalformedPackedRight,
            representation=matching.MatchPackedDenseFieldRepresentationSpec.from_field(
                field(MalformedPackedRight.vector),
                dimensions=matching.MatchVectorDimensions(2),
            ),
        ),
        kernel=matching.MatchKernelSpec(
            kernel_ref_id=matching.MatchKernelRefId("phase7:malformed-packed:dot"),
            kind=matching.MatchKernelKind.DENSE_DOT_PRODUCT,
            score_direction=matching.MatchScoreDirection.HIGHER_IS_BETTER,
        ),
        result_shape=matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
        policies=native_spec().policies,
        filters=matching.MatchFilterSet.no_filters(),
        work_limits=matching.MatchWorkLimits.standard_exact_dense(),
    )


def _publish(
    txn: SyncWriteTransaction,
    family: Literal["native", "h14"],
    spec: matching.MatchSpec[RedLeft, RedRight],
) -> matching.H14ProjectionArtifact | None:
    if family == "native":
        matching.publish_native_exact_plan(txn, spec)
        return None
    artifact, blobs = h14_fixture()
    matching.publish_h14_projection(txn, artifact, blobs)
    return artifact


@pytest.mark.parametrize("family", ["native", "h14"])
@pytest.mark.parametrize(("left_present", "right_present"), [(True, True), (False, True), (True, False), (False, False)])
def test_r021_missing_score_is_substituted_before_ranking(
    db_connection: SyncDatabaseConnection,
    family: Literal["native", "h14"],
    left_present: bool,
    right_present: bool,
    system_session_id: SessionId,
) -> None:
    original = _spec(family)
    spec = validated_model_update(
        original,
        {
            "policies": validated_model_update(
                original.policies,
                {
                    "missing_representation": matching.EmitDeclaredMissingScorePolicy(score=matching.MatchScoreValue(-7)),
                },
            )
        },
    )
    representation_values: dict[str, object] = (
        {"vector": _packed(1, 0)} if family == "native" else {**h14_fixture_values(0.0), "vector": _packed(1, 0)}
    )

    def seed(txn: SyncWriteTransaction) -> None:
        artifact = _publish(txn, family, spec)
        inserted_left = txn.insert(
            RedLeft,
            RedLeft.model_validate({"label": "left", "present": left_present, **representation_values}),
        )
        inserted_right = txn.insert(
            RedRight,
            RedRight.model_validate({"label": "right", "present": right_present, **representation_values}),
        )
        if artifact is not None and left_present:
            bind_fixture_code(txn, RedLeft, inserted_left, artifact)
        if artifact is not None and right_present:
            bind_fixture_code(txn, RedRight, inserted_right, artifact)

    session = db_connection.session(SessionId.schema())
    session.write(fn=seed)
    result = session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(result, matching.TopKPerLeftMatchResult)
    assert len(result.edges) == 1
    assert float(result.edges[0].score.canonical) == (1.0 if left_present and right_present else -7.0)


@pytest.mark.parametrize(
    "malformed",
    [
        b"",
        b"EMB\x01\x00",
        _packed(1, 2)[:-1],
        _packed(1),
        _packed(1, 2, 3),
        _packed(float("nan"), 0),
        _packed(float("inf"), 0),
        b"BAD!!" + _packed(1, 2)[5:],
    ],
)
def test_r022_r049_malformed_packed_source_has_typed_rejection(
    db_connection: SyncDatabaseConnection,
    malformed: bytes,
    system_session_id: SessionId,
) -> None:
    spec = _malformed_spec()

    def seed(txn: SyncWriteTransaction) -> MalformedPackedLeft:
        matching.publish_native_exact_plan(txn, spec)
        left = txn.insert(MalformedPackedLeft, MalformedPackedLeft(label="left", vector=_packed(1, 0)))
        txn.insert(MalformedPackedRight, MalformedPackedRight(label="right", vector=_packed(1, 0)))
        return left

    session = db_connection.session(SessionId.schema())
    original = session.write(fn=seed)
    control = session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(control, matching.TopKPerLeftMatchResult)
    assert len(control.edges) == 1
    assert float(control.edges[0].score.canonical) == 1.0
    try:
        changed = validated_model_update(original, {"vector": malformed})
    except ValidationError as error:
        assert all(item["loc"] == ("vector",) for item in error.errors())
    else:
        try:
            session.write(fn=lambda txn: txn.update(MalformedPackedLeft, changed))
        except DataError:
            pass
        else:
            with pytest.raises(matching.MatchError):
                session.read(fn=lambda txn: matching.match(txn, spec))
            return
    preserved = session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(preserved, matching.TopKPerLeftMatchResult)
    assert len(preserved.edges) == 1
    assert float(preserved.edges[0].score.canonical) == 1.0


def test_r019_top_k_counts_logical_neighbors_after_deduplication(
    db_connection: SyncDatabaseConnection,
