    def seed(txn: SyncWriteTransaction) -> None:
        _publish(txn, "native", spec)
        txn.insert(RedLeft, RedLeft(label="left", vector=_packed(1, 0)))
        for identity, label, score in [(1, "duplicate", 10.0), (2, "duplicate", 10.0), (3, "other", 9.0)]:
            txn.insert(RedRight, RedRight(sys_id=SysId(UUID(int=identity)), label=label, vector=_packed(score, 0)))

    session = db_connection.session(SessionId.schema())
