@pytest.mark.parametrize("family", ["native", "h14"])
def test_phase7_rejects_cross_family_final_kernel_after_successful_control(
    db_connection: SyncDatabaseConnection,
    family: Literal["native", "h14"],
    system_session_id: SessionId,
) -> None:
    spec = _spec(family)

    def seed(txn: SyncWriteTransaction) -> None:
        artifact = _publish(txn, family, spec)
        left = txn.insert(RedLeft, RedLeft(label="left", vector=_packed(1, 0), **h14_fixture_values(0.0)))
        right = txn.insert(RedRight, RedRight(label="right", vector=_packed(1, 0), **h14_fixture_values(0.0)))
        if artifact is not None:
            bind_fixture_code(txn, RedLeft, left, artifact)
            bind_fixture_code(txn, RedRight, right, artifact)

    session = db_connection.session(SessionId.schema())
    session.write(fn=seed)
    control = session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(control, matching.TopKPerLeftMatchResult)
    assert len(control.edges) == 1
    assert float(control.edges[0].score.canonical) == 1.0
    other_kernel = _spec("h14" if family == "native" else "native").kernel
    incompatible = validated_model_update(spec, {"kernel": other_kernel})
    with pytest.raises(matching.MatchPhysicalPlanError):
        session.read(fn=lambda txn: matching.match(txn, incompatible))


def test_r020_native_cursor_continues_the_complete_top_k(
    db_connection: SyncDatabaseConnection,
    system_session_id: SessionId,
) -> None:
    original = _spec("native")
    spec = validated_model_update(
        original,
        {
            "result_shape": matching.TopKPerLeftMatchShape(
                neighbor_count=matching.NeighborCount(3),
                pagination=matching.FirstMatchPage(page_size=matching.MatchPageSize(1)),
            )
        },
    )

    def seed(txn: SyncWriteTransaction) -> None:
        _publish(txn, "native", spec)
        txn.insert(RedLeft, RedLeft(label="query", vector=_packed(1, 0)))
        for index in range(3):
            txn.insert(RedRight, RedRight(label=str(index), vector=_packed(float(index), 0)))

    session = db_connection.session(SessionId.schema())
    session.write(fn=seed)
    first = session.read(fn=lambda txn: matching.match(txn, spec))
    assert isinstance(first, matching.TopKPerLeftMatchResult)
    assert [edge.right.label for edge in first.edges] == ["2"]
    assert isinstance(first.page, matching.MatchNextPage)
    second_spec = validated_model_update(
        spec,
        {
            "result_shape": validated_model_update(
                spec.result_shape,
                {
                    "pagination": matching.MatchPageAfterCursor(page_size=matching.MatchPageSize(2), cursor=first.page.cursor),
                },
            )
        },
    )
    second = session.read(fn=lambda txn: matching.match(txn, second_spec))
    assert isinstance(second, matching.TopKPerLeftMatchResult)
    assert [edge.right.label for edge in second.edges] == ["1", "0"]
    assert isinstance(second.page, matching.MatchPageComplete)


