@pytest.mark.parametrize("family", ["native", "h14"])
def test_phase7_native_filters_execute_before_scoring(
    db_connection: SyncDatabaseConnection,
    family: Literal["native", "h14"],
    system_session_id: SessionId,
) -> None:
    original = _spec(family)
    no_filter = matching.NoMatchFilter()
    left_filter = matching.MatchEndpointFilterSpec.from_expression(field(RedLeft.label) == "keep")
    right_filter = matching.MatchEndpointFilterSpec.from_expression(field(RedRight.label) == "keep")
    empty_filter = matching.MatchEndpointFilterSpec.from_expression(field(RedLeft.label) == "absent")
    pair_filter = matching.MatchPairFieldComparisonSpec.from_fields(
        field(RedLeft.label),
        matching.MatchPairComparisonOperator.EQUAL,
        field(RedRight.label),
    )
    filter_profiles = {
        "left": matching.MatchFilterSet(left=left_filter, right=no_filter, pair=no_filter),
        "right": matching.MatchFilterSet(left=no_filter, right=right_filter, pair=no_filter),
        "pair": matching.MatchFilterSet(left=no_filter, right=no_filter, pair=pair_filter),
        "all": matching.MatchFilterSet(left=left_filter, right=right_filter, pair=pair_filter),
        "selective": matching.MatchFilterSet(left=left_filter, right=right_filter, pair=no_filter),
        "empty": matching.MatchFilterSet(left=empty_filter, right=no_filter, pair=no_filter),
    }
    specs = {
        profile: validated_model_update(
            original,
            {
                "spec_ref_id": matching.MatchSpecRefId(f"phase7:filters:{family}:{profile}"),
                "filters": filters,
                "result_shape": matching.TopKPerLeftMatchShape(neighbor_count=matching.NeighborCount(1)),
                "work_limits": validated_model_update(
                    original.work_limits,
                    {
                        "max_left_rows": matching.MatchRowCountLimit(2),
                        "max_right_rows": matching.MatchRowCountLimit(2),
                    },
                ),
            },
        )
        for profile, filters in filter_profiles.items()
    }

    def seed(txn: SyncWriteTransaction) -> None:
        artifact = _publish(txn, family, next(iter(specs.values())))
        if family == "native":
            for spec in tuple(specs.values())[1:]:
                matching.publish_native_exact_plan(txn, spec)
        for label in ("keep", "drop"):
            values: dict[str, object] = {"vector": _packed(1, 0)}
            if family == "h14":
                values.update(h14_fixture_values(0.0))
            left = txn.insert(RedLeft, RedLeft(label=label, **values))
            right = txn.insert(RedRight, RedRight(label=label, **values))
            if artifact is not None:
                bind_fixture_code(txn, RedLeft, left, artifact)
                bind_fixture_code(txn, RedRight, right, artifact)

    session = db_connection.session(SessionId.schema())
    session.write(fn=seed)
    expected_edges = {"left": 1, "right": 2, "pair": 2, "all": 1, "selective": 1, "empty": 0}
    expected_pairs = {"left": 2, "right": 2, "pair": 2, "all": 1, "selective": 1, "empty": 0}
    results = session.read(fn=lambda txn: lazy_tuple(*(matching.match_lazy(txn, spec) for spec in specs.values())).resolve())
    for profile, result in zip(specs, results, strict=True):
        assert isinstance(result, matching.TopKPerLeftMatchResult)
        assert len(result.edges) == expected_edges[profile]
        assert result.work.pair_evaluations == matching.MatchPairEvaluationCount(expected_pairs[profile])

def test_r008_semantic_packed_spec_does_not_require_operator_profile() -> None:
    original = _spec("native").left.representation
    payload = original.model_dump(exclude={"native_profile", "execution_choice"})
    representation = matching.MatchPackedDenseFieldRepresentationSpec[RedLeft].model_validate(payload)
    assert representation.dimensions == matching.MatchVectorDimensions(2)

