"""H14 V1 fit and encoding primitives over immutable little-endian fp32 tensors.

These primitives do not read application rows or select training populations. The
caller must supply the authorized, scope-bound population before artifact publication.
"""

from __future__ import annotations

import math
from collections.abc import Mapping
from typing import Self

import numpy as np
from numpy.typing import NDArray

from pydantic import BaseModel, ConfigDict, Field, model_validator

from l2055_lazy_result.purity import pure_lazy

from l1470_matching_contracts.projection_models import (
    H14ProjectionArtifact,
    ProjectionTensorDigest,
    current_numpy_backend_fingerprint,
)


def _generate_h14_residual_payload() -> bytes:
    generator = np.random.Generator(np.random.PCG64(256))
    matrix = np.asarray(
        generator.standard_normal((768, 256), dtype=np.float32) / math.sqrt(768),
        dtype="<f4",
    )
    return matrix.tobytes()


_H14_RESIDUAL_PAYLOAD = _generate_h14_residual_payload()


class H14FitTensors(BaseModel, frozen=True):
    """Immutable numerical contents of a fitted H14 generation."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    mean: bytes
    rotation: bytes
    thresholds: bytes
    residual_projection: bytes = Field(default_factory=lambda: _H14_RESIDUAL_PAYLOAD)
    signal_order: tuple[int, ...]

    @model_validator(mode="after")
    def validate_tensors(self: Self) -> Self:
        for payload, count in (
            (self.mean, 768),
            (self.rotation, 768 * 768),
            (self.thresholds, 768),
            (self.residual_projection, 768 * 256),
        ):
            if len(payload) != count * 4:
                raise ValueError("H14 tensors require their canonical fp32 shape")
            if not np.isfinite(np.frombuffer(payload, dtype="<f4")).all():
                raise ValueError("H14 tensors must contain finite values")
        if len(self.signal_order) != 768 or set(self.signal_order) != set(range(768)):
            raise ValueError("H14 signal order must be a permutation of 768 dimensions")
        rotation = np.frombuffer(self.rotation, dtype="<f4").reshape(768, 768)
        gram = rotation.T @ rotation
        if not np.allclose(gram, np.eye(768, dtype=np.float32), atol=2e-4, rtol=2e-4):
            raise ValueError("H14 rotation tensor must be orthogonal")
        return self


@pure_lazy
def _validate_vectors(values: NDArray[np.float32]) -> None:
    if values.dtype != np.dtype("<f4"):
        raise ValueError("H14 source vectors require canonical little-endian fp32")
    if not values.flags.c_contiguous:
        raise ValueError("H14 source vectors require canonical contiguous storage")
    if not np.isfinite(values).all():
        raise ValueError("H14 source vectors must contain finite values")
    if np.any(np.abs(values) > 1 + 1e-5):
        raise ValueError("H14 source vectors must be normalized or zero")
    norms = np.linalg.norm(values, axis=-1)
    zero_vectors = np.all(values == 0, axis=-1)
    if not np.all(zero_vectors | np.isclose(norms, 1, atol=1e-5, rtol=0)):
        raise ValueError("H14 source vectors must be normalized or zero")


def validate_h14_source_payload(payload: bytes) -> None:
    """Check one canonical source payload with the fitting and encoding rules."""
    if len(payload) != 768 * 4:
        raise ValueError("H14 source payload must contain 768 little-endian fp32 coordinates")
    _validate_vectors(np.frombuffer(payload, dtype="<f4"))


def fit_h14(
    queries: NDArray[np.float32],
    positives: NDArray[np.float32],
    negatives: NDArray[np.float32],
) -> H14FitTensors:
    """Fit one positive and four dense hard negatives per normalized query.

    Negative centroids and positive rows each contribute once to the document fit
    population. Equal signal strengths retain source-dimension order.
    """
    if queries.ndim != 2 or queries.shape[1] != 768 or queries.shape[0] == 0:
        raise ValueError("H14 fit requires a nonempty 768-dimensional query population")
    if positives.shape != queries.shape:
        raise ValueError("H14 fit requires one positive vector per query")
    if negatives.shape != (queries.shape[0], 4, 768):
        raise ValueError("H14 fit requires four hard negatives per query")
    for values in (queries, positives, negatives):
        _validate_vectors(values)
    negative_centroids = np.mean(negatives, axis=1, dtype=np.float32)
    documents = np.stack((positives, negative_centroids), axis=1).reshape(-1, 768)
    mean = np.mean(np.concatenate((queries, documents)), axis=0, dtype=np.float32)
    centered_queries = np.asarray(queries - mean, dtype=np.float32)
    targets = np.asarray((positives - mean) - (negative_centroids - mean), dtype=np.float32)
    covariance = centered_queries.T @ targets
    left, _, right = np.linalg.svd(covariance, full_matrices=True)
    rotation = np.asarray(left @ right, dtype=np.float32)
    rotated_documents = np.asarray(documents - mean, dtype=np.float32) @ rotation
    thresholds = np.asarray(np.median(rotated_documents, axis=0), dtype=np.float32)
    signal = np.linalg.norm(covariance, axis=1) + np.linalg.norm(covariance, axis=0)
    order = np.argsort(-signal, kind="stable")
    return H14FitTensors(
        mean=mean.astype("<f4").tobytes(),
        rotation=rotation.astype("<f4").tobytes(),
        thresholds=thresholds.astype("<f4").tobytes(),
        residual_projection=h14_residual_matrix().astype("<f4").tobytes(),
        signal_order=tuple(int(index) for index in order),
    )


def h14_residual_matrix() -> NDArray[np.float32]:
    """Return a copy of the one materialized pinned residual projection."""
    return np.frombuffer(_H14_RESIDUAL_PAYLOAD, dtype="<f4").reshape(768, 256).copy()


@pure_lazy
def bind_h14_tensors(
    artifact: H14ProjectionArtifact,
    blobs: Mapping[ProjectionTensorDigest, bytes],
) -> H14FitTensors:
    """Verify all referenced blobs and the pinned residual generator before use."""
    if artifact.numeric_contract.numpy_version != np.__version__:
        raise ValueError("H14 artifact NumPy version does not match this runtime")
    if artifact.numeric_contract.numpy_backend_fingerprint != current_numpy_backend_fingerprint():
        raise ValueError("H14 artifact numerical backend does not match this runtime")
    references = (
        artifact.mean_tensor,
        artifact.rotation_tensor,
        artifact.threshold_tensor,
        artifact.residual_tensor,
    )
    verified: list[bytes] = []
    for reference in references:
        content = blobs.get(reference.digest)
        if content is None:
            raise ValueError("H14 artifact tensor is missing")
        if not isinstance(content, bytes):
            raise ValueError("H14 artifact tensors require immutable bytes")
        reference.verify(content)
        verified.append(content)
    if verified[3] != _H14_RESIDUAL_PAYLOAD:
        raise ValueError("H14 residual projection does not match the pinned generator")
    return H14FitTensors(
        mean=verified[0],
        rotation=verified[1],
        thresholds=verified[2],
        residual_projection=verified[3],
        signal_order=tuple(artifact.signal_order),
    )


@pure_lazy
def encode_h14_batch(
    vectors: NDArray[np.float32],
    fitted: H14FitTensors,
) -> NDArray[np.uint8]:
    """Encode a normalized batch while constructing the pinned residual matrix once."""
    if vectors.ndim != 2 or vectors.shape[1] != 768:
        raise ValueError("H14 batch encoding requires 768 source dimensions")
    _validate_vectors(vectors)
    mean = np.frombuffer(fitted.mean, dtype="<f4")
    rotation = np.frombuffer(fitted.rotation, dtype="<f4").reshape(768, 768)
    centered = np.asarray(vectors - mean, dtype=np.float32)
    rotated = centered @ rotation
    selected = np.asarray(fitted.signal_order[:384])
    mixed = centered.copy()
    mixed[:, selected] += rotated[:, selected]
    residual = rotated.copy()
    residual[:, selected] = 0
    residual_projection = np.frombuffer(fitted.residual_projection, dtype="<f4").reshape(768, 256)
    projected = residual @ residual_projection
    return np.packbits(np.concatenate((mixed >= 0, projected >= 0), axis=1), axis=1, bitorder="big")


@pure_lazy
def encode_h14(vector: NDArray[np.float32], fitted: H14FitTensors) -> bytes:
    """Encode query or document identically, base block first and most-significant bit first."""
    if vector.shape != (768,):
        raise ValueError("H14 encoding requires 768 source dimensions")
    packed = encode_h14_batch(vector.reshape(1, 768), fitted)[0].tobytes()
    assert isinstance(packed, bytes)
    return packed


def h14_hamming(left: bytes, right: bytes) -> int:
    """Count differing bits in two canonical 1,024-bit codes."""
    if len(left) != 128 or len(right) != 128:
        raise ValueError("H14 codes must contain exactly 128 bytes")
    return sum((first ^ second).bit_count() for first, second in zip(left, right, strict=True))

