class RequireMaintainedRowStep[T: DatabaseObjectRow[SysId]](NonPublishingStep[T]):
    """Reject a failed source compare-and-swap before binding publication."""

    def __init__(self: Self, ref_id: ServerPlanRefId, model_cls: type[T], source_ref: ServerPlanRefId) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._source_ref = source_ref

    @property
    def level(self: RequireMaintainedRowStep[T]) -> int:
        return 0

    def result_cardinality(self: RequireMaintainedRowStep[T]) -> Cardinality:
        return Cardinality.SCALAR

    def runtime_result_is_terminal_scalar(self: RequireMaintainedRowStep[T]) -> bool:
        return True

    def is_read_only(self: RequireMaintainedRowStep[T]) -> bool:
        return True

    def execution_role(self: RequireMaintainedRowStep[T]) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self: RequireMaintainedRowStep[T]) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def tables_read(self: RequireMaintainedRowStep[T]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: RequireMaintainedRowStep[T]) -> frozenset[str]:
        return frozenset()

    def compile(self: RequireMaintainedRowStep[T], ctx: CompilationContext) -> CompiledStep[T]:
        del ctx
        return CompiledStep()

    def execute_runtime(self: RequireMaintainedRowStep[T], resolved: ResolvedRefs) -> T:
        rows = resolved.get(str(self._source_ref))
        assert isinstance(rows, list | tuple)
        if len(rows) != 1:
            raise MatchFreshnessError(
                MatchErrorContext(
                    spec_ref_id=MatchSpecRefId("producer:maintenance_results"),
                    invariant=MatchInvariant.ARTIFACT_SOURCE_DELTA,
                    expected=MatchExpectedValue("h14_maintenance_one_unchanged_source"),
                    observed=MatchObservedValue("h14_maintenance_source_changed"),
                    safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                )
            )
        row = rows[0]
        assert isinstance(row, self._model_cls)
        return row


class CollectMaintainedRowsStep[T: DatabaseObjectRow[SysId]](NonPublishingStep[tuple[T, ...]]):
    def __init__(
        self: Self,
        ref_id: ServerPlanRefId,
        model_cls: type[T],
        source_refs: tuple[ServerPlanRefId, ...],
    ) -> None:
        super().__init__(ref_id)
        self._model_cls = model_cls
        self._source_refs = source_refs

    @property
    def level(self: CollectMaintainedRowsStep[T]) -> int:
        return 0

    def result_cardinality(self: CollectMaintainedRowsStep[T]) -> Cardinality:
        return Cardinality.SCALAR

    def runtime_result_is_terminal_scalar(self: CollectMaintainedRowsStep[T]) -> bool:
        return True

    def is_read_only(self: CollectMaintainedRowsStep[T]) -> bool:
        return True

    def execution_role(self: CollectMaintainedRowsStep[T]) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def dependencies(self: CollectMaintainedRowsStep[T]) -> frozenset[str]:
        return frozenset(str(ref) for ref in self._source_refs)

    def tables_read(self: CollectMaintainedRowsStep[T]) -> frozenset[str]:
        return frozenset()

    def tables_written(self: CollectMaintainedRowsStep[T]) -> frozenset[str]:
        return frozenset()

    def compile(self: CollectMaintainedRowsStep[T], ctx: CompilationContext) -> CompiledStep[tuple[T, ...]]:
        del ctx
        return CompiledStep()

    def execute_runtime(self: CollectMaintainedRowsStep[T], resolved: ResolvedRefs) -> tuple[T, ...]:
        rows: list[T] = []
        for ref in self._source_refs:
            value = resolved.get(str(ref))
            assert isinstance(value, self._model_cls)
            rows.append(value)
        return tuple(rows)

