from l2070_batching.step import NonPublishingStep, StepExecutionRole

_PLAN_FIELDS = frozenset(MatchingNativeExactPlanRow.model_fields).difference(
    ApplicationObjectRow.model_fields,
) | {"sys_id"}


@pure_lazy
def cached_db_column_name(model_cls: type[ApplicationObjectRow], field_name: str) -> SqlColumnName:
    return matching_db_column_name(model_cls, DynamicFieldName(field_name))


@pure_lazy
def native_publication_rows_step(
    ref_id: ServerPlanRefId,
    *,
    expected: MatchingNativeExactPlanRow,
    after_refs: frozenset[ServerPlanRefId],
) -> GrammarRowsStep[dict[str, object]]:
    """Read all colliding identities after insert conflict resolution completes."""

    def column(name: str) -> SqlColumnRef:
        return SqlColumnRef(SqlColumnName(cached_db_column_name(MatchingNativeExactPlanRow, name)))

    identity = SqlBinaryOp(column("sys_id"), BinaryOp.EQ, SqlParam(expected.sys_id))
    scope = SqlBinaryOp(
        SqlBinaryOp(column("spec_ref_id"), BinaryOp.EQ, SqlParam(str(expected.spec_ref_id))),
        BinaryOp.AND,
        SqlBinaryOp(column("deployment_scope"), BinaryOp.EQ, SqlParam(str(expected.deployment_scope))),
    )
    statement = SqlSelect(
        select=SqlSelectList(
            [SqlSelectAlias(column(name), SqlAliasName(name)) for name in sorted(MatchingNativeExactPlanRow.model_fields)]
        ),
        from_=SqlTableIdent(SqlTableName(get_table_name(MatchingNativeExactPlanRow))),
        where=SqlBinaryOp(identity, BinaryOp.OR, scope),
    )
    # A fresh statement snapshot must see a concurrent winner after DO NOTHING waits.
    return GrammarRowsStep(
        ref_id,
        statement,
        config=_GrammarRowsConfig(deps=after_refs, batchable=False),
    )


class VerifyNativePublicationStep(NonPublishingStep[MatchingNativeExactPlanRow]):
    """Check all declared plan fields against an immutable publication snapshot."""

    def __init__(
        self: VerifyNativePublicationStep,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        expected: MatchingNativeExactPlanRow,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._expected_json = expected.model_dump_json(include=set(_PLAN_FIELDS))
        self._spec_ref_id = expected.spec_ref_id

    @property
    def level(self: VerifyNativePublicationStep) -> int:
        return 0

    def result_cardinality(self: VerifyNativePublicationStep) -> Cardinality:
        return Cardinality.SCALAR

    def is_read_only(self: VerifyNativePublicationStep) -> bool:
        return True

    def execution_role(self: VerifyNativePublicationStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def runtime_result_is_terminal_scalar(self: VerifyNativePublicationStep) -> bool:
        return True

    def dependencies(self: VerifyNativePublicationStep) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def tables_read(self: VerifyNativePublicationStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: VerifyNativePublicationStep) -> frozenset[str]:
        return frozenset()

    def compile(self: VerifyNativePublicationStep, ctx: CompilationContext) -> CompiledStep[MatchingNativeExactPlanRow]:
        del ctx
        return CompiledStep()

    def _conflict(self: VerifyNativePublicationStep) -> MatchCompatibilityError:
        return MatchCompatibilityError(
            MatchErrorContext(
                invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                expected=MatchExpectedValue("immutable_native_exact_deployment"),
                observed=MatchObservedValue("native_republication_conflict"),
                safe_action=MatchSafeAction.MIGRATE_PERSISTED_SPEC,
                spec_ref_id=self._spec_ref_id,
            )
        )

    def execute_runtime(self: VerifyNativePublicationStep, resolved: ResolvedRefs) -> MatchingNativeExactPlanRow:
        rows = resolved.get(str(self._source_ref))
        if not isinstance(rows, Sequence) or len(rows) != 1 or not isinstance(rows[0], Mapping):
            raise self._conflict()
        if not set(MatchingNativeExactPlanRow.model_fields).issubset(rows[0]) or rows[0]["sys_id"] is None:
            raise self._conflict()
        try:
            row = MatchingNativeExactPlanRow.model_validate(
                {name: rows[0][name] for name in MatchingNativeExactPlanRow.model_fields if name in rows[0]}
            )
        except ValidationError as error:
            raise self._conflict() from error
        if row.model_dump_json(include=set(_PLAN_FIELDS)) != self._expected_json:
            raise self._conflict()
        return row

