from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import TypeVar

from pydantic import BaseModel

from l2055_lazy_result.purity import pure_lazy

from impl.common.l2050_sql_types.sql_branded_types import SqlColumnName, SqlTableName, SqlTypeName, SqlJsonPath
from impl.common.l2070_server_plan.steps.grammar_execute import UtilityEffectStep
from impl.common.l2070_server_plan.steps.grammar_fetchall import GrammarRowsStep, _GrammarRowsConfig
from impl.common.l2100_sql_grammar.domain.ddl.ddl_relation_lock import SqlLockTablesAccessShare
from impl.common.l2100_sql_grammar.domain.infra.bootstrap_interrogation import SqlBootstrapPhysicalInterrogation
from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectList, SqlSubqueryTableRef
from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam, SqlStar
from impl.common.l2100_sql_grammar.base import SqlRenderable
