from impl.common.l2100_sql_grammar.tree.enums import BinaryOp
from impl.common.l2100_sql_grammar.tree.expr_compound import SqlCase, SqlFuncCall, SqlSubquery
from impl.common.l2100_sql_grammar.tree.expr_json import JsonAccessKind, SqlJsonAccess
from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and, sql_or
from impl.common.l5250_matching.schema_names import matching_db_column_name as cached_db_column_name
from l1000_schema.schema_def import DatabaseObjectRow
from l1000_schema.table_utils import get_table_name
from l1400_types import DynamicFieldName, SysId
from l1470_matching_contracts.models import (
    MatchSpec,
    MatchPackedDenseFieldRepresentationSpec,
)
from l3250_migrations.versioned_table_helpers import VersionedTableType, get_auxiliary_table_name
from l7000_versioned_schema.versioned_schema import VersionedObjectRow
from logged_table import build_merged_log_model
from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
from l1100_exceptions.exceptions import TableNotFoundError
from l1400_types import ServerPlanRefId
from l1470_matching_contracts.errors import (
    MatchErrorContext,
    MatchPhysicalPlanError,
)
from l1470_matching_contracts.types import (
    MatchExpectedValue,
