type NativeStorageRequirements = tuple[tuple[SqlTableName, SqlColumnName, SqlTypeName], ...]
LeftRowT = TypeVar("LeftRowT", bound=DatabaseObjectRow[SysId])
RightRowT = TypeVar("RightRowT", bound=DatabaseObjectRow[SysId])


@pure_lazy
def native_source_storage_requirements(spec: MatchSpec[LeftRowT, RightRowT]) -> NativeStorageRequirements:
    """Declare source and audit precision without database access."""
    requirements_list: list[tuple[SqlTableName, SqlColumnName, SqlTypeName]] = []
    for relation in (spec.left, spec.right):
        representation = relation.representation
        assert isinstance(representation, MatchPackedDenseFieldRepresentationSpec)
        tables = (
            tuple(get_auxiliary_table_name(relation.row_type, kind) for kind in VersionedTableType)
            if issubclass(relation.row_type, VersionedObjectRow)
            else (get_table_name(relation.row_type),)
        )
        column = cached_db_column_name(relation.row_type, DynamicFieldName(representation.field_name))
        physical_type = SqlTypeName(f"vector({int(representation.dimensions)})")
        for table in tables:
            requirements_list.append((SqlTableName(table), SqlColumnName(column), physical_type))
        if issubclass(relation.row_type, VersionedObjectRow):
            log_model = build_merged_log_model((relation.row_type,), backend_type="postgres")
            for prefix in ("old", "new"):
                requirements_list.append(
                    (
                        SqlTableName(get_table_name(log_model)),
                        SqlColumnName(cached_db_column_name(log_model, DynamicFieldName(f"{prefix}_{column}"))),
                        physical_type,
                    )
                )
    return tuple(sorted(set(requirements_list)))


def native_source_storage_admission_expression(requirements: NativeStorageRequirements) -> SqlRenderable:
    """Check live PostgreSQL storage in the caller's existing preflight statement."""
    columns: dict[str, set[str]] = {}
    for table, column, _ in requirements:
        columns.setdefault(str(table), set()).add(str(column))
    facts = SqlBootstrapPhysicalInterrogation(
        table_names=(),
        columns_by_table=tuple((table, tuple(sorted(names))) for table, names in sorted(columns.items())),
        indexes_by_table=(),
        presence="present",
        include_column_metadata=True,
    )
    predicates = tuple(
        sql_and(
            SqlBinaryOp(SqlColumnRef(SqlColumnName("table_name")), BinaryOp.EQ, SqlParam(str(table))),
            SqlBinaryOp(SqlColumnRef(SqlColumnName("column_name")), BinaryOp.EQ, SqlParam(str(column))),
            SqlBinaryOp(SqlColumnRef(SqlColumnName("presence")), BinaryOp.EQ, SqlParam("present")),
            SqlBinaryOp(
                SqlJsonAccess(
                    JsonAccessKind.GET_TEXT,
                    SqlColumnRef(SqlColumnName("payload_json")),
                    path=SqlJsonPath("$.data_type"),
                ),
                BinaryOp.EQ,
                SqlParam(str(kind)),
            ),
        )
        for table, column, kind in requirements
    )
    observed_count = SqlSubquery(
        SqlSelect(
            select=SqlSelectList([SqlFuncCall("COUNT", [SqlStar()])]),
            from_=SqlSubqueryTableRef(facts, SqlTableName("native_storage_admission")),
            where=sql_or(*predicates),
        )
    )
    return SqlNativeExactProjection(
        postgres=SqlCase(((SqlBinaryOp(observed_count, BinaryOp.EQ, SqlParam(len(requirements))), SqlParam(1)),), else_=SqlParam(0)),
        portable=SqlParam(1),
    )


def _storage_unavailable(spec_ref_id: MatchSpecRefId) -> MatchPhysicalPlanError:
    return MatchPhysicalPlanError(
        MatchErrorContext(
            invariant=MatchInvariant.PHYSICAL_PLAN_UNAVAILABLE,
            expected=MatchExpectedValue("schema_admitted_native_source_storage"),
            observed=MatchObservedValue("native_source_storage_mismatch"),
            safe_action=MatchSafeAction.MIGRATE_PERSISTED_SPEC,
            spec_ref_id=spec_ref_id,
        )
    )


class LockNativeSourceStorageStep(UtilityEffectStep):
    """Acquire schema locks and classify missing sources before publication."""

    def __init__(
        self: LockNativeSourceStorageStep,
        ref_id: ServerPlanRefId,
        *,
        requirements: NativeStorageRequirements,
        spec_ref_id: MatchSpecRefId,
    ) -> None:
        super().__init__(ref_id, SqlLockTablesAccessShare(tuple(table for table, _, _ in requirements)))
        self._spec_ref_id = spec_ref_id

    def normalize_execution_error(self: LockNativeSourceStorageStep, error: Exception) -> Exception:
        if isinstance(error, TableNotFoundError):
            return _storage_unavailable(self._spec_ref_id)
        return error


class _PhysicalColumnDefinition(BaseModel, frozen=True):
    data_type: str


@pure_lazy
def native_source_storage_rows_step(
    ref_id: ServerPlanRefId,
    *,
    requirements: NativeStorageRequirements,
    after_refs: frozenset[ServerPlanRefId],
) -> GrammarRowsStep[dict[str, object]]:
    columns: dict[str, set[str]] = {}
    for table_name, column_name, _ in requirements:
        columns.setdefault(str(table_name), set()).add(str(column_name))
    interrogation = SqlBootstrapPhysicalInterrogation(
        table_names=(),
        columns_by_table=tuple((name, tuple(sorted(names))) for name, names in sorted(columns.items())),
        indexes_by_table=(),
        presence="present",
        include_column_metadata=True,
    )
    query = SqlSelect(
        select=SqlSelectList(
            [
                SqlColumnRef(SqlColumnName(name))
                for name in (
                    "table_name",
                    "column_name",
                    "presence",
                    "payload_json",
                )
            ]
        ),
        from_=SqlSubqueryTableRef(interrogation, SqlTableName("native_storage_facts")),
    )
    return GrammarRowsStep(ref_id, query, config=_GrammarRowsConfig(deps=after_refs, batchable=False))


class RequireNativeSourceStorageStep(NonPublishingStep[None]):
    """Refuse publication before mutations when deployed column types differ."""

    def __init__(
        self: RequireNativeSourceStorageStep,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        requirements: NativeStorageRequirements,
        spec_ref_id: MatchSpecRefId,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._requirements = requirements
        self._spec_ref_id = spec_ref_id

    @property
    def level(self: RequireNativeSourceStorageStep) -> int:
        return 0

    def result_cardinality(self: RequireNativeSourceStorageStep) -> Cardinality:
        return Cardinality.SCALAR

    def is_read_only(self: RequireNativeSourceStorageStep) -> bool:
        return True

    def execution_role(self: RequireNativeSourceStorageStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def runtime_result_is_terminal_scalar(self: RequireNativeSourceStorageStep) -> bool:
        return True

    def dependencies(self: RequireNativeSourceStorageStep) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def tables_read(self: RequireNativeSourceStorageStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: RequireNativeSourceStorageStep) -> frozenset[str]:
        return frozenset()

    def compile(self: RequireNativeSourceStorageStep, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        return CompiledStep()

    def _unavailable(self: RequireNativeSourceStorageStep) -> MatchPhysicalPlanError:
        return _storage_unavailable(self._spec_ref_id)

    def execute_runtime(self: RequireNativeSourceStorageStep, resolved: ResolvedRefs) -> None:
        rows = resolved.get(str(self._source_ref))
        if not isinstance(rows, Sequence):
            raise self._unavailable()
        observed: dict[tuple[str, str], str] = {}
        for row in rows:
            if not isinstance(row, Mapping) or row.get("presence") != "present":
                raise self._unavailable()
            table_name, column_name, payload = row.get("table_name"), row.get("column_name"), row.get("payload_json")
            if not isinstance(table_name, str) or not isinstance(column_name, str) or not isinstance(payload, str):
                raise self._unavailable()
            key = (table_name, column_name)
            if key in observed:
                raise self._unavailable()
            try:
                observed[key] = _PhysicalColumnDefinition.model_validate_json(payload).data_type
            except ValueError as error:
                raise self._unavailable() from error
        expected = {(str(table), str(column)): str(kind) for table, column, kind in self._requirements}
        if observed != expected:
            raise self._unavailable()

