@pure_lazy
def persisted_tensor_rows_step(
    ref_id: ServerPlanRefId,
    *,
    artifact_id: MatchProjectionArtifactId,
    after_refs: frozenset[ServerPlanRefId],
) -> GrammarRowsStep[MatchingProjectionTensorRow]:
    """Read native binary payloads without constructing a multi-megabyte JSON array."""
    model = MatchingProjectionTensorRow
    query = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(SqlColumnRef(SqlColumnName(cached_db_column_name(model, name))), SqlAliasName(name))
                for name in model.model_fields
            ]
        ),
        from_=SqlTableIdent(SqlTableName(get_table_name(model))),
        where=SqlBinaryOp(
            SqlColumnRef(SqlColumnName(cached_db_column_name(model, "artifact_id"))),
            BinaryOp.EQ,
            SqlParam(artifact_id),
        ),
    )
    return GrammarRowsStep(
        ref_id,
        query,
        model_cls=model,
        config=_GrammarRowsConfig(
            deps=after_refs,
            batchable=False,
            result_mode=GrammarRowsResultMode.HYDRATE_MANY,
        ),
    )


def _unavailable() -> MatchArtifactError:
    return MatchArtifactError(
        MatchErrorContext(
            spec_ref_id=MatchSpecRefId("producer:projection_loader"),
            invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
            expected=MatchExpectedValue("complete_verified_projection_generation"),
            observed=MatchObservedValue("projection_generation_unavailable"),
            safe_action=MatchSafeAction.REBUILD_ARTIFACT,
