    )


class LoadH14ProjectionStep(NonPublishingStep[H14ProjectionFitResult]):
    """Validate persisted content without fitting or additional database operations."""

    def __init__(
        self: LoadH14ProjectionStep,
        ref_id: ServerPlanRefId,
        *,
        artifact_ref: ServerPlanRefId,
        tensors_ref: ServerPlanRefId,
        artifact_id: MatchProjectionArtifactId,
    ) -> None:
        super().__init__(ref_id)
        self._artifact_ref = artifact_ref
        self._tensors_ref = tensors_ref
        self._artifact_id = artifact_id

    @property
    def level(self: LoadH14ProjectionStep) -> int:
        return 0

    def result_cardinality(self: LoadH14ProjectionStep) -> Cardinality:
        return Cardinality.SCALAR

    def is_read_only(self: LoadH14ProjectionStep) -> bool:
        return True

    def execution_role(self: LoadH14ProjectionStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def runtime_result_is_terminal_scalar(self: LoadH14ProjectionStep) -> bool:
        return True

    def dependencies(self: LoadH14ProjectionStep) -> frozenset[str]:
        return frozenset({str(self._artifact_ref), str(self._tensors_ref)})

    def tables_read(self: LoadH14ProjectionStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: LoadH14ProjectionStep) -> frozenset[str]:
        return frozenset()

    def compile(self: LoadH14ProjectionStep, ctx: CompilationContext) -> CompiledStep[H14ProjectionFitResult]:
        del ctx
        return CompiledStep()

    def execute_runtime(self: LoadH14ProjectionStep, resolved: ResolvedRefs) -> H14ProjectionFitResult:
        artifacts = resolved.get(str(self._artifact_ref))
        tensors = resolved.get(str(self._tensors_ref))
        if not isinstance(artifacts, Sequence) or len(artifacts) != 1:
            raise _unavailable()
        row = artifacts[0]
        if not isinstance(row, MatchingProjectionArtifactRow):
            raise _unavailable()
        if not isinstance(tensors, Sequence) or len(tensors) != 4:
            raise _unavailable()
        roles: dict[str, MatchingProjectionTensorRow] = {}
        for tensor in tensors:
            if not isinstance(tensor, MatchingProjectionTensorRow) or tensor.role in roles:
                raise _unavailable()
            roles[tensor.role] = tensor
        if set(roles) != {"mean", "rotation", "threshold", "residual"}:
            raise _unavailable()
        try:
            artifact = H14ProjectionArtifact.model_validate_json(row.contract_payload)
            if (
                artifact.artifact_id != self._artifact_id
                or row.artifact_id != artifact.artifact_id
                or row.artifact_fingerprint != artifact.fingerprint()
                or row.algorithm_version != artifact.algorithm_version
                or row.tenant_scope != str(artifact.fit_scope.tenant)
                or row.workspace_scope != str(artifact.fit_scope.workspace)
                or row.branch_scope != str(artifact.fit_scope.branch)
                or row.revision_scope != str(artifact.fit_scope.revision)
                or row.permission_scope != str(artifact.fit_scope.permission)
            ):
                raise _unavailable()
            for role, reference in (
                ("mean", artifact.mean_tensor),
                ("rotation", artifact.rotation_tensor),
                ("threshold", artifact.threshold_tensor),
                ("residual", artifact.residual_tensor),
            ):
                tensor = roles[role]
                if (
                    tensor.artifact_id != artifact.artifact_id
                    or tensor.digest != reference.digest
                    or tensor.shape != "x".join(str(int(size)) for size in reference.shape)
                    or tensor.byte_count != int(reference.byte_count)
                    or tensor.dtype != reference.dtype
                    or tensor.byte_order != reference.byte_order
                    or tensor.tenant_scope != row.tenant_scope
                    or tensor.workspace_scope != row.workspace_scope
                    or tensor.branch_scope != row.branch_scope
                    or tensor.permission_scope != row.permission_scope
                ):
                    raise _unavailable()
                reference.verify(tensor.payload)
            result = H14ProjectionFitResult(
                artifact=artifact,
                mean_payload=roles["mean"].payload,
                rotation_payload=roles["rotation"].payload,
                threshold_payload=roles["threshold"].payload,
                residual_payload=roles["residual"].payload,
            )
            from impl.common.l5250_matching.h14_numerics import bind_h14_tensors

            bind_h14_tensors(artifact, result.blobs())
            return result
        except (ValueError, TypeError) as error:
            raise _unavailable() from error

