"""Verify immutable H14 publication without returning tensor payloads."""

from __future__ import annotations
from l1470_matching_contracts.types import MatchSpecRefId

import hashlib
from collections.abc import Mapping, Sequence

from impl.common.l2050_sql_types.sql_branded_types import SqlAliasName, SqlColumnName, SqlTableName
from impl.common.l2070_server_plan.steps.grammar_fetchall import GrammarRowsStep, _GrammarRowsConfig
from impl.common.l2100_sql_grammar.domain.infra.expr_primitives import SqlSha256HexDigest
from impl.common.l2100_sql_grammar.tree.clauses import SqlSelectAlias, SqlSelectList
from impl.common.l2100_sql_grammar.tree.enums import AggregateKind, BinaryOp
from impl.common.l2100_sql_grammar.tree.expr_compound import SqlAggregate, SqlSubquery
from impl.common.l2100_sql_grammar.tree.expr_leaf import SqlColumnRef, SqlParam, SqlStar
from impl.common.l2100_sql_grammar.tree.expr_ops import SqlBinaryOp, sql_and
from impl.common.l2100_sql_grammar.tree.identifiers import SqlTableIdent
from impl.common.l2100_sql_grammar.tree.statements import SqlSelect
from impl.common.l5250_matching.operator_metadata import MatchingProjectionArtifactRow, MatchingProjectionTensorRow
from impl.common.l5250_matching.schema_names import matching_db_column_name
from l1000_schema.schema_def import ApplicationObjectRow
from l1000_schema.table_utils import get_table_name
from l1400_types import DynamicFieldName, ServerPlanRefId
from l2055_lazy_result.purity import pure_lazy
from l1470_matching_contracts.errors import (
    MatchArtifactError,
    MatchErrorContext,
)
from l1470_matching_contracts.types import (
    MatchExpectedValue,
    MatchInvariant,
    MatchObservedValue,
    MatchSafeAction,
)
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompilationContext, CompiledStep, ResolvedRefs
from l2070_batching.sql_renderable import SqlRenderable
from l2070_batching.step import NonPublishingStep, StepExecutionRole


@pure_lazy
def cached_db_column_name(model_cls: type[ApplicationObjectRow], field_name: str) -> SqlColumnName:
    return matching_db_column_name(model_cls, DynamicFieldName(field_name))


@pure_lazy
def _row_predicate(row: MatchingProjectionArtifactRow | MatchingProjectionTensorRow) -> SqlRenderable:
    model = type(row)
    names = set(model.model_fields).difference(ApplicationObjectRow.model_fields) | {"sys_id"}
    predicates: list[SqlRenderable] = []
    for name in sorted(names):
        value = getattr(row, name)
        column = SqlColumnRef(SqlColumnName(cached_db_column_name(model, name)))
        if name == "payload":
            assert isinstance(value, bytes)
            predicates.append(SqlBinaryOp(SqlSha256HexDigest(column), BinaryOp.EQ, SqlParam(hashlib.sha256(value).hexdigest())))
        else:
            predicates.append(SqlBinaryOp(column, BinaryOp.EQ, SqlParam(value)))
    return sql_and(*predicates)


@pure_lazy
def h14_publication_rows_step(
    ref_id: ServerPlanRefId,
    *,
    artifact: MatchingProjectionArtifactRow,
    tensors: Sequence[MatchingProjectionTensorRow],
    after_refs: frozenset[ServerPlanRefId],
) -> GrammarRowsStep[dict[str, object]]:
    """Count rows whose complete immutable fields match the supplied generation."""
    assert len(tensors) == 4
    tensor_predicate = _row_predicate(tensors[0])
    for tensor in tensors[1:]:
        tensor_predicate = SqlBinaryOp(tensor_predicate, BinaryOp.OR, _row_predicate(tensor))
    projections: list[SqlSelectAlias] = []
    for name, model, predicate in (
        ("artifact_count", MatchingProjectionArtifactRow, _row_predicate(artifact)),
        ("tensor_count", MatchingProjectionTensorRow, tensor_predicate),
        (
            "total_tensor_count",
            MatchingProjectionTensorRow,
            SqlBinaryOp(
                SqlColumnRef(SqlColumnName(cached_db_column_name(MatchingProjectionTensorRow, "artifact_id"))),
                BinaryOp.EQ,
                SqlParam(artifact.artifact_id),
            ),
        ),
    ):
        query = SqlSelect(
            select=SqlSelectList([SqlAggregate(AggregateKind.COUNT, SqlStar())]),
            from_=SqlTableIdent(SqlTableName(get_table_name(model))),
            where=predicate,
        )
        projections.append(SqlSelectAlias(SqlSubquery(query), SqlAliasName(name)))
    return GrammarRowsStep(
        ref_id,
        SqlSelect(select=SqlSelectList(projections)),
        config=_GrammarRowsConfig(deps=after_refs, batchable=False),
    )


class VerifyH14PublicationStep(NonPublishingStep[None]):
    """Reject any publication that conflicts with immutable persisted content."""

    def __init__(self: VerifyH14PublicationStep, ref_id: ServerPlanRefId, *, source_ref: ServerPlanRefId) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref

    @property
    def level(self: VerifyH14PublicationStep) -> int:
        return 0

    def result_cardinality(self: VerifyH14PublicationStep) -> Cardinality:
        return Cardinality.SCALAR

    def is_read_only(self: VerifyH14PublicationStep) -> bool:
        return True

    def execution_role(self: VerifyH14PublicationStep) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def runtime_result_is_terminal_scalar(self: VerifyH14PublicationStep) -> bool:
        return True

    def dependencies(self: VerifyH14PublicationStep) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def tables_read(self: VerifyH14PublicationStep) -> frozenset[str]:
        return frozenset()

    def tables_written(self: VerifyH14PublicationStep) -> frozenset[str]:
        return frozenset()

    def compile(self: VerifyH14PublicationStep, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        return CompiledStep()

    def execute_runtime(self: VerifyH14PublicationStep, resolved: ResolvedRefs) -> None:
        rows = resolved.get(str(self._source_ref))
        if isinstance(rows, Sequence) and len(rows) == 1 and isinstance(rows[0], Mapping):
            artifact_count = rows[0].get("artifact_count")
            tensor_count = rows[0].get("tensor_count")
            total_tensor_count = rows[0].get("total_tensor_count")
            if (
                type(artifact_count) is int
                and artifact_count == 1
                and type(tensor_count) is int
                and tensor_count == 4
                and type(total_tensor_count) is int
                and total_tensor_count == 4
            ):
                return
        raise MatchArtifactError(
            MatchErrorContext(
                spec_ref_id=MatchSpecRefId("producer:projection_publication"),
                invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                expected=MatchExpectedValue("immutable_h14_generation"),
                observed=MatchObservedValue("h14_republication_conflict"),
                safe_action=MatchSafeAction.REBUILD_ARTIFACT,
            )
        )

