@pure_lazy
def _one_ref(value: object, operation: str) -> ServerPlanRefId:
    refs = tuple(collect_plan_ref_dependencies(value))
    if len(refs) != 1:
        raise TypeError(f"{operation} requires one plan-backed source")
    return ServerPlanRefId(refs[0])


@dataclass(frozen=True, slots=True)
class _QuantizedStorageAuthority:
    """Bind private storage reads to permission-filtered endpoint relations."""

    left_source_ref: ServerPlanRefId
    right_source_ref: ServerPlanRefId


@pure_lazy
def _execute_quantized_storage_query[RowT: DatabaseObjectRow[SysId]](
    query: ReadQueryBuilder[RowT],
    model_cls: type[RowT],
    authority: _QuantizedStorageAuthority,
) -> LazyResult[Sequence[dict[str, SqlCell]]]:
    from impl.common.l2070_server_plan.steps.query_execute_raw import (
        QueryExecuteRawStep,
        _QueryExecuteRawStepConfig,
    )
    from l2060_query_builder.plan_query_builder import ReadQueryBuilder

    if not isinstance(query, ReadQueryBuilder):
        raise TypeError("quantized storage query requires a plan-backed query builder")
    if model_cls not in QUANTIZED_PROJECTION_TABLES:
        raise TypeError("quantized storage query requires a quantized physical model")
    source_dependencies = (
        authority.left_source_ref,
        authority.right_source_ref,
    )
    base_spec = query.to_query_spec()
    query_spec = replace(
        base_spec,
        permission_grammar=None,
        permission_context_ref=None,
        permission_context_type=None,
        permission_state=QueryPermissionState.PROVIDER_AUTHORITY_RESOLVED,
        permission_user_id_unresolved=False,
        server_ref_dependencies=tuple(
            dict.fromkeys((*base_spec.server_ref_dependencies, *source_dependencies)),
        ),
    )
    step: QueryExecuteRawStep[dict[str, SqlCell]] = QueryExecuteRawStep(
        ServerPlanRefId(query._plan._next_ref()),
        model_cls,
        _QueryExecuteRawStepConfig(query_spec=query_spec),
    )
    return query._publish_query_step_lazy(step)


def _row_value(row: object, name: str) -> object:
    if isinstance(row, Mapping):
        return row.get(name)
    return getattr(row, name, None)


def _pair_filter_allows(spec: MatchSpec[Any, Any], left: object, right: object) -> bool:
    pair_filter = spec.filters.pair
    if isinstance(pair_filter, NoMatchFilter):
        return True
    if not isinstance(pair_filter, MatchPairFieldComparisonSpec):
        raise TypeError("quantized matching received an unknown pair filter")
    left_value = _row_value(left, str(pair_filter.left_field_name))
    right_value = _row_value(right, str(pair_filter.right_field_name))
    if left_value is None or right_value is None:
        return False
    left_comparable: Any = left_value
    right_comparable: Any = right_value
    operator = pair_filter.operator
    if operator is MatchPairComparisonOperator.EQUAL:
        return bool(left_comparable == right_comparable)
    if operator is MatchPairComparisonOperator.NOT_EQUAL:
        return bool(left_comparable != right_comparable)
    if operator is MatchPairComparisonOperator.LESS_THAN:
        return bool(left_comparable < right_comparable)
    if operator is MatchPairComparisonOperator.LESS_THAN_OR_EQUAL:
        return bool(left_comparable <= right_comparable)
    if operator is MatchPairComparisonOperator.GREATER_THAN:
        return bool(left_comparable > right_comparable)
    if operator is MatchPairComparisonOperator.GREATER_THAN_OR_EQUAL:
        return bool(left_comparable >= right_comparable)
    raise TypeError(f"Unknown pair comparison operator: {operator}")


def _projection_state(artifact_rows: list[object], tensor_rows: list[object]) -> QjlProjectionState | TurboQuantProjectionState:
    if not artifact_rows:
        raise DbPermissionError("quantized matching private storage is unavailable to this session")
    if len(artifact_rows) != 1:
        raise ValueError("quantized matching requires exactly one artifact generation")
    artifact_row = _hydrate_quantized_storage_row(
        QuantizedProjectionArtifactRow,
        artifact_rows[0],
    )
    typed_tensors = tuple(_hydrate_quantized_storage_row(QuantizedProjectionTensorRow, row) for row in tensor_rows)
    tensors = {row.role: row for row in typed_tensors}
    if artifact_row.family == "qjl":
        from l1470_matching_contracts.projection_models import QjlProjectionArtifact

        projection = tensors.get("projection")
        if projection is None:
            raise ValueError("QJL matching projection tensor is missing")
        return QjlProjectionState(
            artifact=QjlProjectionArtifact.model_validate_json(artifact_row.contract_payload),
            projection_payload=projection.payload,
        )
    from l1470_matching_contracts.projection_models import TurboQuantInnerProductArtifact

    rotation = tensors.get("rotation")
    residual = tensors.get("residual")
    if rotation is None or residual is None:
        raise ValueError("TurboQuant matching projection tensors are incomplete")
    return TurboQuantProjectionState(
        artifact=TurboQuantInnerProductArtifact.model_validate_json(artifact_row.contract_payload),
        rotation_payload=rotation.payload,
        residual_payload=residual.payload,
    )


def _query_request(vector: Sequence[object], state: QjlProjectionState | TurboQuantProjectionState) -> tuple[str, bytes]:
    import numpy as np
    from impl.common.l5250_matching.quantized_numerics import prepare_qjl_query, prepare_turboquant_query

    coordinate_values: list[float] = []
    for value in vector:
        if isinstance(value, bool) or not isinstance(value, int | float):
            raise TypeError("quantized matching query coordinates must be numeric")
        coordinate_values.append(float(value))
    coordinates = np.asarray(tuple(coordinate_values), dtype=np.float32)
    if isinstance(state, QjlProjectionState):
        qjl_prepared = prepare_qjl_query(coordinates, state)
        spec = json.dumps(
            {
                "family": "qjl",
                "projection_dimensions": int(state.artifact.projection_dimensions),
            },
            sort_keys=True,
            separators=(",", ":"),
        )
        return spec, struct.pack(
            f"<{len(qjl_prepared.projected_query)}f",
            *qjl_prepared.projected_query,
        )
    turbo_prepared = prepare_turboquant_query(coordinates, state)
    spec = json.dumps(
        {
            "family": "turboquant_inner_product",
            "source_dimensions": int(state.artifact.source_dimensions),
            "mse_bit_width": int(state.artifact.mse_bit_width),
            "residual_dimensions": int(state.artifact.residual_dimensions),
            "centroids": state.artifact.codebook.centroids,
        },
        sort_keys=True,
        separators=(",", ":"),
    )
    values = (*turbo_prepared.rotated_query, *turbo_prepared.projected_query)
    return spec, struct.pack(f"<{len(values)}f", *values)


def _code_request(base_spec: str, row: QuantizedCodeRow) -> tuple[str, bytes]:
    values = json.loads(base_spec)
    if not isinstance(values, dict):
        raise TypeError("quantized native request must be one object")
    if row.vector_norm is None:
        raise ValueError("quantized estimator code has no source norm")
    values["vector_norm"] = row.vector_norm
    if row.family == "qjl":
        QjlCodePayload(
            projection_artifact_id=row.artifact_id,
            packed_signs=row.packed_primary,
            vector_norm=QuantizedVectorNorm(row.vector_norm),
        )
        return json.dumps(values, sort_keys=True, separators=(",", ":")), row.packed_primary
    if row.packed_residual is None or row.residual_norm is None:
        raise ValueError("TurboQuant matching code is incomplete")
    TurboQuantInnerProductCodePayload(
        projection_artifact_id=row.artifact_id,
        packed_mse_indices=row.packed_primary,
        packed_residual_signs=row.packed_residual,
        vector_norm=QuantizedVectorNorm(row.vector_norm),
        residual_norm=QuantizedResidualNorm(row.residual_norm),
    )
    values["residual_norm"] = row.residual_norm
    return (
        json.dumps(values, sort_keys=True, separators=(",", ":")),
        row.packed_primary + row.packed_residual,
    )


def _fp32_payload(value: object, dimensions: int) -> bytes:
    if not isinstance(value, Sequence) or isinstance(value, str | bytes | bytearray) or len(value) != dimensions:
        raise TypeError("quantized exact-rerank vector is invalid")
    coordinates: list[float] = []
    for coordinate in value:
        if isinstance(coordinate, bool) or not isinstance(coordinate, int | float):
            raise TypeError("quantized exact-rerank coordinates must be numeric")
        coordinates.append(float(coordinate))
    return struct.pack(f"<{dimensions}f", *coordinates)


def _native_score_rows(value: object) -> list[tuple[str, int, float]]:
    if not isinstance(value, Sequence) or isinstance(value, str | bytes | bytearray):
        raise TypeError("native score batch returned an invalid relation")
    scores: list[tuple[str, int, float]] = []
    for row in value:
        if isinstance(row, Mapping):
            raw_identity = row.get("query_identity")
            raw_key = row.get("native_key")
            raw_score = row.get("score")
        elif isinstance(row, Sequence) and not isinstance(row, str | bytes | bytearray) and len(row) == 3:
            raw_identity, raw_key, raw_score = row
        else:
            raise TypeError("native score batch returned an invalid row")
        if (
            not isinstance(raw_identity, str)
            or isinstance(raw_key, bool)
            or not isinstance(raw_key, int)
            or isinstance(raw_score, bool)
            or not isinstance(raw_score, int | float)
        ):
            raise TypeError("native score batch returned invalid values")
        scores.append((raw_identity, raw_key, float(raw_score)))
    return scores


@dataclass(frozen=True, slots=True)
class _PreparedQuantizedBatch:
    state: QjlProjectionState | TurboQuantProjectionState | None
    rights: tuple[tuple[str, int, QuantizedCodeRow], ...]
    queries: tuple[tuple[str, str, bytes], ...]
    requests: tuple[tuple[str, bytes, bytes], ...]
    score_identities: tuple[tuple[str, int], ...]


@dataclass(frozen=True, slots=True)
class _QuantizedRefs:
    left: ServerPlanRefId
    right: ServerPlanRefId
    artifacts: ServerPlanRefId
    tensors: ServerPlanRefId
    codes: ServerPlanRefId
    guard: ServerPlanRefId


class _QuantizedMatchingSpoolStep(_CrossBranchUSearchNativeSpoolStep):
    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        refs: _QuantizedRefs,
        query_field_name: str,
        sqlite_native: bool,
        spec: MatchSpec[Any, Any],
    ) -> None:
        super().__init__(
            ref_id,
            artifact_ref_id=refs.artifacts,
            eligibility_ref_id=refs.codes,
            query_vector=_CrossBranchUSearchQueryVector(coordinates=(0.0,), metric="ip"),
            limits=get_usearch_request_limits(),
            identity_scope=_NativeIdentityScope.UNVERSIONED,
        )
        self._refs = refs
        self._query_field_name = query_field_name
        self._sqlite_native = sqlite_native
        self._spec = spec

    def dependencies(self) -> frozenset[str]:
        return frozenset(
            {
                str(self._refs.left),
                str(self._refs.right),
                str(self._refs.artifacts),
                str(self._refs.tensors),
                str(self._refs.codes),
                str(self._refs.guard),
            },
        )

    def _prepare_batch(self, resolved: ResolvedRefs) -> _PreparedQuantizedBatch:
        artifact_rows = resolved.require(self._refs.artifacts, list, site="quantized matching artifacts")
        tensor_rows = resolved.require(self._refs.tensors, list, site="quantized matching tensors")
        code_rows = resolved.require(self._refs.codes, list, site="quantized matching codes")
        left_rows = resolved.require(self._refs.left, list, site="quantized matching left rows")
        right_rows = resolved.require(self._refs.right, list, site="quantized matching right rows")
        representation = self._spec.right.representation
        if not isinstance(representation, MatchQuantizedCodeRepresentationSpec):
            raise TypeError("quantized matching requires a quantized right representation")
        if not left_rows or not right_rows:
            return _PreparedQuantizedBatch(
                state=None,
                rights=(),
                queries=(),
                requests=(),
                score_identities=(),
            )
        if not artifact_rows:
            raise MatchArtifactError(
                MatchErrorContext(
                    spec_ref_id=self._spec.spec_ref_id,
                    invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                    expected=MatchExpectedValue("declared_artifact"),
                    observed=MatchObservedValue("missing"),
                    safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                ),
            )
        artifact_row = _hydrate_quantized_storage_row(
            QuantizedProjectionArtifactRow,
            artifact_rows[0],
        )
        if artifact_row.family != representation.family.value:
            raise MatchArtifactError(
                MatchErrorContext(
                    spec_ref_id=self._spec.spec_ref_id,
                    invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                    expected=MatchExpectedValue(representation.family.value),
                    observed=MatchObservedValue(artifact_row.family),
                    safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                ),
            )
        try:
            state = _projection_state(artifact_rows, tensor_rows)
        except (TypeError, ValueError) as error:
            raise MatchArtifactError(
                MatchErrorContext(
                    spec_ref_id=self._spec.spec_ref_id,
                    invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                    expected=MatchExpectedValue("valid_projection_state"),
                    observed=MatchObservedValue("invalid_projection_state"),
                    safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                ),
            ) from error
        declared_dimensions = int(representation.source_dimensions)
        artifact_dimensions = int(state.artifact.source_dimensions)
        if declared_dimensions != artifact_dimensions:
            raise MatchCompatibilityError(
                MatchErrorContext(
                    spec_ref_id=self._spec.spec_ref_id,
                    invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                    expected=MatchExpectedValue(f"dimensions_{declared_dimensions}"),
                    observed=MatchObservedValue(f"dimensions_{artifact_dimensions}"),
                    safe_action=MatchSafeAction.FIX_DECLARATION,
                ),
            )
        left_representation = self._spec.left.representation
        if not isinstance(left_representation, MatchDenseVectorFieldRepresentationSpec):
            raise TypeError("quantized matching requires a dense-vector left representation")
        query_dimensions = int(left_representation.dimensions)
        if query_dimensions != artifact_dimensions:
            raise MatchCompatibilityError(
                MatchErrorContext(
                    spec_ref_id=self._spec.spec_ref_id,
                    invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                    expected=MatchExpectedValue(f"dimensions_{artifact_dimensions}"),
                    observed=MatchObservedValue(f"dimensions_{query_dimensions}"),
                    safe_action=MatchSafeAction.FIX_DECLARATION,
                ),
            )
        typed_codes = tuple(_hydrate_quantized_storage_row(QuantizedCodeRow, row) for row in code_rows)
        mismatched_code = next(
            (code for code in typed_codes if code.family != representation.family.value),
            None,
        )
        if mismatched_code is not None:
            raise MatchArtifactError(
                MatchErrorContext(
                    spec_ref_id=self._spec.spec_ref_id,
                    invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                    expected=MatchExpectedValue(representation.family.value),
                    observed=MatchObservedValue(mismatched_code.family),
                    safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                ),
            )
        if isinstance(state, QjlProjectionState):
            expected_code_bytes = (int(state.artifact.projection_dimensions) + 7) // 8
            malformed_code = next(
                (code for code in typed_codes if len(code.packed_primary) != expected_code_bytes),
                None,
            )
            if malformed_code is not None:
                raise MatchArtifactError(
                    MatchErrorContext(
                        spec_ref_id=self._spec.spec_ref_id,
                        invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                        expected=MatchExpectedValue(f"bytes_{expected_code_bytes}"),
                        observed=MatchObservedValue(f"bytes_{len(malformed_code.packed_primary)}"),
                        safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                    ),
                )
        else:
            expected_primary_bytes = (int(state.artifact.source_dimensions) * int(state.artifact.mse_bit_width) + 7) // 8
            expected_residual_bytes = (int(state.artifact.residual_dimensions) + 7) // 8
            malformed_code = next(
                (
                    code
                    for code in typed_codes
                    if len(code.packed_primary) != expected_primary_bytes
                    or code.packed_residual is None
                    or len(code.packed_residual) != expected_residual_bytes
                ),
                None,
            )
            if malformed_code is not None:
                observed_residual_bytes = 0 if malformed_code.packed_residual is None else len(malformed_code.packed_residual)
                raise MatchArtifactError(
                    MatchErrorContext(
                        spec_ref_id=self._spec.spec_ref_id,
                        invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                        expected=MatchExpectedValue(
                            f"bytes_{expected_primary_bytes}_{expected_residual_bytes}",
                        ),
                        observed=MatchObservedValue(
                            f"bytes_{len(malformed_code.packed_primary)}_{observed_residual_bytes}",
                        ),
                        safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                    ),
                )
        codes = {str(row.source_identity): row for row in typed_codes}
        require_current = isinstance(self._spec.policies.freshness, RequireCurrentFreshnessPolicy)
        declared_watermark = int(representation.source_watermark)
        rights: list[tuple[str, int, QuantizedCodeRow]] = []
        for key, row in enumerate(right_rows, start=1):
            visible_watermark = _row_value(row, str(representation.source_watermark_field_name))
            if isinstance(visible_watermark, bool) or not isinstance(visible_watermark, int):
                raise TypeError("quantized endpoint source watermark must be an integer")
            if require_current and visible_watermark != declared_watermark:
                raise MatchFreshnessError(
                    MatchErrorContext(
                        spec_ref_id=self._spec.spec_ref_id,
                        invariant=MatchInvariant.ARTIFACT_STALE,
                        expected=MatchExpectedValue(f"watermark_{declared_watermark}"),
                        observed=MatchObservedValue(f"watermark_{visible_watermark}"),
                        safe_action=MatchSafeAction.WAIT_FOR_FRESHNESS,
                    ),
                )
            identity = str(_row_value(row, "sys_id"))
            code = codes.get(identity)
            if code is None:
                raise MatchMissingRepresentationError(
                    MatchErrorContext(
                        spec_ref_id=self._spec.spec_ref_id,
                        invariant=MatchInvariant.MISSING_REPRESENTATION,
                        expected=MatchExpectedValue("quantized_code"),
                        observed=MatchObservedValue("missing"),
                        safe_action=MatchSafeAction.FIX_SOURCE_DATA,
                    ),
                )
            rights.append((identity, key, code))
        queries: list[tuple[str, str, bytes]] = []
        for row in left_rows:
            identity = str(_row_value(row, "sys_id"))
            vector = _row_value(row, self._query_field_name)
            if not isinstance(vector, Sequence) or isinstance(vector, str | bytes | bytearray):
                raise TypeError("quantized matching query vector is invalid")
            expected_dimensions = int(state.artifact.source_dimensions)
            if len(vector) != expected_dimensions:
                raise MatchCompatibilityError(
                    MatchErrorContext(
                        spec_ref_id=self._spec.spec_ref_id,
                        invariant=MatchInvariant.NON_FINITE_REPRESENTATION,
                        expected=MatchExpectedValue(f"dimensions_{expected_dimensions}"),
                        observed=MatchObservedValue(f"dimensions_{len(vector)}"),
                        safe_action=MatchSafeAction.FIX_SOURCE_DATA,
                    ),
                )
            try:
                request_spec, payload = _query_request(vector, state)
            except (TypeError, ValueError) as error:
                raise MatchCompatibilityError(
                    MatchErrorContext(
                        spec_ref_id=self._spec.spec_ref_id,
                        invariant=MatchInvariant.NON_FINITE_REPRESENTATION,
                        expected=MatchExpectedValue("valid_query_vector"),
                        observed=MatchObservedValue("invalid_query_vector"),
                        safe_action=MatchSafeAction.FIX_SOURCE_DATA,
                    ),
                ) from error
            queries.append((identity, request_spec, payload))
        native_requests: list[tuple[str, bytes, bytes]] = []
        score_identities: list[tuple[str, int]] = []
        for query_identity, base_spec, query_payload in queries:
            for _identity, native_key, code in rights:
                try:
                    request_spec, packed = _code_request(base_spec, code)
                except (TypeError, ValueError) as error:
                    raise MatchArtifactError(
                        MatchErrorContext(
                            spec_ref_id=self._spec.spec_ref_id,
                            invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
                            expected=MatchExpectedValue("valid_quantized_code"),
                            observed=MatchObservedValue("invalid_quantized_code"),
                            safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                        ),
                    ) from error
                native_requests.append((request_spec, query_payload, packed))
                score_identities.append((query_identity, native_key))
        return _PreparedQuantizedBatch(
            state=state,
            rights=tuple(rights),
            queries=tuple(queries),
            requests=tuple(native_requests),
            score_identities=tuple(score_identities),
        )

    def _statements(
        self,
        resolved: ResolvedRefs,
        *,
        sql_conn: Any | None,
        use_sqlite_native: bool,
        prepared_scores: tuple[tuple[tuple[str, int], ...], Sequence[float]] | None = None,
    ) -> tuple[list[SqlRenderable], _CrossBranchUSearchExecutionReceipt]:
        batch = self._prepare_batch(resolved)
        state = batch.state
        rights = batch.rights
        queries = batch.queries
        statements: list[SqlRenderable] = [
            SqlDelete(
                SqlTableIdent(self._spool_table),
                where=SqlWhereClause(
                    SqlBinaryOp(SqlColumnRef(SqlColumnName("scope_id")), BinaryOp.EQ, SqlParam(self._scope_id)),
                ),
            ),
            SqlDelete(
                SqlTableIdent(self._eligibility_spool_table),
                where=SqlWhereClause(
                    SqlBinaryOp(SqlColumnRef(SqlColumnName("scope_id")), BinaryOp.EQ, SqlParam(self._scope_id)),
                ),
            ),
        ]
        if state is None:
            representation = self._spec.right.representation
            assert isinstance(representation, MatchQuantizedCodeRepresentationSpec)
            return statements, _CrossBranchUSearchExecutionReceipt(
                artifact_id=SysId(uuid5(NAMESPACE_URL, str(representation.projection_artifact_id))),
                artifact_epoch=USearchArtifactEpoch(1),
                artifact_format=f"quantized/{representation.family.value}",
                visible_identity_count=0,
                eligible_native_key_count=0,
                requested_candidate_count=0,
                examined_member_count=0,
                computed_distance_count=0,
                returned_native_hit_count=0,
                score_count=0,
            )
        eligibility_rows = tuple(
            (self._scope_id, query_identity, identity, None, None, key, None, None)
            for query_identity, _spec, _payload in queries
            for identity, key, _code in rights
        )
        if eligibility_rows:
            statements.append(
                SqlInsert(
                    SqlTableIdent(self._eligibility_spool_table),
                    columns=SqlColumnList(
                        [
                            SqlColumnName("scope_id"),
                            SqlColumnName("query_identity"),
                            SqlColumnName("object_id"),
                            SqlColumnName("branch_id"),
                            SqlColumnName("revision_id"),
                            SqlColumnName("native_key"),
                            SqlColumnName("chunk_id"),
                            SqlColumnName("chunk_metadata"),
                        ],
                    ),
                    values=SqlValuesClause(
                        [SqlValuesRow([SqlParam(value) for value in row]) for row in eligibility_rows],
                    ),
                ),
            )
        score_rows: list[tuple[object, ...]] = []
        artifact_sys_id = SysId(uuid5(NAMESPACE_URL, str(state.artifact.artifact_id)))
        native_requests = batch.requests
        score_identities = batch.score_identities
        native_scores: Sequence[float]
        if prepared_scores is not None:
            score_identities, native_scores = prepared_scores
        elif use_sqlite_native and native_requests:
            if sql_conn is None:
                raise RuntimeError("SQLite quantized scoring requires its owning SQL connection")
            batch_rows = tuple(
                (query_identity, native_key, spec, query, code)
                for (query_identity, native_key), (spec, query, code) in zip(
                    score_identities,
                    native_requests,
                    strict=True,
                )
            )
            with allow_direct_sql_in_step_execution():
                raw_scores = sql_conn._execute_direct_internal(
                    SqliteQuantizedBatchScoreSelect(batch_rows),
                    fetch_mode="all",
                )
            if not isinstance(raw_scores, Sequence) or isinstance(raw_scores, str | bytes | bytearray):
                raise TypeError("SQLite quantized batch returned an invalid score relation")
            sqlite_native_scores: list[float] = []
            returned_identities: list[tuple[str, int]] = []
            for row in raw_scores:
                if isinstance(row, Mapping):
                    raw_score = row.get("score")
                    raw_key = row.get("native_key")
                    raw_identity = row.get("query_identity")
                elif isinstance(row, Sequence) and not isinstance(row, str | bytes | bytearray) and len(row) == 3:
                    raw_identity, raw_key, raw_score = row
                else:
                    raise TypeError("SQLite quantized batch returned an invalid score row")
                if (
                    isinstance(raw_score, bool)
                    or not isinstance(raw_score, int | float)
                    or isinstance(raw_key, bool)
                    or not isinstance(raw_key, int)
                    or not isinstance(raw_identity, str)
                ):
                    raise TypeError("SQLite quantized batch returned invalid score values")
                sqlite_native_scores.append(float(raw_score))
                returned_identities.append((raw_identity, raw_key))
            native_scores = sqlite_native_scores
            score_identities = tuple(returned_identities)
        else:
            from nera_usearch_native._native import score_quantized_batch

            native_scores = score_quantized_batch(list(native_requests))
        if len(native_scores) != len(score_identities):
            raise ValueError("quantized native batch returned an incomplete score relation")
        for (query_identity, native_key), score in zip(score_identities, native_scores, strict=True):
            score_rows.append(
                (
                    self._scope_id,
                    query_identity,
                    artifact_sys_id,
                    1,
                    native_key,
                    -score,
                    "negative_inner_product",
                ),
            )
        if score_rows:
            statements.append(
                SqlInsert(
                    SqlTableIdent(self._spool_table),
                    columns=SqlColumnList(
                        [
                            SqlColumnName("scope_id"),
                            SqlColumnName("query_identity"),
                            SqlColumnName("artifact_id"),
                            SqlColumnName("artifact_epoch"),
                            SqlColumnName("native_key"),
                            SqlColumnName("distance"),
                            SqlColumnName("distance_kind"),
                        ],
                    ),
                    values=SqlValuesClause(
                        [SqlValuesRow([SqlParam(value) for value in row]) for row in score_rows],
                    ),
                ),
            )
        score_count = len(score_rows)
        return statements, _CrossBranchUSearchExecutionReceipt(
            artifact_id=artifact_sys_id,
            artifact_epoch=USearchArtifactEpoch(1),
            artifact_format=f"quantized/{state.artifact.algorithm_version}",
            visible_identity_count=len(rights),
            eligible_native_key_count=len(rights),
            requested_candidate_count=len(rights),
            examined_member_count=score_count,
            computed_distance_count=score_count,
            returned_native_hit_count=score_count,
            score_count=score_count,
        )

    def _eligible_rerank_candidate_rows(
        self,
        resolved: ResolvedRefs,
        raw_candidates: Sequence[object],
    ) -> tuple[tuple[str, int, float, str, str, str, str], ...]:
        from impl.common.l5250_matching.native_result_support import _canonical_endpoint_identity

        left_rows = resolved.require(self._refs.left, list, site="quantized rerank left rows")
        right_rows = resolved.require(self._refs.right, list, site="quantized rerank right rows")
        left_by_id = {str(_row_value(row, "sys_id")): row for row in left_rows}
        right_by_key = {key: row for key, row in enumerate(right_rows, start=1)}
        excludes_self = self._spec.policies.self_edges.value == "exclude" and get_table_name(self._spec.left.row_type) == get_table_name(
            self._spec.right.row_type
        )
        eligible: list[tuple[str, int, float, str, str, str, str]] = []
        for row in raw_candidates:
            if isinstance(row, Mapping):
                raw_identity = row.get("query_identity")
                raw_key = row.get("native_key")
                raw_distance = row.get("distance")
            elif isinstance(row, Sequence) and not isinstance(row, str | bytes | bytearray) and len(row) == 3:
                raw_identity, raw_key, raw_distance = row
            else:
                raise TypeError("quantized candidate selection returned an invalid row")
            if (
                not isinstance(raw_identity, str)
                or isinstance(raw_key, bool)
                or not isinstance(raw_key, int)
                or isinstance(raw_distance, bool)
                or not isinstance(raw_distance, int | float)
                or not isfinite(float(raw_distance))
            ):
                raise TypeError("quantized candidate selection returned invalid values")
            left = left_by_id.get(raw_identity)
            right = right_by_key.get(raw_key)
            if left is None or right is None:
                raise ValueError("quantized candidate identity is not visible in the endpoint snapshot")
            left_identity = _canonical_endpoint_identity(self._spec.left, left)
            right_identity = _canonical_endpoint_identity(self._spec.right, right)
            if excludes_self and left_identity == right_identity:
                continue
            if not _pair_filter_allows(self._spec, left, right):
                continue
            eligible.append(
                (
                    raw_identity,
                    raw_key,
                    float(raw_distance),
                    left_identity,
                    right_identity,
                    str(_row_value(left, "sys_id")),
                    str(_row_value(right, "sys_id")),
                ),
            )
        return tuple(eligible)

    def _duplicate_score_mode(self) -> QuantizedDuplicateScoreMode:
        duplicate_policy = self._spec.policies.duplicates
        if isinstance(duplicate_policy, CombineDuplicatePairsPolicy):
            if duplicate_policy.score_combination is MatchDuplicateScoreCombination.SUM:
                return QuantizedDuplicateScoreMode.SUM
            return QuantizedDuplicateScoreMode.MAX
        return QuantizedDuplicateScoreMode.SELECT_REPRESENTATIVE

    @staticmethod
    def _validated_candidate_pairs(candidate_pairs: Sequence[object]) -> tuple[tuple[str, int], ...]:
        validated: list[tuple[str, int]] = []
        for candidate_pair in candidate_pairs:
            if not isinstance(candidate_pair, Sequence) or isinstance(candidate_pair, str | bytes | bytearray):
                raise TypeError("quantized eligible candidate selection returned an invalid row")
            query_identity, native_key = candidate_pair
            if not isinstance(query_identity, str) or isinstance(native_key, bool) or not isinstance(native_key, int):
                raise TypeError("quantized eligible candidate selection returned invalid values")
            validated.append((query_identity, native_key))
        return tuple(validated)

    def _rerank_sync(self, resolved: ResolvedRefs, sql_conn: Any) -> None:
        kernel = self._spec.kernel
        right_representation = self._spec.right.representation
        if not isinstance(kernel, MatchQuantizedInnerProductKernelSpec) or not isinstance(kernel.rerank_candidate_count, NeighborCount):
            return
        if not isinstance(right_representation, MatchQuantizedCodeRepresentationSpec) or not isinstance(
            right_representation.exact_vector_field_name, MatchFieldName
        ):
            raise ValueError("quantized rerank requires the declared exact source-vector field")
        right_rows = resolved.require(self._refs.right, list, site="quantized rerank right rows")
        with allow_direct_sql_in_step_execution():
            raw_candidates = sql_conn._execute_direct_internal(
                SqlQuantizedCandidateSelect(
                    score_table=SqlTableIdent(self._spool_table),
                    scope_id=self._scope_id,
                    candidate_count=len(right_rows),
                ),
                fetch_mode="all",
            )
        if not isinstance(raw_candidates, Sequence) or isinstance(raw_candidates, str | bytes | bytearray):
            raise TypeError("quantized candidate selection returned an invalid relation")
        eligible_rows = self._eligible_rerank_candidate_rows(resolved, raw_candidates)
        with allow_direct_sql_in_step_execution():
            candidate_pairs = sql_conn._execute_direct_internal(
                SqlQuantizedEligibleCandidateSelect(
                    rows=eligible_rows,
                    candidate_count=int(kernel.rerank_candidate_count),
                    duplicate_score_mode=self._duplicate_score_mode(),
                ),
                fetch_mode="all",
            )
        if not isinstance(candidate_pairs, Sequence) or isinstance(candidate_pairs, str | bytes | bytearray):
            raise TypeError("quantized eligible candidate selection returned an invalid relation")
        left_rows = resolved.require(self._refs.left, list, site="quantized rerank left rows")
        left_by_id = {str(_row_value(row, "sys_id")): row for row in left_rows}
        right_by_key = {key: row for key, row in enumerate(right_rows, start=1)}
        dimensions = int(right_representation.source_dimensions)
        exact_spec = json.dumps(
            {"dimensions": dimensions, "encoding": "fp32", "metric": "inner_product"},
            sort_keys=True,
            separators=(",", ":"),
        )
        requests: list[tuple[str, int, str, bytes, bytes]] = []
        for query_identity, native_key in self._validated_candidate_pairs(candidate_pairs):
            left = left_by_id.get(query_identity)
            right = right_by_key.get(native_key)
            if left is None or right is None:
                raise ValueError("quantized candidate identity is not visible in the endpoint snapshot")
            requests.append(
                (
                    query_identity,
                    native_key,
                    exact_spec,
                    _fp32_payload(_row_value(left, self._query_field_name), dimensions),
                    _fp32_payload(
                        _row_value(right, str(right_representation.exact_vector_field_name)),
                        dimensions,
                    ),
                ),
            )
        if self._sqlite_native:
            with allow_direct_sql_in_step_execution():
                exact_scores = _native_score_rows(
                    sql_conn._execute_direct_internal(
                        SqliteDenseBatchScoreSelect(tuple(requests)),
                        fetch_mode="all",
                    ),
                )
        else:
            from nera_usearch_native._native import score_encoded

            exact_scores = [
                (query_identity, native_key, score_encoded(spec, left, right))
                for query_identity, native_key, spec, left, right in requests
            ]
        artifact_id = SysId(uuid5(NAMESPACE_URL, str(right_representation.projection_artifact_id)))
        replacement_rows = tuple(
            (
                self._scope_id,
                query_identity,
                artifact_id,
                1,
                native_key,
                -score,
                "negative_inner_product",
            )
            for query_identity, native_key, score in exact_scores
        )
        statements: list[SqlRenderable] = [
            SqlDelete(
                SqlTableIdent(self._spool_table),
                where=SqlWhereClause(
                    SqlBinaryOp(SqlColumnRef(SqlColumnName("scope_id")), BinaryOp.EQ, SqlParam(self._scope_id)),
                ),
            ),
        ]
        if replacement_rows:
            statements.append(
                SqlInsert(
                    SqlTableIdent(self._spool_table),
                    columns=SqlColumnList(
                        [
                            SqlColumnName("scope_id"),
                            SqlColumnName("query_identity"),
                            SqlColumnName("artifact_id"),
                            SqlColumnName("artifact_epoch"),
                            SqlColumnName("native_key"),
                            SqlColumnName("distance"),
                            SqlColumnName("distance_kind"),
                        ],
                    ),
                    values=SqlValuesClause(
                        [SqlValuesRow([SqlParam(value) for value in row]) for row in replacement_rows],
                    ),
                ),
            )
        for statement in statements:
            with allow_direct_sql_in_step_execution():
                sql_conn._execute_direct_internal(statement)

    async def _rerank_async(self, resolved: ResolvedRefs, sql_conn: Any) -> None:
        kernel = self._spec.kernel
        right_representation = self._spec.right.representation
        if not isinstance(kernel, MatchQuantizedInnerProductKernelSpec) or not isinstance(kernel.rerank_candidate_count, NeighborCount):
            return
        if not isinstance(right_representation, MatchQuantizedCodeRepresentationSpec) or not isinstance(
            right_representation.exact_vector_field_name, MatchFieldName
        ):
            raise ValueError("quantized rerank requires the declared exact source-vector field")
        right_rows = resolved.require(self._refs.right, list, site="quantized rerank right rows")
        with allow_direct_sql_in_step_execution():
            raw_candidates = await sql_conn._execute_direct_internal_async(
                SqlQuantizedCandidateSelect(
                    score_table=SqlTableIdent(self._spool_table),
                    scope_id=self._scope_id,
                    candidate_count=len(right_rows),
                ),
                fetch_mode="all",
            )
        if not isinstance(raw_candidates, Sequence) or isinstance(raw_candidates, str | bytes | bytearray):
            raise TypeError("quantized candidate selection returned an invalid relation")
        eligible_rows = self._eligible_rerank_candidate_rows(resolved, raw_candidates)
        with allow_direct_sql_in_step_execution():
            candidate_pairs = await sql_conn._execute_direct_internal_async(
                SqlQuantizedEligibleCandidateSelect(
                    rows=eligible_rows,
                    candidate_count=int(kernel.rerank_candidate_count),
                    duplicate_score_mode=self._duplicate_score_mode(),
                ),
                fetch_mode="all",
            )
        if not isinstance(candidate_pairs, Sequence) or isinstance(candidate_pairs, str | bytes | bytearray):
            raise TypeError("quantized eligible candidate selection returned an invalid relation")
        left_rows = resolved.require(self._refs.left, list, site="quantized rerank left rows")
        left_by_id = {str(_row_value(row, "sys_id")): row for row in left_rows}
        right_by_key = {key: row for key, row in enumerate(right_rows, start=1)}
        dimensions = int(right_representation.source_dimensions)
        exact_spec = json.dumps(
            {"dimensions": dimensions, "encoding": "fp32", "metric": "inner_product"},
            sort_keys=True,
            separators=(",", ":"),
        )
        requests: list[tuple[str, int, str, bytes, bytes]] = []
        for query_identity, native_key in self._validated_candidate_pairs(candidate_pairs):
            left = left_by_id.get(query_identity)
            right = right_by_key.get(native_key)
            if left is None or right is None:
                raise ValueError("quantized candidate identity is not visible in the endpoint snapshot")
            requests.append(
                (
                    query_identity,
                    native_key,
                    exact_spec,
                    _fp32_payload(_row_value(left, self._query_field_name), dimensions),
                    _fp32_payload(
                        _row_value(right, str(right_representation.exact_vector_field_name)),
                        dimensions,
                    ),
                ),
            )
        if self._sqlite_native:
            with allow_direct_sql_in_step_execution():
                exact_scores = _native_score_rows(
                    await sql_conn._execute_direct_internal_async(
                        SqliteDenseBatchScoreSelect(tuple(requests)),
                        fetch_mode="all",
                    ),
                )
        else:
            from nera_usearch_native._native import score_encoded_batch_async

            scores = await score_encoded_batch_async(
                [(spec, left, right) for _identity, _key, spec, left, right in requests],
            )
            exact_scores = [
                (query_identity, native_key, score)
                for (query_identity, native_key, _spec, _left, _right), score in zip(
                    requests,
                    scores,
                    strict=True,
                )
            ]
        artifact_id = SysId(uuid5(NAMESPACE_URL, str(right_representation.projection_artifact_id)))
        replacement_rows = tuple(
            (
                self._scope_id,
                query_identity,
                artifact_id,
                1,
                native_key,
                -score,
                "negative_inner_product",
            )
            for query_identity, native_key, score in exact_scores
        )
        statements: list[SqlRenderable] = [
            SqlDelete(
                SqlTableIdent(self._spool_table),
                where=SqlWhereClause(
                    SqlBinaryOp(SqlColumnRef(SqlColumnName("scope_id")), BinaryOp.EQ, SqlParam(self._scope_id)),
                ),
            ),
        ]
        if replacement_rows:
            statements.append(
                SqlInsert(
                    SqlTableIdent(self._spool_table),
                    columns=SqlColumnList(
                        [
                            SqlColumnName("scope_id"),
                            SqlColumnName("query_identity"),
                            SqlColumnName("artifact_id"),
                            SqlColumnName("artifact_epoch"),
                            SqlColumnName("native_key"),
                            SqlColumnName("distance"),
                            SqlColumnName("distance_kind"),
                        ],
                    ),
                    values=SqlValuesClause(
                        [SqlValuesRow([SqlParam(value) for value in row]) for row in replacement_rows],
                    ),
                ),
            )
        for statement in statements:
            with allow_direct_sql_in_step_execution():
                await sql_conn._execute_direct_internal_async(statement)

    def execute_runtime(self, resolved: ResolvedRefs, hydrator: RuntimeHydrator[Any]) -> _CrossBranchUSearchExecutionReceipt:
        if hydrator.sql_conn is None:
            raise RuntimeError("quantized matching spooling requires a SQL connection")
        statements, receipt = self._statements(
            resolved,
            sql_conn=hydrator.sql_conn,
            use_sqlite_native=self._sqlite_native,
        )
        for statement in statements:
            with allow_direct_sql_in_step_execution():
                hydrator.sql_conn._execute_direct_internal(statement)
        self._rerank_sync(resolved, hydrator.sql_conn)
        return receipt

    def async_runtime_callback(self) -> AsyncRuntimeCallback:
        return partial(_execute_quantized_spool_async, step=self)


async def _execute_quantized_spool_async(
    resolved: ResolvedRefs,
    hydrator: RuntimeHydrator[Any],
    *,
    step: _QuantizedMatchingSpoolStep,
) -> _CrossBranchUSearchExecutionReceipt:
    if hydrator.sql_conn is None:
        raise RuntimeError("quantized matching spooling requires a SQL connection")
    batch = step._prepare_batch(resolved)
    if step._sqlite_native and batch.requests:
        rows = tuple(
            (query_identity, native_key, spec, query, code)
            for (query_identity, native_key), (spec, query, code) in zip(
                batch.score_identities,
                batch.requests,
                strict=True,
            )
        )
        with allow_direct_sql_in_step_execution():
            raw_scores = await hydrator.sql_conn._execute_direct_internal_async(
                SqliteQuantizedBatchScoreSelect(rows),
                fetch_mode="all",
            )
        parsed_scores = _native_score_rows(raw_scores)
        score_identities = tuple((identity, native_key) for identity, native_key, _score in parsed_scores)
        native_scores = tuple(score for _identity, _native_key, score in parsed_scores)
    else:
        from nera_usearch_native._native import score_quantized_batch_async

        score_identities = batch.score_identities
        native_scores = tuple(await score_quantized_batch_async(list(batch.requests)))
    statements, receipt = step._statements(
        resolved,
        sql_conn=hydrator.sql_conn,
        use_sqlite_native=False,
        prepared_scores=(score_identities, native_scores),
    )
    for statement in statements:
        with allow_direct_sql_in_step_execution():
            await hydrator.sql_conn._execute_direct_internal_async(statement)
    await step._rerank_async(resolved, hydrator.sql_conn)
    return receipt


@dataclass(frozen=True, slots=True)
class _QuantizedIntentConfig:
    spec: MatchSpec[Any, Any]
    left_ref: ServerPlanRefId
    right_ref: ServerPlanRefId
    artifact_ref: ServerPlanRefId
    tensor_ref: ServerPlanRefId
    code_ref: ServerPlanRefId
    query_field_name: str


class QuantizedMatchIntent(IntentStep[MatchResult[LeftRowT, RightRowT]]):
    intent_tags = frozenset({"read", "matching", "quantized", "intent"})
    intent_cardinality = Cardinality.SCALAR
    intent_read_only = True

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        config_ref: ScalarServerRef[_QuantizedIntentConfig],
    ) -> None:
        from impl.common.l2070_server_plan.steps.intent_query_extended import _require_seeded_config

        super().__init__(ref_id)
        config = _require_seeded_config(config_ref, type(self).__name__)
        self._spec = config.spec
        self._left_ref = config.left_ref
        self._right_ref = config.right_ref
        self._artifact_ref = config.artifact_ref
        self._tensor_ref = config.tensor_ref
        self._code_ref = config.code_ref
        self._query_field_name = config.query_field_name

    def lower(self, ctx: LoweringContext) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l5250_matching.native_result_support import (
            _ExactDenseDecodeConfig,
            _ExactDenseDecodeStep,
            _ExactDensePreflightRowsStep,
            _ExactDenseWorkGuardStep,
        )
        from impl.common.l5250_matching.usearch_native import _USearchMatchingRowsStep

        preflight_rows_ref = ServerPlanRefId(f"{self.ref_id}_preflight_rows")
        guard_ref = ServerPlanRefId(f"{self.ref_id}_preflight")
        spool_ref = ServerPlanRefId(f"{self.ref_id}_native_batch")
        rows_ref = ServerPlanRefId(f"{self.ref_id}_rows")
        return (
            _ExactDensePreflightRowsStep(
                preflight_rows_ref,
                self._spec,
                left_permission=None,
                right_permission=None,
                versioned_branch_id=None,
                left_source_ref=self._left_ref,
                right_source_ref=self._right_ref,
            ),
            _ExactDenseWorkGuardStep(guard_ref, source_ref=preflight_rows_ref, spec=self._spec),
            _QuantizedMatchingSpoolStep(
                spool_ref,
                refs=_QuantizedRefs(
                    left=self._left_ref,
                    right=self._right_ref,
                    artifacts=self._artifact_ref,
                    tensors=self._tensor_ref,
                    codes=self._code_ref,
                    guard=guard_ref,
                ),
                query_field_name=self._query_field_name,
                sqlite_native=(ctx.backend_profile.providers.vector_candidate_provider.uses_database_native_vector_scalars()),
                spec=self._spec,
            ),
            _USearchMatchingRowsStep(
                rows_ref,
                spool_ref=spool_ref,
                left_ref=self._left_ref,
                right_ref=self._right_ref,
                spec=self._spec,
            ),
            _ExactDenseDecodeStep(
                self.ref_id,
                config=_ExactDenseDecodeConfig(
                    source_ref=rows_ref,
                    preflight_rows_ref=preflight_rows_ref,
                    preflight_ref=guard_ref,
                    spec=self._spec,
                ),
            ),
        )


@pure_lazy
def build_quantized_match_intent(
    ref_id: ServerPlanRefId,
    spec: MatchSpec[LeftRowT, RightRowT],
    txn: LazyReadTransaction,
) -> QuantizedMatchIntent[LeftRowT, RightRowT]:
    from impl.common.l5250_matching.usearch_native import _projection_source_ref
    from l1470_matching_contracts.models import MatchQuantizedCodeRepresentationSpec

    left_representation = spec.left.representation
    right_representation = spec.right.representation
    if not isinstance(left_representation, MatchDenseVectorFieldRepresentationSpec) or not isinstance(
        right_representation,
        MatchQuantizedCodeRepresentationSpec,
    ):
        raise TypeError("quantized matching requires dense queries and packed right codes")
    left_ref = _projection_source_ref(txn, spec.left, spec.filters.left, permission_filter_required=True)
    right_ref = _projection_source_ref(txn, spec.right, spec.filters.right, permission_filter_required=True)
    storage_authority = _QuantizedStorageAuthority(
        left_source_ref=left_ref,
        right_source_ref=right_ref,
    )
    artifacts_query = txn.query_lazy(QuantizedProjectionArtifactRow).filter(
        field(QuantizedProjectionArtifactRow.artifact_id) == right_representation.projection_artifact_id,
    )
    artifacts = _execute_quantized_storage_query(
        artifacts_query,
        QuantizedProjectionArtifactRow,
        storage_authority,
    )
    tensors_query = txn.query_lazy(QuantizedProjectionTensorRow).filter(
        field(QuantizedProjectionTensorRow.artifact_id) == right_representation.projection_artifact_id,
    )
    tensors = _execute_quantized_storage_query(
        tensors_query,
        QuantizedProjectionTensorRow,
        storage_authority,
    )
    codes_query = (
        txn.query_lazy(QuantizedCodeRow)
        .filter(
            field(QuantizedCodeRow.artifact_id) == right_representation.projection_artifact_id,
        )
        .filter(
            field(QuantizedCodeRow.representation_ref_id) == right_representation.representation_ref_id,
        )
        .filter(
            field(QuantizedCodeRow.source_watermark) == QuantizedSourceWatermark(int(right_representation.source_watermark)),
        )
    )
    codes = _execute_quantized_storage_query(
        codes_query,
        QuantizedCodeRow,
        storage_authority,
    )
    config_ref = ServerRefs.scalar(
        _QuantizedIntentConfig(
            spec=spec,
            left_ref=left_ref,
            right_ref=right_ref,
            artifact_ref=_one_ref(artifacts, "quantized artifact query"),
            tensor_ref=_one_ref(tensors, "quantized tensor query"),
            code_ref=_one_ref(codes, "quantized code query"),
            query_field_name=str(left_representation.field_name),
        ),
    )
    return QuantizedMatchIntent(ref_id, config_ref)

