"""Source provenance for normalized and case-folded Unicode code points."""

from __future__ import annotations

import unicodedata
from typing import Literal

from l1470_matching_contracts.types import MatchUnicodeNormalizationForm


def _ordered_decomposition(source: str, form: Literal["NFD", "NFKD"]) -> list[tuple[str, int]]:
    ordered: list[tuple[str, int]] = []
    combining_run: list[tuple[str, int]] = []
    for offset, character in enumerate(source):
        for decomposed in unicodedata.normalize(form, character):
            if unicodedata.combining(decomposed) == 0:
                ordered.extend(sorted(combining_run, key=lambda item: unicodedata.combining(item[0])))
                combining_run.clear()
                ordered.append((decomposed, offset))
            else:
                combining_run.append((decomposed, offset))
    ordered.extend(sorted(combining_run, key=lambda item: unicodedata.combining(item[0])))
    return ordered


def normalized_source_spans(
    source: str, *, unicode_form: MatchUnicodeNormalizationForm, casefold: bool,
) -> tuple[tuple[int, int], ...]:
    """Return the contributing source interval for each output code point."""
    decomposition_form: Literal["NFD", "NFKD"] = (
        "NFKD" if unicode_form in (MatchUnicodeNormalizationForm.NFKC, MatchUnicodeNormalizationForm.NFKD) else "NFD"
    )
    normalized = unicodedata.normalize(unicode_form.value, source)
    source_parts = _ordered_decomposition(source, decomposition_form)
    normalized_parts = _ordered_decomposition(normalized, decomposition_form)
    contributors: list[list[int]] = [[] for _ in normalized]
    for (source_character, source_offset), (output_character, output_offset) in zip(
        source_parts, normalized_parts, strict=True,
    ):
        assert source_character == output_character
        contributors[output_offset].append(source_offset)
    spans: list[tuple[int, int]] = []
    for character, offsets in zip(normalized, contributors, strict=True):
        span = (min(offsets), max(offsets) + 1)
        spans.extend(span for _ in (character.casefold() if casefold else character))
    return tuple(spans)

