@pure_lazy
def _projection_source_ref(
    txn: LazyReadTransaction,
    relation: MatchRelationSpec[Any],
    endpoint_filter: object,
    *,
    permission_filter_required: bool,
) -> ServerPlanRefId:
    row_type = relation.row_type
    field_owners: dict[str, type[DatabaseObjectRow[SysId]]] = {name: row_type for name in row_type.model_fields}
    shape = txn.planning_catalog.polymorphic_for_base(row_type)
    for subtype in () if shape is None else shape.subtypes:
        if issubclass(subtype, row_type):
            for name in subtype.model_fields:
                field_owners.setdefault(name, subtype)
    query = txn.query_lazy(row_type)
    if isinstance(endpoint_filter, MatchEndpointFilterSpec):
        query = query.filter(endpoint_filter.expression)
    elif not isinstance(endpoint_filter, NoMatchFilter):
        raise TypeError("USearch matching requires a declared endpoint filter variant")
    selected = query.select(
        *(field(getattr(owner, name)) for name, owner in field_owners.items()),
    )
    from l7000_versioned_schema.versioned_schema import VersionedObjectRow

    if issubclass(row_type, VersionedObjectRow):
        lazy_method = getattr(selected, "lazy", None)
        if not callable(lazy_method):
            raise TypeError("USearch matching endpoint must publish a lazy SQL relation")
        projected = lazy_method(_internal_projection=True)
    elif permission_filter_required:
        lazy_method = getattr(query, "lazy", None)
        if not callable(lazy_method):
            raise TypeError("USearch matching endpoint must publish a lazy SQL relation")
        projected = lazy_method()
    else:
        from impl.common.l2070_server_plan.steps.intent_query_extended import (
            QueryExecuteRawIntent,
            _QueryExecuteRawConfig,
        )

        query_spec = selected._build_spec()
        plan = txn._get_transaction_plan_lazy()
        projected = txn._add_intent(
            QueryExecuteRawIntent(
                ref_id=ServerPlanRefId(plan._next_ref()),
                model_cls=row_type,
                config=_QueryExecuteRawConfig(
                    query_spec=query_spec,
                    raw_access_authorized=True,
                    direct_raw_terminal=True,
                ),
            ),
        )
    from l2070_batching.server_ref import inspect_server_value_shape_for_planning

    shape_value = inspect_server_value_shape_for_planning(
        projected,
        site="USearch matching endpoint projection",
    )
    if shape_value.symbolic_ref_id is None:
        raise RuntimeError("USearch matching endpoint must publish one SQL relation")
    return shape_value.symbolic_ref_id


def _metric_name(metric: VectorMetric) -> str:
    return {
        VectorMetric.COSINE: "cos",
        VectorMetric.EUCLIDEAN: "l2sq",
        VectorMetric.DOT_PRODUCT: "ip",
    }[metric]


