class _MatchingQuery:
    identity: str
    coordinates: tuple[float, ...]


class _USearchMatchingBatchSpoolStep(_CrossBranchUSearchNativeSpoolStep):
    """Score all left query identities and publish one query-owned score spool."""

    def __init__(
        self: Self,
        ref_id: ServerPlanRefId,
        *,
        artifact_ref_id: ServerPlanRefId,
        eligibility_ref_id: ServerPlanRefId,
        query_ref_id: ServerPlanRefId,
        guard_ref_id: ServerPlanRefId,
        query_model: type[DatabaseObjectRow[SysId]],
        query_field_name: str,
        indexed_model: type[DatabaseObjectRow[SysId]],
        index_name: str,
        query_vector: _CrossBranchUSearchQueryVector,
        sqlite_native: bool,
        sqlite_persistent: bool,
    ) -> None:
        super().__init__(
            ref_id,
            artifact_ref_id=artifact_ref_id,
            eligibility_ref_id=eligibility_ref_id,
            query_vector=query_vector,
            limits=get_usearch_request_limits(),
            identity_scope=_NativeIdentityScope.UNVERSIONED,
        )
        self._query_ref_id = query_ref_id
        self._guard_ref_id = guard_ref_id
        self._query_model = query_model
        self._query_field_name = query_field_name
        self._indexed_model = indexed_model
        self._index_name = index_name
        self._sqlite_native = sqlite_native
        self._sqlite_persistent = sqlite_persistent

    def dependencies(self: Self) -> frozenset[str]:
        native_dependencies = frozenset({str(self._eligibility_ref_id)}) if self._sqlite_persistent else super().dependencies()
        return native_dependencies | frozenset(
            {str(self._query_ref_id), str(self._guard_ref_id)},
        )

    def _queries(self: Self, resolved: ResolvedRefs) -> tuple[_MatchingQuery, ...]:
        raw_rows = resolved.require(
            self._query_ref_id,
            list,
            site="USearch matching query relation",
        )
        queries: list[_MatchingQuery] = []
        dimensions = len(self._query_vector.coordinates)
        for raw_row in raw_rows:
            if isinstance(raw_row, Mapping):
                raw_identity = raw_row.get("sys_id")
                raw_vector = raw_row.get(self._query_field_name)
            elif isinstance(raw_row, self._query_model):
                raw_identity = raw_row.sys_id
                raw_vector = getattr(raw_row, self._query_field_name)
            else:
                raise NativeSearchIntegrityError(
                    "USearch matching query relation returned an invalid row",
                )
            if not isinstance(raw_identity, SysId):
                try:
                    raw_identity = SysId(str(raw_identity))
                except (TypeError, ValueError) as error:
                    raise NativeSearchIntegrityError(
                        "USearch matching query identity is invalid",
                        original_exception=error,
                    ) from error
            if not isinstance(raw_vector, Sequence) or isinstance(raw_vector, str | bytes | bytearray):
                raise NativeSearchIntegrityError("USearch matching query vector is invalid")
            coordinates = tuple(float(value) for value in raw_vector)
            if len(coordinates) != dimensions or any(not isfinite(value) for value in coordinates):
                raise NativeSearchIntegrityError(
                    "USearch matching query vector has invalid dimensions or values",
                )
            queries.append(_MatchingQuery(str(raw_identity), coordinates))
        return tuple(sorted(queries, key=lambda query: query.identity))

    def _prepare_persistent_spool(
        self: Self,
        resolved: ResolvedRefs,
    ) -> _PreparedCrossBranchUSearchSpool:
        from l5200_vector_index.usearch_request_limits import validate_usearch_request_limits

        raw_rows = resolved.require(
            self._eligibility_ref_id,
            list,
            site="USearch matching eligibility input",
        )
        validate_usearch_request_limits(self._limits, eligibility_rows=len(raw_rows))
        scope = SqlBinaryOp(
            SqlColumnRef(SqlColumnName("scope_id")),
            BinaryOp.EQ,
            SqlParam(self._scope_id),
        )
        statements = (
            SqlDelete(SqlTableIdent(self._spool_table), where=SqlWhereClause(scope)),
            SqlDelete(
                SqlTableIdent(self._eligibility_spool_table),
                where=SqlWhereClause(scope),
            ),
        )
        eligible: list[_CrossBranchUSearchEligibleIdentity] = []
        keys: set[USearchNativeKey] = set()
        for raw_row in raw_rows:
            if not isinstance(raw_row, Mapping):
                raise NativeSearchIntegrityError(
                    "USearch matching eligibility row must be a mapping",
                )
            raw_key = raw_row.get("native_key")
            if isinstance(raw_key, bool) or not isinstance(raw_key, int) or raw_key <= 0:
                raise NativeSearchIntegrityError(
                    "USearch matching eligibility contains an invalid native key",
                )
            try:
                identity = _CrossBranchUSearchEligibleIdentity.model_validate(
                    {
                        "object_id": raw_row.get("object_id"),
                        "branch_id": raw_row.get("branch_id"),
                        "revision_id": raw_row["revision_id"],
                        "native_key": raw_key,
                        "chunk_id": raw_row.get("chunk_id"),
                        "chunk_metadata": raw_row.get("chunk_metadata"),
                    },
                )
            except (KeyError, ValidationError) as error:
                raise NativeSearchIntegrityError(
                    "USearch matching eligibility contains an invalid row identity",
                    original_exception=error,
                ) from error
            eligible.append(identity)
            keys.add(USearchNativeKey(raw_key))
        if not eligible:
            return _PreparedCrossBranchUSearchSpool(statements, None, ())
        request = USearchExactSearchRequest(
            blob=b"persistent",
            dimensions=len(self._query_vector.coordinates),
            metric=self._query_vector.metric,
            query=self._query_vector.coordinates,
            eligible_keys=tuple(sorted(keys)),
            artifact_id=SysId(
                uuid5(
                    NAMESPACE_URL,
                    f"nera:sqlite-usearch:{get_table_name(self._indexed_model)}:{self._index_name}",
                ),
            ),
            artifact_epoch=USearchArtifactEpoch(1),
            limits=self._limits,
        )
        return _PreparedCrossBranchUSearchSpool(
            statements,
            request,
            tuple(eligible),
        )

    def _requests(
        self: Self,
        prepared: _PreparedCrossBranchUSearchSpool,
    ) -> tuple[USearchExactSearchRequest, ...]:
        request = prepared.request
        if request is None:
            return ()
        return request.requests if isinstance(request, USearchRunSearchRequest) else (request,)

    def _score_sql(
        self: Self,
        prepared: _PreparedCrossBranchUSearchSpool,
        queries: tuple[_MatchingQuery, ...],
    ) -> tuple[Any, ...]:
        if self._sqlite_persistent:
            return (
                (
                    SqliteUSearchPersistentBatchScoreRelation(
                        source_table=SqlTableName(get_table_name(self._indexed_model)),
                        field_name=self._index_name,
                        query_vectors=tuple(query.coordinates for query in queries),
                        eligible_object_ids=tuple(sorted({str(identity.object_id) for identity in prepared.eligible})),
                        ef_search=50,
                        branch_id=None,
                        revision_id=None,
                    ),
                )
                if prepared.eligible and queries
                else ()
            )
        return tuple(
            SqliteUSearchBatchCompleteScoreSelect(
                artifact=request.blob,
                dimensions=request.dimensions,
                metric=request.metric,
                query_vectors=tuple(query.coordinates for query in queries),
                eligible_keys=tuple(int(key) for key in request.eligible_keys),
            )
            for request in self._requests(prepared)
            if request.eligible_keys and queries
        )

    def _portable_scores(
        self: Self,
        prepared: _PreparedCrossBranchUSearchSpool,
        queries: tuple[_MatchingQuery, ...],
    ) -> tuple[tuple[str, USearchRuntimeScore], ...]:
        scored: list[tuple[str, USearchRuntimeScore]] = []
        query_vectors = tuple(query.coordinates for query in queries)
        for request in self._requests(prepared):
            batches = request.search_batch(query_vectors)
            for query, scores in zip(queries, batches, strict=True):
                scored.extend((query.identity, score) for score in scores)
        return tuple(scored)

    async def _portable_scores_async(
        self: Self,
        prepared: _PreparedCrossBranchUSearchSpool,
        queries: tuple[_MatchingQuery, ...],
    ) -> tuple[tuple[str, USearchRuntimeScore], ...]:
        scored: list[tuple[str, USearchRuntimeScore]] = []
        query_vectors = tuple(query.coordinates for query in queries)
        for request in self._requests(prepared):
            batches = await request.search_batch_async(query_vectors)
            for query, scores in zip(queries, batches, strict=True):
                scored.extend((query.identity, score) for score in scores)
        return tuple(scored)

    @staticmethod
    def _sql_row_mapping(row: object) -> Mapping[str, object]:
        if isinstance(row, Mapping):
            return row
        if isinstance(row, Sequence) and not isinstance(row, str | bytes | bytearray):
            columns = {
                4: ("query_ordinal", "native_key", "score", "distance"),
                7: (
                    "query_ordinal",
                    "object_id",
                    "score",
                    "distance",
                    "distance_kind",
                    "chunk_id",
                    "chunk_metadata",
                ),
            }.get(len(row))
            if columns is not None:
                return dict(zip(columns, row, strict=True))
        raise NativeSearchIntegrityError(
            "SQLite USearch matching returned an invalid score relation",
        )

    def _decode_sql_scores(
        self: Self,
        rows: Sequence[Mapping[str, object]],
        queries: tuple[_MatchingQuery, ...],
        prepared: _PreparedCrossBranchUSearchSpool,
    ) -> tuple[tuple[str, USearchRuntimeScore], ...]:
        object_keys = {str(identity.object_id): identity.native_key for identity in prepared.eligible}
        scored: list[tuple[str, USearchRuntimeScore]] = []
        for row in rows:
            ordinal = row.get("query_ordinal")
            raw_key = row.get("native_key")
            raw_object_id = row.get("object_id")
            key = raw_key if isinstance(raw_key, int) and not isinstance(raw_key, bool) else object_keys.get(str(raw_object_id))
            score = row.get("score")
            distance = row.get("distance")
            if (
                isinstance(ordinal, bool)
                or not isinstance(ordinal, int)
                or not 1 <= ordinal <= len(queries)
                or isinstance(key, bool)
                or not isinstance(key, int)
                or key <= 0
                or isinstance(score, bool)
                or not isinstance(score, int | float)
                or isinstance(distance, bool)
                or not isinstance(distance, int | float)
                or not isfinite(float(score))
                or not isfinite(float(distance))
            ):
                raise NativeSearchIntegrityError(
                    "SQLite USearch matching returned an invalid score row",
                )
            scored.append(
                (
                    queries[ordinal - 1].identity,
                    USearchRuntimeScore(
                        native_key=USearchNativeKey(key),
                        score=float(score),
                        distance=float(distance),
                    ),
                ),
            )
        return tuple(scored)

    def _validate_scores(
        self: Self,
        prepared: _PreparedCrossBranchUSearchSpool,
        queries: tuple[_MatchingQuery, ...],
        scored: tuple[tuple[str, USearchRuntimeScore], ...],
    ) -> None:
        expected = {
            (query.identity, int(key))
            for query in queries
            for key in (() if prepared.request is None else prepared.request.eligible_keys)
        }
        observed = {(identity, int(score.native_key)) for identity, score in scored}
        if len(scored) != len(observed) or observed != expected:
            raise NativeSearchIntegrityError(
                "USearch matching scores must cover each query-key pair exactly once",
            )

    def _publication_statements(
        self: Self,
        prepared: _PreparedCrossBranchUSearchSpool,
        scored: tuple[tuple[str, USearchRuntimeScore], ...],
    ) -> Iterator[Any]:
        yield from prepared.statements
        request = prepared.request
        if request is None:
            return
        score_columns = SqlColumnList(
            [
                SqlColumnName("scope_id"),
                SqlColumnName("query_identity"),
                SqlColumnName("artifact_id"),
                SqlColumnName("artifact_epoch"),
                SqlColumnName("native_key"),
                SqlColumnName("distance"),
                SqlColumnName("distance_kind"),
            ],
        )
        eligibility_columns = SqlColumnList(
            [
                SqlColumnName("scope_id"),
                SqlColumnName("query_identity"),
                SqlColumnName("object_id"),
                SqlColumnName("branch_id"),
                SqlColumnName("revision_id"),
                SqlColumnName("native_key"),
                SqlColumnName("chunk_id"),
                SqlColumnName("chunk_metadata"),
            ],
        )
        query_identities = tuple(dict.fromkeys(identity for identity, _score in scored))
        eligibility_rows = (
            (
                self._scope_id,
                query_identity,
                str(row.object_id),
                None if row.branch_id is None else str(row.branch_id),
                None if row.revision_id is None else str(row.revision_id),
                int(row.native_key),
                None if row.chunk_id is None else str(row.chunk_id),
                row.chunk_metadata,
            )
            for query_identity in query_identities
            for row in prepared.eligible
        )
        score_rows = (
            (
                self._scope_id,
                query_identity,
                request.artifact_id,
                request.artifact_epoch,
                int(score.native_key),
                score.distance,
                usearch_distance_kind(request.metric),
            )
            for query_identity, score in scored
        )
        for columns, rows, table in (
            (eligibility_columns, eligibility_rows, self._eligibility_spool_table),
            (score_columns, score_rows, self._spool_table),
        ):
            for batch in batched(rows, 500):
                yield SqlInsert(
                    SqlTableIdent(table),
                    columns=columns,
                    values=SqlValuesClause(
                        [SqlValuesRow([SqlParam(value) for value in row]) for row in batch],
                    ),
                )

    def _receipt(
        self: Self,
        prepared: _PreparedCrossBranchUSearchSpool,
        queries: tuple[_MatchingQuery, ...],
        scored: tuple[tuple[str, USearchRuntimeScore], ...],
    ) -> _CrossBranchUSearchExecutionReceipt:
        request = prepared.request
        return _CrossBranchUSearchExecutionReceipt(
            artifact_id=None if request is None else request.artifact_id,
            artifact_epoch=None if request is None else request.artifact_epoch,
            artifact_format=None if request is None else "usearch-matching-batch-v1",
            visible_identity_count=len(prepared.eligible),
            eligible_native_key_count=0 if request is None else len(request.eligible_keys),
            requested_candidate_count=(0 if request is None else len(queries) * len(request.eligible_keys)),
            examined_member_count=0 if request is None else len(request.eligible_keys),
            computed_distance_count=len(scored),
            returned_native_hit_count=len(scored),
            score_count=len(scored),
        )

    def execute_runtime(
        self: Self,
        resolved: ResolvedRefs,
        hydrator: RuntimeHydrator[Any],
    ) -> _CrossBranchUSearchExecutionReceipt:
        from impl.common.l2070_server_plan.execution_context import allow_direct_sql_in_step_execution

        conn = hydrator.sql_conn
        if conn is None:
            raise RuntimeError("USearch matching spooling requires a SQL connection")
        prepared = self._prepare_persistent_spool(resolved) if self._sqlite_persistent else self._prepare_spool(resolved)
        queries = self._queries(resolved)
        if self._sqlite_native:
            rows: list[Mapping[str, object]] = []
            for statement in self._score_sql(prepared, queries):
                with allow_direct_sql_in_step_execution():
                    result = conn._execute_direct_internal(statement, fetch_mode="all")
                if not isinstance(result, Sequence) or isinstance(result, str | bytes | bytearray):
                    raise NativeSearchIntegrityError(
                        "SQLite USearch matching returned no score relation",
                    )
                rows.extend(self._sql_row_mapping(row) for row in result)
            scored = self._decode_sql_scores(rows, queries, prepared)
        else:
            scored = self._portable_scores(prepared, queries)
        self._validate_scores(prepared, queries, scored)
        for statement in self._publication_statements(prepared, scored):
            with allow_direct_sql_in_step_execution():
                conn._execute_direct_internal(statement)
        receipt = self._receipt(prepared, queries, scored)
        receipt.record_diagnostic()
        return receipt

    def async_runtime_callback(self: Self) -> AsyncRuntimeCallback:
        return partial(_execute_usearch_matching_batch_async, step=self)


async def _execute_usearch_matching_batch_async(
    resolved: ResolvedRefs,
    hydrator: RuntimeHydrator[Any],
    *,
    step: _USearchMatchingBatchSpoolStep,
) -> _CrossBranchUSearchExecutionReceipt:
    from impl.common.l2070_server_plan.execution_context import allow_direct_sql_in_step_execution

    conn = hydrator.sql_conn
    if conn is None:
        raise RuntimeError("USearch matching spooling requires a SQL connection")
    prepared = step._prepare_persistent_spool(resolved) if step._sqlite_persistent else await step._prepare_spool_async(resolved)
    queries = step._queries(resolved)
    if step._sqlite_native:
        rows: list[Mapping[str, object]] = []
        for statement in step._score_sql(prepared, queries):
            with allow_direct_sql_in_step_execution():
                result = await conn._execute_direct_internal_async(statement, fetch_mode="all")
            if not isinstance(result, Sequence) or isinstance(result, str | bytes | bytearray):
                raise NativeSearchIntegrityError(
                    "SQLite USearch matching returned no score relation",
                )
            rows.extend(step._sql_row_mapping(row) for row in result)
        scored = step._decode_sql_scores(rows, queries, prepared)
    else:
        scored = await step._portable_scores_async(prepared, queries)
    step._validate_scores(prepared, queries, scored)
    for statement in step._publication_statements(prepared, scored):
        with allow_direct_sql_in_step_execution():
            await conn._execute_direct_internal_async(statement)
    receipt = step._receipt(prepared, queries, scored)
    receipt.record_diagnostic()
    return receipt


_LEFT_ALIAS = SqlAliasName("match_left")
_RIGHT_ALIAS = SqlAliasName("match_right")
_SCORE_ALIAS = SqlAliasName("native_score")
_ELIGIBILITY_ALIAS = SqlAliasName("native_eligibility")
_CANDIDATE_ALIAS = SqlAliasName("match_candidates")
_DEDUPLICATED_ALIAS = SqlAliasName("match_deduplicated")
_RANKED_ALIAS = SqlAliasName("match_ranked")
_SCORE_COLUMN = SqlColumnName("match_score")
_LEFT_RANK_COLUMN = SqlColumnName("left_rank")
_RIGHT_RANK_COLUMN = SqlColumnName("right_rank")
_PAIR_COUNT_COLUMN = SqlColumnName("pair_evaluations")
_LEFT_IDENTITY_COLUMN = SqlColumnName("left_identity")
_RIGHT_IDENTITY_COLUMN = SqlColumnName("right_identity")
_DUPLICATE_RANK_COLUMN = SqlColumnName("match_duplicate_rank")
_DUPLICATE_COUNT_COLUMN = SqlColumnName("match_duplicate_count")


def _native_score_expression() -> SqlCase:
    distance = SqlColumnRef(SqlColumnName("distance"), qualifier=_SCORE_ALIAS)
    kind = SqlColumnRef(SqlColumnName("distance_kind"), qualifier=_SCORE_ALIAS)
    nonnegative_distance = SqlCase(
        whens=[(SqlBinaryOp(distance, BinaryOp.LT, SqlParam(0.0)), SqlParam(0.0))],
        else_=distance,
    )
    return SqlCase(
        whens=[
            (
                SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("negative_inner_product")),
                SqlBinaryOp(SqlParam(0.0), BinaryOp.SUB, distance),
            ),
            (
                SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("negative_cosine_similarity")),
                SqlBinaryOp(
                    SqlBinaryOp(SqlParam(1.0), BinaryOp.SUB, distance),
                    BinaryOp.DIV,
                    SqlParam(2.0),
                ),
            ),
            (
                SqlBinaryOp(kind, BinaryOp.EQ, SqlParam("squared_euclidean_distance")),
                SqlBinaryOp(
                    SqlParam(1.0),
                    BinaryOp.DIV,
                    SqlBinaryOp(
                        SqlParam(1.0),
                        BinaryOp.ADD,
                        SqlFuncCall("SQRT", [nonnegative_distance]),
                    ),
                ),
            ),
        ],
        else_=SqlBinaryOp(SqlParam(1.0), BinaryOp.SUB, distance),
    )


def _native_matching_statement(
    ctx: CompilationContext,
    spec: MatchSpec[Any, Any],
    *,
    left_ref: ServerPlanRefId,
    right_ref: ServerPlanRefId,
    scope_id: str,
) -> tuple[SqlSelect, tuple[str, ...], SqlColumnTypeHints]:
    from impl.common.l5250_matching.native_result_support import (
        _EndpointSqlSource,
        _candidate_predicate,
        _endpoint_source_relation,
        _identity_sql_expression,
        _selected_model_columns,
    )
    from impl.common.l5250_matching.exact_dense import _cursor_predicate
    from impl.common.l2070_server_plan.steps.cross_branch import (
        _usearch_eligibility_spool_table,
        _usearch_score_spool_table,
    )

    left_cte = ctx.cte_refs.get(str(left_ref))
    right_cte = ctx.cte_refs.get(str(right_ref))
    if not isinstance(left_cte, CteReference) or not isinstance(right_cte, CteReference):
        raise RuntimeError("USearch matching endpoints must publish SQL relations")
    left_projection, left_columns, left_hints = _selected_model_columns(
        spec.left.row_type,
        source_alias=_LEFT_ALIAS,
        output_prefix="left__",
        planning_catalog=ctx.planning_catalog,
    )
    right_projection, right_columns, right_hints = _selected_model_columns(
        spec.right.row_type,
        source_alias=_RIGHT_ALIAS,
        output_prefix="right__",
        planning_catalog=ctx.planning_catalog,
    )
    left_id = SqlColumnRef(SqlColumnName("sys_id"), qualifier=_LEFT_ALIAS)
    right_id = SqlColumnRef(SqlColumnName("sys_id"), qualifier=_RIGHT_ALIAS)
    native_key = SqlColumnRef(SqlColumnName("native_key"), qualifier=_SCORE_ALIAS)
    score = _native_score_expression()
    pair_predicate = _candidate_predicate(
        spec,
        left_permission=None,
        right_permission=None,
        versioned_branch_id=None,
        versioned_sources_prefiltered=True,
        include_presence=False,
    )
    candidate_where = sql_and(
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("scope_id"), qualifier=_SCORE_ALIAS),
            BinaryOp.EQ,
            SqlParam(scope_id),
        ),
        SqlBinaryOp(
            SqlColumnRef(SqlColumnName("scope_id"), qualifier=_ELIGIBILITY_ALIAS),
            BinaryOp.EQ,
            SqlParam(scope_id),
        ),
        *(() if pair_predicate is None else (pair_predicate,)),
    )
    left_identity = SqlCast(_identity_sql_expression(spec.left, _LEFT_ALIAS), parse_cast_target_type("TEXT"))
    right_identity = SqlCast(_identity_sql_expression(spec.right, _RIGHT_ALIAS), parse_cast_target_type("TEXT"))
    duplicate_partition = (left_identity, right_identity)
    duplicate_policy = spec.policies.duplicates
    candidate_score: SqlRenderable = score
    if isinstance(duplicate_policy, CombineDuplicatePairsPolicy):
        candidate_score = SqlWindow(
            func=SqlFuncCall(
                "SUM" if duplicate_policy.score_combination is MatchDuplicateScoreCombination.SUM else "MAX",
                [score],
            ),
            partition_by=duplicate_partition,
        )
    candidates = SqlSelect(
        select=SqlSelectList(
            [
                *left_projection,
                *right_projection,
                SqlSelectAlias(left_identity, SqlAliasName(_LEFT_IDENTITY_COLUMN)),
                SqlSelectAlias(right_identity, SqlAliasName(_RIGHT_IDENTITY_COLUMN)),
                SqlSelectAlias(candidate_score, SqlAliasName(_SCORE_COLUMN)),
                SqlSelectAlias(
                    SqlWindow(
                        func_name=FunctionKind.ROW_NUMBER,
                        partition_by=duplicate_partition,
                        order_by=(
                            SqlOrderByItem(left_id, OrderDirection.ASC),
                            SqlOrderByItem(right_id, OrderDirection.ASC),
                        ),
                    ),
                    SqlAliasName(_DUPLICATE_RANK_COLUMN),
                ),
                SqlSelectAlias(
                    SqlWindow(func=SqlFuncCall("COUNT", [left_id]), partition_by=duplicate_partition),
                    SqlAliasName(_DUPLICATE_COUNT_COLUMN),
                ),
                SqlSelectAlias(SqlWindow(func=SqlFuncCall("COUNT", [left_id])), SqlAliasName(_PAIR_COUNT_COLUMN)),
            ],
        ),
        from_=_endpoint_source_relation(
            _EndpointSqlSource(SqlTableName(left_cte.ref_id), left_cte.columns),
            spec.left.row_type,
            _LEFT_ALIAS,
        ),
        joins=(
            SqlJoin(
                JoinKind.INNER,
                SqlTableAlias(SqlTableIdent(_usearch_score_spool_table()), _SCORE_ALIAS),
                SqlBinaryOp(
                    SqlColumnRef(SqlColumnName("query_identity"), qualifier=_SCORE_ALIAS),
                    BinaryOp.EQ,
                    SqlCast(left_id, parse_cast_target_type("TEXT")),
                ),
            ),
            SqlJoin(
                JoinKind.INNER,
                SqlTableAlias(
                    SqlTableIdent(_usearch_eligibility_spool_table()),
                    _ELIGIBILITY_ALIAS,
                ),
                sql_and(
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("query_identity"), qualifier=_ELIGIBILITY_ALIAS),
                        BinaryOp.EQ,
                        SqlColumnRef(SqlColumnName("query_identity"), qualifier=_SCORE_ALIAS),
                    ),
                    SqlBinaryOp(
                        SqlColumnRef(SqlColumnName("native_key"), qualifier=_ELIGIBILITY_ALIAS),
                        BinaryOp.EQ,
                        native_key,
                    ),
                ),
            ),
            SqlJoin(
                JoinKind.INNER,
                _endpoint_source_relation(
                    _EndpointSqlSource(SqlTableName(right_cte.ref_id), right_cte.columns),
                    spec.right.row_type,
                    _RIGHT_ALIAS,
                ),
                SqlBinaryOp(
                    right_id,
                    BinaryOp.EQ,
                    SqlCast(
                        SqlColumnRef(SqlColumnName("object_id"), qualifier=_ELIGIBILITY_ALIAS),
                        parse_cast_target_type("UUID"),
                    ),
                ),
            ),
        ),
        where=candidate_where,
    )
    candidate_columns = (
        *left_columns,
        *right_columns,
        str(_LEFT_IDENTITY_COLUMN),
        str(_RIGHT_IDENTITY_COLUMN),
        str(_DUPLICATE_COUNT_COLUMN),
        str(_PAIR_COUNT_COLUMN),
    )
    deduplicated_score: SqlRenderable = SqlColumnRef(_SCORE_COLUMN, qualifier=_CANDIDATE_ALIAS)
    deduplicated = SqlSelect(
        select=SqlSelectList(
            [
                *(
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(column), qualifier=_CANDIDATE_ALIAS),
                        SqlAliasName(column),
                    )
                    for column in candidate_columns
                ),
                SqlSelectAlias(deduplicated_score, SqlAliasName(_SCORE_COLUMN)),
            ],
        ),
        from_=SqlTableAlias(candidates, _CANDIDATE_ALIAS),
        where=SqlBinaryOp(
            SqlColumnRef(_DUPLICATE_RANK_COLUMN, qualifier=_CANDIDATE_ALIAS),
            BinaryOp.EQ,
            SqlParam(1),
        ),
    )
    ranked_left_identity = SqlColumnRef(_LEFT_IDENTITY_COLUMN, qualifier=_DEDUPLICATED_ALIAS)
    ranked_right_identity = SqlColumnRef(_RIGHT_IDENTITY_COLUMN, qualifier=_DEDUPLICATED_ALIAS)
    ranked_score = SqlColumnRef(_SCORE_COLUMN, qualifier=_DEDUPLICATED_ALIAS)
    rank_partition: tuple[SqlRenderable, ...]
    rank_ties: tuple[SqlRenderable, ...]
    if isinstance(spec.result_shape, TopKPerRightMatchShape):
        rank_partition = (ranked_right_identity,)
        rank_ties = (ranked_left_identity,)
    elif isinstance(spec.result_shape, GlobalTopKMatchShape | ThresholdJoinMatchShape):
        rank_partition = ()
        rank_ties = (ranked_left_identity, ranked_right_identity)
    else:
        rank_partition = (ranked_left_identity,)
        rank_ties = (ranked_right_identity,)
    ranked_columns = (*candidate_columns, str(_SCORE_COLUMN))
    ranked = SqlSelect(
        select=SqlSelectList(
            [
                *(
                    SqlSelectAlias(
                        SqlColumnRef(SqlColumnName(column), qualifier=_DEDUPLICATED_ALIAS),
                        SqlAliasName(column),
                    )
                    for column in ranked_columns
                ),
                SqlSelectAlias(
                    SqlWindow(
                        func_name=FunctionKind.ROW_NUMBER,
                        partition_by=rank_partition,
                        order_by=(
                            SqlOrderByItem(ranked_score, OrderDirection.DESC),
                            *(SqlOrderByItem(identity, OrderDirection.ASC) for identity in rank_ties),
                        ),
                    ),
                    SqlAliasName(_LEFT_RANK_COLUMN),
                ),
                *(
                    [
                        SqlSelectAlias(
                            SqlWindow(
                                func_name=FunctionKind.ROW_NUMBER,
                                partition_by=(ranked_right_identity,),
                                order_by=(
                                    SqlOrderByItem(ranked_score, OrderDirection.DESC),
                                    SqlOrderByItem(ranked_left_identity, OrderDirection.ASC),
                                ),
                            ),
                            SqlAliasName(_RIGHT_RANK_COLUMN),
                        ),
                    ]
                    if isinstance(spec.result_shape, MutualNeighborMatchShape)
                    else []
                ),
            ],
        ),
        from_=SqlTableAlias(deduplicated, _DEDUPLICATED_ALIAS),
    )
    output_columns = (
        *left_columns,
        *right_columns,
        str(_LEFT_IDENTITY_COLUMN),
        str(_RIGHT_IDENTITY_COLUMN),
        str(_SCORE_COLUMN),
        str(_LEFT_RANK_COLUMN),
        *((str(_RIGHT_RANK_COLUMN),) if isinstance(spec.result_shape, MutualNeighborMatchShape) else ()),
        str(_PAIR_COUNT_COLUMN),
        str(_DUPLICATE_COUNT_COLUMN),
    )
    shape_predicate: SqlRenderable
    order: tuple[SqlOrderByItem, ...]
    if isinstance(spec.result_shape, TopKPerLeftMatchShape):
        shape_predicate = SqlBinaryOp(
            SqlColumnRef(_LEFT_RANK_COLUMN, qualifier=_RANKED_ALIAS),
            BinaryOp.LE,
            SqlParam(int(spec.result_shape.neighbor_count)),
        )
        order = (
            SqlOrderByItem(SqlColumnRef(SqlColumnName("left__sys_id"), qualifier=_RANKED_ALIAS), OrderDirection.ASC),
            SqlOrderByItem(SqlColumnRef(_LEFT_RANK_COLUMN, qualifier=_RANKED_ALIAS), OrderDirection.ASC),
        )
    elif isinstance(spec.result_shape, TopKPerRightMatchShape):
        shape_predicate = SqlBinaryOp(
            SqlColumnRef(_LEFT_RANK_COLUMN, qualifier=_RANKED_ALIAS),
            BinaryOp.LE,
            SqlParam(int(spec.result_shape.neighbor_count)),
        )
        order = (
            SqlOrderByItem(SqlColumnRef(SqlColumnName("right__sys_id"), qualifier=_RANKED_ALIAS), OrderDirection.ASC),
            SqlOrderByItem(SqlColumnRef(_LEFT_RANK_COLUMN, qualifier=_RANKED_ALIAS), OrderDirection.ASC),
        )
    elif isinstance(spec.result_shape, GlobalTopKMatchShape):
        shape_predicate = SqlBinaryOp(
            SqlColumnRef(_LEFT_RANK_COLUMN, qualifier=_RANKED_ALIAS),
            BinaryOp.LE,
            SqlParam(int(spec.result_shape.neighbor_count)),
        )
        order = (SqlOrderByItem(SqlColumnRef(_LEFT_RANK_COLUMN, qualifier=_RANKED_ALIAS), OrderDirection.ASC),)
    elif isinstance(spec.result_shape, MutualNeighborMatchShape):
        shape_predicate = sql_and(
            SqlBinaryOp(
                SqlColumnRef(_LEFT_RANK_COLUMN, qualifier=_RANKED_ALIAS),
                BinaryOp.LE,
                SqlParam(int(spec.result_shape.left_neighbor_count)),
            ),
            SqlBinaryOp(
                SqlColumnRef(_RIGHT_RANK_COLUMN, qualifier=_RANKED_ALIAS),
                BinaryOp.LE,
                SqlParam(int(spec.result_shape.right_neighbor_count)),
            ),
        )
        order = (
            SqlOrderByItem(SqlColumnRef(SqlColumnName("left__sys_id"), qualifier=_RANKED_ALIAS), OrderDirection.ASC),
            SqlOrderByItem(SqlColumnRef(_LEFT_RANK_COLUMN, qualifier=_RANKED_ALIAS), OrderDirection.ASC),
        )
    else:
        assert isinstance(spec.result_shape, ThresholdJoinMatchShape)
        shape_predicate = SqlBinaryOp(
            SqlColumnRef(_SCORE_COLUMN, qualifier=_RANKED_ALIAS),
            BinaryOp.GE if spec.result_shape.boundary.value == "inclusive" else BinaryOp.GT,
            SqlParam(float(spec.result_shape.threshold)),
        )
        order = (
            SqlOrderByItem(SqlColumnRef(_SCORE_COLUMN, qualifier=_RANKED_ALIAS), OrderDirection.DESC),
            SqlOrderByItem(SqlColumnRef(SqlColumnName("left__sys_id"), qualifier=_RANKED_ALIAS), OrderDirection.ASC),
            SqlOrderByItem(SqlColumnRef(SqlColumnName("right__sys_id"), qualifier=_RANKED_ALIAS), OrderDirection.ASC),
        )
    predicate = shape_predicate
    limit: int | None = None
    if isinstance(spec.result_shape, GlobalTopKMatchShape):
        pagination = spec.result_shape.pagination
        if isinstance(pagination, MatchPageAfterCursor):
            predicate = sql_and(predicate, _cursor_predicate(spec, pagination.cursor))
        if isinstance(pagination, FirstMatchPage | MatchPageAfterCursor):
            limit = int(pagination.page_size) + 1
    outer = SqlSelect(
        select=SqlSelectList(
            [
                SqlSelectAlias(
                    SqlColumnRef(SqlColumnName(column), qualifier=_RANKED_ALIAS),
                    SqlAliasName(column),
                )
                for column in output_columns
            ],
        ),
        from_=SqlTableAlias(ranked, _RANKED_ALIAS),
        where=predicate,
        order_by=order,
        limit=limit,
    )
    hints = combine_sql_column_type_hints(
        output_columns,
        left_hints,
        right_hints,
        SqlColumnTypeHints(
            double_columns=frozenset({str(_SCORE_COLUMN)}),
            bigint_columns=frozenset(
                {
                    str(_LEFT_RANK_COLUMN),
                    str(_RIGHT_RANK_COLUMN),
                    str(_PAIR_COUNT_COLUMN),
                    str(_DUPLICATE_COUNT_COLUMN),
                }
                & set(output_columns),
            ),
            text_columns=frozenset({str(_LEFT_IDENTITY_COLUMN), str(_RIGHT_IDENTITY_COLUMN)}),
        ),
    )
    return outer, output_columns, hints


class _USearchMatchingRowsStep(NonPublishingStep[list[dict[str, object]]]):
    def __init__(
        self: Self,
        ref_id: ServerPlanRefId,
        *,
        spool_ref: ServerPlanRefId,
        left_ref: ServerPlanRefId,
        right_ref: ServerPlanRefId,
        spec: MatchSpec[Any, Any],
    ) -> None:
        super().__init__(ref_id)
        self._spool_ref = spool_ref
        self._left_ref = left_ref
        self._right_ref = right_ref
        self._spec = spec

    @property
    def level(self: Self) -> int:
        return 0

    def execution_role(self: Self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def result_cardinality(self: Self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: Self) -> bool:
        return True

    def dependencies(self: Self) -> frozenset[str]:
        return frozenset(
            {str(self._spool_ref), str(self._left_ref), str(self._right_ref)},
        )

    def tables_read(self: Self) -> frozenset[str]:
        from impl.common.l2070_server_plan.steps.cross_branch import (
            _usearch_eligibility_spool_table,
            _usearch_score_spool_table,
        )

        return frozenset(
            {str(_usearch_score_spool_table()), str(_usearch_eligibility_spool_table())},
        )

    def tables_written(self: Self) -> frozenset[str]:
        return frozenset()

    def compile(self: Self, ctx: CompilationContext) -> CompiledStep[list[dict[str, object]]]:
        grammar, columns, hints = _native_matching_statement(
            ctx,
            self._spec,
            left_ref=self._left_ref,
            right_ref=self._right_ref,
            scope_id=str(self._spool_ref),
        )
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column, role="usearch_matching") for column in columns),
        )
        auxiliary_ctes = tuple(
            (binding.ref_id, binding.auxiliary_query)
            for ref_id in (self._left_ref, self._right_ref)
            if isinstance((binding := ctx.cte_refs.get(str(ref_id))), CteReference) and binding.auxiliary_query is not None
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=hints,
            grammar=grammar,
            auxiliary_ctes=auxiliary_ctes,
            needs_returning=True,
            closed_post_op=raw_rows_post_op(),
        )


@dataclass(frozen=True, slots=True)
class _USearchIntentConfig:
    spec: MatchSpec[Any, Any]
    left_source_ref: ServerPlanRefId
    right_source_ref: ServerPlanRefId
    query_field_name: str
    native_representation: MatchUSearchIndexRepresentationSpec[Any]
    query_vector: _CrossBranchUSearchQueryVector
    right_permission: SqlRenderable | None
    versioned_branch_id: BranchId | None
    versioned_revision_id: RevisionId | None


class USearchMatchIntent(IntentStep[MatchResult[LeftRowT, RightRowT]]):
    """One bounded native batch followed by SQL-owned result selection."""

    intent_tags = frozenset({"read", "matching", "usearch", "intent"})
    intent_cardinality = Cardinality.SCALAR
    intent_read_only = True

    def __init__(
        self: USearchMatchIntent[Any, Any],
        ref_id: ServerPlanRefId,
        config_ref: ScalarServerRef[_USearchIntentConfig],
    ) -> None:
        from impl.common.l2070_server_plan.steps.intent_query_extended import _require_seeded_config

        super().__init__(ref_id)
        config = _require_seeded_config(config_ref, type(self).__name__)
        self._spec = config.spec
        self._left_source_ref = config.left_source_ref
        self._right_source_ref = config.right_source_ref
        self._query_field_name = config.query_field_name
        self._native_representation = config.native_representation
        self._query_vector = config.query_vector
        self._right_permission = config.right_permission
        self._versioned_branch_id = config.versioned_branch_id
        self._versioned_revision_id = config.versioned_revision_id

    def lower(
        self: USearchMatchIntent[LeftRowT, RightRowT],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        return self._lower_usearch(ctx)

    def _lower_usearch(
        self: USearchMatchIntent[LeftRowT, RightRowT],
        ctx: LoweringContext,
    ) -> Sequence[ServerPlanStep[Any]]:
        from impl.common.l5250_matching.native_result_support import (
            _ExactDenseDecodeConfig,
            _ExactDenseDecodeStep,
            _ExactDensePreflightRowsStep,
            _ExactDenseWorkGuardStep,
        )
        from impl.common.l2050_sql_types.sql_branded_types import SqlIndexName

        preflight_rows_ref = ServerPlanRefId(f"{self.ref_id}_preflight_rows")
        guard_ref = ServerPlanRefId(f"{self.ref_id}_preflight")
        eligibility_ref = ServerPlanRefId(f"{self.ref_id}_eligibility")
        artifact_ref = ServerPlanRefId(f"{self.ref_id}_artifact")
        spool_ref = ServerPlanRefId(f"{self.ref_id}_native_batch")
        rows_ref = ServerPlanRefId(f"{self.ref_id}_rows")
        limits = get_usearch_request_limits()
        index_name = SqlIndexName(str(self._native_representation.index_name))
        sqlite_native = ctx.backend_profile.providers.vector_candidate_provider.uses_database_native_vector_scalars()
        from l7000_versioned_schema.versioned_schema import VersionedObjectRow

        sqlite_persistent = sqlite_native and not issubclass(
            self._spec.right.row_type,
            VersionedObjectRow,
        )
        eligibility_step: ServerPlanStep[Any] = (
            _PersistentMatchingEligibilityStep(
                eligibility_ref,
                source_ref=self._right_source_ref,
                limits=limits,
                permission=self._right_permission,
            )
            if sqlite_persistent
            else _SingleBranchUSearchEligibilityStep(
                eligibility_ref,
                source=_VisibleVectorSource(
                    model_cls=self._spec.right.row_type,
                    index_name=index_name,
                    source_query=None,
                    branch_ref_id=None,
                    source_ref_id=self._right_source_ref,
                    branch_id=self._versioned_branch_id,
                    revision_id=self._versioned_revision_id,
                ),
                limits=limits,
            )
        )
        artifact_steps: tuple[ServerPlanStep[Any], ...] = (
            ()
            if sqlite_persistent
            else (
                _CrossBranchUSearchArtifactStep(
                    artifact_ref,
                    model_cls=self._spec.right.row_type,
                    index_name=index_name,
                    limits=limits,
                ),
            )
        )
        return (
            _ExactDensePreflightRowsStep(
                preflight_rows_ref,
                self._spec,
                left_permission=None,
                right_permission=None,
                versioned_branch_id=None,
                left_source_ref=self._left_source_ref,
                right_source_ref=self._right_source_ref,
            ),
            _ExactDenseWorkGuardStep(
                guard_ref,
                source_ref=preflight_rows_ref,
                spec=self._spec,
            ),
            eligibility_step,
            *artifact_steps,
            _USearchMatchingBatchSpoolStep(
                spool_ref,
                artifact_ref_id=artifact_ref,
                eligibility_ref_id=eligibility_ref,
                query_ref_id=self._left_source_ref,
                guard_ref_id=guard_ref,
                query_model=self._spec.left.row_type,
                query_field_name=self._query_field_name,
                indexed_model=self._spec.right.row_type,
                index_name=str(self._native_representation.index_name),
                query_vector=self._query_vector,
                sqlite_native=sqlite_native,
                sqlite_persistent=sqlite_persistent,
            ),
            _USearchMatchingRowsStep(
                rows_ref,
                spool_ref=spool_ref,
                left_ref=self._left_source_ref,
                right_ref=self._right_source_ref,
                spec=self._spec,
            ),
            _ExactDenseDecodeStep(
                self.ref_id,
                config=_ExactDenseDecodeConfig(
                    source_ref=rows_ref,
                    preflight_rows_ref=preflight_rows_ref,
                    preflight_ref=guard_ref,
                    spec=self._spec,
                ),
            ),
        )


@pure_lazy
def build_usearch_match_intent(
    ref_id: ServerPlanRefId,
    spec: MatchSpec[LeftRowT, RightRowT],
    txn: LazyReadTransaction,
) -> USearchMatchIntent[LeftRowT, RightRowT]:
    """Bind a canonical native representation to its declared maintained index."""
    from impl.common.l2050_sql_types.sql_branded_types import SqlIndexName
    from l5200_vector_index.vector_config import get_vector_config

    left_representation = spec.left.representation
    right_representation = spec.right.representation
    if not isinstance(left_representation, MatchDenseVectorFieldRepresentationSpec):
        raise TypeError("USearch matching requires a packed dense left query field")
    if not isinstance(right_representation, MatchUSearchIndexRepresentationSpec):
        raise TypeError("USearch matching requires a maintained right index")
    config = get_vector_config(
        spec.right.row_type,
        str(right_representation.index_name),
    )
    if config is None:
        raise ValueError("USearch matching requires a declared right vector index")
    if config.metric is not right_representation.metric:
        raise ValueError("USearch matching metric does not match the declared index")
    if int(left_representation.dimensions) != int(right_representation.dimensions):
        raise ValueError("USearch matching endpoint dimensions must agree")
    from impl.common.l2070_server_plan.steps._permission_filter import (
        compile_permission_expression,
    )

    left_permission = compile_permission_expression(
        spec.left.row_type,
        txn.session_id,
        txn,
        table_alias=str(_LEFT_ALIAS),
    )
    right_permission = compile_permission_expression(
        spec.right.row_type,
        txn.session_id,
        txn,
        table_alias="visible_native_match",
    )
    left_source_ref = _projection_source_ref(
        txn,
        spec.left,
        spec.filters.left,
        permission_filter_required=left_permission is not None,
    )
    right_source_ref = _projection_source_ref(
        txn,
        spec.right,
        spec.filters.right,
        permission_filter_required=right_permission is not None,
    )
    query_vector = _CrossBranchUSearchQueryVector.for_index(
        spec.right.row_type,
        SqlIndexName(str(right_representation.index_name)),
        (0.0,) * int(right_representation.dimensions),
    )
    from l7000_versioned_schema.versioned_schema import VersionedObjectRow

    branch_value = getattr(txn, "branch_anchor", None)
    revision_value = getattr(txn, "revision_id", None)
    if issubclass(spec.right.row_type, VersionedObjectRow) and not (
        isinstance(branch_value, BranchId) or isinstance(revision_value, RevisionId)
    ):
        raise TypeError(
            "Versioned USearch matching requires a resolved branch or revision identity",
        )
    config_ref = ServerRefs.scalar(
        _USearchIntentConfig(
            spec=spec,
            left_source_ref=left_source_ref,
            right_source_ref=right_source_ref,
            query_field_name=str(left_representation.field_name),
            native_representation=right_representation,
            query_vector=query_vector,
            right_permission=right_permission,
            versioned_branch_id=(branch_value if isinstance(branch_value, BranchId) else None),
            versioned_revision_id=(revision_value if isinstance(revision_value, RevisionId) else None),
        ),
    )
    return USearchMatchIntent(ref_id, config_ref)


class _PersistentMatchingEligibilityStep(NonPublishingStep[list[dict[str, object]]]):
    """Publish bounded visible object identities for persistent SQLite scoring."""

    def __init__(
        self: Self,
        ref_id: ServerPlanRefId,
        *,
        source_ref: ServerPlanRefId,
        limits: Any,
        permission: SqlRenderable | None,
    ) -> None:
        super().__init__(ref_id)
        self._source_ref = source_ref
        self._limits = limits
        self._permission = permission

    @property
    def level(self: Self) -> int:
        return 0

    def execution_role(self: Self) -> StepExecutionRole:
        return StepExecutionRole.SQL

    def result_cardinality(self: Self) -> Cardinality:
        return Cardinality.MANY

    def is_read_only(self: Self) -> bool:
        return True

    def dependencies(self: Self) -> frozenset[str]:
        return frozenset({str(self._source_ref)})

    def tables_read(self: Self) -> frozenset[str]:
        return frozenset()

    def tables_written(self: Self) -> frozenset[str]:
        return frozenset()

    def compile(self: Self, ctx: CompilationContext) -> CompiledStep[list[dict[str, object]]]:
        binding = ctx.cte_refs.get(str(self._source_ref))
        if not isinstance(binding, CteReference):
            raise RuntimeError("Persistent matching eligibility requires a SQL relation")
        source_alias = SqlAliasName("visible_native_match")
        object_id = SqlColumnRef(SqlColumnName("sys_id"), qualifier=source_alias)
        grammar = SqlSelect(
            select=SqlSelectList(
                [
                    SqlSelectAlias(object_id, SqlAliasName("object_id")),
                    SqlSelectAlias(SqlParam(None), SqlAliasName("branch_id")),
                    SqlSelectAlias(SqlParam(None), SqlAliasName("revision_id")),
                    SqlSelectAlias(
                        SqlWindow(
                            func_name=FunctionKind.ROW_NUMBER,
                            order_by=(SqlOrderByItem(object_id, OrderDirection.ASC),),
                        ),
                        SqlAliasName("native_key"),
                    ),
                    SqlSelectAlias(SqlParam(None), SqlAliasName("chunk_id")),
                    SqlSelectAlias(SqlParam(None), SqlAliasName("chunk_metadata")),
                ],
            ),
            from_=SqlTableAlias(SqlTableIdent(SqlTableName(binding.ref_id)), source_alias),
            where=self._permission,
            limit=int(self._limits.max_eligibility_rows) + 1,
        )
        columns = (
            "object_id",
            "branch_id",
            "revision_id",
            "native_key",
            "chunk_id",
            "chunk_metadata",
        )
        output_shape = CompiledOutputShape(
            tuple(synthetic_output_field(column, role="usearch_matching_eligibility") for column in columns),
        )
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=SqlColumnTypeHints(
                text_columns=frozenset({"object_id", "branch_id", "revision_id", "chunk_id", "chunk_metadata"}),
                bigint_columns=frozenset({"native_key"}),
            ),
            grammar=grammar,
            auxiliary_ctes=(() if binding.auxiliary_query is None else ((binding.ref_id, binding.auxiliary_query),)),
            needs_returning=True,
            closed_post_op=raw_rows_post_op(),
        )

