"""Typed bounded public failures for generic matching."""

from __future__ import annotations
from typing import (
    Literal,
)
from l1470_matching_contracts.types import (
    MatchPairEvaluationCount,
    MatchBitComparisonCount,
    MatchStageOperationCount,
)

from typing import Annotated

from pydantic import BaseModel, ConfigDict, Field, field_validator

from l1470_matching_contracts.types import (
    MatchExpectedValue,
    MatchInvariant,
    MatchObservedValue,
    MatchSafeAction,
    MatchSpecRefId,
)

BoundedExpectedValue = Annotated[MatchExpectedValue, Field(max_length=256)]
BoundedObservedValue = Annotated[MatchObservedValue, Field(max_length=256)]
BoundedMatchSpecRefId = Annotated[MatchSpecRefId, Field(max_length=256)]


def _is_safe_context_token(value: str) -> bool:
    return all(character.isalnum() or character in "._:-" for character in value)


class MatchErrorContext(BaseModel):
    """Safe bounded context shared by all public matching failures."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    invariant: MatchInvariant
    expected: BoundedExpectedValue
    observed: BoundedObservedValue
    safe_action: MatchSafeAction
    spec_ref_id: BoundedMatchSpecRefId
    candidate_stage_operations: MatchStageOperationCount = MatchStageOperationCount(0)
    executed_work: "MatchErrorWork" = Field(default_factory=lambda: MatchUnobservedErrorWork())

    @field_validator("expected", "observed")
    @classmethod
    def _require_safe_context_token(
        cls: type[MatchErrorContext],
        value: MatchExpectedValue | MatchObservedValue,
    ) -> MatchExpectedValue | MatchObservedValue:
        if not _is_safe_context_token(value):
            msg = "matching error context values must be bounded machine-readable tokens"
            raise ValueError(msg)
        return value

    @field_validator("spec_ref_id")
    @classmethod
    def _require_safe_spec_ref_id(cls: type[MatchErrorContext], value: MatchSpecRefId) -> MatchSpecRefId:
        if not _is_safe_context_token(value):
            msg = "matching error specification identities must be bounded machine-readable tokens"
            raise ValueError(msg)
        return value


class MatchError(RuntimeError):
    """Base class for public matching failures."""

    context: MatchErrorContext

    def __init__(self: MatchError, context: MatchErrorContext) -> None:
        self.context = context
        super().__init__(context.invariant.value)


class MatchDeclarationError(MatchError):
    """A semantic declaration is invalid or internally inconsistent."""


class MatchCompatibilityError(MatchError):
    """Two declared semantic contracts are incompatible."""


class MatchMissingRepresentationError(MatchError):
    """A required endpoint representation is unavailable."""


class MatchFreshnessError(MatchError):
    """An artifact does not satisfy the declared freshness contract."""


class MatchWorkLimitError(MatchError):
    """A conservative work envelope exceeds a declared hard limit."""


class MatchPhysicalPlanError(MatchError):
    """The authoritative physical plan cannot execute safely."""


class MatchArtifactError(MatchError):
    """An artifact identity, generation, or fingerprint is invalid."""


class MatchResultCardinalityError(MatchError):
    """An exact result exceeds its declared publication bound."""


class MatchCursorError(MatchError):
    """A page cursor does not belong to the requested result snapshot."""


class MatchTransactionTypeError(MatchDeclarationError):
    """A matching data operation did not receive the required transaction kind."""


class MatchNotDeployedError(MatchPhysicalPlanError):
    """Executable matching is intentionally unavailable before Phase 2."""


class MatchUnknownVariantError(MatchDeclarationError):
    """Persisted closed dispatch received an unknown variant."""

class MatchUnobservedErrorWork(BaseModel):
    """No scorer work metrics are available for this failure."""

    model_config = ConfigDict(frozen=True, extra="forbid")
    kind: Literal["unobserved"] = "unobserved"


class MatchNativeErrorWork(BaseModel):
    """Executed native scorer work retained by a failed operation."""

    model_config = ConfigDict(frozen=True, extra="forbid")
    kind: Literal["native"] = "native"
    pair_evaluations: MatchPairEvaluationCount


class MatchH14ErrorWork(BaseModel):
    """Executed H14 scorer work retained by a failed operation."""

    model_config = ConfigDict(frozen=True, extra="forbid")
    kind: Literal["h14"] = "h14"
    bit_comparisons: MatchBitComparisonCount


class MatchExpressionEvaluationError(MatchError):
    """A typed score expression cannot produce a portable finite result."""


class MatchExpressionDeclarationError(MatchDeclarationError):
    """A typed score expression declaration is outside the closed grammar."""


class MatchAdministrativeAuthorizationError(MatchError):
    """The caller cannot access protected matching diagnostics."""

type MatchErrorWork = Annotated[
    MatchUnobservedErrorWork | MatchNativeErrorWork | MatchH14ErrorWork,
    Field(discriminator="kind"),
]

