"""Typed contracts for rank and score fusion."""

from __future__ import annotations

from enum import StrEnum
import hashlib
import json
import math
from typing import Annotated, Self

from pydantic import BaseModel, ConfigDict, SkipValidation, model_validator

from l1000_schema.schema_def import DatabaseObjectRow
from l1400_types import SysId
from l1470_matching_contracts.graph_producer_models import (
    MatchProducerFamily,
    MatchRepresentationProducerRefId,
)
from l1470_matching_contracts.models import GlobalTopKMatchResult, MatchRuntimeMetrics
from l1470_matching_contracts.types import (
    MatchArtifactFingerprint,
    MatchArtifactWatermark,
    MatchPairIdentity,
    MatchPermissionFitScope,
    MatchScoreDirection,
    MatchScoreValue,
    MatchSnapshotFingerprint,
    _MatchBrandedPositiveInt,
    _MatchBrandedString,
)


class MatchFusionInputId(_MatchBrandedString):
    """Stable identity of one input ranking or score source."""


class MatchFusionItemId(_MatchBrandedString):
    """Stable identity of one item shared by fusion inputs."""


class MatchOrdinalRank(_MatchBrandedPositiveInt):
    """One-based position in an input ranking."""


class MatchRawScoreValue(MatchScoreValue):
    """Finite diagnostic or source score before fusion."""


class MatchFusionWeight(MatchScoreValue):
    """Positive contribution weight for one fusion source."""


class MatchCombinerIntercept(MatchScoreValue):
    """Finite intercept of one learned score combiner."""


class MatchFusedScoreValue(MatchScoreValue):
    """Finite score emitted by a fusion method."""


class MatchOrdinalRankInput(BaseModel, frozen=True):
    """One ranked item with an unused diagnostic source score."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    input_id: MatchFusionInputId
    item_id: MatchFusionItemId
    rank: MatchOrdinalRank
    raw_score: MatchRawScoreValue

    @model_validator(mode="after")
    def validate_score(self: Self) -> Self:
        if not math.isfinite(self.raw_score):
            raise ValueError("Fusion input raw score must be finite")
        return self


class MatchScoreNormalization(StrEnum):
    """Closed normalization rules for weighted fusion."""

    MIN_MAX = "min_max"


class MatchScoreDomainMode(StrEnum):
    """Absence mode for fusion calls that do not fit a combiner."""

    UNDECLARED = "undeclared"


class MatchWeightedFusionInput(BaseModel, frozen=True):
    """One finite source score for one fusion item."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    input_id: MatchFusionInputId
    item_id: MatchFusionItemId
    raw_score: MatchRawScoreValue

    @model_validator(mode="after")
    def validate_score(self: Self) -> Self:
        if not math.isfinite(self.raw_score):
            raise ValueError("Weighted fusion source score must be finite")
        return self


class MatchInputScoreDomain(BaseModel, frozen=True):
    """Closed finite source-score interval used by a weighted combiner."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    minimum: MatchRawScoreValue
    maximum: MatchRawScoreValue

    @model_validator(mode="after")
    def validate_domain(self: Self) -> Self:
        if not math.isfinite(self.minimum) or not math.isfinite(self.maximum):
            raise ValueError("Fusion score-domain bounds must be finite")
        if self.minimum >= self.maximum:
            raise ValueError("Fusion score-domain minimum must be below its maximum")
        return self


class MatchWeightedFusionSpec(BaseModel, frozen=True):
    """Weight and complete score semantics for one fusion source."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    input_id: MatchFusionInputId
    input_domain: MatchInputScoreDomain | MatchScoreDomainMode = MatchScoreDomainMode.UNDECLARED
    weight: MatchFusionWeight
    normalization: MatchScoreNormalization
    direction: MatchScoreDirection

    @model_validator(mode="after")
    def validate_weight(self: Self) -> Self:
        if not math.isfinite(self.weight) or self.weight <= 0:
            raise ValueError("Weighted fusion weights must be finite and positive")
        return self


class MatchWeightedScoreCombinerSpec(BaseModel, frozen=True):
    """Complete weighted-fusion declaration with final score direction."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    inputs: tuple[MatchWeightedFusionSpec, ...]
    final_direction: MatchScoreDirection

    @model_validator(mode="after")
    def validate_combiner(self: Self) -> Self:
        if not self.inputs:
            raise ValueError("Weighted combiner requires at least one input")
        if any(spec.input_domain is MatchScoreDomainMode.UNDECLARED for spec in self.inputs):
            raise ValueError("Weighted combiner inputs require declared score domains")
        if len({spec.input_id for spec in self.inputs}) != len(self.inputs):
            raise ValueError("Weighted combiner inputs require distinct identities")
        if not math.isclose(math.fsum(spec.weight for spec in self.inputs), 1.0, abs_tol=1e-12):
            raise ValueError("Weighted combiner weights must sum to one")
        return self


class MatchFusionEndpointPair(BaseModel, frozen=True):
    """Typed endpoint pair addressed by one fusion item identity."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    item_id: MatchFusionItemId
    pair_identity: MatchPairIdentity
    left: Annotated[DatabaseObjectRow[SysId], SkipValidation]
    right: Annotated[DatabaseObjectRow[SysId], SkipValidation]


class MatchProducerGlobalTopKResult(
    GlobalTopKMatchResult[DatabaseObjectRow[SysId], DatabaseObjectRow[SysId]],
):
    """Public global matching result produced by one Phase 8 family."""

    producer_family: MatchProducerFamily
    visibility_scope: MatchPermissionFitScope
    runtime_metrics: MatchRuntimeMetrics


class MatchLearnedCombinerArtifactId(_MatchBrandedString):
    """Content identity of one fitted learned combiner."""


class MatchLearnedCombinerAlgorithm(StrEnum):
    """Closed fitted-combiner algorithm family."""

    LINEAR = "linear"


class MatchLearnedCombinerImplementationVersion(_MatchBrandedString):
    """Stable implementation identity of a learned combiner."""


class MatchLearnedCombinerArtifact(BaseModel, frozen=True):
    """Immutable linear combiner bound to fit population and watermark."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    producer_ref_id: MatchRepresentationProducerRefId
    algorithm: MatchLearnedCombinerAlgorithm
    implementation_version: MatchLearnedCombinerImplementationVersion
    feature_inputs: tuple[MatchFusionInputId, ...]
    coefficients: tuple[float, ...]
    intercept: MatchCombinerIntercept
    training_fingerprint: MatchArtifactFingerprint
    source_snapshot: MatchSnapshotFingerprint
    fit_scope: MatchPermissionFitScope
    source_watermark: MatchArtifactWatermark

    @model_validator(mode="after")
    def validate_artifact(self: Self) -> Self:
        if self.algorithm is not MatchLearnedCombinerAlgorithm.LINEAR:
            raise ValueError("Learned combiner algorithm must be linear")
        if not self.implementation_version:
            raise ValueError("Learned combiner implementation version cannot be empty")
        if not self.feature_inputs or len(set(self.feature_inputs)) != len(self.feature_inputs):
            raise ValueError("Learned combiner feature inputs must be nonempty and distinct")
        if len(self.coefficients) != len(self.feature_inputs):
            raise ValueError("Learned combiner requires one coefficient per feature input")
        if not math.isfinite(self.intercept) or any(
            not math.isfinite(value) for value in self.coefficients
        ):
            raise ValueError("Learned combiner parameters must be finite")
        return self

    @property
    def artifact_id(self: MatchLearnedCombinerArtifact) -> MatchLearnedCombinerArtifactId:
        """Bind model parameters to complete fit authority."""
        payload = {
            "algorithm": self.algorithm,
            "coefficients": [format(value, ".17g") for value in self.coefficients],
            "feature_inputs": [str(value) for value in self.feature_inputs],
            "fit_scope": str(self.fit_scope),
            "implementation_version": self.implementation_version,
            "intercept": format(self.intercept, ".17g"),
            "producer_ref_id": str(self.producer_ref_id),
            "source_snapshot": str(self.source_snapshot),
            "source_watermark": int(self.source_watermark),
            "training_fingerprint": str(self.training_fingerprint),
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()
        return MatchLearnedCombinerArtifactId(
            f"learned-combiner:{hashlib.sha256(encoded).hexdigest()}",
        )


class MatchFusedScore(BaseModel, frozen=True):
    """One canonically ordered fused item score."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    item_id: MatchFusionItemId
    score: MatchFusedScoreValue
    rank: MatchOrdinalRank

    @model_validator(mode="after")
    def validate_score(self: Self) -> Self:
        if not math.isfinite(self.score):
            raise ValueError("Fused score must be finite")
        return self

