"""Immutable contracts for graph-derived matching representations."""

from __future__ import annotations

import hashlib
import json
from enum import StrEnum
import math
from typing import Annotated, Literal, Self

from pydantic import (
    AliasChoices,
    BaseModel,
    ConfigDict,
    Field,
    SkipValidation,
    field_validator,
    model_validator,
)

from l1000_schema.schema_def import DatabaseObjectRow
from l1400_types import SysId
from l9600_graphs.graph_types import GraphId
from l1470_matching_contracts.producer_lifecycle_models import (
    MatchProducerDeterminism,
    MatchProducerInputSpec,
    MatchProducerLifecycleDefaults,
    MatchProducerOutputSpec,
    MatchProducerUpdateMode,
)
from l1470_matching_contracts.types import (
    MatchArtifactFingerprint,
    MatchArtifactWatermark,
    MatchPermissionFitScope,
    MatchProducerCallCount,
    MatchScoreValue,
    MatchSnapshotFingerprint,
    MatchVectorDimensions,
    _MatchBrandedNonnegativeInt,
    _MatchBrandedPositiveInt,
    _MatchBrandedString,
)


class MatchProducerFamily(StrEnum):
    """Closed Phase 8 representation-producer families."""

    PAGE_RANK = "pagerank"
    PERSONALIZED_PAGE_RANK = "personalized_pagerank"
    BIPARTITE_SVD = "bipartite_svd"
    SPECTRAL = "spectral"
    EXTERNAL_MODEL = "external_model"
    PROJECTION = "projection"


class MatchProducerCoordinate(BaseModel, frozen=True):
    """One permission-approved polymorphic producer output."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    family: MatchProducerFamily
    visibility_scope: MatchPermissionFitScope
    node_id: SysId
    node: Annotated[DatabaseObjectRow[SysId], SkipValidation]
    values: tuple[float, ...]

    @model_validator(mode="after")
    def validate_coordinate(self: Self) -> Self:
        if self.node.sys_id != self.node_id:
            raise ValueError("Producer coordinate node must match its declared identity")
        if not self.values or any(not math.isfinite(value) for value in self.values):
            raise ValueError("Producer coordinate values must be nonempty and finite")
        return self


class MatchProducerArtifactId(_MatchBrandedString):
    """Identity of one materialized producer representation generation."""


class MatchPageRankArtifactId(_MatchBrandedString):
    """Identity of one PageRank representation generation."""


class MatchRepresentationProducerRefId(_MatchBrandedString):
    """Stable identity of one representation producer declaration."""


class MatchGraphIdentity(_MatchBrandedString):
    """Stable identity of the graph consumed by a producer."""


class MatchGraphEdgeVisitLimit(_MatchBrandedPositiveInt):
    """Maximum selected graph edges a PageRank producer can visit."""

    def __new__(cls: type[Self], value: int | Self) -> Self:
        limit = super().__new__(cls, value)
        if limit > 480:
            raise ValueError("PageRank edge visit limit cannot exceed 480")
        return limit


class MatchGraphEdgeVisitCount(_MatchBrandedNonnegativeInt):
    """Observed graph edges visited by one producer execution."""


class MatchMatrixCellEvaluationCount(_MatchBrandedNonnegativeInt):
    """Observed matrix cells evaluated by one producer execution."""


class MatchMatrixCellEvaluationLimit(_MatchBrandedPositiveInt):
    """Maximum matrix cells one bounded producer can evaluate."""

    def __new__(cls: type[Self], value: int | Self) -> Self:
        limit = super().__new__(cls, value)
        if limit > 1_000_000:
            raise ValueError("Matrix cell evaluation limit cannot exceed 1000000")
        return limit


class MatchProducerWorkMetrics(BaseModel, frozen=True):
    """Observed graph and matrix work checked against declared limits."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    graph_edge_visit_count: MatchGraphEdgeVisitCount
    graph_edge_visit_limit: MatchGraphEdgeVisitLimit
    matrix_cell_evaluation_count: MatchMatrixCellEvaluationCount
    matrix_cell_evaluation_limit: MatchMatrixCellEvaluationLimit
    provider_call_count: MatchProducerCallCount = MatchProducerCallCount(0)

    @model_validator(mode="after")
    def validate_bounds(self: Self) -> Self:
        if self.graph_edge_visit_count > self.graph_edge_visit_limit:
            raise ValueError("Graph edge visit count exceeds its declared limit")
        if self.matrix_cell_evaluation_count > self.matrix_cell_evaluation_limit:
            raise ValueError("Matrix cell evaluation count exceeds its declared limit")
        return self


class MatchBoundedProducerExecution(BaseModel, frozen=True):
    """Numeric producer outputs with exact work instrumentation."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    edge_outputs: tuple[float, ...]
    matrix_outputs: tuple[float, ...]
    metrics: MatchProducerWorkMetrics

    @model_validator(mode="after")
    def validate_outputs(self: Self) -> Self:
        outputs = self.edge_outputs + self.matrix_outputs
        if any(not math.isfinite(value) for value in outputs):
            raise ValueError("Bounded producer outputs must be finite")
        if len(self.edge_outputs) != self.metrics.graph_edge_visit_count:
            raise ValueError("Graph output count must equal the graph work counter")
        if len(self.matrix_outputs) != self.metrics.matrix_cell_evaluation_count:
            raise ValueError("Matrix output count must equal the matrix work counter")
        return self


class MatchProducerNodeLimit(_MatchBrandedPositiveInt):
    """Maximum visible nodes consumed by one producer execution."""


class MatchProducerSeedLimit(_MatchBrandedNonnegativeInt):
    """Maximum graph seeds consumed by one producer execution."""


class MatchProducerMaterializationLimit(_MatchBrandedPositiveInt):
    """Maximum coordinates materialized by one producer execution."""


class MatchPageRankIterationLimit(_MatchBrandedPositiveInt):
    """Maximum PageRank iterations admitted by one execution."""


class MatchPageRankIterationCount(_MatchBrandedPositiveInt):
    """Executed or selected positive PageRank iteration count."""


class MatchGraphSeedWeight(MatchScoreValue):
    """Positive finite restart weight of one graph seed."""


class MatchRestartProbability(MatchScoreValue):
    """Finite PageRank restart probability in the interval (0, 1]."""


class MatchEdgeSelectionFingerprintMode(StrEnum):
    """Closed derivation mode for graph edge-selection identity."""

    CANONICAL = "canonical"


class MatchPageRankComplexityContract(BaseModel, frozen=True):
    """Conservative graph, iteration, seed, and materialization costs."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    visible_node_limit: MatchProducerNodeLimit
    graph_edge_visit_limit: MatchGraphEdgeVisitLimit
    iteration_limit: MatchPageRankIterationLimit
    seed_limit: MatchProducerSeedLimit
    materialized_coordinate_limit: MatchProducerMaterializationLimit

    @model_validator(mode="after")
    def validate_iterations(self: Self) -> Self:
        if self.iteration_limit <= 0 or self.iteration_limit > 25:
            raise ValueError("PageRank complexity iterations must be between 1 and 25")
        return self

    @property
    def graph_edge_visit_upper_bound(self: MatchPageRankComplexityContract) -> int:
        """Return the maximum edge visits across all iterations."""
        return int(self.graph_edge_visit_limit) * self.iteration_limit

    @property
    def operation_upper_bound(self: MatchPageRankComplexityContract) -> int:
        """Return the declared graph and materialization operation envelope."""
        return (
            self.iteration_limit
            * (int(self.visible_node_limit) + int(self.graph_edge_visit_limit))
            + int(self.seed_limit)
            + int(self.materialized_coordinate_limit)
        )


class MatchGraphSeedIdentity(BaseModel, frozen=True):
    """One node and weight in a personalized graph restart distribution."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    node_id: SysId
    weight: MatchGraphSeedWeight

    @field_validator("weight")
    @classmethod
    def validate_weight(cls, value: MatchGraphSeedWeight) -> MatchGraphSeedWeight:
        if not math.isfinite(value) or value <= 0:
            raise ValueError("Graph seed weight must be finite and positive")
        return value


class MatchPageRankGraphSourceSpec(BaseModel, frozen=True):
    """Typed graph source resolved under the caller transaction snapshot."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    graph_row_type: Annotated[type[DatabaseObjectRow[SysId]], SkipValidation]
    node_row_type: Annotated[type[DatabaseObjectRow[SysId]], SkipValidation]
    graph_id: GraphId
    edge_selectors: tuple[Annotated[object, SkipValidation], ...]
    edge_selection_fingerprint: MatchArtifactFingerprint | MatchEdgeSelectionFingerprintMode = (
        MatchEdgeSelectionFingerprintMode.CANONICAL
    )

    @property
    def graph_identity(self: MatchPageRankGraphSourceSpec) -> MatchGraphIdentity:
        """Return the stable graph identity selected by this source."""
        return MatchGraphIdentity(str(self.graph_id))

    @property
    def selector_fingerprint(self: MatchPageRankGraphSourceSpec) -> MatchArtifactFingerprint:
        """Return the declared or canonical edge-selection identity."""
        if isinstance(self.edge_selection_fingerprint, MatchArtifactFingerprint):
            return self.edge_selection_fingerprint
        payload = tuple(str(selector) for selector in self.edge_selectors)
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()
        return MatchArtifactFingerprint(hashlib.sha256(encoded).hexdigest())


def _default_page_rank_complexity() -> MatchPageRankComplexityContract:
    return MatchPageRankComplexityContract(
        visible_node_limit=MatchProducerNodeLimit(128),
        graph_edge_visit_limit=MatchGraphEdgeVisitLimit(480),
        iteration_limit=MatchPageRankIterationLimit(25),
        seed_limit=MatchProducerSeedLimit(128),
        materialized_coordinate_limit=MatchProducerMaterializationLimit(128),
    )


class MatchPageRankProducerSpec(BaseModel, frozen=True):
    """Content-addressed bounded PageRank producer declaration."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    producer_ref_id: MatchRepresentationProducerRefId
    algorithm: Literal["pagerank", "personalized_pagerank"]
    graph_source: MatchPageRankGraphSourceSpec
    restart_probability: MatchRestartProbability
    iterations: MatchPageRankIterationCount
    edge_visit_limit: MatchGraphEdgeVisitLimit
    seeds: tuple[MatchGraphSeedIdentity, ...] = ()
    visibility_scope: MatchPermissionFitScope
    fit_scope: MatchPermissionFitScope = Field(
        default=MatchPermissionFitScope("derive:visibility-scope"),
        validation_alias=AliasChoices("fit_scope", "visibility_scope"),
    )
    output_role: Literal[
        "stored_representation",
        "query_representation",
        "scored_candidate_relation",
    ]
    input_spec: MatchProducerInputSpec = Field(
        default_factory=MatchProducerLifecycleDefaults.input_spec,
    )
    output_spec: MatchProducerOutputSpec = Field(
        default_factory=MatchProducerLifecycleDefaults.output_spec,
    )
    determinism: MatchProducerDeterminism = MatchProducerDeterminism.DETERMINISTIC
    update_mode: MatchProducerUpdateMode = MatchProducerUpdateMode.SNAPSHOT_RECOMPUTE
    source_watermark: MatchArtifactWatermark = MatchArtifactWatermark(0)
    complexity: MatchPageRankComplexityContract = Field(
        default_factory=_default_page_rank_complexity,
    )

    @model_validator(mode="after")
    def validate_producer(self: Self) -> Self:
        if self.fit_scope != self.visibility_scope:
            raise ValueError("PageRank fit scope must equal its visibility scope")
        if not math.isfinite(self.restart_probability) or not 0 < self.restart_probability <= 1:
            raise ValueError("PageRank restart probability must be finite and in (0, 1]")
        if self.iterations <= 0 or self.iterations > 25:
            raise ValueError("PageRank iterations must be between 1 and 25")
        if self.algorithm == "pagerank" and self.seeds:
            raise ValueError("Uniform PageRank cannot declare personalized seeds")
        if self.algorithm == "personalized_pagerank" and not self.seeds:
            raise ValueError("Personalized PageRank requires at least one seed")
        node_ids = tuple(seed.node_id for seed in self.seeds)
        if len(set(node_ids)) != len(node_ids):
            raise ValueError("PageRank seeds require distinct node identities")
        object.__setattr__(self, "seeds", tuple(sorted(self.seeds, key=lambda seed: str(seed.node_id))))
        if (
            self.iterations > self.complexity.iteration_limit
            or self.edge_visit_limit > self.complexity.graph_edge_visit_limit
            or len(self.seeds) > self.complexity.seed_limit
        ):
            raise ValueError("PageRank declaration exceeds its complexity contract")
        return self

    @property
    def graph_identity(self: MatchPageRankProducerSpec) -> MatchGraphIdentity:
        """Return the graph identity selected by the typed source."""
        return self.graph_source.graph_identity

    def artifact_id_for(
        self: MatchPageRankProducerSpec,
        source_snapshot: MatchSnapshotFingerprint,
    ) -> MatchPageRankArtifactId:
        """Return the complete semantic producer fingerprint for one snapshot."""
        payload = {
            "algorithm": self.algorithm,
            "edge_selection_fingerprint": str(self.graph_source.selector_fingerprint),
            "edge_visit_limit": int(self.edge_visit_limit),
            "graph_identity": str(self.graph_identity),
            "iterations": self.iterations,
            "output_role": self.output_role,
            "producer_ref_id": str(self.producer_ref_id),
            "restart_probability": format(self.restart_probability, ".17g"),
            "seeds": [
                {"node_id": str(seed.node_id), "weight": format(seed.weight, ".17g")}
                for seed in self.seeds
            ],
            "source_snapshot": str(source_snapshot),
            "source_watermark": int(self.source_watermark),
            "visibility_scope": str(self.visibility_scope),
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return MatchPageRankArtifactId(f"pagerank:{hashlib.sha256(encoded.encode()).hexdigest()}")


class MatchPageRankExecutionMetrics(BaseModel, frozen=True):
    """Authoritative graph work observed by the transaction executor."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    graph_identity: MatchGraphIdentity
    source_snapshot: MatchSnapshotFingerprint
    edge_visit_count: MatchGraphEdgeVisitCount
    iteration_count: MatchPageRankIterationCount

    @model_validator(mode="after")
    def validate_counts(self: Self) -> Self:
        if self.iteration_count <= 0:
            raise ValueError("PageRank metrics iteration count must be positive")
        return self


class MatchPageRankCoordinate(BaseModel, frozen=True):
    """One graph node coordinate in a PageRank representation."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    node_id: SysId
    node: Annotated[DatabaseObjectRow[SysId], SkipValidation]
    value: MatchScoreValue

    @model_validator(mode="after")
    def validate_node_identity(self: Self) -> Self:
        if self.node.sys_id != self.node_id:
            raise ValueError("PageRank coordinate node must match its declared identity")
        return self


class MatchPageRankRepresentation(BaseModel, frozen=True):
    """Canonical node-ordered output from one bounded PageRank execution."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    kind: Literal["pagerank"] = "pagerank"
    artifact_id: MatchPageRankArtifactId
    producer_ref_id: MatchRepresentationProducerRefId
    graph_identity: MatchGraphIdentity
    source_snapshot: MatchSnapshotFingerprint
    source_watermark: MatchArtifactWatermark
    visibility_scope: MatchPermissionFitScope
    output_role: Literal[
        "stored_representation",
        "query_representation",
        "scored_candidate_relation",
    ]
    dimensions: MatchVectorDimensions
    iterations: MatchPageRankIterationCount
    termination: Literal["fixed_iterations", "converged", "max_iterations"]
    coordinates: tuple[MatchPageRankCoordinate, ...]
    work_metrics: MatchProducerWorkMetrics

    @model_validator(mode="after")
    def validate_coordinates(self: Self) -> Self:
        if self.iterations <= 0:
            raise ValueError("PageRank representation requires a positive iteration count")
        if len(self.coordinates) != self.dimensions:
            raise ValueError("PageRank coordinate count must equal declared dimensions")
        node_ids = tuple(coordinate.node_id for coordinate in self.coordinates)
        if len(set(node_ids)) != len(node_ids):
            raise ValueError("PageRank coordinates require distinct node identities")
        if node_ids != tuple(sorted(node_ids, key=str)):
            raise ValueError("PageRank coordinates must use canonical node identity order")
        if any(coordinate.value < 0 for coordinate in self.coordinates):
            raise ValueError("PageRank coordinates must be nonnegative")
        return self

