"""Persistable operator-owned compatibility records for native exact matching."""

from __future__ import annotations

import hashlib
import math
from enum import StrEnum
from typing import Literal, Self

from pydantic import BaseModel, ConfigDict, model_validator

from l1470_matching_contracts.types import (
    MatchCompatibilityVersion,
    MatchPlanIdentity,
    MatchVectorDimensions,
)


class NativeExactExecutionStrategy(StrEnum):
    """Closed exact scan shapes selected before physical execution."""

    PER_LEFT_LATERAL = "per_left_lateral"
    BATCH_SCAN = "batch_scan"


class NativeExactScoreSchedule(StrEnum):
    """Closed scoring schedules executed by native exact plans."""

    RESULT_ONLY = "result_only"
    THRESHOLD_PREFLIGHT_AND_RESULT = "threshold_preflight_and_result"

    @property
    def pass_count(self: NativeExactScoreSchedule) -> Literal[1, 2]:
        return 2 if self is NativeExactScoreSchedule.THRESHOLD_PREFLIGHT_AND_RESULT else 1


class NativeEstimatedRowCount(int):
    """Nonnegative cardinality estimate used only by physical planning."""


class NativeCostEstimate(float):
    """Finite nonnegative physical work estimate."""


class NativeExactExecutionInputs(BaseModel, frozen=True):
    """Authorized cardinality estimates consumed by the exact cost model."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    left_rows: NativeEstimatedRowCount
    right_rows: NativeEstimatedRowCount
    selected_right_rows: NativeEstimatedRowCount
    dimensions: MatchVectorDimensions
    score_schedule: NativeExactScoreSchedule = NativeExactScoreSchedule.RESULT_ONLY

    @model_validator(mode="before")
    @classmethod
    def reject_wrong_brands(cls: type[NativeExactExecutionInputs], values: object) -> object:
        if not isinstance(values, dict):
            return values
        for name in ("left_rows", "right_rows", "selected_right_rows"):
            value = values.get(name)
            if type(value) is int:
                values = {**values, name: NativeEstimatedRowCount(value)}
            elif not isinstance(value, NativeEstimatedRowCount):
                raise ValueError(f"{name} requires a native row-count estimate")
        dimensions = values.get("dimensions")
        if type(dimensions) is int:
            values = {**values, "dimensions": MatchVectorDimensions(dimensions)}
        elif not isinstance(dimensions, MatchVectorDimensions):
            raise ValueError("dimensions requires MatchVectorDimensions")
        return values

    @model_validator(mode="after")
    def validate_counts(self: Self) -> Self:
        if min(self.left_rows, self.right_rows, self.selected_right_rows) < 0:
            raise ValueError("Native exact cost inputs must be nonnegative")
        if self.dimensions <= 0:
            raise ValueError("Native exact dimensions must be positive")
        if self.selected_right_rows > self.right_rows:
            raise ValueError("selected rows cannot exceed the right relation")
        return self


class NoNativeExactPlanChoice(BaseModel, frozen=True):
    """Nominal absence for matching kernels without a native exact profile."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    kind: Literal["none"] = "none"


def _native_score_work(inputs: NativeExactExecutionInputs) -> NativeCostEstimate:
    return NativeCostEstimate(
        int(inputs.left_rows) * int(inputs.right_rows) * int(inputs.dimensions)
        * inputs.score_schedule.pass_count,
    )


def _native_choice_values(
    inputs: NativeExactExecutionInputs,
) -> tuple[NativeExactExecutionStrategy, NativeCostEstimate, NativeCostEstimate, MatchPlanIdentity]:
    score_work = _native_score_work(inputs)
    lateral_cost = NativeCostEstimate(
        int(inputs.left_rows) * math.log2(int(inputs.right_rows) + 1) + score_work,
    )
    batch_scan_cost = NativeCostEstimate(int(inputs.right_rows) + score_work)
    strategy = (
        NativeExactExecutionStrategy.PER_LEFT_LATERAL
        if lateral_cost < batch_scan_cost
        else NativeExactExecutionStrategy.BATCH_SCAN
    )
    payload = f"native-exact-cost-v3|{inputs.model_dump_json()}|{strategy.value}|{lateral_cost}|{batch_scan_cost}"
    identity = MatchPlanIdentity(hashlib.sha256(payload.encode("utf-8")).hexdigest())
    return strategy, lateral_cost, batch_scan_cost, identity


class NativeExactPlanChoice(BaseModel, frozen=True):
    """Persistable, self-verifying choice for exact physical profiles."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    kind: Literal["native_exact"] = "native_exact"
    model_version: Literal["native-exact-cost-v3"] = "native-exact-cost-v3"
    inputs: NativeExactExecutionInputs
    strategy: NativeExactExecutionStrategy
    lateral_cost: NativeCostEstimate
    batch_scan_cost: NativeCostEstimate
    plan_identity: MatchPlanIdentity

    @property
    def estimated_score_work(self: NativeExactPlanChoice) -> NativeCostEstimate:
        """Estimate coordinate work across all planned scoring passes."""
        return _native_score_work(self.inputs)

    @model_validator(mode="before")
    @classmethod
    def restore_cost_brands(cls: type[NativeExactPlanChoice], values: object) -> object:
        if not isinstance(values, dict):
            return values
        restored = dict(values)
        for name in ("lateral_cost", "batch_scan_cost"):
            value = restored.get(name)
            if type(value) is int or type(value) is float:
                restored[name] = NativeCostEstimate(value)
            elif not isinstance(value, NativeCostEstimate):
                raise ValueError(f"{name} requires a native cost estimate")
        return restored

    @model_validator(mode="after")
    def verify_derived_fields(self: Self) -> Self:
        for cost in (self.lateral_cost, self.batch_scan_cost):
            if not math.isfinite(cost) or cost < 0:
                raise ValueError("Native exact costs must be finite and nonnegative")
        expected = _native_choice_values(self.inputs)
        observed = (self.strategy, self.lateral_cost, self.batch_scan_cost, self.plan_identity)
        if observed != expected:
            raise ValueError("Native exact choice must match its immutable cost inputs")
        return self


def select_native_exact_strategy(inputs: NativeExactExecutionInputs) -> NativeExactPlanChoice:
    """Compare deterministic operation estimates and use batch scan on ties."""
    strategy, lateral_cost, batch_scan_cost, identity = _native_choice_values(inputs)
    return NativeExactPlanChoice(
        inputs=inputs,
        strategy=strategy,
        lateral_cost=lateral_cost,
        batch_scan_cost=batch_scan_cost,
        plan_identity=identity,
    )


class PgvectorPhysicalType(StrEnum):
    """Concrete extension storage families, not interchangeable semantic aliases."""

    VECTOR = "vector"
    HALFVEC = "halfvec"
    SPARSEVEC = "sparsevec"
    BIT = "bit"


class PgvectorMetric(StrEnum):
    """Exact native metric families admitted by the matching profile."""

    INNER_PRODUCT = "inner_product"
    COSINE = "cosine"
    L2 = "l2"
    HAMMING = "hamming"


class NativeExactVectorProfile(BaseModel, frozen=True):
    """One extension-version-bound exact physical contract without ANN parameters."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    kind: Literal["pgvector_exact_v1"] = "pgvector_exact_v1"
    extension_version: MatchCompatibilityVersion
    physical_type: PgvectorPhysicalType
    metric: PgvectorMetric
    dimensions: MatchVectorDimensions
    exact: Literal[True] = True

    @model_validator(mode="after")
    def validate_compatibility(self: Self) -> Self:
        if (self.physical_type is PgvectorPhysicalType.BIT) != (self.metric is PgvectorMetric.HAMMING):
            raise ValueError("Native vector physical type and metric are incompatible")
        parts = self.extension_version.split(".")
        if len(parts) != 3 or any(not part.isdecimal() for part in parts):
            raise ValueError("pgvector extension version must be an exact major.minor.patch version")
        version = tuple(int(part) for part in parts)
        if self.physical_type is not PgvectorPhysicalType.VECTOR and version < (0, 7, 0):
            raise ValueError("halfvec, sparsevec and bit operators require pgvector 0.7 or later")
        if version < (0, 5, 0):
            raise ValueError("Native matching requires pgvector 0.5 or later")
        return self

    @property
    def operator(self: NativeExactVectorProfile) -> str:
        """Return the extension operator fixed by the metric."""
        match self.metric:
            case PgvectorMetric.INNER_PRODUCT:
                return "<#>"
            case PgvectorMetric.COSINE:
                return "<=>"
            case PgvectorMetric.L2:
                return "<->"
            case PgvectorMetric.HAMMING:
                return "<~>"

    @property
    def operator_class(self: NativeExactVectorProfile) -> str:
        """Identify the compatible operator family, without admitting ANN execution."""
        match self.metric:
            case PgvectorMetric.INNER_PRODUCT:
                suffix = "ip_ops"
            case PgvectorMetric.COSINE:
                suffix = "cosine_ops"
            case PgvectorMetric.L2:
                suffix = "l2_ops"
            case PgvectorMetric.HAMMING:
                suffix = "hamming_ops"
        return f"{self.physical_type.value}_{suffix}"

    def identity(self: NativeExactVectorProfile) -> MatchPlanIdentity:
        """Include concrete operator semantics as well as all persisted profile fields."""
        payload = "\0".join((self.model_dump_json(), self.operator, self.operator_class))
        return MatchPlanIdentity(hashlib.sha256(payload.encode("utf-8")).hexdigest())

    def verify_extension(self: NativeExactVectorProfile, installed: MatchCompatibilityVersion) -> None:
        """Reject extension drift instead of resolving another profile during execution."""
        if installed != self.extension_version:
            raise ValueError("pgvector extension drift requires a physical-plan migration")


class NativeExactDeploymentPlan(BaseModel, frozen=True):
    """Operator-owned physical profile and immutable cost-model decision."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    profile: NativeExactVectorProfile
    choice: NativeExactPlanChoice

    @model_validator(mode="after")
    def validate_one_physical_contract(self: Self) -> Self:
        if self.profile.dimensions != self.choice.inputs.dimensions:
            raise ValueError("Native deployment dimensions must match cost-model inputs")
        if self.profile.metric is not PgvectorMetric.INNER_PRODUCT:
            raise ValueError("Phase 7 exact dense deployment requires inner product")
        if self.profile.physical_type is not PgvectorPhysicalType.VECTOR:
            raise ValueError("Exact fp32 deployment requires vector storage")
        return self

