"""Immutable tensor and packed-code contracts for H14 V1 artifacts."""

from __future__ import annotations

import base64
import binascii
import hashlib
import json
import math
from enum import StrEnum
from typing import Annotated, Literal, Self

from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    Field as PydanticField,
    GetCoreSchemaHandler,
    SkipValidation,
    field_validator,
    model_validator,
)
from pydantic_core import CoreSchema, core_schema, to_jsonable_python

from l1000_schema.schema_def import DatabaseObjectRow
from l1400_types import SysId
from l2055_lazy_result.purity import pure_lazy
from l1470_matching_contracts.types import (
    MatchArtifactFingerprint,
    MatchArtifactScopeValue,
    MatchFieldName,
    MatchPermissionFitScope,
    MatchRepresentationRefId,
    MatchVectorDimensions,
    _MatchBrandedNonnegativeInt,
    _MatchBrandedPositiveInt,
    _MatchBrandedString,
)


class MatchProjectionArtifactId(_MatchBrandedString):
    """Identity of one immutable projection generation."""


class ProjectionTensorDigest(MatchArtifactFingerprint):
    """SHA-256 digest of canonical tensor bytes."""


class ProjectionTensorByteCount(_MatchBrandedPositiveInt):
    """Physical size of one immutable tensor blob."""


class BinaryDimensions(_MatchBrandedPositiveInt):
    """Number of semantic binary coordinates."""


class SignalDimensionCount(_MatchBrandedPositiveInt):
    """Number of ranked source dimensions selected for mixing."""


class ProjectionSeed(_MatchBrandedNonnegativeInt):
    """Seed belonging to a declared projection algorithm."""


class SignalDimensionIndex(_MatchBrandedNonnegativeInt):
    """Zero-based source dimension in a complete signal ranking."""


class ProjectionTrainingFingerprint(MatchArtifactFingerprint):
    """Digest of the training population or its labeled row identities."""


class ProjectionSplitPolicyId(_MatchBrandedString):
    """Versioned split and cross-fit policy identity."""


class ProjectionImplementationVersion(_MatchBrandedString):
    """Concrete numerical implementation and version identity."""


class PackedH14Code(bytes):
    """Exactly 128 bytes, with no padding coordinates."""

    __nera_h14_code_type__ = True

    def __new__(cls: type[Self], value: bytes | str) -> Self:
        if isinstance(value, str):
            if value.startswith("\\x"):
                try:
                    value = bytes.fromhex(value[2:])
                except ValueError as error:
                    raise ValueError("H14 text value must be canonical bit or base64 encoding") from error
            elif len(value) == 1024 and not set(value) - {"0", "1"}:
                value = int(value, 2).to_bytes(128, byteorder="big")
            else:
                try:
                    value = base64.b64decode(value, validate=True)
                except (binascii.Error, ValueError) as error:
                    raise ValueError("H14 text value must be canonical bit or base64 encoding") from error
        if isinstance(value, bytes) and len(value) == 132 and int.from_bytes(value[:4], "big") == 1024:
            value = value[4:]
        if isinstance(value, bytes) and len(value) == 1024 and set(value) <= {0, 1}:
            value = int("".join(str(bit) for bit in value), 2).to_bytes(128, "big")
        if isinstance(value, bytes) and len(value) == 1024 and set(value) <= {ord("0"), ord("1")}:
            value = int(value.decode("ascii"), 2).to_bytes(128, "big")
        if isinstance(value, bytes) and len(value) == 512 and all(
            byte >> 4 in {0, 1} and byte & 0x0F in {0, 1} for byte in value
        ):
            digits = "".join(f"{byte >> 4}{byte & 0x0F}" for byte in value)
            value = int(digits, 2).to_bytes(128, "big")
        if not isinstance(value, bytes) or len(value) != 128:
            raise ValueError("H14 packed code requires exactly 128 bytes")
        return super().__new__(cls, value)

    @classmethod
    def __get_pydantic_core_schema__(
        cls: type[Self],
        source_type: object,
        handler: GetCoreSchemaHandler,
    ) -> CoreSchema:
        del source_type, handler
        return core_schema.no_info_plain_validator_function(cls)

    def unwrap_sql_bind(self: PackedH14Code, dialect: object) -> object:
        """Bind packed bits natively on PostgreSQL and as bytes elsewhere."""
        backend = str(getattr(dialect, "backend_type", dialect))
        if backend in {"postgres", "postgresql"}:
            return "".join(f"{byte:08b}" for byte in self)
        return bytes(self)


class ArtifactTensorRef(BaseModel, frozen=True):
    """Digest-addressed little-endian fp32 blob with an exact shape."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    digest: ProjectionTensorDigest
    shape: tuple[MatchVectorDimensions, ...]
    byte_count: ProjectionTensorByteCount
    dtype: Literal["float32"] = "float32"
    byte_order: Literal["little_endian"] = "little_endian"

    @model_validator(mode="after")
    def validate_shape(self: Self) -> Self:
        if not self.shape or math.prod(self.shape) * 4 != self.byte_count:
            raise ValueError("Tensor byte count must equal its fp32 shape size")
        return self

    def verify(self: ArtifactTensorRef, payload: bytes) -> None:
        """Reject truncated or changed content before tensor decoding."""
        if len(payload) != self.byte_count:
            raise ValueError("Tensor byte count does not match its reference")
        if hashlib.sha256(payload).hexdigest() != self.digest:
            raise ValueError("Tensor digest does not match its reference")


class H14CodeLayout(BaseModel, frozen=True):
    """Pinned symmetric H14 V1 base and residual blocks."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    kind: Literal["h14_hamming_scoremix_1024_v1"] = "h14_hamming_scoremix_1024_v1"
    source_dimensions: MatchVectorDimensions = MatchVectorDimensions(768)
    output_dimensions: BinaryDimensions = BinaryDimensions(1024)
    selected_dimensions: SignalDimensionCount = SignalDimensionCount(384)
    residual_dimensions: BinaryDimensions = BinaryDimensions(256)
    residual_seed: ProjectionSeed = ProjectionSeed(256)
    matrix_generator: Literal["numpy_pcg64_standard_normal_float32"] = "numpy_pcg64_standard_normal_float32"
    byte_order: Literal["source_coordinate_first"] = "source_coordinate_first"
    bit_order: Literal["most_significant_first"] = "most_significant_first"
    block_order: Literal["base_then_residual"] = "base_then_residual"
    sign_convention: Literal["nonnegative_is_one"] = "nonnegative_is_one"
    padding_bits: Literal[0] = 0

    @model_validator(mode="after")
    def require_v1_dimensions(self: Self) -> Self:
        if (self.source_dimensions, self.output_dimensions, self.selected_dimensions, self.residual_dimensions, self.residual_seed) != (
            768,
            1024,
            384,
            256,
            256,
        ):
            raise ValueError("H14 V1 dimensions and residual seed are fixed")
        return self


class H14FitSourceRef(BaseModel, frozen=True):
    """One permission-checked database row used by supervised H14 fitting."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    row_type: Annotated[type[DatabaseObjectRow[SysId]], SkipValidation]
    row_id: SysId
    field_name: MatchFieldName
    source_fingerprint: ProjectionTrainingFingerprint

    @field_validator("row_type", mode="before")
    @classmethod
    def validate_row_type(cls: type[Self], value: object) -> type[DatabaseObjectRow[SysId]]:
        if not isinstance(value, type) or not issubclass(value, DatabaseObjectRow):
            raise ValueError("H14 fit sources require a database row class")
        return value


class MatchProjectionFitScope(BaseModel, frozen=True):
    """Authorized population that may influence a learned projection."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    deployment: MatchArtifactScopeValue = MatchArtifactScopeValue("default")
    tenant: MatchArtifactScopeValue
    workspace: MatchArtifactScopeValue
    branch: MatchArtifactScopeValue
    revision: MatchArtifactScopeValue
    permission: MatchPermissionFitScope


@pure_lazy
def current_numpy_backend_fingerprint() -> ProjectionImplementationVersion:
    """Identify the concrete NumPy build and linked numerical backend."""
    import numpy as np

    config = getattr(np.__config__, "CONFIG", {})
    encoded = json.dumps(config, sort_keys=True, default=str, separators=(",", ":"))
    return ProjectionImplementationVersion(hashlib.sha256(encoded.encode()).hexdigest())


class ProjectionNumericContract(BaseModel, frozen=True):
    """Pinned fit precision, solver, and deterministic signal tie rule."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    fit_dtype: Literal["float32"] = "float32"
    numpy_version: ProjectionImplementationVersion
    numpy_backend_fingerprint: ProjectionImplementationVersion = Field(
        default_factory=lambda: current_numpy_backend_fingerprint(),
    )
    svd_implementation: ProjectionImplementationVersion
    svd_algorithm: Literal["full_orthogonal_procrustes"] = "full_orthogonal_procrustes"
    signal_tie_order: Literal["source_dimension_ascending"] = "source_dimension_ascending"
    negative_aggregation: Literal["arithmetic_mean_four"] = "arithmetic_mean_four"
    mean_population: Literal["query_positive_negative_centroid"] = "query_positive_negative_centroid"


class NoH14ProjectionArtifact(BaseModel, frozen=True):
    """Explicit absence of an inline H14 artifact contract."""

    kind: Literal["none"] = "none"


class H14ProjectionArtifact(BaseModel, frozen=True):
    """Complete immutable H14 V1 generation, without embedded mutable tensors."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    artifact_id: MatchProjectionArtifactId
    algorithm_version: Literal["h14_hamming_scoremix_1024_v1"] = "h14_hamming_scoremix_1024_v1"
    source_model: Literal["nera:gte-modernbert-base"] = "nera:gte-modernbert-base"
    hard_negative_count: Literal[4] = 4
    mean_tensor: ArtifactTensorRef
    rotation_tensor: ArtifactTensorRef
    threshold_tensor: ArtifactTensorRef
    residual_tensor: ArtifactTensorRef
    signal_order: tuple[SignalDimensionIndex, ...]
    fit_scope: MatchProjectionFitScope
    training_fingerprint: ProjectionTrainingFingerprint
    training_identity_fingerprint: ProjectionTrainingFingerprint
    evaluation_identity_fingerprint: ProjectionTrainingFingerprint
    split_policy: ProjectionSplitPolicyId
    numeric_contract: ProjectionNumericContract
    code_layout: H14CodeLayout = H14CodeLayout()

    @model_validator(mode="after")
    def validate_h14_tensors(self: Self) -> Self:
        for reference, shape in (
            (self.mean_tensor, (768,)),
            (self.rotation_tensor, (768, 768)),
            (self.threshold_tensor, (768,)),
            (self.residual_tensor, (768, 256)),
        ):
            if reference.shape != shape:
                raise ValueError("H14 tensor shape does not match its declared role")
        if len(self.signal_order) != 768 or set(self.signal_order) != set(range(768)):
            raise ValueError("H14 signal order must be a permutation of 768 dimensions")
        expected_id = self.content_id(**self.model_dump(exclude={"artifact_id"}))
        if self.artifact_id != expected_id:
            raise ValueError("H14 artifact identity must bind every immutable content field")
        return self

    @classmethod
    def content_id(cls: type[H14ProjectionArtifact], **values: object) -> MatchProjectionArtifactId:
        complete = {
            "algorithm_version": "h14_hamming_scoremix_1024_v1",
            "source_model": "nera:gte-modernbert-base",
            "hard_negative_count": 4,
            "code_layout": H14CodeLayout(),
            **values,
        }
        payload = to_jsonable_python(complete)
        if not isinstance(payload, dict) or not all(isinstance(key, str) for key in payload):
            raise TypeError("H14 artifact content must serialize to a string-keyed object")
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return MatchProjectionArtifactId(f"h14:{hashlib.sha256(encoded.encode()).hexdigest()}")

    def fingerprint(self: H14ProjectionArtifact) -> MatchArtifactFingerprint:
        """Hash every semantic field and tensor digest using canonical JSON."""
        payload = json.dumps(self.model_dump(mode="json"), sort_keys=True, separators=(",", ":"))
        return MatchArtifactFingerprint(hashlib.sha256(payload.encode("utf-8")).hexdigest())


class H14ProjectionFitResult(BaseModel, frozen=True):
    """Complete H14 artifact and its four immutable tensor payloads."""

    model_config = ConfigDict(
        frozen=True,
        extra="forbid",
        arbitrary_types_allowed=True,
        ser_json_bytes="base64",
        val_json_bytes="base64",
    )

    artifact: H14ProjectionArtifact
    mean_payload: bytes
    rotation_payload: bytes
    threshold_payload: bytes
    residual_payload: bytes

    @model_validator(mode="after")
    def verify_payloads(self: Self) -> Self:
        for reference, payload in (
            (self.artifact.mean_tensor, self.mean_payload),
            (self.artifact.rotation_tensor, self.rotation_payload),
            (self.artifact.threshold_tensor, self.threshold_payload),
            (self.artifact.residual_tensor, self.residual_payload),
        ):
            reference.verify(payload)
        return self

    def blobs(self: H14ProjectionFitResult) -> dict[ProjectionTensorDigest, bytes]:
        """Return a fresh digest-addressed map for caller-owned publication."""
        return {
            self.artifact.mean_tensor.digest: self.mean_payload,
            self.artifact.rotation_tensor.digest: self.rotation_payload,
            self.artifact.threshold_tensor.digest: self.threshold_payload,
            self.artifact.residual_tensor.digest: self.residual_payload,
        }


class H14BinaryCodePayload(BaseModel, frozen=True):
    """One canonical packed code bound to a representation and projection generation."""

    model_config = ConfigDict(
        frozen=True,
        extra="forbid",
        arbitrary_types_allowed=True,
        ser_json_bytes="base64",
        val_json_bytes="base64",
    )

    kind: Literal["h14_binary_code"] = "h14_binary_code"
    projection_artifact_id: MatchProjectionArtifactId
    representation_id: MatchRepresentationRefId
    packed_bits: PackedH14Code


class ProjectionDimensions(_MatchBrandedPositiveInt):
    """Number of rows in a deterministic estimator projection."""


class QuantizationBitWidth(_MatchBrandedPositiveInt):
    """Number of bits assigned to one scalar code."""

    def __new__(cls: type[Self], value: int | Self) -> Self:
        width = super().__new__(cls, value)
        if width > 8:
            raise ValueError("QuantizationBitWidth cannot exceed eight bits")
        return width


class QuantizedVectorNorm(float):
    """Finite nonnegative source-vector norm."""

    def __new__(cls: type[Self], value: float) -> Self:
        result = super().__new__(cls, value)
        if not math.isfinite(result) or result < 0.0:
            raise ValueError("Quantized vector norms must be finite and nonnegative")
        return result

    @classmethod
    def __get_pydantic_core_schema__(
        cls: type[Self],
        source_type: object,
        handler: GetCoreSchemaHandler,
    ) -> CoreSchema:
        del source_type, handler
        return core_schema.no_info_after_validator_function(cls, core_schema.float_schema(ge=0.0))


class QuantizedResidualNorm(QuantizedVectorNorm):
