class HalfPrecisionRepresentationContract(BaseModel, frozen=True):
    """Explicit IEEE binary16 storage and loss contract."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    source_precision: Literal["float32"] = "float32"
    storage_precision: Literal["float16"] = "float16"
    loss_kind: Literal["round_to_nearest_even"] = "round_to_nearest_even"
    maximum_finite_magnitude: float = 65504.0
    relative_error_bound: float = 2.0**-10
    absolute_subnormal_error_bound: float = 2.0**-24

    def encode(self: HalfPrecisionRepresentationContract, values: object) -> bytes:
        """Encode finite values as canonical little-endian binary16 bytes."""
        import numpy as np

        source = np.asarray(values, dtype="<f4")
        if not np.isfinite(source).all() or np.max(np.abs(source), initial=0.0) > self.maximum_finite_magnitude:
            raise ValueError("Half-precision values must be finite and representable")
        return np.asarray(source, dtype="<f2").tobytes(order="C")

    def decode(self: HalfPrecisionRepresentationContract, payload: bytes) -> object:
        """Decode canonical binary16 bytes into float32 coordinates."""
        import numpy as np

        if len(payload) % 2:
            raise ValueError("Half-precision payload length must be a multiple of two bytes")
        return np.frombuffer(payload, dtype="<f2").astype("<f4")

    def absolute_error_bound(self: HalfPrecisionRepresentationContract, values: object) -> float:
        """Return the declared binary16 absolute error bound for a vector."""
        import numpy as np

        source = np.asarray(values, dtype="<f4")
        return float(np.max(np.abs(source), initial=0.0) * self.relative_error_bound + self.absolute_subnormal_error_bound)


class ProductQuantizationArtifact(BaseModel, frozen=True):
    """Immutable codebook generation for product-quantized codes."""

    model_config = ConfigDict(frozen=True, extra="forbid", ser_json_bytes="base64", val_json_bytes="base64")

    artifact_id: MatchProjectionArtifactId
    source_dimensions: MatchVectorDimensions
    subquantizers: ProductQuantizerCount
    centroids_per_subquantizer: ProductQuantizerCentroidCount
    codebook_digest: ProjectionTensorDigest
    codebook_payload: bytes

    @model_validator(mode="after")
    def validate_generation(self: Self) -> Self:
        if int(self.source_dimensions) % int(self.subquantizers):
            raise ValueError("Product-quantizer dimensions must divide evenly across subquantizers")
        digest = ProjectionTensorDigest(hashlib.sha256(self.codebook_payload).hexdigest())
        if self.codebook_digest != digest:
            raise ValueError("Product-quantizer codebook digest does not match its payload")
        expected = self.content_id(
            source_dimensions=self.source_dimensions,
            subquantizers=self.subquantizers,
            centroids_per_subquantizer=self.centroids_per_subquantizer,
            codebook_digest=self.codebook_digest,
        )
        if self.artifact_id != expected:
            raise ValueError("Product-quantizer artifact identity must bind its generation")
        return self

    @classmethod
    def content_id(
        cls: type[ProductQuantizationArtifact],
        *,
        source_dimensions: MatchVectorDimensions,
        subquantizers: ProductQuantizerCount,
        centroids_per_subquantizer: ProductQuantizerCentroidCount,
        codebook_digest: ProjectionTensorDigest,
    ) -> MatchProjectionArtifactId:
        payload: dict[str, object] = {
            "source_dimensions": int(source_dimensions),
            "subquantizers": int(subquantizers),
            "centroids_per_subquantizer": int(centroids_per_subquantizer),
            "codebook_digest": str(codebook_digest),
        }
        return _projection_content_id("product-quantizer", payload)

    @classmethod
    def create(
        cls: type[ProductQuantizationArtifact],
        *,
        source_dimensions: MatchVectorDimensions,
        subquantizers: ProductQuantizerCount,
        centroids_per_subquantizer: ProductQuantizerCentroidCount,
        codebook_payload: bytes,
    ) -> ProductQuantizationArtifact:
        """Create one content-addressed product-quantizer generation."""
        digest = ProjectionTensorDigest(hashlib.sha256(codebook_payload).hexdigest())
        return cls(
            artifact_id=cls.content_id(
                source_dimensions=source_dimensions,
                subquantizers=subquantizers,
                centroids_per_subquantizer=centroids_per_subquantizer,
                codebook_digest=digest,
            ),
            source_dimensions=source_dimensions,
            subquantizers=subquantizers,
            centroids_per_subquantizer=centroids_per_subquantizer,
            codebook_digest=digest,
            codebook_payload=codebook_payload,
        )


class ProductQuantizedCodePayload(BaseModel, frozen=True):
    """Packed product-quantizer indices bound to one codebook generation."""

    model_config = ConfigDict(frozen=True, extra="forbid", ser_json_bytes="base64", val_json_bytes="base64")

    codebook_artifact_id: MatchProjectionArtifactId
    packed_indices: bytes

    def verify(self: ProductQuantizedCodePayload, artifact: ProductQuantizationArtifact) -> None:
        """Reject a code from another generation or with the wrong width."""
        if self.codebook_artifact_id != artifact.artifact_id:
            raise ValueError("Product-quantized code uses a different codebook generation")
        if len(self.packed_indices) != int(artifact.subquantizers):
            raise ValueError("Product-quantized code width does not match its codebook generation")
        if any(value >= int(artifact.centroids_per_subquantizer) for value in self.packed_indices):
            raise ValueError("Product-quantized code contains an out-of-range centroid index")


