class ScalarCodebookArtifact(BaseModel, frozen=True):
    """Ordered scalar centroids and their decision boundaries."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    algorithm: Literal[
        "normal_equal_probability_conditional_mean_v1",
        "turboquant_beta_lloyd_max_v1",
    ] = "turboquant_beta_lloyd_max_v1"
    centroids: tuple[float, ...]
    boundaries: tuple[float, ...]

    @model_validator(mode="after")
    def validate_codebook(self: Self) -> Self:
        if len(self.centroids) < 2 or len(self.boundaries) != len(self.centroids) - 1:
            raise ValueError("Scalar codebook requires one fewer boundary than centroids")
        if any(not math.isfinite(value) for value in (*self.centroids, *self.boundaries)):
            raise ValueError("Scalar codebook values must be finite")
        if tuple(sorted(self.centroids)) != self.centroids or tuple(sorted(self.boundaries)) != self.boundaries:
            raise ValueError("Scalar codebook values must be ordered")
        return self


