class TurboQuantMseCodePayload(BaseModel, frozen=True):
    """One packed TurboQuant MSE scalar-index code."""

    model_config = ConfigDict(frozen=True, extra="forbid", ser_json_bytes="base64", val_json_bytes="base64")

    projection_artifact_id: MatchProjectionArtifactId
    packed_indices: bytes
    vector_norm: QuantizedVectorNorm

    def unpack_indices(self: TurboQuantMseCodePayload, artifact: TurboQuantMseArtifact) -> tuple[int, ...]:
        """Decode canonical unsigned scalar indices."""
        width = int(artifact.bit_width)
        count = int(artifact.source_dimensions)
        value = int.from_bytes(self.packed_indices, "big")
        padding = len(self.packed_indices) * 8 - count * width
        value >>= padding
        mask = (1 << width) - 1
        return tuple((value >> ((count - index - 1) * width)) & mask for index in range(count))


