"""Deterministic immutable registry for matching declarations."""

from __future__ import annotations

import json
from collections.abc import (
    Mapping,
)
from typing import (
    Annotated,
)
from pydantic import (
    SkipValidation,
    ValidationError,
    model_validator,
)
from l1000_schema.typed_field import (
    Expression,
)
from l1400_types import (
    ServerPlanRefId,
)
from l1470_matching_contracts.native_profiles import (
    NativeExactDeploymentPlan,
    NoNativeExactPlanChoice,
)
from l1470_matching_contracts.types import (
    MatchKernelKind,
    MatchPersistedVariantName,
    MatchRowTypeRef,
    MatchSpecFingerprint,
)

from typing import Generic, TypeVar

from pydantic import BaseModel, ConfigDict, Field

from l1000_schema.schema_def import DatabaseObjectRow
from l1400_types import SysId
from l1470_matching_contracts.errors import (
    MatchDeclarationError,
    MatchErrorContext,
    MatchUnknownVariantError,
)
from l1470_matching_contracts.models import (
    MatchSpec,
    MatchSpecRegistration,
    PersistedMatchSpecEnvelope,
)
from l1470_matching_contracts.types import (
    MatchExpectedValue,
    MatchInvariant,
    MatchObservedValue,
    MatchPersistedVariant,
    MatchSafeAction,
    MatchSpecRefId,
)

LeftRowT = TypeVar("LeftRowT", bound=DatabaseObjectRow[SysId])
RightRowT = TypeVar("RightRowT", bound=DatabaseObjectRow[SysId])


class MatchSpecRegistry(BaseModel, Generic[LeftRowT, RightRowT]):
    """Immutable registry whose composition is independent of declaration order."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    registrations: tuple[MatchSpecRegistration[LeftRowT, RightRowT], ...]
    row_types: "MatchRowTypeCatalog" = Field(
        default_factory=lambda: MatchRowTypeCatalog(registrations=()),
    )

    @classmethod
    def empty(
        cls: type[MatchSpecRegistry[LeftRowT, RightRowT]],
        *,
        row_types: MatchRowTypeCatalog | None = None,
    ) -> MatchSpecRegistry[LeftRowT, RightRowT]:
        """Construct an empty registry with an optional static row-type catalog."""
        return cls(registrations=(), row_types=row_types or MatchRowTypeCatalog(registrations=()))

    @classmethod
    def compose(
        cls: type[MatchSpecRegistry[LeftRowT, RightRowT]],
        specs: tuple[MatchSpec[LeftRowT, RightRowT], ...],
    ) -> MatchSpecRegistry[LeftRowT, RightRowT]:
        """Compose declarations deterministically and reject identity conflicts."""
        registry = cls.empty(
            row_types=MatchRowTypeCatalog.from_types(
                tuple({spec.left.row_type for spec in specs} | {spec.right.row_type for spec in specs}),
            ),
        )
        for spec in specs:
            registry = registry.register(spec)
        return registry

    def register(
        self: MatchSpecRegistry[LeftRowT, RightRowT],
        spec: MatchSpec[LeftRowT, RightRowT],
    ) -> MatchSpecRegistry[LeftRowT, RightRowT]:
        """Return a registry that contains ``spec`` with one authoritative meaning."""
        registration = MatchSpecRegistration[LeftRowT, RightRowT](spec=spec)
        existing = next(
            (item for item in self.registrations if item.spec_ref_id == spec.spec_ref_id),
            None,
        )
        if existing is not None:
            if existing.fingerprint == registration.fingerprint:
                return self
            raise MatchDeclarationError(
                context=_duplicate_identity_context(existing, registration),
            )
        return MatchSpecRegistry[LeftRowT, RightRowT](
            row_types=self.row_types,
            registrations=tuple(
                sorted(
                    (*self.registrations, registration),
                    key=lambda item: str(item.spec_ref_id),
                ),
            ),
        )

    def resolve(
        self: MatchSpecRegistry[LeftRowT, RightRowT],
        spec_ref_id: MatchSpecRefId,
    ) -> MatchSpec[LeftRowT, RightRowT]:
        """Resolve one registered specification or fail closed."""
        registration = next(
            (item for item in self.registrations if item.spec_ref_id == spec_ref_id),
            None,
        )
        if registration is None:
            raise MatchDeclarationError(
                context=_missing_registered_spec_context(spec_ref_id),
            )
        return registration.spec

    def validate_persisted(
        self: MatchSpecRegistry[LeftRowT, RightRowT],
        envelope: PersistedMatchSpecEnvelope,
    ) -> MatchSpec[LeftRowT, RightRowT]:
        """Validate one persisted identity through exhaustive closed dispatch."""
        if envelope.variant != MatchPersistedVariant.V1.value:
            raise MatchUnknownVariantError(
                context=_unknown_variant_context(envelope),
            )
        registration = next(
            (item for item in self.registrations if item.spec_ref_id == envelope.spec_ref_id),
            None,
        )
        if registration is None:
            raise MatchDeclarationError(
                context=_missing_persisted_spec_context(envelope),
            )
        if registration.fingerprint != envelope.fingerprint:
            raise MatchDeclarationError(
                context=_persisted_fingerprint_context(registration, envelope),
            )
        return registration.spec

    def restore(
        self: MatchSpecRegistry[LeftRowT, RightRowT],
        envelope: PersistedMatchSpecEnvelope,
    ) -> MatchSpec[LeftRowT, RightRowT]:
        """Restore one complete envelope through the persisted wire representation."""
        return self.restore_payload(envelope.model_dump(mode="python", round_trip=True))

    def restore_json(
        self: MatchSpecRegistry[LeftRowT, RightRowT],
        encoded: str,
    ) -> MatchSpec[LeftRowT, RightRowT]:
        """Restore one complete JSON envelope without dynamic type loading."""
        payload: object = json.loads(encoded)
        if not isinstance(payload, Mapping):
            raise MatchUnknownVariantError(context=_malformed_envelope_context())
        return self.restore_payload(payload)

    def restore_payload(
        self: MatchSpecRegistry[LeftRowT, RightRowT],
        payload: Mapping[str, object],
    ) -> MatchSpec[LeftRowT, RightRowT]:
        """Restore one parsed envelope through closed nested dispatch."""
        spec_ref_id = MatchSpecRefId(str(payload.get("spec_ref_id", "unknown_specification")))
        variant = str(payload.get("variant", "missing_variant"))
        if variant != MatchPersistedVariant.V1.value:
            raise MatchUnknownVariantError(
                context=_unknown_variant_values_context(spec_ref_id, "envelope", variant),
            )
        specification = payload.get("specification")
        if not isinstance(specification, Mapping):
            raise MatchUnknownVariantError(
                context=_unknown_variant_values_context(spec_ref_id, "specification", "missing_specification"),
            )
        _validate_closed_variant_tags(specification, spec_ref_id)
        try:
            hydrated = _hydrate_persisted_value(specification, self.row_types)
        except KeyError as exc:
            missing_ref = MatchRowTypeRef(str(exc.args[0]))
            raise MatchUnknownVariantError(
                context=_unknown_variant_values_context(spec_ref_id, "row_type", str(missing_ref)),
            ) from None
        assert isinstance(hydrated, Mapping)
        try:
            deployment_payload = payload.get("native_deployment")
            deployment = (
                NativeExactDeploymentPlan.model_validate(deployment_payload)
                if deployment_payload is not None else NoNativeExactPlanChoice()
            )
            restored = MatchSpec[LeftRowT, RightRowT].model_validate(hydrated, context=deployment)
        except ValidationError as exc:
            raise MatchUnknownVariantError(
                context=_nested_validation_context(spec_ref_id, exc),
            ) from None
        expected_fingerprint = MatchSpecFingerprint(str(payload.get("fingerprint", "invalid_fingerprint")))
        if restored.semantic_fingerprint != expected_fingerprint:
            registration = MatchSpecRegistration[LeftRowT, RightRowT](spec=restored)
            envelope = PersistedMatchSpecEnvelope(
                variant=MatchPersistedVariantName(variant),
                spec_ref_id=spec_ref_id,
                fingerprint=expected_fingerprint,
                specification=restored,
            )
            raise MatchDeclarationError(context=_persisted_fingerprint_context(registration, envelope))
        return restored


def _duplicate_identity_context(
    existing: MatchSpecRegistration[LeftRowT, RightRowT],
    incoming: MatchSpecRegistration[LeftRowT, RightRowT],
) -> MatchErrorContext:
    return MatchErrorContext(
        invariant=MatchInvariant.DUPLICATE_SPEC_IDENTITY,
        expected=MatchExpectedValue(str(existing.fingerprint)),
        observed=MatchObservedValue(str(incoming.fingerprint)),
        safe_action=MatchSafeAction.FIX_DECLARATION,
        spec_ref_id=existing.spec_ref_id,
    )


def _unknown_variant_context(envelope: PersistedMatchSpecEnvelope) -> MatchErrorContext:
    return MatchErrorContext(
        invariant=MatchInvariant.UNKNOWN_PERSISTED_VARIANT,
        expected=MatchExpectedValue(MatchPersistedVariant.V1.value),
        observed=MatchObservedValue(str(envelope.variant)),
        safe_action=MatchSafeAction.MIGRATE_PERSISTED_SPEC,
        spec_ref_id=envelope.spec_ref_id,
    )


def _missing_registered_spec_context(spec_ref_id: MatchSpecRefId) -> MatchErrorContext:
    return MatchErrorContext(
        invariant=MatchInvariant.PERSISTED_SPEC_MISSING,
        expected=MatchExpectedValue("registered_specification"),
        observed=MatchObservedValue("missing_specification"),
        safe_action=MatchSafeAction.MIGRATE_PERSISTED_SPEC,
        spec_ref_id=spec_ref_id,
    )


def _missing_persisted_spec_context(envelope: PersistedMatchSpecEnvelope) -> MatchErrorContext:
    return _missing_registered_spec_context(envelope.spec_ref_id)


def _persisted_fingerprint_context(
    registration: MatchSpecRegistration[LeftRowT, RightRowT],
    envelope: PersistedMatchSpecEnvelope,
) -> MatchErrorContext:
    return MatchErrorContext(
        invariant=MatchInvariant.PERSISTED_FINGERPRINT_MISMATCH,
        expected=MatchExpectedValue(str(registration.fingerprint)),
        observed=MatchObservedValue(str(envelope.fingerprint)),
        safe_action=MatchSafeAction.MIGRATE_PERSISTED_SPEC,
        spec_ref_id=envelope.spec_ref_id,
    )

def _row_type_ref(row_type: type[DatabaseObjectRow[SysId]]) -> MatchRowTypeRef:
    return MatchRowTypeRef(f"{row_type.__module__}.{row_type.__qualname__}")


class MatchRowTypeRegistration(BaseModel):
    """One statically supplied row type available during restoration."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    row_type_ref: MatchRowTypeRef
    row_type: Annotated[type[DatabaseObjectRow[SysId]], SkipValidation]


class MatchRowTypeCatalog(BaseModel):
    """Closed row-type catalog used without dynamic module loading."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    registrations: tuple[MatchRowTypeRegistration, ...]

    @classmethod
    def from_types(
        cls: type[MatchRowTypeCatalog],
        row_types: tuple[type[DatabaseObjectRow[SysId]], ...],
    ) -> MatchRowTypeCatalog:
        """Build a deterministic catalog and reject qualified-name aliases."""
        registrations = tuple(
            sorted(
                (MatchRowTypeRegistration(row_type_ref=_row_type_ref(row_type), row_type=row_type) for row_type in row_types),
                key=lambda item: str(item.row_type_ref),
            ),
        )
        return cls(registrations=registrations)

    @model_validator(mode="after")
    def _require_unique_references(self: MatchRowTypeCatalog) -> MatchRowTypeCatalog:
        references = tuple(item.row_type_ref for item in self.registrations)
        if len(set(references)) != len(references):
            msg = "matching row-type references must be unique"
            raise ValueError(msg)
        return self

    def resolve(self: MatchRowTypeCatalog, row_type_ref: MatchRowTypeRef) -> type[DatabaseObjectRow[SysId]]:
        """Resolve one explicitly registered row type."""
        registration = next(
            (item for item in self.registrations if item.row_type_ref == row_type_ref),
            None,
        )
        if registration is None:
            raise KeyError(row_type_ref)
        return registration.row_type


_ROW_TYPE_FIELDS = frozenset({"left_row_type", "owner", "right_row_type", "row_type"})


_CLOSED_VARIANT_TAGS: dict[str, frozenset[str]] = {
    "filters.left": frozenset({"endpoint", "none", "pair_field_comparison"}),
    "filters.pair": frozenset({"endpoint", "none", "pair_field_comparison"}),
    "filters.right": frozenset({"endpoint", "none", "pair_field_comparison"}),
    "kernel": frozenset(kind.value for kind in MatchKernelKind),
    "kernel.pruning_bound": frozenset({"none"}),
    "left.identity": frozenset({"field", "sys_id"}),
    "left.representation": frozenset(
        {
            "dense_coordinates",
            "dense_vector_field",
            "h14_binary_field",
            "identity_only",
            "packed_dense_field",
            "text_field",
            "token_field",
        },
    ),
    "left.representation.availability": frozenset({"all_rows", "presence", "presence_with_failure"}),
    "left.representation.normalization": frozenset(
        {"unicode_words_case_sensitive", "unicode_words_casefolded"},
    ),
    "left.source": frozenset({"singleton", "table"}),
    "policies.duplicates": frozenset({"combine", "keep_first", "reject"}),
    "policies.explanations": frozenset({"dense_coordinates", "none"}),
    "policies.freshness": frozenset(
        {"accept_stale_with_diagnostics", "exact_completion", "require_bounded_watermark", "require_current"},
    ),
    "policies.missing_representation": frozenset(
        {"emit_declared_score", "fail", "omit_pair", "require_materialization"},
    ),
    "result_shape": frozenset({"global_top_k", "threshold_join", "top_k_per_left", "top_k_per_right"}),
    "result_shape.pagination": frozenset({"after", "first", "none"}),
    "right.identity": frozenset({"field", "sys_id"}),
    "right.representation": frozenset(
        {
            "dense_coordinates",
            "dense_vector_field",
            "h14_binary_field",
            "identity_only",
            "packed_dense_field",
            "text_field",
            "token_field",
        },
    ),
    "right.representation.availability": frozenset({"all_rows", "presence", "presence_with_failure"}),
    "right.representation.normalization": frozenset(
        {"unicode_words_case_sensitive", "unicode_words_casefolded"},
    ),
    "right.source": frozenset({"singleton", "table"}),
}


_COMPLEXITY_TAGS = frozenset({"constant", "minimum", "product", "symbol", "unknown"})


_EXPRESSION_TAGS = frozenset({"add", "divide", "function", "left_field", "multiply", "right_field", "subtract"})


def _allowed_variant_tags(path: str) -> frozenset[str] | None:
    direct = _CLOSED_VARIANT_TAGS.get(path)
    if direct is not None:
        return direct
    if path.startswith("kernel.evaluation_complexity."):
        return _COMPLEXITY_TAGS
    if path == "kernel.expression" or path.startswith("kernel.expression."):
        return _EXPRESSION_TAGS
    return None


def _validate_closed_variant_tags(
    value: object,
    spec_ref_id: MatchSpecRefId,
    *,
    path: str = "",
) -> None:
    if isinstance(value, Mapping):
        kind_value = value.get("kind")
        allowed = _allowed_variant_tags(path)
        if kind_value is not None and allowed is not None and str(kind_value) not in allowed:
            raise MatchUnknownVariantError(
                context=_unknown_variant_values_context(spec_ref_id, path, str(kind_value)),
            )
        for key, item in value.items():
            child_path = str(key) if not path else f"{path}.{key}"
            _validate_closed_variant_tags(item, spec_ref_id, path=child_path)
    elif isinstance(value, list | tuple):
        for item in value:
            _validate_closed_variant_tags(item, spec_ref_id, path=path)


def _hydrate_persisted_expression(
    payload: Mapping[object, object],
    catalog: MatchRowTypeCatalog,
) -> Expression:
    owner_value = payload.get("owner")
    owner = None if owner_value is None else catalog.resolve(MatchRowTypeRef(str(owner_value)))
    left_value = payload.get("left")
    right_value = payload.get("right")
    raw_args_value = payload.get("args", ())
    raw_args = raw_args_value if isinstance(raw_args_value, list | tuple) else ()
    dependencies_value = payload.get("server_ref_dependencies", ())
    dependencies = dependencies_value if isinstance(dependencies_value, list | tuple) else ()
    return Expression(
        field=None if payload.get("field") is None else str(payload["field"]),
        operator=None if payload.get("operator") is None else str(payload["operator"]),
        value=_hydrate_persisted_value(payload.get("value"), catalog),
        left=(
            _hydrate_persisted_expression(left_value, catalog)
            if isinstance(left_value, Mapping) and left_value.get("__matching_expression__") is True
            else None
        ),
        right=(
            _hydrate_persisted_expression(right_value, catalog)
            if isinstance(right_value, Mapping) and right_value.get("__matching_expression__") is True
            else None
        ),
        logical_op=None if payload.get("logical_op") is None else str(payload["logical_op"]),
        function=None if payload.get("function") is None else str(payload["function"]),
        args=[
            _hydrate_persisted_expression(item, catalog)
            if isinstance(item, Mapping) and item.get("__matching_expression__") is True
            else _hydrate_persisted_value(item, catalog)
            for item in raw_args
        ],
        owner=owner,
        server_ref_dependencies=tuple(ServerPlanRefId(str(item)) for item in dependencies),
    )


def _hydrate_persisted_value(value: object, catalog: MatchRowTypeCatalog, *, field_name: str = "") -> object:
    if field_name in _ROW_TYPE_FIELDS and isinstance(value, str):
        return catalog.resolve(MatchRowTypeRef(value))
    if isinstance(value, Mapping):
        if value.get("__matching_expression__") is True:
            return _hydrate_persisted_expression(value, catalog)
        return {str(key): _hydrate_persisted_value(item, catalog, field_name=str(key)) for key, item in value.items()}
    if isinstance(value, list | tuple):
        return tuple(_hydrate_persisted_value(item, catalog) for item in value)
    return value


def _malformed_envelope_context() -> MatchErrorContext:
    return MatchErrorContext(
        invariant=MatchInvariant.UNKNOWN_PERSISTED_VARIANT,
        expected=MatchExpectedValue("persisted_envelope_mapping"),
        observed=MatchObservedValue("malformed_envelope"),
        safe_action=MatchSafeAction.MIGRATE_PERSISTED_SPEC,
        spec_ref_id=MatchSpecRefId("unknown_specification"),
    )


def _unknown_variant_values_context(
    spec_ref_id: MatchSpecRefId,
    location: str,
    observed: str,
) -> MatchErrorContext:
    expected = "registered_row_type" if location == "row_type" else "registered_closed_variant"
    observed_value = observed if location == "row_type" else f"{location}:{observed}"
    return MatchErrorContext(
        invariant=MatchInvariant.UNKNOWN_PERSISTED_VARIANT,
        expected=MatchExpectedValue(expected),
        observed=MatchObservedValue(observed_value),
        safe_action=MatchSafeAction.MIGRATE_PERSISTED_SPEC,
        spec_ref_id=spec_ref_id,
    )


def _nested_validation_context(spec_ref_id: MatchSpecRefId, error: ValidationError) -> MatchErrorContext:
    first_error = error.errors()[0]
    location_parts = tuple(
        str(part) for part in first_error["loc"] if str(part) not in {"MatchKernelSpec", "MatchTypedExpressionKernelSpec"}
    )
    location = ".".join(location_parts[:-1]) or "specification"
    value = first_error.get("input")
    observed = (
        value if isinstance(value, str) and len(value) <= 128
        else str(first_error["type"])
    )
    return _unknown_variant_values_context(spec_ref_id, location, observed)

