"""Immutable contracts for transductive SVD matching representations."""

from __future__ import annotations

import hashlib
import json
import math
from enum import StrEnum
from typing import Annotated, Literal, Self

from pydantic import BaseModel, ConfigDict, SkipValidation, model_validator

from l1000_schema.schema_def import DatabaseObjectRow
from l1400_types import SysId

from l1470_matching_contracts.graph_producer_models import (
    MatchGraphIdentity,
    MatchRepresentationProducerRefId,
)
from l1470_matching_contracts.types import (
    MatchArtifactFingerprint,
    MatchPermissionFitScope,
    MatchRepresentationRefId,
    MatchSnapshotFingerprint,
    MatchVectorDimensions,
    _MatchBrandedNonnegativeInt,
    _MatchBrandedPositiveInt,
    _MatchBrandedString,
)


class MatchSvdRank(_MatchBrandedPositiveInt):
    """Requested positive rank of one fitted SVD artifact."""

    def __new__(cls: type[Self], value: int | Self) -> Self:
        rank = super().__new__(cls, value)
        if rank > 65_536:
            raise ValueError("SVD rank cannot exceed 65536")
        return rank


class MatchMatrixRowCount(_MatchBrandedPositiveInt):
    """Positive matrix row count used by a fitted producer."""


class MatchMatrixColumnCount(_MatchBrandedPositiveInt):
    """Positive matrix column count used by a fitted producer."""


class MatchMatrixNonzeroLimit(_MatchBrandedNonnegativeInt):
    """Maximum nonzero values consumed by a fitted matrix producer."""


class MatchProducerWorkspaceByteLimit(_MatchBrandedPositiveInt):
    """Maximum temporary workspace bytes declared by a producer."""


class MatchMatrixIterationLimit(_MatchBrandedPositiveInt):
    """Maximum iterative solver steps admitted by one fit."""


class MatchMatrixIterationCount(_MatchBrandedPositiveInt):
    """Positive iterative solver step count."""


class MatchSvdArtifactId(_MatchBrandedString):
    """Content identity shared by both factors of one fitted SVD."""


class MatchSvdComplexityContract(BaseModel, frozen=True):
    """Matrix sparsity, rank, solver, iteration, and workspace assumptions."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    matrix_rows: MatchMatrixRowCount
    matrix_columns: MatchMatrixColumnCount
    matrix_nonzero_limit: MatchMatrixNonzeroLimit
    rank: MatchSvdRank
    iteration_limit: MatchMatrixIterationLimit
    solver: Literal["deterministic_subspace_iteration", "randomized_subspace_iteration"]
    workspace_byte_limit: MatchProducerWorkspaceByteLimit

    @model_validator(mode="after")
    def validate_assumptions(self: Self) -> Self:
        if self.iteration_limit <= 0:
            raise ValueError("SVD complexity iteration limit must be positive")
        if self.rank > min(self.matrix_rows, self.matrix_columns):
            raise ValueError("SVD complexity rank cannot exceed either matrix dimension")
        if self.matrix_nonzero_limit > self.matrix_cell_upper_bound:
            raise ValueError("SVD nonzero limit cannot exceed the matrix cell count")
        return self

    @property
    def matrix_cell_upper_bound(self: MatchSvdComplexityContract) -> int:
        """Return the dense matrix cell bound."""
        return int(self.matrix_rows) * int(self.matrix_columns)

    @property
    def multiply_add_upper_bound(self: MatchSvdComplexityContract) -> int:
        """Return the sparse two-sided iteration arithmetic bound."""
        return (
            2
            * int(self.matrix_nonzero_limit)
            * int(self.rank)
            * self.iteration_limit
        )


class MatchSpectralArtifactId(_MatchBrandedString):
    """Content identity of one fitted spectral graph representation."""


class MatchSvdFactorRole(StrEnum):
    """Semantic side emitted by a bipartite SVD fit."""

    LEFT = "left"
    RIGHT = "right"


class MatchSpectralCoordinate(BaseModel, frozen=True):
    """One concrete graph endpoint and its spectral coordinates."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    node_id: SysId
    node: Annotated[DatabaseObjectRow[SysId], SkipValidation]
    values: tuple[float, ...]

    @model_validator(mode="after")
    def validate_coordinate(self: Self) -> Self:
        if self.node.sys_id != self.node_id:
            raise ValueError("Spectral coordinate node must match its declared identity")
        if not self.values or any(not math.isfinite(value) for value in self.values):
            raise ValueError("Spectral coordinate values must be nonempty and finite")
        return self


class MatchSpectralRepresentation(BaseModel, frozen=True):
    """Canonical graph spectral representation for one fitted artifact."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    artifact_id: MatchSpectralArtifactId
    graph_identity: MatchGraphIdentity
    visibility_scope: MatchPermissionFitScope
    source_snapshot: MatchSnapshotFingerprint
    dimensions: MatchVectorDimensions
    coordinates: tuple[MatchSpectralCoordinate, ...]

    @model_validator(mode="after")
    def validate_representation(self: Self) -> Self:
        node_ids = tuple(coordinate.node_id for coordinate in self.coordinates)
        if len(set(node_ids)) != len(node_ids):
            raise ValueError("Spectral representation requires distinct node identities")
        if node_ids != tuple(sorted(node_ids, key=str)):
            raise ValueError("Spectral representation nodes must use canonical identity order")
        if any(len(coordinate.values) != self.dimensions for coordinate in self.coordinates):
            raise ValueError("Spectral coordinate width must equal representation dimensions")
        return self


class MatchSpectralArtifact(BaseModel, frozen=True):
    """Complete identity of one transductive spectral graph fit."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    producer_ref_id: MatchRepresentationProducerRefId
    graph_identity: MatchGraphIdentity
    edge_selection_fingerprint: MatchArtifactFingerprint
    source_adjacency_fingerprint: MatchArtifactFingerprint
    source_snapshot: MatchSnapshotFingerprint
    fit_population_fingerprint: MatchArtifactFingerprint
    rank: MatchSvdRank
    solver: Literal["symmetric_eigendecomposition", "randomized_eigendecomposition"]
    initialization_fingerprint: MatchArtifactFingerprint
    iterations: MatchMatrixIterationCount
    normalization: Literal[
        "unnormalized_laplacian",
        "symmetric_normalized_laplacian",
        "random_walk_laplacian",
    ]
    visibility_scope: MatchPermissionFitScope

    @model_validator(mode="after")
    def validate_fit(self: Self) -> Self:
        if self.iterations <= 0:
            raise ValueError("Spectral iterations must be positive")
        return self

    @property
    def artifact_id(self: MatchSpectralArtifact) -> MatchSpectralArtifactId:
        """Bind graph, solver, population, and numerical inputs."""
        payload = {
            "edge_selection_fingerprint": str(self.edge_selection_fingerprint),
            "source_adjacency_fingerprint": str(self.source_adjacency_fingerprint),
            "fit_population_fingerprint": str(self.fit_population_fingerprint),
            "graph_identity": str(self.graph_identity),
            "initialization_fingerprint": str(self.initialization_fingerprint),
            "iterations": self.iterations,
            "normalization": self.normalization,
            "producer_ref_id": str(self.producer_ref_id),
            "rank": int(self.rank),
            "solver": self.solver,
            "source_snapshot": str(self.source_snapshot),
            "visibility_scope": str(self.visibility_scope),
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return MatchSpectralArtifactId(
            f"spectral:{hashlib.sha256(encoded.encode()).hexdigest()}",
        )


class MatchSvdFitArtifact(BaseModel, frozen=True):
    """Complete transductive identity of one bipartite SVD fit."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    producer_ref_id: MatchRepresentationProducerRefId
    source_snapshot: MatchSnapshotFingerprint
    fit_population_fingerprint: MatchArtifactFingerprint
    left_source_fingerprint: MatchArtifactFingerprint
    right_source_fingerprint: MatchArtifactFingerprint
    source_matrix_fingerprint: MatchArtifactFingerprint
    rank: MatchSvdRank
    solver: Literal["deterministic_subspace_iteration", "randomized_subspace_iteration"]
    initialization_fingerprint: MatchArtifactFingerprint
    iterations: MatchMatrixIterationCount
    visibility_scope: MatchPermissionFitScope

    @model_validator(mode="after")
    def validate_fit(self: Self) -> Self:
        if self.iterations <= 0:
            raise ValueError("SVD iterations must be positive")
        return self

    @property
    def artifact_id(self: MatchSvdFitArtifact) -> MatchSvdArtifactId:
        """Return a fingerprint that binds all transductive fit inputs."""
        payload = {
            "fit_population_fingerprint": str(self.fit_population_fingerprint),
            "initialization_fingerprint": str(self.initialization_fingerprint),
            "iterations": self.iterations,
            "left_source_fingerprint": str(self.left_source_fingerprint),
            "producer_ref_id": str(self.producer_ref_id),
            "rank": int(self.rank),
            "right_source_fingerprint": str(self.right_source_fingerprint),
            "source_matrix_fingerprint": str(self.source_matrix_fingerprint),
            "solver": self.solver,
            "source_snapshot": str(self.source_snapshot),
            "visibility_scope": str(self.visibility_scope),
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return MatchSvdArtifactId(f"svd:{hashlib.sha256(encoded.encode()).hexdigest()}")


class MatchSvdCoordinate(BaseModel, frozen=True):
    """One concrete endpoint and its fitted SVD factor coordinates."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    node_id: SysId
    node: Annotated[DatabaseObjectRow[SysId], SkipValidation]
    values: tuple[float, ...]

    @model_validator(mode="after")
    def validate_coordinate(self: Self) -> Self:
        if self.node.sys_id != self.node_id:
            raise ValueError("SVD coordinate node must match its declared identity")
        if not self.values or any(not math.isfinite(value) for value in self.values):
            raise ValueError("SVD coordinate values must be nonempty and finite")
        return self


class MatchSvdRepresentation(BaseModel, frozen=True):
    """One role-safe matrix factor representation from a shared SVD fit."""

    model_config = ConfigDict(frozen=True, extra="forbid", arbitrary_types_allowed=True)

    artifact_id: MatchSvdArtifactId
    side_role: MatchSvdFactorRole
    visibility_scope: MatchPermissionFitScope
    source_snapshot: MatchSnapshotFingerprint
    dimensions: MatchVectorDimensions
    coordinates: tuple[MatchSvdCoordinate, ...]

    @model_validator(mode="after")
    def validate_representation(self: Self) -> Self:
        node_ids = tuple(coordinate.node_id for coordinate in self.coordinates)
        if len(set(node_ids)) != len(node_ids):
            raise ValueError("SVD representation requires distinct node identities")
        if node_ids != tuple(sorted(node_ids, key=str)):
            raise ValueError("SVD representation nodes must use canonical identity order")
        if any(len(coordinate.values) != self.dimensions for coordinate in self.coordinates):
            raise ValueError("SVD coordinate width must equal representation dimensions")
        return self


class MatchSvdRepresentationSpec(BaseModel, frozen=True):
    """One side-role-specific representation emitted by an SVD fit."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    kind: Literal["svd_factor"] = "svd_factor"
    fit_artifact: MatchSvdFitArtifact
    side_role: MatchSvdFactorRole

    @property
    def representation_ref_id(self: MatchSvdRepresentationSpec) -> MatchRepresentationRefId:
        """Bind representation identity to the fitted factor side."""
        return MatchRepresentationRefId(
            f"{self.fit_artifact.artifact_id}:{self.side_role.value}",
        )


def validate_svd_fit_population(
    *,
    artifact: MatchSvdFitArtifact,
    current_population_fingerprint: MatchArtifactFingerprint,
) -> None:
    """Reject every output from a stale transductive population fit."""
    if artifact.fit_population_fingerprint != current_population_fingerprint:
        raise ValueError("SVD fit population changed; rebuild both factor representations")


def validate_svd_factor_roles(
    *,
    left: MatchSvdRepresentationSpec,
    right: MatchSvdRepresentationSpec,
) -> None:
    """Reject exchanged or independently fitted bipartite factor roles."""
    if left.side_role is not MatchSvdFactorRole.LEFT:
        raise ValueError("left SVD endpoint requires the left factor role")
    if right.side_role is not MatchSvdFactorRole.RIGHT:
        raise ValueError("right SVD endpoint requires the right factor role")
    if left.fit_artifact.artifact_id != right.fit_artifact.artifact_id:
        raise ValueError("SVD endpoints require one shared fit artifact")

