_MAX_EXACT_DENSE_DIMENSIONS = 65_536


def _branded_string_schema(cls: type[str]) -> CoreSchema:
    def _reject_other_brand(value: object) -> object:
        if isinstance(value, _MatchBrandedString) and type(value) is not cls:
            msg = f"{cls.__name__} cannot reinterpret {type(value).__name__}"
            raise ValueError(msg)
        return value

    return core_schema.no_info_after_validator_function(
        cls,
        core_schema.no_info_before_validator_function(
            _reject_other_brand,
            core_schema.str_schema(min_length=1),
        ),
        serialization=core_schema.plain_serializer_function_ser_schema(
            str,
            return_schema=core_schema.str_schema(),
        ),
    )


class _MatchBrandedString(str):
    """Nonempty nominal string used as a base for matching values."""

    __slots__ = ()

    def __new__(cls: type[Self], value: str | Self) -> Self:
        if isinstance(value, _MatchBrandedString) and type(value) is not cls:
            msg = f"{cls.__name__} cannot reinterpret {type(value).__name__}"
            raise ValueError(msg)
        if not isinstance(value, str):
            msg = f"{cls.__name__} requires a string"
            raise TypeError(msg)
        if not value:
            msg = f"{cls.__name__} cannot be empty"
            raise ValueError(msg)
        return super().__new__(cls, value)

    @classmethod
    def __get_pydantic_core_schema__(
        cls: type[_MatchBrandedString],
        source_type: object,
        handler: GetCoreSchemaHandler,
    ) -> CoreSchema:
        del source_type, handler
        return _branded_string_schema(cls)


