class _MatchBrandedPositiveInt(int):
    """Nominal positive integer for matching units."""

    __slots__ = ()

    def __new__(cls: type[Self], value: int) -> Self:
        if isinstance(value, _MatchBrandedPositiveInt) and type(value) is not cls:
            msg = f"{cls.__name__} cannot reinterpret {type(value).__name__}"
            raise ValueError(msg)
        if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            msg = f"{cls.__name__} requires a positive integer"
            raise ValueError(msg)
        return int.__new__(cls, value)

    @classmethod
    def __get_pydantic_core_schema__(
        cls: type[_MatchBrandedPositiveInt],
        source_type: object,
        handler: GetCoreSchemaHandler,
    ) -> CoreSchema:
        del source_type, handler

        def validate(value: object) -> _MatchBrandedPositiveInt:
            if not isinstance(value, int) or isinstance(value, bool):
                raise ValueError(f"{cls.__name__} requires a positive integer")
            return cls(value)

        return core_schema.no_info_plain_validator_function(
            validate,
            json_schema_input_schema=core_schema.int_schema(gt=0, strict=True),
            serialization=core_schema.plain_serializer_function_ser_schema(
                int,
                return_schema=core_schema.int_schema(),
