        if isinstance(value, _MatchBrandedNonnegativeInt) and type(value) is not cls:
            msg = f"{cls.__name__} cannot reinterpret {type(value).__name__}"
            raise ValueError(msg)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            msg = f"{cls.__name__} requires a nonnegative integer"
            raise ValueError(msg)
        return int.__new__(cls, value)

    @classmethod
    def __get_pydantic_core_schema__(
        cls: type[_MatchBrandedNonnegativeInt],
        source_type: object,
        handler: GetCoreSchemaHandler,
    ) -> CoreSchema:
        del source_type, handler

        def validate(value: object) -> _MatchBrandedNonnegativeInt:
            if isinstance(value, _MatchBrandedNonnegativeInt) and type(value) is not cls:
                msg = f"{cls.__name__} cannot reinterpret {type(value).__name__}"
                raise ValueError(msg)
            assert isinstance(value, int) and not isinstance(value, bool)
            return cls(value)

        return core_schema.no_info_after_validator_function(validate, core_schema.int_schema(ge=0))


