class MatchDenseValue(float):
    """Finite scalar coordinate in an exact dense representation."""

    __slots__ = ()

    def __new__(cls: type[Self], value: float | int | Self) -> Self:
        if not isinstance(value, int | float) or isinstance(value, bool):
            msg = "MatchDenseValue requires a number"
            raise ValueError(msg)
        numeric = float(value)
        if not math.isfinite(numeric):
            msg = "MatchDenseValue requires a finite number"
            raise ValueError(msg)
        return float.__new__(cls, numeric)

    @classmethod
    def __get_pydantic_core_schema__(
        cls: type[MatchDenseValue],
        source_type: object,
        handler: GetCoreSchemaHandler,
    ) -> CoreSchema:
        del source_type, handler
        return core_schema.no_info_after_validator_function(cls, core_schema.float_schema(allow_inf_nan=False))

    @classmethod
    def maximum_exact_coordinate(cls: type[MatchDenseValue]) -> MatchDenseValue:
        """Return the largest coordinate that guarantees finite dense accumulation."""
        return cls(_MAX_EXACT_DENSE_COORDINATE)


