"""Versioned vector input declarations; no native execution or storage ownership."""

from __future__ import annotations

from enum import StrEnum
import hashlib
import math
import struct
import sys
from typing import Annotated, Literal, Self

from pydantic import BaseModel, ConfigDict, Field, model_validator

from l1470_matching_contracts.types import (
    MatchPlanIdentity,
    MatchRepresentationRefId,
    MatchVectorDimensions,
    _MatchBrandedString,
)


class VectorFormatVersion(_MatchBrandedString):
    """Immutable serialized run format identity."""


class VectorNumericVersion(_MatchBrandedString):
    """Immutable arithmetic contract identity."""


class VectorKernelVersion(_MatchBrandedString):
    """Immutable scorer implementation identity."""


class VectorLayout(StrEnum):
    DENSE = "dense"
    SPARSE = "sparse"
    PACKED_BITS = "packed_bits"


class VectorEncoding(StrEnum):
    FP32 = "fp32"
    FP16 = "fp16"
    INT8 = "int8"
    BITS = "bits"


class VectorMetric(StrEnum):
    INNER_PRODUCT = "inner_product"
    COSINE = "cosine"
    L2 = "l2"
    L1 = "l1"
    HAMMING = "hamming"
    JACCARD = "jaccard"


class QuantizationOverflow(StrEnum):
    REJECT = "reject"
    SATURATE = "saturate"


class _FrozenContract(BaseModel):
    model_config = ConfigDict(
        frozen=True,
        extra="forbid",
        validate_default=True,
        revalidate_instances="always",
    )


def _require_finite(value: float) -> float:
    if isinstance(value, bool) or not math.isfinite(value):
        raise ValueError("Vector values must be finite numbers")
    return value


class Int8Quantization(_FrozenContract):
    scale: float = Field(gt=0, allow_inf_nan=False, strict=True)
    zero_point: int = Field(ge=-128, le=127, strict=True)
    overflow: QuantizationOverflow
    rounding: Literal["nearest_ties_even"] = "nearest_ties_even"

    def encode(self: Int8Quantization, value: float) -> int:
        """Round the scaled coordinate before the integer zero-point offset."""
        scaled = _require_finite(value) / self.scale
        if not math.isfinite(scaled):
            if self.overflow is QuantizationOverflow.SATURATE:
                return 127 if scaled > 0 else -128
            raise ValueError("INT8 coordinate exceeds the encoded range")
        code = round(scaled) + self.zero_point
        if not -128 <= code <= 127:
            if self.overflow is QuantizationOverflow.REJECT:
                raise ValueError("INT8 coordinate exceeds the encoded range")
            return min(127, max(-128, code))
        return code

    def decode(self: Int8Quantization, code: int) -> float:
        """Reconstruct a signed byte without integer overflow or saturation."""
        if type(code) is not int or not -128 <= code <= 127:
            raise ValueError("INT8 code must be an integer between -128 and 127")
        return _require_finite((code - self.zero_point) * self.scale)


class SparseCoordinates(_FrozenContract):
    indices: tuple[Annotated[int, Field(strict=True, ge=0)], ...]
    values: tuple[Annotated[float, Field(allow_inf_nan=False)], ...]


class VectorRepresentationContract(_FrozenContract):
    identity: MatchRepresentationRefId
    format_version: VectorFormatVersion
    numeric_version: VectorNumericVersion
    kernel_version: VectorKernelVersion
    layout: VectorLayout
    encoding: VectorEncoding
    metric: VectorMetric
    dimensions: MatchVectorDimensions
    quantization: Int8Quantization | None = None
    projected: bool = Field(default=False, strict=True)
    byte_order: Literal["little_endian"] = "little_endian"
    bit_order: Literal["most_significant_first"] = "most_significant_first"
    accumulator: Literal["float64"] = "float64"
    nonfinite: Literal["reject"] = "reject"
    cosine_zero: Literal["score_zero"] = "score_zero"
    empty_jaccard: Literal["similarity_one"] = "similarity_one"

    @model_validator(mode="after")
    def validate_representation(self: Self) -> Self:
        bits = self.layout is VectorLayout.PACKED_BITS
        if bits != (self.encoding is VectorEncoding.BITS):
            raise ValueError("Packed-bit layout requires bit encoding, and only that layout accepts it")
        if bits != (self.metric in (VectorMetric.HAMMING, VectorMetric.JACCARD)):
            raise ValueError("Hamming and Jaccard require packed bits; dense metrics require coordinates")
        if (self.encoding is VectorEncoding.INT8) != (self.quantization is not None):
            raise ValueError("INT8 requires quantization; other encodings forbid it")
        if self.quantization is not None:
            maximum_code = max(abs(-128 - self.quantization.zero_point), abs(127 - self.quantization.zero_point))
            # Bound the worst L2 sum with a factor of two for rounding headroom.
            coordinate_limit = math.sqrt(sys.float_info.max / (8 * self.dimensions))
            if maximum_code * self.quantization.scale > coordinate_limit:
                raise ValueError("INT8 reconstruction exceeds the finite float64 accumulation domain")
        return self

    def _encode_values(self: VectorRepresentationContract, values: tuple[float, ...]) -> bytes:
        for value in values:
            _require_finite(value)
        if self.encoding is VectorEncoding.INT8:
            quantization = self.quantization
            assert quantization is not None
            return bytes(quantization.encode(value) & 255 for value in values)
        code = "f" if self.encoding is VectorEncoding.FP32 else "e"
        try:
            return b"".join(struct.pack("<" + code, value) for value in values)
        except (OverflowError, struct.error) as error:
            raise ValueError("Vector coordinate exceeds the finite encoding range") from error

    def encode_dense(self: VectorRepresentationContract, values: tuple[float, ...]) -> bytes:
        """Encode a complete dense vector with explicit rounding and overflow rules."""
        if self.layout is not VectorLayout.DENSE or len(values) != self.dimensions:
            raise ValueError("Dense encoding requires a complete dense vector")
        return self._encode_values(values)

    def decode_dense(self: VectorRepresentationContract, payload: bytes) -> tuple[float, ...]:
        """Reject wrong lengths and nonfinite stored coordinates before execution."""
        if self.layout is not VectorLayout.DENSE:
            raise ValueError("Dense decoding requires a dense representation")
        width = {VectorEncoding.FP32: 4, VectorEncoding.FP16: 2, VectorEncoding.INT8: 1}[self.encoding]
        if len(payload) != self.dimensions * width:
            raise ValueError("Dense payload length does not match dimensions and encoding")
        return self._decode_values(payload)

    def _decode_values(self: VectorRepresentationContract, payload: bytes) -> tuple[float, ...]:
        if self.encoding is VectorEncoding.INT8:
            quantization = self.quantization
            assert quantization is not None
            return tuple(quantization.decode(value if value < 128 else value - 256) for value in payload)
        code = "f" if self.encoding is VectorEncoding.FP32 else "e"
        width = 4 if self.encoding is VectorEncoding.FP32 else 2
        values: list[float] = []
        for offset in range(0, len(payload), width):
            value = struct.unpack_from("<" + code, payload, offset)[0]
            assert isinstance(value, float)
            values.append(_require_finite(value))
        return tuple(values)

    def encode_sparse(self: VectorRepresentationContract, values: SparseCoordinates) -> bytes:
        """Validate and encode only the declared nonzero sparse coordinates."""
        self.validate_sparse(values)
        return self._encode_values(values.values)

    def validate_sparse(self: Self, values: SparseCoordinates) -> Self:
        """Require sorted unique nonzero coordinates; absent coordinates denote zero."""
        if self.layout is not VectorLayout.SPARSE or len(values.indices) != len(values.values):
            raise ValueError("Sparse validation requires matching sparse indices and values")
        previous = -1
        for index, value in zip(values.indices, values.values, strict=True):
            if not previous < index < self.dimensions:
                raise ValueError("Sparse indices must be sorted, unique, and within dimensions")
            if value == 0.0:
                raise ValueError("Canonical sparse coordinates omit explicit zeros")
            previous = index
        encoded = self._encode_values(values.values)
        if any(value == 0.0 for value in self._decode_values(encoded)):
            raise ValueError("Canonical sparse coordinates omit values that encode as zero")
        return self

    def validate_bits(self: Self, payload: bytes) -> Self:
        """Require exact packed length and zero low-order padding bits."""
        if self.layout is not VectorLayout.PACKED_BITS or len(payload) != (self.dimensions + 7) // 8:
            raise ValueError("Packed payload length does not match its bit dimensions")
        padding = (-self.dimensions) % 8
        if padding and payload[-1] & ((1 << padding) - 1):
            raise ValueError("Packed payload has nonzero padding bits")
        return self

    def fingerprint(self: VectorRepresentationContract) -> MatchPlanIdentity:
        """Identify all persisted representation and numerical fields, without runtime state."""
        return MatchPlanIdentity(hashlib.sha256(self.model_dump_json().encode("utf-8")).hexdigest())

