"""Declarative score, result, and planned capability contracts for vector matching."""

from __future__ import annotations

from enum import StrEnum
import math
from typing import Literal, Self

from pydantic import Field, model_validator

from l1400_types import BackendType
from l1470_matching_contracts.types import (
    MatchExactness,
    MatchGuarantee,
    MatchResultLimit,
    MatchResultShapeKind,
    MatchThresholdBoundary,
    NeighborCount,
)
from l1470_matching_contracts.vector_contracts import (
    VectorEncoding,
    VectorLayout,
    VectorMetric,
    VectorRepresentationContract,
    _FrozenContract,
    _require_finite,
)


class VectorDistanceKind(StrEnum):
    NEGATIVE_INNER_PRODUCT = "negative_inner_product"
    ONE_MINUS_INNER_PRODUCT = "one_minus_inner_product"
    NEGATIVE_COSINE = "negative_cosine"
    COSINE_DISTANCE = "cosine_distance"
    L2 = "l2"
    SQUARED_L2 = "squared_l2"
    L1 = "l1"
    HAMMING = "hamming"
    JACCARD_DISTANCE = "jaccard_distance"


class VectorScoreMapping(StrEnum):
    NEGATE = "negate"
    ONE_MINUS = "one_minus"
    RECIPROCAL = "reciprocal"
    RECIPROCAL_SQRT = "reciprocal_sqrt"
    NORMALIZED_HAMMING = "normalized_hamming"


class VectorScoreContract(_FrozenContract):
    representation: VectorRepresentationContract
    distance: VectorDistanceKind
    mapping: VectorScoreMapping

    @model_validator(mode="after")
    def validate_mapping(self: Self) -> Self:
        expected = {
            VectorDistanceKind.NEGATIVE_INNER_PRODUCT: (VectorMetric.INNER_PRODUCT, VectorScoreMapping.NEGATE),
            VectorDistanceKind.ONE_MINUS_INNER_PRODUCT: (VectorMetric.INNER_PRODUCT, VectorScoreMapping.ONE_MINUS),
            VectorDistanceKind.NEGATIVE_COSINE: (VectorMetric.COSINE, VectorScoreMapping.NEGATE),
            VectorDistanceKind.COSINE_DISTANCE: (VectorMetric.COSINE, VectorScoreMapping.ONE_MINUS),
            VectorDistanceKind.L2: (VectorMetric.L2, VectorScoreMapping.RECIPROCAL),
            VectorDistanceKind.SQUARED_L2: (VectorMetric.L2, VectorScoreMapping.RECIPROCAL_SQRT),
            VectorDistanceKind.L1: (VectorMetric.L1, VectorScoreMapping.RECIPROCAL),
            VectorDistanceKind.HAMMING: (VectorMetric.HAMMING, self.mapping),
            VectorDistanceKind.JACCARD_DISTANCE: (VectorMetric.JACCARD, VectorScoreMapping.ONE_MINUS),
        }[self.distance]
        if (self.representation.metric, self.mapping) != expected:
            raise ValueError("Distance kind, metric, and score mapping do not agree")
        if self.distance is VectorDistanceKind.HAMMING and self.mapping not in (
            VectorScoreMapping.NEGATE,
            VectorScoreMapping.NORMALIZED_HAMMING,
        ):
            raise ValueError("Hamming supports negative distance or normalized similarity")
        return self

    def _validate_distance(self: VectorScoreContract, value: float) -> None:
        _require_finite(value)
        if self.distance is VectorDistanceKind.NEGATIVE_COSINE and not -1 <= value <= 1:
            raise ValueError("Negative cosine must be between -1 and 1")
        if self.distance is VectorDistanceKind.COSINE_DISTANCE and not 0 <= value <= 2:
            raise ValueError("Cosine distance must be between 0 and 2")
        if self.distance is VectorDistanceKind.JACCARD_DISTANCE and not 0 <= value <= 1:
            raise ValueError("Jaccard distance must be between 0 and 1")
        if self.distance in (VectorDistanceKind.L1, VectorDistanceKind.L2, VectorDistanceKind.SQUARED_L2) and value < 0:
            raise ValueError("Norm distances must be nonnegative")
        if self.distance is VectorDistanceKind.HAMMING and (
            not 0 <= value <= self.representation.dimensions or value != math.trunc(value)
        ):
            raise ValueError("Hamming distance must be an integer within bit dimensions")

    def score(self: VectorScoreContract, raw_distance: float) -> float:
        """Map an explicit adapter distance to its declared public similarity."""
        self._validate_distance(raw_distance)
        if self.mapping is VectorScoreMapping.NEGATE:
            return -raw_distance
        if self.mapping is VectorScoreMapping.ONE_MINUS:
            return _require_finite(1.0 - raw_distance)
        if self.mapping is VectorScoreMapping.RECIPROCAL:
            return 1.0 / (1.0 + raw_distance)
        if self.mapping is VectorScoreMapping.RECIPROCAL_SQRT:
            return 1.0 / (1.0 + math.sqrt(raw_distance))
        return 1.0 - raw_distance / self.representation.dimensions

    def accepts(
        self: VectorScoreContract,
        raw_distance: float,
        threshold: float,
        boundary: MatchThresholdBoundary = MatchThresholdBoundary.INCLUSIVE,
    ) -> bool:
        """Apply even out-of-domain thresholds without unsafe inverse conversion."""
        _require_finite(threshold)
        score = self.score(raw_distance)
        if boundary is MatchThresholdBoundary.INCLUSIVE:
            return score >= threshold
        if boundary is MatchThresholdBoundary.EXCLUSIVE:
            return score > threshold
        raise ValueError("Unknown threshold boundary")

    def distance_for_score(self: VectorScoreContract, score: float) -> float:
        """Invert representable scores; reciprocal zero denotes an unbounded distance."""
        _require_finite(score)
        if self.mapping is VectorScoreMapping.NEGATE:
            result = -score
        elif self.mapping is VectorScoreMapping.ONE_MINUS:
            result = _require_finite(1.0 - score)
        elif self.mapping is VectorScoreMapping.NORMALIZED_HAMMING:
            if not 0 <= score <= 1:
                raise ValueError("Normalized Hamming score must be between 0 and 1")
            return (1.0 - score) * self.representation.dimensions
        else:
            if not 0 <= score <= 1:
                raise ValueError("Reciprocal score must be between 0 and 1")
            if score == 0:
                return math.inf
            result = 1.0 / score - 1.0
            if self.mapping is VectorScoreMapping.RECIPROCAL_SQRT:
                result *= result
        self._validate_distance(result)
        return result


class VectorCandidateMethod(StrEnum):
    EXHAUSTIVE = "exhaustive"
    HNSW = "hnsw"


class VectorScoreTarget(StrEnum):
    STORED_REPRESENTATION = "stored_representation"
    SOURCE_DENSE = "source_dense"
    ESTIMATOR = "estimator"


class VectorSearchContract(_FrozenContract):
    representation: VectorRepresentationContract
    candidate_method: VectorCandidateMethod
    score_target: VectorScoreTarget
    guarantee: MatchGuarantee
    dense_rerank: bool = False
    source_vectors_available: bool = False

    @property
    def source_exactness(self: VectorSearchContract) -> MatchExactness:
        if self.candidate_method is VectorCandidateMethod.HNSW or self.score_target is VectorScoreTarget.ESTIMATOR:
            return MatchExactness.APPROXIMATE
        if self.dense_rerank and self.source_vectors_available:
            return MatchExactness.EXACT
        if self.representation.projected or self.representation.encoding is not VectorEncoding.FP32:
            return MatchExactness.APPROXIMATE
        return MatchExactness.EXACT

    @model_validator(mode="after")
    def validate_exactness(self: Self) -> Self:
        if self.dense_rerank and (not self.source_vectors_available or self.score_target is not VectorScoreTarget.SOURCE_DENSE):
            raise ValueError("Dense reranking requires source vectors and a source-dense score target")
        if self.guarantee is MatchGuarantee.EXACT:
            if self.candidate_method is not VectorCandidateMethod.EXHAUSTIVE:
                raise ValueError("Approximate candidates cannot guarantee complete exact results")
            if self.score_target is VectorScoreTarget.SOURCE_DENSE and self.source_exactness is not MatchExactness.EXACT:
                raise ValueError("Exact source scores require canonical source coordinates or complete dense reranking")
        return self


class VectorResultContract(_FrozenContract):
    shape: MatchResultShapeKind
    result_limit: MatchResultLimit
    neighbors: NeighborCount | None = None
    threshold: float | None = Field(default=None, allow_inf_nan=False)
    boundary: MatchThresholdBoundary = MatchThresholdBoundary.INCLUSIVE
    mutual: bool = False
    reverse_neighbors: NeighborCount | None = None
    tie_order: Literal["left_identity_then_right_identity"] = "left_identity_then_right_identity"

    @model_validator(mode="after")
    def validate_shape(self: Self) -> Self:
        if self.shape is MatchResultShapeKind.THRESHOLD_JOIN:
            if self.threshold is None or self.neighbors is not None:
                raise ValueError("Threshold joins require a threshold and forbid a neighbor count")
        elif self.neighbors is None or self.threshold is not None:
            raise ValueError("Top-k shapes require a neighbor count and forbid a threshold")
        if self.mutual:
            if self.shape is not MatchResultShapeKind.TOP_K_PER_LEFT or self.reverse_neighbors is None:
                raise ValueError("Mutual neighbors require per-left top-k and a reverse neighbor count")
        elif self.reverse_neighbors is not None:
            raise ValueError("Reverse neighbor counts require mutual neighbors")
        return self


class PlannedVectorMethod(StrEnum):
    SQLITE_NATIVE_EXACT = "sqlite_native_exact"
    PORTABLE_NATIVE_EXACT = "portable_native_exact"


class PgvectorReferenceType(StrEnum):
    VECTOR = "vector"
    HALFVEC = "halfvec"
    SPARSEVEC = "sparsevec"
    BIT = "bit"


class PgvectorReferenceOperator(StrEnum):
    NEGATIVE_INNER_PRODUCT = "<#>"
    COSINE_DISTANCE = "<=>"
    L2 = "<->"
    L1 = "<+>"
    HAMMING = "<~>"
    JACCARD = "<%>"


class RequiredVectorCapability(_FrozenContract):
    backend: BackendType
    layout: VectorLayout
    encoding: VectorEncoding
    metric: VectorMetric
    method: PlannedVectorMethod
    state: Literal["planned_not_runtime_support"] = "planned_not_runtime_support"
    native_usearch_version: Literal["2.23.0"] = "2.23.0"
    pgvector_reference_version: Literal["0.8.0"] = "0.8.0"

    @model_validator(mode="after")
    def validate_physical_obligation(self: Self) -> Self:
        if self.backend not in (BackendType.SQLITE, BackendType.POSTGRES, BackendType.MARIADB):
            raise ValueError("Capability obligations cover maintained in-tree backends")
        expected_method = (
            PlannedVectorMethod.SQLITE_NATIVE_EXACT if self.backend is BackendType.SQLITE else PlannedVectorMethod.PORTABLE_NATIVE_EXACT
        )
        if self.method is not expected_method:
            raise ValueError("Capability method does not match the backend execution boundary")
        bits = self.layout is VectorLayout.PACKED_BITS
        if bits != (self.encoding is VectorEncoding.BITS) or bits != (self.metric in (VectorMetric.HAMMING, VectorMetric.JACCARD)):
            raise ValueError("Capability metric, layout, and encoding do not agree")
        return self

    @property
    def pgvector_type(self: RequiredVectorCapability) -> PgvectorReferenceType | None:
        """Return the reference storage type, not a deployed backend selection."""
        if self.encoding is VectorEncoding.INT8:
            return None
        if self.layout is VectorLayout.SPARSE:
            return PgvectorReferenceType.SPARSEVEC if self.encoding is VectorEncoding.FP32 else None
        if self.layout is VectorLayout.PACKED_BITS:
            return PgvectorReferenceType.BIT
        return PgvectorReferenceType.HALFVEC if self.encoding is VectorEncoding.FP16 else PgvectorReferenceType.VECTOR

    @property
    def pgvector_operator(self: RequiredVectorCapability) -> PgvectorReferenceOperator | None:
        if self.pgvector_type is None:
            return None
        return {
            VectorMetric.INNER_PRODUCT: PgvectorReferenceOperator.NEGATIVE_INNER_PRODUCT,
            VectorMetric.COSINE: PgvectorReferenceOperator.COSINE_DISTANCE,
            VectorMetric.L2: PgvectorReferenceOperator.L2,
            VectorMetric.L1: PgvectorReferenceOperator.L1,
            VectorMetric.HAMMING: PgvectorReferenceOperator.HAMMING,
            VectorMetric.JACCARD: PgvectorReferenceOperator.JACCARD,
        }[self.metric]


def required_vector_capabilities(backend: BackendType) -> tuple[RequiredVectorCapability, ...]:
    """Return mandatory implementation obligations, not detected runtime capabilities."""
    if backend not in (BackendType.SQLITE, BackendType.POSTGRES, BackendType.MARIADB):
        raise ValueError("The mandatory capability matrix covers only maintained in-tree backends")
    method = PlannedVectorMethod.SQLITE_NATIVE_EXACT if backend is BackendType.SQLITE else PlannedVectorMethod.PORTABLE_NATIVE_EXACT
    numeric = tuple(
        RequiredVectorCapability(backend=backend, layout=layout, encoding=encoding, metric=metric, method=method)
        for layout in (VectorLayout.DENSE, VectorLayout.SPARSE)
        for encoding in (VectorEncoding.FP32, VectorEncoding.FP16, VectorEncoding.INT8)
        for metric in (VectorMetric.INNER_PRODUCT, VectorMetric.COSINE, VectorMetric.L2, VectorMetric.L1)
    )
    bits = tuple(
        RequiredVectorCapability(
            backend=backend, layout=VectorLayout.PACKED_BITS, encoding=VectorEncoding.BITS, metric=metric, method=method
        )
        for metric in (VectorMetric.HAMMING, VectorMetric.JACCARD)
    )
    return numeric + bits

