"""Deterministic, metadata-only selection for leveled native run compaction."""
from __future__ import annotations

from fractions import Fraction
from threading import Lock
from typing import Self

from pydantic import BaseModel, ConfigDict, Field, model_validator

from l1100_exceptions import NativeSearchBudgetExceededError, NativeSearchIntegrityError, PhysicalLimit
from l1400_types import SysId
from l2055_lazy_result.purity import pure_lazy
from l1470_matching_contracts.vector_contracts import VectorFormatVersion, VectorKernelVersion, VectorNumericVersion
from l5200_vector_index.usearch_run_models import USearchRunId
from l5200_vector_index.usearch_types import (
    USearchMembershipDigest,
    USearchMetric,
    USearchPayloadDigest,
    USearchProjectionIdentity,
    USearchRunEncoding,
    USearchRunLayout,
)


class USearchCompactionPolicy(BaseModel):
    """Byte and run-count bounds; queries never consume this policy to build runs."""

    model_config = ConfigDict(frozen=True)

    output_run_bytes: int = Field(default=8 * 1024 * 1024, gt=0)
    base_level_bytes: int = Field(default=32 * 1024 * 1024, gt=0)
    growth_factor: int = Field(default=10, ge=2)
    level_zero_run_trigger: int = Field(default=4, ge=2)
    level_zero_byte_trigger: int = Field(default=32 * 1024 * 1024, gt=0)
    max_compaction_bytes: int = Field(default=128 * 1024 * 1024, gt=0)
    level_zero_stop_runs: int = Field(default=16, ge=2)
    level_zero_stop_bytes: int = Field(default=256 * 1024 * 1024, gt=0)

    @model_validator(mode="after")
    def _bounds(self: Self) -> Self:
        if self.output_run_bytes > self.max_compaction_bytes:
            raise ValueError("Compaction output target exceeds its input budget")
        if self.level_zero_stop_runs <= self.level_zero_run_trigger:
            raise ValueError("Level-zero stop threshold must exceed the compaction trigger")
        if self.level_zero_stop_bytes <= self.level_zero_byte_trigger:
            raise ValueError("Level-zero byte stop threshold must exceed the compaction trigger")
        return self


DEFAULT_USEARCH_COMPACTION_POLICY = USearchCompactionPolicy()
_policy_lock = Lock()
_policy = DEFAULT_USEARCH_COMPACTION_POLICY


def get_usearch_compaction_policy() -> USearchCompactionPolicy:
    """Return the immutable policy for new maintenance plans."""
    with _policy_lock:
        return _policy


def configure_usearch_compaction_policy(policy: USearchCompactionPolicy) -> None:
    """Set process policy before the application constructs maintenance plans."""
    global _policy
    with _policy_lock:
        _policy = policy


def validate_usearch_append_pressure(
    *, level_zero_runs: int, level_zero_bytes: int, policy: USearchCompactionPolicy,
) -> None:
    """Reject an append that enters the declared level-zero stop region."""
    exceeded: dict[PhysicalLimit, tuple[int, int]] = {}
    if level_zero_runs > policy.level_zero_stop_runs:
        exceeded[PhysicalLimit.NATIVE_ACTIVE_RUNS] = (
            level_zero_runs, policy.level_zero_stop_runs,
        )
    if level_zero_bytes > policy.level_zero_stop_bytes:
        exceeded[PhysicalLimit.NATIVE_COMPACTION_BACKLOG_BYTES] = (
            level_zero_bytes, policy.level_zero_stop_bytes,
        )
    if exceeded:
        raise NativeSearchBudgetExceededError(exceeded_dimensions=exceeded)


class USearchCompactionRun(BaseModel):
    """Snapshot metadata sufficient to select inputs without loading payload bytes."""

    model_config = ConfigDict(frozen=True)

    run_id: USearchRunId
    artifact_id: SysId
    published_epoch: int = Field(gt=0)
    level: int = Field(ge=0)
    first_native_key: int = Field(gt=0)
    last_native_key: int = Field(gt=0)
    serialized_bytes: int = Field(gt=0)
    member_count: int = Field(gt=0)
    payload_sha256: USearchPayloadDigest = Field(pattern=r"^[0-9a-f]{64}$")
    membership_sha256: USearchMembershipDigest = Field(pattern=r"^[0-9a-f]{64}$")
    format_version: VectorFormatVersion
    numeric_version: VectorNumericVersion
    kernel_version: VectorKernelVersion
    projection_identity: USearchProjectionIdentity
    dimensions: int = Field(gt=0)
    metric: USearchMetric
    encoding: USearchRunEncoding
    layout: USearchRunLayout

    @pure_lazy
    def compatibility_identity(
        self: Self,
    ) -> tuple[
        VectorFormatVersion,
        VectorNumericVersion,
        VectorKernelVersion,
        USearchProjectionIdentity,
        int,
        USearchMetric,
        USearchRunEncoding,
        USearchRunLayout,
    ]:
        """Preserve the complete representation contract in selection and publication proofs."""
        return (
            self.format_version, self.numeric_version, self.kernel_version,
            self.projection_identity, self.dimensions, self.metric, self.encoding, self.layout,
        )

    @model_validator(mode="after")
    def _range(self: Self) -> Self:
        if self.first_native_key > self.last_native_key:
            raise ValueError("Compaction run key range is reversed")
        return self


class USearchCompactionSelection(BaseModel):
    """Immutable input proof to compare again in the publication transaction."""

    model_config = ConfigDict(frozen=True)

    artifact_id: SysId
    artifact_epoch: int = Field(gt=0)
    input_runs: tuple[USearchCompactionRun, ...]
    source_level: int = Field(ge=0)
    destination_level: int = Field(gt=0)
    input_bytes: int = Field(gt=0)
    next_cursor: int = Field(gt=0)

    def matches_current_snapshot(
        self: Self, *, artifact_id: SysId, artifact_epoch: int,
        active_inputs: tuple[USearchCompactionRun, ...],
    ) -> bool:
        """Recheck the input proof while the publication transaction holds its lock."""
        if artifact_id != self.artifact_id or artifact_epoch != self.artifact_epoch:
            return False
        if len(active_inputs) != len(self.input_runs):
            return False
        current = {run.run_id: run for run in active_inputs}
        if len(current) != len(active_inputs):
            return False
        return all(current.get(run.run_id) == run for run in self.input_runs)


@pure_lazy
def validate_compaction_input_selection(
    selection: USearchCompactionSelection, policy: USearchCompactionPolicy,
) -> None:
    """Check the detached selection before transport or native allocation."""
    inputs = selection.input_runs
    identities = {run.run_id for run in inputs}
    byte_count = sum(run.serialized_bytes for run in inputs)
    if not inputs or len(identities) != len(inputs) or byte_count != selection.input_bytes:
        raise NativeSearchIntegrityError("Compaction input selection has an invalid byte or identity proof")
    if selection.destination_level != selection.source_level + 1 or any(
        run.member_count <= 0
        or run.serialized_bytes <= 0
        or run.first_native_key <= 0
        or run.last_native_key < run.first_native_key
        or run.artifact_id != selection.artifact_id
        or run.published_epoch <= 0
        or run.published_epoch > selection.artifact_epoch
        or run.level not in {selection.source_level, selection.destination_level}
        or run.compatibility_identity() != inputs[0].compatibility_identity()
        for run in inputs
    ):
        raise NativeSearchIntegrityError("Compaction input selection has an invalid snapshot or representation proof")
    if byte_count > policy.max_compaction_bytes:
        raise NativeSearchBudgetExceededError(exceeded_dimensions={
            PhysicalLimit.NATIVE_ARTIFACT_BYTES: (byte_count, policy.max_compaction_bytes),
        })


def select_usearch_compaction(
    runs: tuple[USearchCompactionRun, ...], *, artifact_id: SysId, artifact_epoch: int,
    policy: USearchCompactionPolicy, cursors: dict[int, int],
) -> USearchCompactionSelection | None:
    """Select a bounded overlap-closed input set from one artifact snapshot."""
    if artifact_epoch <= 0 or any(level < 0 or cursor <= 0 for level, cursor in cursors.items()):
        raise NativeSearchIntegrityError("Compaction epoch or cursor is invalid")
    if runs and any(run.compatibility_identity() != runs[0].compatibility_identity() for run in runs):
        raise NativeSearchIntegrityError("Compaction inputs have incompatible representation identities")
    levels: dict[int, list[USearchCompactionRun]] = {}
    identities: set[USearchRunId] = set()
    for run in runs:
        if run.artifact_id != artifact_id or run.published_epoch > artifact_epoch:
            raise NativeSearchIntegrityError("Compaction input is outside the selected artifact snapshot")
        if run.run_id in identities:
            raise NativeSearchIntegrityError("Compaction selection repeats an immutable run")
        identities.add(run.run_id)
        levels.setdefault(run.level, []).append(run)
    for level, entries in levels.items():
        entries.sort(key=lambda run: (run.first_native_key, str(run.run_id)))
        if level > 0 and any(
            left.last_native_key >= right.first_native_key for left, right in zip(entries, entries[1:])
        ):
            raise NativeSearchIntegrityError("Higher-level compaction inputs have overlapping key ranges")
    scores: dict[int, Fraction] = {}
    for level, entries in levels.items():
        total = sum(run.serialized_bytes for run in entries)
        if level == 0:
            scores[level] = max(
                Fraction(len(entries), policy.level_zero_run_trigger),
                Fraction(total, policy.level_zero_byte_trigger),
            )
        else:
            scores[level] = Fraction(total, policy.base_level_bytes * policy.growth_factor ** (level - 1))
    eligible = [level for level, score in scores.items() if score >= 1]
    if not eligible:
        return None
    source = min(eligible, key=lambda level: (-scores[level], level))
    entries = levels[source]
    if source == 0:
        candidates = sorted(entries, key=lambda run: (run.published_epoch, str(run.run_id)))
    else:
        cursor = cursors.get(source, 1)
        candidates = [next((run for run in entries if run.first_native_key >= cursor), entries[0])]
    destination = levels.get(source + 1, [])
    selected: list[USearchCompactionRun] = []
    overlaps: list[USearchCompactionRun] = []
    for candidate in candidates:
        proposed = [*selected, candidate]
        first = min(run.first_native_key for run in proposed)
        last = max(run.last_native_key for run in proposed)
        closed: list[USearchCompactionRun] = []
        while True:
            expanded = [run for run in destination if run.first_native_key <= last and run.last_native_key >= first]
            if len(expanded) == len(closed):
                break
            closed = expanded
            first = min(first, *(run.first_native_key for run in closed))
            last = max(last, *(run.last_native_key for run in closed))
        size = sum(run.serialized_bytes for run in (*proposed, *closed))
        if size > policy.max_compaction_bytes:
            break
        selected, overlaps = proposed, closed
    if not selected:
        return None
    inputs = tuple([*selected, *overlaps])
    return USearchCompactionSelection(
        artifact_id=artifact_id, artifact_epoch=artifact_epoch, input_runs=inputs,
        source_level=source, destination_level=source + 1,
        input_bytes=sum(run.serialized_bytes for run in inputs),
        next_cursor=max(run.last_native_key for run in inputs) + 1,
    )

