"""Typed database authority for immutable canonical-content runs.

Run membership describes canonical embeddings, not source-object or chunk identities.
The caller transaction publishes a run and its members with the artifact epoch.
"""
from __future__ import annotations

from hashlib import sha256
from typing import Self

from pydantic import ConfigDict, Field, field_validator, model_validator

from l1000_schema.schema_def import ApplicationObjectRow, Column, Index, NO_FOREIGN_KEY
from l1000_schema.table_registry import register_table
from l1400_types import DynamicFieldName, RowId, SysId
from l1470_matching_contracts.vector_contracts import (
    VectorFormatVersion, VectorKernelVersion, VectorNumericVersion,
)
from l4000_permissions.no_security_scheme import NoSecurityScheme
from l4000_permissions.permission_registry import register_permissions
from l5200_vector_index.content_addressable_models import EmbeddingVectorId
from l5200_vector_index.usearch_types import (
    USearchEmbeddingDigest,
    USearchMembershipDigest,
    USearchMetric,
    USearchPayloadDigest,
    USearchProjectionIdentity,
    USearchRunEncoding,
    USearchRunLayout,
)


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(
    plural="sys_usearch_runs", singular="sys_usearch_run", audited=False,
    indexes=[Index(
        name="idx_sys_usearch_runs_artifact_epoch",
        columns=(DynamicFieldName("artifact_id"), DynamicFieldName("published_epoch")),
        navigation=False,
    )],
)
class USearchRun(ApplicationObjectRow["USearchRunId"]):
    """An immutable native payload with a versioned membership digest."""

    model_config = ConfigDict(hide_input_in_errors=True)

    sys_id: USearchRunId = Field(
        default_factory=lambda: USearchRunId.new(),
        json_schema_extra={"primary_key": True, "autoincrement": False, "nullable": False},
    )
    artifact_id: SysId = Column(nullable=False)
    level: int = Column(default=0, nullable=False)
    published_epoch: int = Column(nullable=False)
    retired_epoch: int | None = Column(default=None, nullable=True)
    format_version: VectorFormatVersion = Column(max_length=64, nullable=False)
    numeric_version: VectorNumericVersion = Column(max_length=64, nullable=False)
    kernel_version: VectorKernelVersion = Column(max_length=64, nullable=False)
    projection_identity: USearchProjectionIdentity = Column(max_length=256, nullable=False)
    dimensions: int = Column(nullable=False)
    metric: USearchMetric = Column(max_length=32, nullable=False)
    encoding: USearchRunEncoding = Column(max_length=32, nullable=False)
    layout: USearchRunLayout = Column(max_length=32, nullable=False)
    payload: bytes = Column(nullable=False)
    payload_sha256: USearchPayloadDigest = Column(max_length=64, nullable=False)
    membership_sha256: USearchMembershipDigest = Column(max_length=64, nullable=False)
    member_count: int = Column(nullable=False)

    @model_validator(mode="after")
    def _validate_contract(self: Self) -> Self:
        if self.level < 0 or self.published_epoch <= 0 or self.member_count < 0:
            raise ValueError("Run level, epoch, or member count is invalid")
        if self.retired_epoch is not None and self.retired_epoch <= self.published_epoch:
            raise ValueError("Run retirement must follow publication")
        if not 1 <= self.dimensions <= 65536 or not self.projection_identity:
            raise ValueError("Run dimensions and projection identity are required")
        if str(self.format_version) != "usearch-run-v1":
            raise ValueError("Run format version is unsupported")
        if str(self.numeric_version) != "f64-v1":
            raise ValueError("Run numerical version is unsupported")
        if self.metric not in {"cos", "ip", "l2sq"}:
            raise ValueError("Run metric is unsupported")
        if str(self.kernel_version) != f"legacy-score-v1/{self.metric}":
            raise ValueError("Run kernel version does not match its metric")
        if self.encoding != "fp32" or self.layout != "dense":
            raise ValueError("Native run v1 requires dense FP32 vectors")
        for digest in (self.payload_sha256, self.membership_sha256):
            if len(digest) != 64 or any(char not in "0123456789abcdef" for char in digest):
                raise ValueError("Run digests must be lowercase SHA-256 values")
        if sha256(self.payload).hexdigest() != self.payload_sha256:
            raise ValueError("Run payload digest does not match its bytes")
        return self


class USearchRunId(RowId[USearchRun]):
    """Identity of one immutable database run."""


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(
    plural="sys_usearch_run_members", singular="sys_usearch_run_member", audited=False,
    indexes=[
        Index(
            name="idx_sys_usearch_run_members_key",
            columns=(DynamicFieldName("run_id"), DynamicFieldName("native_key")),
            unique=True, navigation=False,
        ),
        Index(
            name="idx_sys_usearch_run_members_vector",
            columns=(DynamicFieldName("run_id"), DynamicFieldName("embedding_vector_id")),
            unique=True, navigation=False,
        ),
    ],
)
class USearchRunMember(ApplicationObjectRow["USearchRunMemberId"]):
    """Bind a durable content key to one run and its original vector digest."""

    sys_id: USearchRunMemberId = Field(
        default_factory=lambda: USearchRunMemberId.new(),
        json_schema_extra={"primary_key": True, "autoincrement": False, "nullable": False},
    )
    run_id: USearchRunId = Column(nullable=False, foreign_key=NO_FOREIGN_KEY)
    native_key: int = Column(nullable=False, sql_type="BIGINT")
    embedding_vector_id: EmbeddingVectorId = Column(nullable=False, foreign_key=NO_FOREIGN_KEY)
    content_hash_short: int = Column(nullable=False, sql_type="BIGINT")
    content_hash_high: int = Column(nullable=False, sql_type="BIGINT")
    embedding_sha256: USearchEmbeddingDigest = Column(max_length=64, nullable=False)

    @field_validator("native_key")
    @classmethod
    def _validate_native_key(cls: type[Self], value: int) -> int:
        if not 0 < value < 2**63:
            raise ValueError("Run native keys must be positive signed 64-bit integers")
        return value

    @field_validator("embedding_sha256")
    @classmethod
    def _validate_embedding_digest(
        cls: type[Self],
        value: USearchEmbeddingDigest,
    ) -> USearchEmbeddingDigest:
        if len(value) != 64 or any(char not in "0123456789abcdef" for char in value):
            raise ValueError("Run embedding digest must be a lowercase SHA-256 value")
        return value


class USearchRunMemberId(RowId[USearchRunMember]):
    """Identity of one immutable run membership row."""


@register_permissions(scheme_factory=NoSecurityScheme)
@register_table(
    plural="sys_usearch_compaction_cursors", singular="sys_usearch_compaction_cursor",
    audited=False,
    indexes=[Index(
        name="idx_sys_usearch_compaction_cursors_artifact_level",
        columns=(DynamicFieldName("artifact_id"), DynamicFieldName("source_level")),
        unique=True, navigation=False,
    )],
)
class USearchCompactionCursor(ApplicationObjectRow["USearchCompactionCursorId"]):
    """The durable next key for one artifact and compaction source level."""

    sys_id: USearchCompactionCursorId = Field(
        default_factory=lambda: USearchCompactionCursorId.new(),
        json_schema_extra={"primary_key": True, "autoincrement": False, "nullable": False},
    )
    artifact_id: SysId = Column(nullable=False, foreign_key=NO_FOREIGN_KEY)
    source_level: int = Column(nullable=False)
    next_native_key: int = Column(nullable=False, sql_type="BIGINT")
    publication_epoch: int = Column(nullable=False)

    @model_validator(mode="after")
    def _validate_cursor(self: Self) -> Self:
        if self.source_level < 0 or self.next_native_key <= 0 or self.publication_epoch <= 0:
            raise ValueError("Compaction cursor level, key, and epoch must be positive")
        return self


class USearchCompactionCursorId(RowId[USearchCompactionCursor]):
    """Identity of one durable compaction cursor."""


USearchRun.model_rebuild()
USearchRunMember.model_rebuild()
USearchCompactionCursor.model_rebuild()

