"""Construct immutable run records without opening or committing transactions."""
from __future__ import annotations

from collections.abc import Mapping, Sequence
from hashlib import sha256
import json
from typing import TYPE_CHECKING, Self

from pydantic import BaseModel, ConfigDict, ValidationError, field_validator
from l1400_types import SysId
from l2055_lazy_result.purity import pure_lazy
from l5200_vector_index.usearch_types import (
    USearchArtifactEpoch,
    USearchEmbeddingDigest,
    USearchMembershipDigest,
    USearchMetric,
    USearchNativeKey,
    USearchPayloadDigest,
    USearchProjectionIdentity,
)
from l5200_vector_index.usearch_request_limits import USearchRequestLimits, validate_usearch_request_limits

if TYPE_CHECKING:
    from l5200_vector_index.usearch_runtime import USearchRunSearchRequest

from l1100_exceptions import NativeSearchIntegrityError
from l1470_matching_contracts.vector_contracts import (
    VectorFormatVersion, VectorKernelVersion, VectorNumericVersion,
)
from l5200_vector_index.hnsw_models import USearchArtifactMember, USearchIndexBlobBase
from l5200_vector_index.usearch_run_models import USearchRun, USearchRunMember


@pure_lazy
def run_membership_digest(members: Sequence[USearchRunMember]) -> USearchMembershipDigest:
    """Hash canonical membership without database row IDs or physical ordering."""
    rows = [
        [member.native_key, str(member.embedding_vector_id),
         member.content_hash_short, member.content_hash_high, member.embedding_sha256]
        for member in sorted(members, key=lambda member: member.native_key)
    ]
    return USearchMembershipDigest(
        sha256(json.dumps(rows, separators=(",", ":"), ensure_ascii=True).encode("ascii")).hexdigest()
    )


def usearch_projection_identity(
    source_dimensions: int | None,
    dimensions: int,
) -> USearchProjectionIdentity:
    """Name the identity or prefix projection used by the native builder."""
    if source_dimensions is not None and source_dimensions != dimensions:
        return USearchProjectionIdentity(f"prefix:{source_dimensions}:{dimensions}")
    return USearchProjectionIdentity(f"identity:{dimensions}")


def prepare_usearch_run(
    artifact: USearchIndexBlobBase,
    members: Sequence[USearchArtifactMember],
    *, projection_identity: USearchProjectionIdentity | None = None,
) -> tuple[USearchRun, tuple[USearchRunMember, ...]]:
    """Bind a newly built native payload to complete canonical membership."""
    from l5200_vector_index.usearch_run_models import USearchRunId

    run_id = USearchRunId.new()
    run_members: list[USearchRunMember] = []
    keys: set[int] = set()
    identities: set[str] = set()
    for member in members:
        if member.artifact_id != artifact.sys_id:
            raise NativeSearchIntegrityError("Run membership belongs to a different artifact")
        if member.native_key in keys or str(member.embedding_vector_id) in identities:
            raise NativeSearchIntegrityError("Run membership has duplicate keys or vectors")
        if member.content_hash_short is None or member.content_hash_high is None or not member.embedding_sha256:
            raise NativeSearchIntegrityError("Run membership requires complete content metadata")
        keys.add(member.native_key)
        identities.add(str(member.embedding_vector_id))
        run_members.append(USearchRunMember(
            run_id=run_id,
            native_key=member.native_key,
            embedding_vector_id=member.embedding_vector_id,
            content_hash_short=member.content_hash_short,
            content_hash_high=member.content_hash_high,
            embedding_sha256=USearchEmbeddingDigest(member.embedding_sha256),
        ))
    if artifact.num_nodes != len(run_members):
        raise NativeSearchIntegrityError("Run payload and membership counts disagree")
    run = USearchRun(
        sys_id=run_id,
        artifact_id=artifact.sys_id,
        published_epoch=artifact.artifact_epoch,
        format_version=VectorFormatVersion("usearch-run-v1"),
        numeric_version=VectorNumericVersion("f64-v1"),
        kernel_version=VectorKernelVersion(f"legacy-score-v1/{artifact.metric_type}"),
        projection_identity=(
            usearch_projection_identity(None, artifact.dimensionality)
            if projection_identity is None else projection_identity
        ),
        dimensions=artifact.dimensionality,
        metric=artifact.metric_type,
        encoding="fp32",
        layout="dense",
        payload=artifact.index_blob,
        payload_sha256=USearchPayloadDigest(artifact.blob_sha256),
        membership_sha256=run_membership_digest(run_members),
        member_count=len(run_members),
    )
    return run, tuple(run_members)


class _ReadRunRow(BaseModel):
    model_config = ConfigDict(hide_input_in_errors=True)

    artifact_id: SysId
    artifact_epoch: USearchArtifactEpoch
    index_blob: bytes | None
    blob_bytes: int
    run_manifest: dict[str, object]
    active_run_count: int = 1

    @field_validator("run_manifest", mode="before")
    @classmethod
    def _decode_manifest(cls: type[Self], value: object) -> object:
        return json.loads(value) if isinstance(value, str) else value


class _RunWithMembers(USearchRun):
    members: tuple[USearchRunMember, ...]


def prepare_usearch_run_search(
    rows: Sequence[Mapping[str, object]], *, query: tuple[float, ...], metric: USearchMetric,
    eligible_keys: tuple[USearchNativeKey, ...], limits: USearchRequestLimits,
    projection_identity: USearchProjectionIdentity | None = None,
) -> USearchRunSearchRequest:
    """Validate selected payloads and membership before executing any native search."""
    from l5200_vector_index.usearch_runtime import USearchExactSearchRequest, USearchRunSearchRequest

    try:
        selected = tuple(_ReadRunRow.model_validate(row) for row in rows)
        active_run_counts = {row.active_run_count for row in selected}
        if len(active_run_counts) != 1:
            raise NativeSearchIntegrityError("Run selection has inconsistent amplification metadata")
        validate_usearch_request_limits(
            limits, eligibility_rows=len(eligible_keys),
            artifact_bytes=sum(row.blob_bytes for row in selected), active_runs=active_run_counts.pop(),
        )
        if not selected or len({(row.artifact_id, row.artifact_epoch) for row in selected}) != 1:
            raise NativeSearchIntegrityError("Run selection must belong to one artifact epoch")
        allowed = set(eligible_keys)
        seen_keys: set[int] = set()
        seen_runs: set[str] = set()
        identities: set[str] = set()
        expected_projection = (
            usearch_projection_identity(None, len(query))
            if projection_identity is None else projection_identity
        )
        requests: list[USearchExactSearchRequest] = []
        for row in selected:
            if row.index_blob is None or len(row.index_blob) != row.blob_bytes:
                raise NativeSearchIntegrityError("Run payload is missing or truncated")
            manifest = dict(row.run_manifest)
            head = manifest.pop("__artifact", None)
            if head is not None:
                if not isinstance(head, dict) or head != {
                    "dimensions": len(query), "metric": metric,
                    "digest": sha256(b"").hexdigest(), "bytes": 0,
                }:
                    raise NativeSearchIntegrityError("Immutable run artifact header is inconsistent")
            run = _RunWithMembers.model_validate({**manifest, "payload": row.index_blob})
            if run.artifact_id != row.artifact_id or run.published_epoch > row.artifact_epoch:
                raise NativeSearchIntegrityError("Run does not belong to the selected publication")
            if run.retired_epoch is not None or str(run.sys_id) in seen_runs:
                raise NativeSearchIntegrityError("Run selection includes a retired or duplicate run")
            seen_runs.add(str(run.sys_id))
            if (
                run.dimensions != len(query) or run.metric != metric
                or run.projection_identity != expected_projection
            ):
                raise NativeSearchIntegrityError("Run representation does not match the query")
            if run.member_count != len(run.members) or run_membership_digest(run.members) != run.membership_sha256:
                raise NativeSearchIntegrityError("Run membership count or digest is invalid")
            keys: list[USearchNativeKey] = []
            for member in run.members:
                if member.run_id != run.sys_id or member.native_key in seen_keys:
                    raise NativeSearchIntegrityError("Run membership has a foreign or duplicate key")
                if str(member.embedding_vector_id) in identities:
                    raise NativeSearchIntegrityError("Run membership repeats a canonical vector")
                identities.add(str(member.embedding_vector_id))
                seen_keys.add(member.native_key)
                if member.native_key in allowed:
                    keys.append(USearchNativeKey(member.native_key))
            if keys:
                requests.append(USearchExactSearchRequest(
                    blob=run.payload, dimensions=run.dimensions, metric=metric, query=query,
                    eligible_keys=tuple(sorted(keys)), artifact_id=SysId(str(run.sys_id)),
                    artifact_epoch=USearchArtifactEpoch(run.published_epoch), limits=limits,
                ))
        if not allowed.issubset(seen_keys):
            raise NativeSearchIntegrityError("Run selection does not contain every eligible key")
        return USearchRunSearchRequest(
            requests=tuple(requests), artifact_id=selected[0].artifact_id,
            artifact_epoch=selected[0].artifact_epoch, metric=metric,
            eligible_keys=eligible_keys, limits=limits,
        )
    except ValidationError as error:
        raise NativeSearchIntegrityError("Immutable run metadata is invalid", original_exception=error) from error

