class _ArtifactPublicationPreparation(BaseModel):
    """Validated rows produced before publication writes execute."""

    model_config = ConfigDict(frozen=True)

    metadata: MatchingArtifactMetadataRow
    coverage: tuple[MatchingArtifactCoverageRow, ...]
    persisted_state: MatchArtifactExecutionState


def _resolved_row_sequence[T](resolved: ResolvedRefs, ref_id: ServerPlanRefId, row_type: type[T]) -> tuple[T, ...]:
    raw_rows = resolved.get(str(ref_id)) or ()
    if not isinstance(raw_rows, Sequence):
        msg = f"Expected row sequence from {ref_id}"
        raise TypeError(msg)
    rows: list[T] = []
    for row in raw_rows:
        if not isinstance(row, row_type):
            msg = f"Expected {row_type.__name__} from {ref_id}, got {type(row).__name__}"
            raise TypeError(msg)
        rows.append(row)
    return tuple(rows)


class _PrepareArtifactPublicationStep(NonPublishingStep[_ArtifactPublicationPreparation]):
    """Validate publication state and prepare rows from transaction-visible inputs."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        spec: MatchSpec[Any, Any],
        state: MatchArtifactExecutionState,
        producer_state: Literal["ready", "failed"],
        pair_scope: str,
        expected_source_watermark: MatchArtifactWatermark | None,
        left_rows_ref: ServerPlanRefId | None,
        right_rows_ref: ServerPlanRefId | None,
        metadata_ref: ServerPlanRefId,
    ) -> None:
        super().__init__(ref_id)
        self._spec = spec
        self._state = state
        self._producer_state = producer_state
        self._pair_scope = pair_scope
        self._expected_source_watermark = expected_source_watermark
        self._left_rows_ref = left_rows_ref
        self._right_rows_ref = right_rows_ref
        self._metadata_ref = metadata_ref

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def runtime_result_is_terminal_scalar(self) -> bool:
        return True

    def dependencies(self) -> frozenset[str]:
        return frozenset(str(ref) for ref in (self._left_rows_ref, self._right_rows_ref, self._metadata_ref) if ref is not None)

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[_ArtifactPublicationPreparation]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> _ArtifactPublicationPreparation:
        spec = self._spec
        state = self._state
        identity = state.identity
        scoped_spec = type(spec).model_validate(
            {
                **{field_name: getattr(spec, field_name) for field_name in type(spec).model_fields},
                "pair_scope": self._pair_scope,
            },
        )
        versioned_sources = issubclass(spec.left.row_type, VersionedObjectRow) or issubclass(
            spec.right.row_type,
            VersionedObjectRow,
        )
        left_rows = () if self._left_rows_ref is None else _resolved_row_sequence(resolved, self._left_rows_ref, spec.left.row_type)
        right_rows = () if self._right_rows_ref is None else _resolved_row_sequence(resolved, self._right_rows_ref, spec.right.row_type)
        all_metadata = _resolved_row_sequence(resolved, self._metadata_ref, MatchingArtifactMetadataRow)
        current_source_row_count = 0 if versioned_sources else len(left_rows) + len(right_rows)
        source_tracking_mode = "snapshot_watermark" if versioned_sources else "row_count"
        prior_metadata = tuple(
            row
            for row in all_metadata
            if row.spec_fingerprint == str(scoped_spec.semantic_fingerprint)
            and row.pair_scope == self._pair_scope
            and row.branch_scope == str(identity.branch_scope)
        )
        authoritative_source_watermark = state.source_watermark
        initial_watermark_bound = MatchArtifactWatermark(max(64, current_source_row_count))
        if not prior_metadata and not versioned_sources and state.source_watermark > initial_watermark_bound:
            raise MatchFreshnessError(
                MatchErrorContext(
                    invariant=MatchInvariant.ARTIFACT_SOURCE_DELTA,
                    expected=MatchExpectedValue(f"source_watermark_at_most_{initial_watermark_bound}"),
                    observed=MatchObservedValue(f"source_watermark_{state.source_watermark}"),
                    safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                    spec_ref_id=spec.spec_ref_id,
                ),
            )
        if prior_metadata:
            prior = prior_metadata[0]
            if state.identity.generation <= prior.generation:
                raise MatchArtifactError(
                    MatchErrorContext(
                        invariant=MatchInvariant.ARTIFACT_GENERATION_REUSE,
                        expected=MatchExpectedValue(f"generation_after_{prior.generation}"),
                        observed=MatchObservedValue(f"generation_{state.identity.generation}"),
                        safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                        spec_ref_id=spec.spec_ref_id,
                    ),
                )
            source_delta = max(0, current_source_row_count - prior.source_row_count)
            authoritative_source_watermark = MatchArtifactWatermark(prior.source_watermark + source_delta)
        if self._expected_source_watermark is not None and authoritative_source_watermark != self._expected_source_watermark:
            raise MatchFreshnessError(
                MatchErrorContext(
                    invariant=MatchInvariant.ARTIFACT_SOURCE_DELTA,
                    expected=MatchExpectedValue(f"source_watermark_{self._expected_source_watermark}"),
                    observed=MatchObservedValue(f"source_watermark_{authoritative_source_watermark}"),
                    safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                    spec_ref_id=spec.spec_ref_id,
                ),
            )
        if (
            state.maintenance_mode is MatchArtifactMaintenanceMode.SYNCHRONOUS
            and state.artifact_watermark != authoritative_source_watermark
        ):
            raise MatchFreshnessError(
                MatchErrorContext(
                    invariant=MatchInvariant.ARTIFACT_STALE,
                    expected=MatchExpectedValue(f"artifact_watermark_{authoritative_source_watermark}"),
                    observed=MatchObservedValue(f"artifact_watermark_{state.artifact_watermark}"),
                    safe_action=MatchSafeAction.REBUILD_ARTIFACT,
                    spec_ref_id=spec.spec_ref_id,
                ),
            )
        persisted_state = MatchArtifactExecutionState.model_validate(
            {
                **state.model_dump(),
                "source_watermark": authoritative_source_watermark,
                "indexed_left_identities": (),
                "indexed_right_identities": (),
            },
        )
        metadata = MatchingArtifactMetadataRow(
            spec_ref_id=str(spec.spec_ref_id),
            spec_fingerprint=str(scoped_spec.semantic_fingerprint),
            artifact_fingerprint=str(identity.artifact_fingerprint),
            pair_scope=self._pair_scope,
            tenant_scope=str(identity.tenant_scope),
            workspace_scope=str(identity.workspace_scope),
            branch_scope=str(identity.branch_scope),
            revision_scope=str(identity.revision_scope),
            producer_ref_id=str(identity.producer_ref_id),
            representation_ref_id=str(identity.representation_ref_id),
            kernel_ref_id=str(identity.kernel_ref_id),
            physical_method=str(identity.physical_method),
            generation=int(identity.generation),
            source_watermark=int(authoritative_source_watermark),
            artifact_watermark=int(state.artifact_watermark),
            source_row_count=current_source_row_count,
            source_tracking_mode=source_tracking_mode,
            permission_scope=str(state.permission_scope),
            state_payload=persisted_state.model_dump_json(),
            producer_state=self._producer_state,
        )
        scope_digest = hashlib.sha256(
            f"{scoped_spec.semantic_fingerprint}\x1f{self._pair_scope}\x1f{identity.branch_scope}".encode(),
        ).hexdigest()
        common = {
            "spec_ref_id": str(spec.spec_ref_id),
            "spec_fingerprint": str(scoped_spec.semantic_fingerprint),
            "pair_scope": self._pair_scope,
        }
        coverage = tuple(
            MatchingArtifactCoverageRow(
                **common,
                branch_scope=str(identity.branch_scope),
                scope_digest=scope_digest,
                endpoint=endpoint,
                identity=str(covered_identity),
                identity_digest=hashlib.sha256(str(covered_identity).encode()).hexdigest(),
            )
            for endpoint, identities in (
                ("left", state.indexed_left_identities),
                ("right", state.indexed_right_identities),
            )
            for covered_identity in identities
        )
        return _ArtifactPublicationPreparation(
            metadata=metadata,
            coverage=coverage,
            persisted_state=persisted_state,
        )


def _artifact_model_contract(
    step: ServerPlanStep[object],
    model_cls: type[MatchingArtifactMetadataRow] | type[MatchingArtifactCoverageRow],
) -> CtePublicationContract:
    columns = tuple(plan.db_column for plan in writable_field_plans(model_cls))
    column_type_hints = model_sql_column_type_hints(model_cls, columns)
    if column_type_hints is None:
        msg = f"Could not resolve SQL column type hints for {model_cls.__name__}"
        raise TypeError(msg)
    return CtePublicationContract(
        publication_source_kind=PublicationSourceKind.DECLARED_LITERAL_RELATION,
        columns=columns,
        column_type_hints=column_type_hints,
        relation_contract=CteRelationContract.model(model_cls),
        relation_role=step.cte_relation_role(),
    )


class _ProjectArtifactPublicationStep[T](ServerPlanStep[T]):
    """Project one closed publication payload for a downstream write."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        preparation_ref: ServerPlanRefId,
        kind: Literal["metadata", "coverage"],
        after_refs: frozenset[ServerPlanRefId] = frozenset(),
    ) -> None:
        super().__init__(ref_id)
        self._preparation_ref = preparation_ref
        self._kind = kind
        self._after_refs = after_refs

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE if self._kind == "metadata" else Cardinality.MANY

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def executor_visible_publication_uses_python_result(self) -> bool:
        return True

    def publishes_decoded_value_as_executor_value(self) -> bool:
        return True

    def is_executor_owned_runtime_step(self) -> bool:
        return True

    def requires_materialized_inputs(self) -> bool:
        return True

    def requires_prior_step_boundary(self) -> bool:
        return True

    def publishes_executor_visible_binding(self) -> bool:
        return True

    def always_publishes_executor_visible_binding(self) -> bool:
        return False

    def runtime_result_is_terminal_scalar(self) -> bool:
        return self._kind == "metadata"

    def cte_publication_contract(self) -> CtePublicationContract:
        model_cls = MatchingArtifactMetadataRow if self._kind == "metadata" else MatchingArtifactCoverageRow
        return _artifact_model_contract(self, model_cls)

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._preparation_ref), *(str(ref) for ref in self._after_refs)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[T]:
        del ctx
        contract = self.cte_publication_contract()
        output_shape = CompiledOutputShape(tuple(synthetic_output_field(column) for column in contract.columns))
        return CompiledStep(
            output_shape=output_shape,
            result_relation=DeclaredResultRelation.from_output_shape(output_shape),
            column_type_hints=contract.column_type_hints,
        )

    def execute_runtime(self, resolved: ResolvedRefs) -> T:
        prepared = resolved.get(str(self._preparation_ref))
        if not isinstance(prepared, _ArtifactPublicationPreparation):
            msg = "Artifact publication preparation did not publish its typed payload"
            raise TypeError(msg)
        value: T = getattr(prepared, self._kind)
        return value


class _CompleteArtifactPublicationStep(NonPublishingStep[None]):
    """Register maintenance only after all publication writes succeed."""

    def __init__(
        self,
        ref_id: ServerPlanRefId,
        *,
        preparation_ref: ServerPlanRefId,
        write_refs: frozenset[ServerPlanRefId],
        spec: MatchSpec[Any, Any],
        pair_scope: str,
        owner_connection_id: ConnectionId,
    ) -> None:
        super().__init__(ref_id)
        self._preparation_ref = preparation_ref
        self._write_refs = write_refs
        self._spec = spec
        self._pair_scope = pair_scope
        self._owner_connection_id = owner_connection_id

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return False

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def runtime_result_is_terminal_scalar(self) -> bool:
        return True

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._preparation_ref), *(str(ref) for ref in self._write_refs)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[None]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> None:
        prepared = resolved.get(str(self._preparation_ref))
        if not isinstance(prepared, _ArtifactPublicationPreparation):
            msg = "Artifact publication preparation did not publish its typed payload"
            raise TypeError(msg)
        register_matching_source_maintenance(
            self._spec,
            prepared.persisted_state,
            self._pair_scope,
            self._owner_connection_id,
        )


@pure_lazy
def _owner_connection_id(txn: LazyWriteTransaction) -> ConnectionId:
    return txn._planning_connection_id


@pure_lazy
def _single_plan_ref[T](value: LazyResult[T]) -> ServerPlanRefId:
    refs = collect_plan_ref_dependencies(value)
    if len(refs) != 1:
        msg = "Matching artifact operation requires one plan-owned dependency"
        raise RuntimeError(msg)
    return next(iter(refs))


@pure_lazy
def publish_matching_artifact_lazy(
    txn: LazyWriteTransaction,
    spec: MatchSpec[Any, Any],
    state: MatchArtifactExecutionState,
    *,
    producer_state: Literal["ready", "failed"] = "ready",
    pair_scope: str | None = None,
    expected_source_watermark: MatchArtifactWatermark | None = None,
) -> LazyResult[None]:
    """Plan validated artifact publication in the caller-owned ServerPlan."""
    resolved_pair_scope = pair_scope if pair_scope is not None else str(spec.pair_scope)
    versioned_sources = issubclass(spec.left.row_type, VersionedObjectRow) or issubclass(
        spec.right.row_type,
        VersionedObjectRow,
    )
    left_rows = None if versioned_sources else txn.query_lazy(spec.left.row_type).execute_lazy()
    right_rows = None if versioned_sources else txn.query_lazy(spec.right.row_type).execute_lazy()
    metadata_rows = txn.query_lazy(MatchingArtifactMetadataRow).execute_lazy()
    plan = txn._get_transaction_plan_lazy()
    preparation_step = _PrepareArtifactPublicationStep(
        ServerPlanRefId(plan._next_ref()),
        spec=spec,
        state=state,
        producer_state=producer_state,
        pair_scope=resolved_pair_scope,
        expected_source_watermark=expected_source_watermark,
        left_rows_ref=None if left_rows is None else _single_plan_ref(left_rows),
        right_rows_ref=None if right_rows is None else _single_plan_ref(right_rows),
        metadata_ref=_single_plan_ref(metadata_rows),
    )
    preparation = ReadQueryBuilder.publish_step_lazy(plan, MatchingArtifactMetadataRow, preparation_step)
    preparation_ref = _single_plan_ref(preparation)
    scoped_spec = type(spec).model_validate(
        {
            **{field_name: getattr(spec, field_name) for field_name in type(spec).model_fields},
            "pair_scope": resolved_pair_scope,
        },
    )
    coverage_scope = (
        (field(MatchingArtifactCoverageRow.spec_fingerprint) == str(scoped_spec.semantic_fingerprint))
        & (field(MatchingArtifactCoverageRow.pair_scope) == resolved_pair_scope)
        & (field(MatchingArtifactCoverageRow.branch_scope) == str(state.identity.branch_scope))
    )
    metadata_scope = (
        (field(MatchingArtifactMetadataRow.spec_fingerprint) == str(scoped_spec.semantic_fingerprint))
        & (field(MatchingArtifactMetadataRow.pair_scope) == resolved_pair_scope)
        & (field(MatchingArtifactMetadataRow.branch_scope) == str(state.identity.branch_scope))
    )
    coverage_delete = (
        txn.query_lazy(MatchingArtifactCoverageRow)
        .filter(coverage_scope)
        .delete_after_lazy(
            after=(preparation,),
        )
    )
    metadata_delete = (
        txn.query_lazy(MatchingArtifactMetadataRow)
        .filter(metadata_scope)
        .delete_after_lazy(
            after=(preparation,),
        )
    )
    metadata_projection = ReadQueryBuilder.publish_step_lazy(
        plan,
        MatchingArtifactMetadataRow,
        _ProjectArtifactPublicationStep[MatchingArtifactMetadataRow](
            ServerPlanRefId(plan._next_ref()),
            preparation_ref=preparation_ref,
            kind="metadata",
            after_refs=frozenset({_single_plan_ref(metadata_delete)}),
        ),
    )
    metadata_insert = txn.insert_lazy(MatchingArtifactMetadataRow, metadata_projection)
    coverage_projection = ReadQueryBuilder.publish_step_lazy(
        plan,
        MatchingArtifactCoverageRow,
        _ProjectArtifactPublicationStep[Sequence[MatchingArtifactCoverageRow]](
            ServerPlanRefId(plan._next_ref()),
            preparation_ref=preparation_ref,
            kind="coverage",
            after_refs=frozenset({_single_plan_ref(coverage_delete), _single_plan_ref(metadata_insert)}),
        ),
    )
    coverage_insert = txn.insert_many_lazy(MatchingArtifactCoverageRow, coverage_projection)
    completion = _CompleteArtifactPublicationStep(
        ServerPlanRefId(plan._next_ref()),
        preparation_ref=preparation_ref,
        write_refs=frozenset(
            {
                _single_plan_ref(metadata_insert),
                _single_plan_ref(coverage_insert),
            },
        ),
        spec=scoped_spec,
        pair_scope=resolved_pair_scope,
        owner_connection_id=_owner_connection_id(txn),
    )
    return ReadQueryBuilder.publish_step_lazy(plan, MatchingArtifactMetadataRow, completion)


@legacy_module_sync(lazy_name="publish_matching_artifact_lazy")
