@pure_lazy
def publish_matching_representation_lazy(
    txn: LazyWriteTransaction,
    artifact: MatchMaterializedProducerRepresentation,
) -> LazyResult[MatchMaterializedProducerRepresentation]:
    """Publish one complete generation atomically in the caller plan."""
    artifact_id = str(artifact.artifact_id)
    producer_ref_id = str(artifact.producer_ref_id)
    coordinate_delete = txn.query_lazy(MatchingProducerCoordinateRow).filter(
        (field(MatchingProducerCoordinateRow.producer_ref_id) == producer_ref_id)
        & (field(MatchingProducerCoordinateRow.side_role) == artifact.side_role),
    ).delete_lazy()
    artifact_delete = txn.query_lazy(MatchingProducerArtifactRow).filter(
        (field(MatchingProducerArtifactRow.producer_ref_id) == producer_ref_id)
        & (field(MatchingProducerArtifactRow.side_role) == artifact.side_role),
    ).delete_lazy()
    delete_refs = tuple(collect_plan_ref_dependencies(coordinate_delete, artifact_delete))
    txn.insert_lazy(
        MatchingProducerArtifactRow,
        LazyResult.of(
            MatchingProducerArtifactRow(
                artifact_id=artifact_id,
                producer_family=artifact.producer_family.value,
                producer_ref_id=str(artifact.producer_ref_id),
                source_snapshot=str(artifact.source_snapshot),
                fit_scope=str(artifact.fit_scope),
                source_watermark=int(artifact.source_watermark),
                dimensions=int(artifact.dimensions),
                side_role=artifact.side_role,
                graph_edge_visits=int(artifact.work_metrics.graph_edge_visit_count),
                matrix_cell_evaluations=int(artifact.work_metrics.matrix_cell_evaluation_count),
                provider_calls=int(artifact.work_metrics.provider_call_count),
                complete=artifact.complete is MatchArtifactCompleteness.COMPLETE,
            ),
        ),
        after_refs=delete_refs,
    )
    for coordinate in artifact.coordinates:
        for coordinate_index, value in enumerate(coordinate.values):
            txn.insert_lazy(
                MatchingProducerCoordinateRow,
                LazyResult.of(
                    MatchingProducerCoordinateRow(
                        artifact_id=artifact_id,
                        producer_ref_id=producer_ref_id,
                        side_role=artifact.side_role,
                        source_id=coordinate.source_id,
                        source_snapshot=str(artifact.source_snapshot),
                        fit_scope=str(artifact.fit_scope),
                        source_watermark=int(artifact.source_watermark),
                        coordinate_index=coordinate_index,
                        value=value,
                    ),
                ),
                after_refs=delete_refs,
            )
    return LazyResult.of(artifact)


