"""Caller-transaction persistence for immutable quantized projection generations."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass

from impl.common.l5250_matching.quantized_numerics import (
    binary_jaccard_score,
    build_qjl_projection,
    build_turboquant_mse_projection,
    build_turboquant_projection,
    decode_turboquant_mse,
    encode_qjl,
    encode_turboquant,
    encode_turboquant_mse,
    prepare_qjl_query,
    prepare_turboquant_query,
    quantized_resource_metrics,
    score_qjl,
    score_turboquant,
    score_turboquant_components,
)
from l1000_schema.typed_field import field
from l1400_types import ServerPlanRefId
from l1470_matching_contracts.projection_models import (
    H14BinaryCodePayload,
    H14ProjectionArtifact,
    H14ProjectionFitResult,
    MatchProjectionArtifactId,
    PackedH14Code,
    QjlCodePayload,
    QjlProjectionArtifact,
    QjlProjectionState,
    QuantizedResidualNorm,
    QuantizedVectorNorm,
    TurboQuantInnerProductArtifact,
    TurboQuantInnerProductCodePayload,
    TurboQuantMseArtifact,
    TurboQuantMseCodePayload,
    TurboQuantMseProjectionState,
    TurboQuantProjectionState,
)
from l1470_matching_contracts.types import MatchRepresentationRefId
from l2050_transaction.legacy_wrappers import legacy_module_async, legacy_module_sync
from l2050_transaction.transaction import (
    AsyncReadTransaction,
    AsyncWriteTransaction,
    LazyReadTransaction,
    LazyWriteTransaction,
    SyncReadTransaction,
    SyncWriteTransaction,
)
from l2055_lazy_result.commit_refs import collect_plan_ref_dependencies
from l2055_lazy_result.lazy_result import LazyResult
from l2055_lazy_result.purity import pure_lazy
from l2070_batching.cardinality import Cardinality
from l2070_batching.compilation import CompilationContext, CompiledStep, ResolvedRefs
from l2070_batching.step import NonPublishingStep, StepExecutionRole
from l5200_vector_index.quantized_projection_models import (
    _hydrate_quantized_storage_row,
    QuantizedCodeRow,
    QuantizedProjectionArtifactRow,
    QuantizedProjectionTensorRow,
    QuantizedSourceIdentity,
    QuantizedSourceWatermark,
)

QuantizedProjectionState = H14ProjectionFitResult | QjlProjectionState | TurboQuantMseProjectionState | TurboQuantProjectionState
QuantizedCodePayload = H14BinaryCodePayload | QjlCodePayload | TurboQuantMseCodePayload | TurboQuantInnerProductCodePayload


@pure_lazy
def _single_ref[T](result: LazyResult[T], operation: str) -> ServerPlanRefId:
    dependencies = tuple(collect_plan_ref_dependencies(result))
    if len(dependencies) != 1:
        raise TypeError(f"{operation} requires exactly one plan-backed source")
    return ServerPlanRefId(dependencies[0])


def _projection_state(
    artifact_rows: object,
    tensor_rows: object,
) -> QuantizedProjectionState | None:
    if not isinstance(artifact_rows, Sequence) or isinstance(artifact_rows, str | bytes):
        raise TypeError("projection artifact source must be a row sequence")
    if not isinstance(tensor_rows, Sequence) or isinstance(tensor_rows, str | bytes):
        raise TypeError("projection tensor source must be a row sequence")
    artifacts = tuple(artifact_rows)
    tensors = tuple(tensor_rows)
    if not artifacts:
        return None
    if len(artifacts) != 1:
        raise ValueError("projection artifact identity is not unique")
    row = _hydrate_quantized_storage_row(QuantizedProjectionArtifactRow, artifacts[0])
    typed_tensors = tuple(
        _hydrate_quantized_storage_row(QuantizedProjectionTensorRow, tensor)
        for tensor in tensors
    )
    by_role = {tensor.role: tensor for tensor in typed_tensors}
    if row.family == "h14":
        h14_artifact = H14ProjectionArtifact.model_validate_json(row.contract_payload)
        mean = by_role.get("mean")
        rotation = by_role.get("rotation")
        threshold = by_role.get("threshold")
        residual = by_role.get("residual")
        if mean is None or rotation is None or threshold is None or residual is None:
            raise ValueError("H14 projection tensors are incomplete")
        return H14ProjectionFitResult(
            artifact=h14_artifact,
            mean_payload=mean.payload,
            rotation_payload=rotation.payload,
            threshold_payload=threshold.payload,
            residual_payload=residual.payload,
        )
    if row.family == "qjl":
        qjl_artifact = QjlProjectionArtifact.model_validate_json(row.contract_payload)
        projection = by_role.get("projection")
        if projection is None:
            raise ValueError("QJL projection tensor is missing")
        return QjlProjectionState(artifact=qjl_artifact, projection_payload=projection.payload)
    if row.family == "turboquant_mse":
        mse_artifact = TurboQuantMseArtifact.model_validate_json(row.contract_payload)
        rotation = by_role.get("rotation")
        if rotation is None:
            raise ValueError("TurboQuant MSE rotation tensor is missing")
        return TurboQuantMseProjectionState(
            artifact=mse_artifact,
            rotation_payload=rotation.payload,
        )
    turbo_artifact = TurboQuantInnerProductArtifact.model_validate_json(row.contract_payload)
    rotation = by_role.get("rotation")
    residual = by_role.get("residual")
    if rotation is None or residual is None:
        raise ValueError("TurboQuant projection tensors are incomplete")
    return TurboQuantProjectionState(
        artifact=turbo_artifact,
        rotation_payload=rotation.payload,
        residual_payload=residual.payload,
    )


def _code_payload(rows: object) -> QuantizedCodePayload | None:
    if not isinstance(rows, Sequence) or isinstance(rows, str | bytes):
        raise TypeError("quantized code source must be a row sequence")
    if not rows:
        return None
    if len(rows) != 1:
        raise ValueError("quantized code identity is not unique")
    row = _hydrate_quantized_storage_row(QuantizedCodeRow, rows[0])
    if row.family == "h14":
        return H14BinaryCodePayload(
            projection_artifact_id=row.artifact_id,
            representation_id=row.representation_ref_id,
            packed_bits=PackedH14Code(row.packed_primary),
        )
    if row.family == "qjl":
        if row.vector_norm is None:
            raise ValueError("QJL packed code has no source norm")
        return QjlCodePayload(
            projection_artifact_id=row.artifact_id,
            packed_signs=row.packed_primary,
            vector_norm=QuantizedVectorNorm(row.vector_norm),
        )
    if row.family == "turboquant_mse":
        if row.vector_norm is None:
            raise ValueError("TurboQuant MSE packed code has no source norm")
        return TurboQuantMseCodePayload(
            projection_artifact_id=row.artifact_id,
            packed_indices=row.packed_primary,
            vector_norm=QuantizedVectorNorm(row.vector_norm),
        )
    if row.packed_residual is None or row.residual_norm is None or row.vector_norm is None:
        raise ValueError("TurboQuant packed code is incomplete")
    return TurboQuantInnerProductCodePayload(
        projection_artifact_id=row.artifact_id,
        packed_mse_indices=row.packed_primary,
        packed_residual_signs=row.packed_residual,
        vector_norm=QuantizedVectorNorm(row.vector_norm),
        residual_norm=QuantizedResidualNorm(row.residual_norm),
    )


@dataclass(frozen=True, slots=True)
class _ProjectionStateConfig:
    artifact_ref: ServerPlanRefId
    tensor_ref: ServerPlanRefId
    expected: QuantizedProjectionState | None


class _ProjectionStateStep(NonPublishingStep[QuantizedProjectionState | None]):
    def __init__(self, ref_id: ServerPlanRefId, config: _ProjectionStateConfig) -> None:
        super().__init__(ref_id)
        self._config = config

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self) -> frozenset[str]:
        return frozenset({"matching", "quantized_projection", "verification"})

    def counts_as_sql_group_for_accounting(self) -> bool | None:
        return False

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._config.artifact_ref), str(self._config.tensor_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[QuantizedProjectionState | None]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> QuantizedProjectionState | None:
        state = _projection_state(
            resolved[str(self._config.artifact_ref)],
            resolved[str(self._config.tensor_ref)],
        )
        if self._config.expected is not None and state != self._config.expected:
            raise ValueError("projection artifact identity collides with different immutable content")
        return state


@dataclass(frozen=True, slots=True)
class _CodePayloadConfig:
    source_ref: ServerPlanRefId
    expected: QuantizedCodePayload | None


class _CodePayloadStep(NonPublishingStep[QuantizedCodePayload | None]):
    def __init__(self, ref_id: ServerPlanRefId, config: _CodePayloadConfig) -> None:
        super().__init__(ref_id)
        self._config = config

    @property
    def level(self) -> int:
        return 0

    def result_cardinality(self) -> Cardinality:
        return Cardinality.ONE

    def is_read_only(self) -> bool:
        return True

    def execution_role(self) -> StepExecutionRole:
        return StepExecutionRole.APPLY

    def step_tags(self) -> frozenset[str]:
        return frozenset({"matching", "quantized_code", "verification"})

    def counts_as_sql_group_for_accounting(self) -> bool | None:
        return False

    def dependencies(self) -> frozenset[str]:
        return frozenset({str(self._config.source_ref)})

    def tables_read(self) -> frozenset[str]:
        return frozenset()

    def tables_written(self) -> frozenset[str]:
        return frozenset()

    def compile(self, ctx: CompilationContext) -> CompiledStep[QuantizedCodePayload | None]:
        del ctx
        return CompiledStep()

    def execute_runtime(self, resolved: ResolvedRefs) -> QuantizedCodePayload | None:
        code = _code_payload(resolved[str(self._config.source_ref)])
        if self._config.expected is not None and code != self._config.expected:
            raise ValueError("quantized code identity collides with different immutable content")
        return code


@pure_lazy
def _publish_projection_rows(
    state: QuantizedProjectionState,
) -> tuple[QuantizedProjectionArtifactRow, tuple[QuantizedProjectionTensorRow, ...]]:
    tensors: tuple[tuple[str, str, bytes], ...]
    algorithm_version: str
    if isinstance(state, H14ProjectionFitResult):
        h14_artifact = state.artifact
        family = "h14"
        tensors = (
            ("mean", str(h14_artifact.mean_tensor.digest), state.mean_payload),
            ("rotation", str(h14_artifact.rotation_tensor.digest), state.rotation_payload),
            ("threshold", str(h14_artifact.threshold_tensor.digest), state.threshold_payload),
            ("residual", str(h14_artifact.residual_tensor.digest), state.residual_payload),
        )
        artifact_id = h14_artifact.artifact_id
        algorithm_version = h14_artifact.algorithm_version
        contract_payload = h14_artifact.model_dump_json()
    elif isinstance(state, QjlProjectionState):
        qjl_artifact = state.artifact
        family = "qjl"
        tensors = (("projection", str(qjl_artifact.projection_matrix.digest), state.projection_payload),)
        artifact_id = qjl_artifact.artifact_id
        algorithm_version = qjl_artifact.algorithm_version
        contract_payload = qjl_artifact.model_dump_json()
    elif isinstance(state, TurboQuantMseProjectionState):
        mse_artifact = state.artifact
        family = "turboquant_mse"
        tensors = (("rotation", str(mse_artifact.rotation_matrix.digest), state.rotation_payload),)
        artifact_id = mse_artifact.artifact_id
        algorithm_version = mse_artifact.algorithm_version
        contract_payload = mse_artifact.model_dump_json()
    else:
        turbo_artifact = state.artifact
        family = "turboquant_inner_product"
        tensors = (
            ("rotation", str(turbo_artifact.rotation_matrix.digest), state.rotation_payload),
            ("residual", str(turbo_artifact.residual_matrix.digest), state.residual_payload),
        )
        artifact_id = turbo_artifact.artifact_id
        algorithm_version = turbo_artifact.algorithm_version
        contract_payload = turbo_artifact.model_dump_json()
    artifact_row = QuantizedProjectionArtifactRow(
        artifact_id=artifact_id,
        family=family,
        algorithm_version=algorithm_version,
        contract_payload=contract_payload,
    )
    tensor_rows = tuple(
        QuantizedProjectionTensorRow.model_validate(
            {
                "artifact_id": artifact_id,
                "role": role,
                "digest": digest,
                "payload": payload,
            },
        )
        for role, digest, payload in tensors
    )
    return artifact_row, tensor_rows


@pure_lazy
def publish_quantized_projection_lazy(
    txn: LazyWriteTransaction,
    state: QuantizedProjectionState,
) -> LazyResult[QuantizedProjectionState | None]:
    """Publish and verify one immutable projection generation in the caller plan."""
    artifact_row, tensor_rows = _publish_projection_rows(state)
    artifacts = txn.upsert_many_lazy(
        QuantizedProjectionArtifactRow,
        (artifact_row,),
        conflict_columns=[field(QuantizedProjectionArtifactRow.artifact_id)],
        on_conflict={field(QuantizedProjectionArtifactRow.artifact_id): field(QuantizedProjectionArtifactRow.artifact_id)},
    )
    tensors = txn.upsert_many_lazy(
        QuantizedProjectionTensorRow,
        tensor_rows,
        conflict_columns=[
            field(QuantizedProjectionTensorRow.artifact_id),
            field(QuantizedProjectionTensorRow.role),
        ],
        on_conflict={field(QuantizedProjectionTensorRow.artifact_id): field(QuantizedProjectionTensorRow.artifact_id)},
    )
    plan = txn._get_transaction_plan_lazy()
    return txn._add_intent(
        _ProjectionStateStep(
            ServerPlanRefId(plan._next_ref()),
            _ProjectionStateConfig(
                artifact_ref=_single_ref(artifacts, "projection artifact publication"),
                tensor_ref=_single_ref(tensors, "projection tensor publication"),
                expected=state,
            ),
        ),
    )


@legacy_module_sync(lazy_name="publish_quantized_projection_lazy")
def publish_quantized_projection(
    txn: SyncWriteTransaction,
    state: QuantizedProjectionState,
