    """Publish one projection generation inside the caller transaction."""
    raise NotImplementedError("legacy delegate stub should be replaced at runtime")


@legacy_module_async(lazy_name="publish_quantized_projection_lazy")
async def publish_quantized_projection_async(
    txn: AsyncWriteTransaction,
    state: QuantizedProjectionState,
