@pure_lazy
def load_quantized_projection_lazy(
    txn: LazyReadTransaction,
    artifact_id: MatchProjectionArtifactId,
) -> LazyResult[QuantizedProjectionState | None]:
    """Load and verify one immutable projection generation through ServerPlan."""
    artifacts = (
        txn.query_lazy(QuantizedProjectionArtifactRow)
        .filter(field(QuantizedProjectionArtifactRow.artifact_id) == artifact_id)
        .execute_lazy()
    )
    tensors = (
