@pure_lazy
def _quantized_code_row(
    *,
    source_identity: QuantizedSourceIdentity,
    representation_ref_id: MatchRepresentationRefId,
    source_watermark: QuantizedSourceWatermark,
    code: QuantizedCodePayload,
) -> QuantizedCodeRow:
    if isinstance(code, H14BinaryCodePayload):
        if code.representation_id != representation_ref_id:
            raise ValueError("H14 code representation does not match its publication identity")
        if not code.packed_bits:
            raise ValueError("H14 packed code payload must not be empty")
        family = "h14"
        primary = bytes(code.packed_bits)
        residual = None
        vector_norm = None
        residual_norm = None
    elif isinstance(code, QjlCodePayload):
        if not code.packed_signs:
            raise ValueError("QJL packed code payload must not be empty")
        family = "qjl"
        primary = code.packed_signs
        residual = None
        vector_norm = float(code.vector_norm)
        residual_norm = None
    elif isinstance(code, TurboQuantMseCodePayload):
        if not code.packed_indices:
            raise ValueError("TurboQuant MSE packed code payload must not be empty")
        family = "turboquant_mse"
        primary = code.packed_indices
        residual = None
        vector_norm = float(code.vector_norm)
        residual_norm = None
    else:
        if not code.packed_mse_indices or not code.packed_residual_signs:
            raise ValueError("TurboQuant packed code payloads must not be empty")
        family = "turboquant_inner_product"
        primary = code.packed_mse_indices
        residual = code.packed_residual_signs
        vector_norm = float(code.vector_norm)
        residual_norm = float(code.residual_norm)
    return QuantizedCodeRow(
        source_identity=source_identity,
        representation_ref_id=representation_ref_id,
        artifact_id=code.projection_artifact_id,
        source_watermark=source_watermark,
        family=family,
        packed_primary=primary,
        packed_residual=residual,
        vector_norm=vector_norm,
        residual_norm=residual_norm,
    )


@pure_lazy
def publish_quantized_code_lazy(
    txn: LazyWriteTransaction,
    *,
    source_identity: QuantizedSourceIdentity,
    representation_ref_id: MatchRepresentationRefId,
    source_watermark: QuantizedSourceWatermark,
    code: QuantizedCodePayload,
) -> LazyResult[QuantizedCodePayload | None]:
    """Publish one packed code without an expanded coordinate relation."""
    row = _quantized_code_row(
        source_identity=source_identity,
        representation_ref_id=representation_ref_id,
        source_watermark=source_watermark,
        code=code,
    )
    rows = txn.upsert_many_lazy(
        QuantizedCodeRow,
        (row,),
        conflict_columns=[field(QuantizedCodeRow.identity_digest)],
        on_conflict={field(QuantizedCodeRow.artifact_id): field(QuantizedCodeRow.artifact_id)},
    )
    plan = txn._get_transaction_plan_lazy()
    return txn._add_intent(
        _CodePayloadStep(
            ServerPlanRefId(plan._next_ref()),
            _CodePayloadConfig(
                source_ref=_single_ref(rows, "quantized code publication"),
                expected=code,
            ),
        ),
    )


